  ('431f6a10-8de4-7ba5-9c76-6fcfbd8673e2', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"Problem"}]}'),
  ('cb491f3c-d80d-7668-b427-8d4b5f1c2b07', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reconstruct airline itinerary starting from "},{"type":"text","text":"JFK","marks":[{"type":"code"}]},{"type":"text","text":" using all tickets exactly once. Return lexicographically smallest itinerary."}]}]}}'),
  ('40022eb8-692a-7b89-9940-f64d45dced2d', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]}'),
  ('b388e026-03da-7ade-9216-8bff28405e9c', 'a4', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Eulerian Path problem on directed graph. Hierholzer''s Algorithm builds post-order itinerary traversing sorted neighbors."}]}]}}'),
  ('51ed3948-20fa-7d17-b4e4-c1e2f9a39ed9', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"Intuition"}]}'),
  ('bb5fc6ec-6486-7eea-9e0e-e74f5b72a994', 'a6', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hierholzer''s algorithm: sort destination lists reverse-alphabetically, pop destinations during DFS, append node post-order, then reverse result."}]}]}}'),
