  ('827d0e99-7596-7882-bf83-677333282567', 'a8', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sort tickets reverse alphabetically so pop() gives smallest destination."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"DFS starting from JFK: while neighbors exist, dfs(neighbors.pop())."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Append airport to result post-order. Return reverse of result."}]}]}]}]}}'),
  ('b71c95ee-5d07-72db-8ffe-d3cf7c12fb53', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"Naive Solution"}]}'),
  ('b16cc936-5c6f-7716-8eaa-94a2616a3215', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Standard DFS backtracking exploring all paths."}]}]}}'),
  ('a5961979-57b5-7108-9c72-62814c364fdb', 'aB', 'code', '{"language":"python","code":"from collections import defaultdict\n\nclass Solution:\n    def findItinerary(self, tickets):\n        n = len(tickets)\n        tickets = sorted(tickets)\n\n        # airport -> indices of its tickets, in lexical order of destination\n        graph = defaultdict(list)\n\n        for i, (src, dst) in enumerate(tickets):\n            graph[src].append(i)\n\n        used = [False] * n\n        path = [\"JFK\"]\n\n        def dfs(airport):\n            if len(path) == n + 1:\n                return True\n\n            for i in graph[airport]:\n                if used[i]:\n                    continue\n\n                used[i] = True\n                path.append(tickets[i][1])\n\n                if dfs(tickets[i][1]):\n                    return True\n\n                used[i] = False  # backtrack\n                path.pop()\n\n            return False\n\n        dfs(\"JFK\")\n        return path","filename":"Python"}'),
  ('492dfcee-7e8b-7fa5-ae57-80a9d36ae687', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    vector<string> findItinerary(vector<vector<string>>& tickets) {\n        int n = tickets.size();\n        sort(tickets.begin(), tickets.end());\n\n        // airport -> indices of its tickets, in lexical order of destination\n        unordered_map<string, vector<int>> graph;\n        for (int i = 0; i < n; i++)\n            graph[tickets[i][0]].push_back(i);\n\n        vector<bool> used(n, false);\n        vector<string> path{\"JFK\"};\n\n        function<bool(const string&)> dfs = [&](const string& airport) -> bool {\n            if ((int)path.size() == n + 1) return true;\n\n            for (int i : graph[airport]) {\n                if (used[i]) continue;\n\n                used[i] = true;\n                path.push_back(tickets[i][1]);\n\n                if (dfs(tickets[i][1])) return true;\n\n                used[i] = false;  // backtrack\n                path.pop_back();\n            }\n\n            return false;\n        };\n\n        dfs(\"JFK\");\n        return path;\n    }\n};","filename":"C++"}'),
  ('dbce329a-a591-7ae5-ae41-749c66644360', 'aD', 'code', '{"language":"java","code":"class Solution {\n    private List<List<String>> tickets;\n    private Map<String, List<Integer>> graph = new HashMap<>();\n    private boolean[] used;\n    private List<String> path = new ArrayList<>();\n\n    public List<String> findItinerary(List<List<String>> tickets) {\n        this.tickets = new ArrayList<>(tickets);\n        this.tickets.sort((a, b) -> a.get(0).equals(b.get(0))\n                ? a.get(1).compareTo(b.get(1))\n                : a.get(0).compareTo(b.get(0)));\n\n        // airport -> indices of its tickets, in lexical order of destination\n        for (int i = 0; i < this.tickets.size(); i++)\n            graph.computeIfAbsent(this.tickets.get(i).get(0), k -> new ArrayList<>()).add(i);\n\n        used = new boolean[this.tickets.size()];\n        path.add(\"JFK\");\n        dfs(\"JFK\");\n\n        return path;\n    }\n\n    private boolean dfs(String airport) {\n        if (path.size() == tickets.size() + 1) return true;\n\n        for (int i : graph.getOrDefault(airport, Collections.emptyList())) {\n            if (used[i]) continue;\n\n            String next = tickets.get(i).get(1);\n            used[i] = true;\n            path.add(next);\n\n            if (dfs(next)) return true;\n\n            used[i] = false;  // backtrack\n            path.remove(path.size() - 1);\n        }\n\n        return false;\n    }\n}","filename":"Java"}'),
  ('41682950-e230-782f-99c9-670aa512ab99', 'aE', 'code', '{"language":"javascript","code":"var findItinerary = function(tickets) {\n    const n = tickets.length;\n    const sorted = [...tickets].sort((a, b) =>\n        a[0] === b[0] ? (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0)\n                      : (a[0] < b[0] ? -1 : 1));\n\n    // airport -> indices of its tickets, in lexical order of destination\n    const graph = new Map();\n    sorted.forEach(([src], i) => {\n        if (!graph.has(src)) graph.set(src, []);\n        graph.get(src).push(i);\n    });\n\n    const used = new Array(n).fill(false);\n    const path = [\"JFK\"];\n\n    const dfs = (airport) => {\n        if (path.length === n + 1) return true;\n\n        for (const i of graph.get(airport) || []) {\n            if (used[i]) continue;\n\n            used[i] = true;\n            path.push(sorted[i][1]);\n\n            if (dfs(sorted[i][1])) return true;\n\n            used[i] = false;  // backtrack\n            path.pop();\n        }\n\n        return false;\n    };\n\n    dfs(\"JFK\");\n    return path;\n};","filename":"JavaScript"}'),
  ('78eade72-a4e6-7af0-a319-21492740a0fa', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(E!) · Aux Space: O(E)","marks":[{"type":"bold"}]}]}]}}'),
