  ('f40712a7-85f4-746e-a0b6-44335a847fc1', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 355","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/design-twitter/"}}]}]}]}}'),
  ('4d30b5f9-411b-743c-9e06-a322bf0ed79e', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"Problem"}]}'),
  ('331c57b9-c1c5-7444-ac3b-24a2ce8aee5b', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Design a simplified Twitter with operations: "},{"type":"text","text":"postTweet()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"getNewsFeed()","marks":[{"type":"code"}]},{"type":"text","text":" (10 most recent tweets), "},{"type":"text","text":"follow()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"unfollow()","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
