  ('a7d8a753-ed16-7bfd-aff5-721d1bc9cb0e', 'a4', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Newsfeed must retrieve the 10 most recent tweets posted by user or anyone they follow."}]}]}}'),
  ('53a273fb-44c4-70db-8680-69a3494505e6', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"Intuition"}]}'),
  ('0e1dee43-90e4-786d-b1c9-895c97ed9128', 'a6', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"K-Way Merge with Heap: each user''s tweets are already chronological. Push latest tweet from each followed user into heap, pop top 10."}]}]}}'),
  ('c330ed2b-1d2a-746f-9764-9f01eeb69fad', 'a7', 'heading', '{"level":1,"content":[{"type":"text","text":"Approach"}]}'),
  ('d5b42c77-4008-7715-ad06-40ea19284aeb', 'a8', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Store tweets per user in list "},{"type":"text","text":"self.tweets[userId] = [(time, tweetId)]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For "},{"type":"text","text":"getNewsFeed(userId)","marks":[{"type":"code"}]},{"type":"text","text":": collect candidate users "},{"type":"text","text":"following[userId] | {userId}","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Push latest tweet tuple "},{"type":"text","text":"(-time, tweetId, user, index)","marks":[{"type":"code"}]},{"type":"text","text":" for each user into heap."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pop 10 times: append tweetId to result and push previous tweet "},{"type":"text","text":"index - 1","marks":[{"type":"code"}]},{"type":"text","text":" from same user if exists."}]}]}]}]}}'),
  ('40573a7d-07df-7829-99b9-e1fcef6874f3', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]}'),
  ('d592e220-4347-7f19-adb8-d0c435019fd3', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Gather all tweets from followed users into one list and sort by timestamp."}]}]}}'),
  ('758acde0-2bad-7312-b8f5-10b53153f9d3', 'aB', 'code', '{"language":"python","code":"from collections import defaultdict\n\nclass Twitter:\n\n    def __init__(self):\n        self.time = 0\n        self.tweets = defaultdict(list)\n        self.following = defaultdict(set)\n\n    def postTweet(self, userId, tweetId):\n        self.time += 1\n\n        self.tweets[userId].append(\n            (self.time, tweetId)\n        )\n\n    def getNewsFeed(self, userId):\n\n        users = self.following[userId] | {userId}\n\n        all_tweets = []\n\n        for user in users:\n            all_tweets.extend(\n                self.tweets[user]\n            )\n\n        all_tweets.sort(\n            reverse=True\n        )\n\n        return [\n            tweet_id\n            for _, tweet_id in all_tweets[:10]\n        ]\n\n    def follow(self, followerId, followeeId):\n        if followerId != followeeId:\n            self.following[followerId].add(\n                followeeId\n            )\n\n    def unfollow(self, followerId, followeeId):\n        self.following[followerId].discard(\n            followeeId\n        )","filename":"Python"}'),
  ('b5b66caa-f94f-7365-bfb9-08f342c5c5bb', 'aC', 'code', '{"language":"cpp","code":"class Twitter {\n    int time = 0;\n    unordered_map<int, vector<pair<int, int>>> tweets;  // user -> {time, tweetId}\n    unordered_map<int, unordered_set<int>> following;\n\npublic:\n    Twitter() {}\n\n    void postTweet(int userId, int tweetId) {\n        time++;\n\n        tweets[userId].push_back({time, tweetId});\n    }\n\n    vector<int> getNewsFeed(int userId) {\n        unordered_set<int> users = following[userId];\n        users.insert(userId);\n\n        vector<pair<int, int>> allTweets;\n\n        for (int user : users) {\n            allTweets.insert(allTweets.end(), tweets[user].begin(), tweets[user].end());\n        }\n\n        sort(allTweets.begin(), allTweets.end(), greater<pair<int, int>>());\n\n        vector<int> result;\n        for (int i = 0; i < (int)allTweets.size() && i < 10; i++) {\n            result.push_back(allTweets[i].second);\n        }\n\n        return result;\n    }\n\n    void follow(int followerId, int followeeId) {\n        if (followerId != followeeId) following[followerId].insert(followeeId);\n    }\n\n    void unfollow(int followerId, int followeeId) {\n        following[followerId].erase(followeeId);\n    }\n};","filename":"C++"}'),
  ('53ec12e5-a7a5-76cd-8e47-4decaed64e75', 'aD', 'code', '{"language":"java","code":"class Twitter {\n    private int time = 0;\n    private Map<Integer, List<int[]>> tweets = new HashMap<>();  // user -> {time, tweetId}\n    private Map<Integer, Set<Integer>> following = new HashMap<>();\n\n    public Twitter() {}\n\n    public void postTweet(int userId, int tweetId) {\n        time++;\n\n        tweets.computeIfAbsent(userId, key -> new ArrayList<>()).add(new int[]{time, tweetId});\n    }\n\n    public List<Integer> getNewsFeed(int userId) {\n        Set<Integer> users = new HashSet<>(following.getOrDefault(userId, new HashSet<>()));\n        users.add(userId);\n\n        List<int[]> allTweets = new ArrayList<>();\n\n        for (int user : users) {\n            allTweets.addAll(tweets.getOrDefault(user, new ArrayList<>()));\n        }\n\n        allTweets.sort((a, b) -> Integer.compare(b[0], a[0]));\n\n        List<Integer> result = new ArrayList<>();\n        for (int i = 0; i < allTweets.size() && i < 10; i++) {\n            result.add(allTweets.get(i)[1]);\n        }\n\n        return result;\n    }\n\n    public void follow(int followerId, int followeeId) {\n        if (followerId != followeeId) {\n            following.computeIfAbsent(followerId, key -> new HashSet<>()).add(followeeId);\n        }\n    }\n\n    public void unfollow(int followerId, int followeeId) {\n        Set<Integer> followees = following.get(followerId);\n        if (followees != null) followees.remove(followeeId);\n    }\n}","filename":"Java"}'),
  ('8855f51a-bb82-7d59-be6d-81efaca93f4b', 'aE', 'code', '{"language":"javascript","code":"class Twitter {\n    constructor() {\n        this.time = 0;\n        this.tweets = new Map();     // user -> [[time, tweetId], ...]\n        this.following = new Map();  // user -> Set of followees\n    }\n\n    postTweet(userId, tweetId) {\n        this.time++;\n\n        if (!this.tweets.has(userId)) this.tweets.set(userId, []);\n        this.tweets.get(userId).push([this.time, tweetId]);\n    }\n\n    getNewsFeed(userId) {\n        const users = new Set(this.following.get(userId) || []);\n        users.add(userId);\n\n        const allTweets = [];\n\n        for (const user of users) {\n            allTweets.push(...(this.tweets.get(user) || []));\n        }\n\n        allTweets.sort((a, b) => b[0] - a[0]);\n\n        return allTweets.slice(0, 10).map(([, tweetId]) => tweetId);\n    }\n\n    follow(followerId, followeeId) {\n        if (followerId !== followeeId) {\n            if (!this.following.has(followerId)) this.following.set(followerId, new Set());\n            this.following.get(followerId).add(followeeId);\n        }\n    }\n\n    unfollow(followerId, followeeId) {\n        this.following.get(followerId)?.delete(followeeId);\n    }\n}","filename":"JavaScript"}'),
  ('cf33894d-d718-76b9-a809-50ac5feda001', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"getNewsFeed: O(T log T) · Space: O(T + F)","marks":[{"type":"bold"}]}]}]}}'),
  ('7a81516e-f293-7ee8-8b39-84529030bb64', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]}'),
  ('a68b40af-5207-7ccd-9cf1-e97eaa09ddbe', 'aH', 'code', '{"language":"python","code":"import heapq\nfrom collections import defaultdict\n\nclass Twitter:\n\n    def __init__(self):\n        self.time = 0\n        self.tweets = defaultdict(list)\n        self.following = defaultdict(set)\n\n    def postTweet(self, userId, tweetId):\n        self.time += 1\n\n        self.tweets[userId].append(\n            (self.time, tweetId)\n        )\n\n    def follow(self, followerId, followeeId):\n        if followerId != followeeId:\n            self.following[followerId].add(\n                followeeId\n            )\n\n    def unfollow(self, followerId, followeeId):\n        self.following[followerId].discard(\n            followeeId\n        )\n\n    def getNewsFeed(self, userId):\n\n        users = self.following[userId] | {userId}\n\n        heap = []\n\n        for user in users:\n            tweets = self.tweets[user]\n\n            if tweets:\n                index = len(tweets) - 1\n                time, tweet_id = tweets[index]\n\n                heapq.heappush(\n                    heap,\n                    (-time, tweet_id, user, index)\n                )\n\n        result = []\n\n        while heap and len(result) < 10:\n\n            _, tweet_id, user, index = (\n                heapq.heappop(heap)\n            )\n\n            result.append(tweet_id)\n\n            index -= 1\n\n            if index >= 0:\n                time, tweet_id = (\n                    self.tweets[user][index]\n                )\n\n                heapq.heappush(\n                    heap,\n                    (-time, tweet_id, user, index)\n                )\n\n        return result","filename":"Python"}'),
  ('811f2512-3a81-77b6-9e9a-6c473fd61fb8', 'aI', 'code', '{"language":"cpp","code":"class Twitter {\n    int time = 0;\n    unordered_map<int, vector<pair<int, int>>> tweets;  // user -> {time, tweetId}\n    unordered_map<int, unordered_set<int>> following;\n\npublic:\n    Twitter() {}\n\n    void postTweet(int userId, int tweetId) {\n        time++;\n\n        tweets[userId].push_back({time, tweetId});\n    }\n\n    void follow(int followerId, int followeeId) {\n        if (followerId != followeeId) following[followerId].insert(followeeId);\n    }\n\n    void unfollow(int followerId, int followeeId) {\n        following[followerId].erase(followeeId);\n    }\n\n    vector<int> getNewsFeed(int userId) {\n        unordered_set<int> users = following[userId];\n        users.insert(userId);\n\n        priority_queue<array<int, 4>> heap;  // max-heap of {time, tweetId, user, index}\n\n        for (int user : users) {\n            auto& userTweets = tweets[user];\n\n            if (!userTweets.empty()) {\n                int index = userTweets.size() - 1;\n                auto [time, tweetId] = userTweets[index];\n\n                heap.push({time, tweetId, user, index});\n            }\n        }\n\n        vector<int> result;\n\n        while (!heap.empty() && result.size() < 10) {\n            auto [_, tweetId, user, index] = heap.top();\n            heap.pop();\n\n            result.push_back(tweetId);\n\n            index--;\n\n            if (index >= 0) {\n                auto [time, nextTweetId] = tweets[user][index];\n\n                heap.push({time, nextTweetId, user, index});\n            }\n        }\n\n        return result;\n    }\n};","filename":"C++"}'),
  ('f29fca26-b3d4-7660-a62a-87f6886f7a97', 'aJ', 'code', '{"language":"java","code":"class Twitter {\n    private int time = 0;\n    private Map<Integer, List<int[]>> tweets = new HashMap<>();  // user -> {time, tweetId}\n    private Map<Integer, Set<Integer>> following = new HashMap<>();\n\n    public Twitter() {}\n\n    public void postTweet(int userId, int tweetId) {\n        time++;\n\n        tweets.computeIfAbsent(userId, key -> new ArrayList<>()).add(new int[]{time, tweetId});\n    }\n\n    public void follow(int followerId, int followeeId) {\n        if (followerId != followeeId) {\n            following.computeIfAbsent(followerId, key -> new HashSet<>()).add(followeeId);\n        }\n    }\n\n    public void unfollow(int followerId, int followeeId) {\n        Set<Integer> followees = following.get(followerId);\n        if (followees != null) followees.remove(followeeId);\n    }\n\n    public List<Integer> getNewsFeed(int userId) {\n        Set<Integer> users = new HashSet<>(following.getOrDefault(userId, new HashSet<>()));\n        users.add(userId);\n\n        // max-heap of {time, tweetId, user, index}\n        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(b[0], a[0]));\n\n        for (int user : users) {\n            List<int[]> userTweets = tweets.getOrDefault(user, new ArrayList<>());\n\n            if (!userTweets.isEmpty()) {\n                int index = userTweets.size() - 1;\n                int[] tweet = userTweets.get(index);\n\n                heap.offer(new int[]{tweet[0], tweet[1], user, index});\n            }\n        }\n\n        List<Integer> result = new ArrayList<>();\n\n        while (!heap.isEmpty() && result.size() < 10) {\n            int[] top = heap.poll();\n            int user = top[2], index = top[3];\n\n            result.add(top[1]);\n\n            index--;\n\n            if (index >= 0) {\n                int[] tweet = tweets.get(user).get(index);\n\n                heap.offer(new int[]{tweet[0], tweet[1], user, index});\n            }\n        }\n\n        return result;\n    }\n}","filename":"Java"}'),
  ('9f2554ca-6f2c-7ea4-afde-957eb4fbf9ab', 'aK', 'code', '{"language":"javascript","code":"class MinHeap {\n    constructor(compare = (a, b) => a - b, items = []) {\n        this.compare = compare;\n        this.data = items;\n        for (let i = (items.length >> 1) - 1; i >= 0; i--) this.siftDown(i);\n    }\n\n    size() { return this.data.length; }\n\n    peek() { return this.data[0]; }\n\n    push(value) {\n        const data = this.data;\n        data.push(value);\n        let i = data.length - 1;\n        while (i > 0) {\n            const parent = (i - 1) >> 1;\n            if (this.compare(data[i], data[parent]) >= 0) break;\n            [data[i], data[parent]] = [data[parent], data[i]];\n            i = parent;\n        }\n    }\n\n    pop() {\n        const data = this.data;\n        const top = data[0];\n        const last = data.pop();\n        if (data.length > 0) {\n            data[0] = last;\n            this.siftDown(0);\n        }\n        return top;\n    }\n\n    siftDown(i) {\n        const data = this.data;\n        while (true) {\n            const left = 2 * i + 1, right = left + 1;\n            let smallest = i;\n            if (left < data.length && this.compare(data[left], data[smallest]) < 0) smallest = left;\n            if (right < data.length && this.compare(data[right], data[smallest]) < 0) smallest = right;\n            if (smallest === i) return;\n            [data[i], data[smallest]] = [data[smallest], data[i]];\n            i = smallest;\n        }\n    }\n}\n\nclass Twitter {\n    constructor() {\n        this.time = 0;\n        this.tweets = new Map();     // user -> [[time, tweetId], ...]\n        this.following = new Map();  // user -> Set of followees\n    }\n\n    postTweet(userId, tweetId) {\n        this.time++;\n\n        if (!this.tweets.has(userId)) this.tweets.set(userId, []);\n        this.tweets.get(userId).push([this.time, tweetId]);\n    }\n\n    follow(followerId, followeeId) {\n        if (followerId !== followeeId) {\n            if (!this.following.has(followerId)) this.following.set(followerId, new Set());\n            this.following.get(followerId).add(followeeId);\n        }\n    }\n\n    unfollow(followerId, followeeId) {\n        this.following.get(followerId)?.delete(followeeId);\n    }\n\n    getNewsFeed(userId) {\n        const users = new Set(this.following.get(userId) || []);\n        users.add(userId);\n\n        const heap = new MinHeap((a, b) => b[0] - a[0]);  // max-heap by time\n\n        for (const user of users) {\n            const tweets = this.tweets.get(user) || [];\n\n            if (tweets.length) {\n                const index = tweets.length - 1;\n                const [time, tweetId] = tweets[index];\n\n                heap.push([time, tweetId, user, index]);\n            }\n        }\n\n        const result = [];\n\n        while (heap.size() > 0 && result.length < 10) {\n            let [, tweetId, user, index] = heap.pop();\n\n            result.push(tweetId);\n\n            index--;\n\n            if (index >= 0) {\n                const [time, nextTweetId] = this.tweets.get(user)[index];\n\n                heap.push([time, nextTweetId, user, index]);\n            }\n        }\n\n        return result;\n    }\n}","filename":"JavaScript"}'),
  ('369ab24e-84e4-71d0-bac5-7fd3887d30a3', 'aL', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"getNewsFeed: O(F + 10 log F) · Space: O(F)","marks":[{"type":"bold"}]}]}]}}'),
