= total // 2\n\n        dp = [False] * (target + 1)\n        dp[0] = True\n\n        for num in nums:\n            for current in range(target, num - 1, -1):\n                dp[current] = (\n                    dp[current]\n                    or\n                    dp[current - num]\n                )\n\n        return dp[target]","filename":"Python"},"revision":1},{"id":"a9cee232-260f-7275-b3ee-cb53f6d7ee91","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    bool canPartition(vector<int>& nums) {\n        int total = accumulate(nums.begin(), nums.end(), 0);\n        if (total % 2) return false;\n\n        int target = total / 2;\n\n        vector<bool> dp(target + 1, false);\n        dp[0] = true;\n\n        for (int num : nums) {\n            for (int current = target; current >= num; current--) {\n                dp[current] = dp[current] || dp[current - num];\n            }\n        }\n\n        return dp[target];\n    }\n};","filename":"C++"},"revision":1},{"id":"05d8cfd8-c2d0-763c-82cd-69a9a0a7677a","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public boolean canPartition(int[] nums) {\n        int total = 0;\n        for (int num : nums) total += num;\n\n        if (total % 2 != 0) return false;\n\n        int target = total / 2;\n\n        boolean[] dp = new boolean[target + 1];\n        dp[0] = true;\n\n        for (int num : nums) {\n            for (int current = target; current >= num; current--) {\n                dp[current] = dp[current] || dp[current - num];\n            }\n        }\n\n        return dp[target];\n    }\n}","filename":"Java"},"revision":1},{"id":"c777cb01-e0eb-708e-a375-b5e789d50ed0","type":"code","position":"aK","content":{"language":"javascript","code":"var canPartition = function(nums) {\n    const total = nums.reduce((a, b) => a + b, 0);\n    if (total % 2) return false;\n\n    const target = total / 2;\n\n    const dp = new Array(target + 1).fill(false);\n    dp[0] = true;\n\n    for (const num of nums) {\n        for (let current = target; current >= num; current--) {\n            dp[current] = dp[current] || dp[current - num];\n        }\n    }\n\n    return dp[target];\n};","filename":"JavaScript"},"revision":1},{"id":"a11c01df-a6d1-7d2f-a341-ba4a6a056658","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n × target) · Space: O(target)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"c4f4507b-585a-7ae1-9e3c-ed9edb0f7e15","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"f876af0e-4ffa-79e4-802d-7e0eb849e0d3","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"0/1 Knapsack Backward Loop","marks":[{"type":"bold"}]},{"type":"text","text":" — Loop backward ("},{"type":"text","text":"range(target, num - 1, -1)","marks":[{"type":"code"}]},{"type":"text","text":") so each number is used only once."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
