SELECT '5f68d5d5-3d49-770e-aa7f-a6082a0a55cc', 'd7ad4748-9b7f-7b42-82c6-260bcda5ea1c', 1, 'PUBLISHED', 'Pacific Atlantic Water Flow', '[{"id":"26a9e84c-9395-77d8-a9ce-b0a161775dbd","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 417","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/pacific-atlantic-water-flow/"}}]}]}]}},"revision":1},{"id":"8ea3662f-2396-74be-8c52-a809506e6d8a","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"672f5523-c38a-7671-91e8-e8759dd5704f","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find grid coordinates that can flow water to BOTH Pacific Ocean (top/left) and Atlantic Ocean (bottom/right)."}]}]}},"revision":1},{"id":"ed55ef1f-8a93-77d9-9482-972ed1001818","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"01a98465-d2b2-75b3-be01-cd4417a1e50d","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reverse problem: ask which cells can be reached by starting at ocean borders and flowing UPHILL."}]}]}},"revision":1},{"id":"5daaccf7-995d-7ee1-a22d-703677c100f7","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"ff71566c-bbca-7ced-9a4f-61b3521b7d03","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Multi-source BFS starting from ocean borders moving uphill."}]}]}},"revision":1},{"id":"353d580d-da30-71d1-8803-467aeffcf07f","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"f2480340-5672-7551-b62b-0661fddaffd8","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Start multi-source BFS from Pacific ocean borders into set P."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Start multi-source BFS from Atlantic ocean borders into set A."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return intersection of sets "},{"type":"text","text":"P & A","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"ef1d5918-c74b-7c48-9e89-30dcf4e7359d","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution"}]},"revision":1},{"id":"1aeb3d06-b595-7327-b2e7-7eeddd5a4170","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For every cell, perform DFS to check if it reaches both oceans."}]}]}},"revision":1},{"id":"e8bd989f-be07-7d83-80d8-bbf5f02ff40e","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def pacificAtlantic(self, heights):\n        rows = len(heights)\n        cols = len(heights[0])\n\n        result = []\n\n        def can_reach(r, c, target):\n            visited = set()\n\n            def dfs(x, y):\n                if (x, y) in visited:\n                    return False\n\n                if target == \"P\" and (x == 0 or y == 0):\n                    return True\n\n                if target == \"A\" and (\n                    x == rows - 1 or y == cols - 1\n                ):\n                    return True\n\n                visited.add((x, y))\n\n                for dx, dy in [\n                    (1, 0), (-1, 0),\n                    (0, 1), (0, -1)\n                ]:\n                    nx, ny = x + dx, y + dy\n\n                    if (\n                        0 <= nx < rows and\n                        0 <= ny < cols and\n                        heights[nx][ny] <= heights[x][y]\n                    ):\n                        if dfs(nx, ny):\n                            return True\n\n                return False\n\n            return dfs(r, c)\n\n        for r in range(rows):\n            for c in range(cols):\n                if (\n                    can_reach(r, c, \"P\")\n                    and can_reach(r, c, \"A\")\n                ):\n                    result.append([r, c])\n\n        return result","filename":"Python"},"revision":1},{"id":"297b46d2-5bf6-7f6b-a98f-87677035d3bc","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    vector<vector<int>> pacificAtlantic(vector<vector<int>>& heights) {\n        int rows = heights.size(), cols = heights[0].size();\n        int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n\n        auto canReach = [&](int r, int c, char target) {\n            vector<vector<bool>> visited(rows, vector<bool>(cols, false));\n\n            function<bool(int, int)> dfs = [&](int x, int y) -> bool {\n                if (visited[x][y]) return false;\n\n                if (target == ''P'' && (x == 0 || y == 0)) return true;\n                if (target == ''A'' && (x == rows - 1 || y == cols - 1)) return true;\n\n                visited[x][y] = true;\n\n                for (auto& d : dirs) {\n                    int nx = x + d[0], ny = y + d[1];\n\n                    if (nx >= 0 && nx < rows && ny >= 0 && ny < cols &&\n                        heights[nx][ny] <= heights[x][y]) {\n                        if (dfs(nx, ny)) return true;\n                    }\n                }\n\n                return false;\n            };\n\n            return dfs(r, c);\n        };\n\n        vector<vector<int>> result;\n\n        for (int r = 0; r < rows; r++)\n            for (int c = 0; c < cols; c++)\n                if (canReach(r, c, ''P'') && canReach(r, c, ''A''))\n                    result.push_back({r, c});\n\n        return result;\n    }\n};","filename":"C++"},"revision":1},{"id":"c6b8d906-b695-7775-a1a3-360fcfdfeaf4","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n    private int[][] heights;\n    private int rows, cols;\n    private boolean[][] visited;\n\n    public List<List<Integer>> pacificAtlantic(int[][] heights) {\n        this.heights = heights;\n        rows = heights.length;\n        cols = heights[0].length;\n\n        List<List<Integer>> result = new ArrayList<>();\n\n        for (int r = 0; r < rows; r++)\n            for (int c = 0; c < cols; c++)\n                if (canReach(r, c, ''P'') && canReach(r, c, ''A''))\n                    result.add(Arrays.asList(r, c));\n\n        return result;\n    }\n\n    private boolean canReach(int r, int c, char target) {\n        visited = new boolean[rows][cols];\n        return dfs(r, c, target);\n    }\n\n    private boolean dfs(int x, int y, char target) {\n        if (visited[x][y]) return false;\n\n        if (target == ''P'' && (x == 0 || y == 0)) return true;\n        if (target == ''A'' && (x == rows - 1 || y == cols - 1)) return true;\n\n        visited[x][y] = true;\n\n        for (int[] d : DIRS) {\n            int nx = x + d[0], ny = y + d[1];\n\n            if (nx >= 0 && nx < rows && ny >= 0 && ny < cols &&\n                heights[nx][ny] <= heights[x][y]) {\n                if (dfs(nx, ny, target)) return true;\n            }\n        }\n\n        return false;\n    }\n}","filename":"Java"},"revision":1},{"id":"83539334-163c-7b37-b924-7427642e4f6c","type":"code","position":"aE","content":{"language":"javascript","code":"var pacificAtlantic = function(heights) {\n    const rows = heights.length;\n    const cols = heights[0].length;\n    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];\n\n    const result = [];\n\n    const canReach = (r, c, target) => {\n        const visited = new Set();\n\n        const dfs = (x, y) => {\n            if (visited.has(x * cols + y)) return false;\n\n            if (target === \"P\" && (x === 0 || y === 0)) return true;\n            if (target === \"A\" && (x === rows - 1 || y === cols - 1)) return true;\n\n            visited.add(x * cols + y);\n\n            for (const [dx, dy] of dirs) {\n                const nx = x + dx, ny = y + dy;\n\n                if (\n                    nx >= 0 && nx < rows &&\n                    ny >= 0 && ny < cols &&\n                    heights[nx][ny] <= heights[x][y]\n                ) {\n                    if (dfs(nx, ny)) return true;\n                }\n            }\n\n            return false;\n        };\n\n        return dfs(r, c);\n    };\n\n    for (let r = 0; r < rows; r++)\n        for (let c = 0; c < cols; c++)\n            if (canReach(r, c, \"P\") && canReach(r, c, \"A\"))\n                result.push([r, c]);\n\n    return result;\n};","filename":"JavaScript"},"revision":1},{"id":"efbd4aed-7536-7128-8527-eb43dce25896","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O((R × C)^2) · Aux Space: O(R × C)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"c358a4a4-bcb4-7ab7-b89b-448faa77d16f","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"2a86ffce-5bb3-7edf-925a-2861ba270816","type":"code","position":"aH","content":{"language":"python","code":"from collections import deque\n\nclass Solution:\n    def pacificAtlantic(self, heights):\n        rows = len(heights)\n        cols = len(heights[0])\n\n        def bfs(starts):\n            visited = set()\n            queue = deque(starts)\n\n            for cell in starts:\n                visited.add(cell)\n\n            while queue:\n                r, c = queue.popleft()\n\n                for dr, dc in [\n                    (1, 0), (-1, 0),\n                    (0, 1), (0, -1)\n                ]:\n                    nr, nc = r + dr, c + dc\n\n                    if (\n                        0 <= nr < rows and\n                        0 <= nc < cols\n                        and (nr, nc) not in visited\n                        and heights[nr][nc] >= heights[r][c]\n                    ):\n                        visited.add((nr, nc))\n                        queue.append((nr, nc))\n\n            return visited\n\n        pacific = []\n\n        for r in range(rows):\n            pacific.append((r, 0))\n\n        for c in range(cols):\n            pacific.append((0, c))\n\n        atlantic = []\n\n        for r in range(rows):\n            atlantic.append((r, cols - 1))\n\n        for c in range(cols):\n            atlantic.append((rows - 1, c))\n\n        p = bfs(pacific)\n        a = bfs(atlantic)\n\n        return [\n            [r, c]\n            for r, c in p & a\n        ]","filename":"Python"},"revision":1},{"id":"4438370a-f167-7728-b2e9-1d47d73e5759","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    vector<vector<int>> pacificAtlantic(vector<vector<int>>& heights) {\n        int rows = heights.size(), cols = heights[0].size();\n        int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n\n        auto bfs = [&](const vector<pair<int, int>>& starts) {\n            vector<vector<bool>> visited(rows, vector<bool>(cols, false));\n            queue<pair<int, int>> q;\n\n            for (auto& [r, c] : starts) {\n                visited[r][c] = true;\n                q.push({r, c});\n            }\n\n            while (!q.empty()) {\n                auto [r, c] = q.front();\n                q.pop();\n\n                for (auto& d : dirs) {\n                    int nr = r + d[0], nc = c + d[1];\n\n                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&\n                        !visited[nr][nc] && heights[nr][nc] >= heights[r][c]) {\n                        visited[nr][nc] = true;\n                        q.push({nr, nc});\n                    }\n                }\n            }\n\n            return visited;\n        };\n\n        vector<pair<int, int>> pacific, atlantic;\n\n        for (int r = 0; r < rows; r++) pacific.push_back({r, 0});\n        for (int c = 0; c < cols; c++) pacific.push_back({0, c});\n\n        for (int r = 0; r < rows; r++) atlantic.push_back({r, cols - 1});\n        for (int c = 0; c < cols; c++) atlantic.push_back({rows - 1, c});\n\n        auto p = bfs(pacific);\n        auto a = bfs(atlantic);\n\n        vector<vector<int>> result;\n\n        for (int r = 0; r < rows; r++)\n            for (int c = 0; c < cols; c++)\n                if (p[r][c] && a[r][c])\n                    result.push_back({r, c});\n\n        return result;\n    }\n};","filename":"C++"},"revision":1},{"id":"2566f69a-3ee5-7b1d-8a7e-50a9562e87df","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n    private int[][] heights;\n    private int rows, cols;\n\n    public List<List<Integer>> pacificAtlantic(int[][] heights) {\n        this.heights = heights;\n        rows = heights.length;\n        cols = heights[0].length;\n\n        List<int[]> pacific = new ArrayList<>();\n        for (int r = 0; r < rows; r++) pacific.add(new int[]{r, 0});\n        for (int c = 0; c < cols; c++) pacific.add(new int[]{0, c});\n\n        List<int[]> atlantic = new ArrayList<>();\n        for (int r = 0; r < rows; r++) atlantic.add(new int[]{r, cols - 1});\n        for (int c = 0; c < cols; c++) atlantic.add(new int[]{rows - 1, c});\n\n        boolean[][] p = bfs(pacific);\n        boolean[][] a = bfs(atlantic);\n\n        List<List<Integer>> result = new ArrayList<>();\n\n        for (int r = 0; r < rows; r++)\n            for (int c = 0; c < cols; c++)\n                if (p[r][c] && a[r][c])\n                    result.add(Arrays.asList(r, c));\n\n        return result;\n    }\n\n    private boolean[][] bfs(List<int[]> starts) {\n        boolean[][] visited = new boolean[rows][cols];\n        Deque<int[]> queue = new ArrayDeque<>();\n\n        for (int[] cell : starts) {\n            visited[cell[0]][cell[1]] = true;\n            queue.offer(cell);\n        }\n\n        while (!queue.isEmpty()) {\n            int[] cell = queue.poll();\n            int r = cell[0], c = cell[1];\n\n            for (int[] d : DIRS) {\n                int nr = r + d[0], nc = c + d[1];\n\n                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&\n                    !visited[nr][nc] && heights[nr][nc] >= heights[r][c]) {\n                    visited[nr][nc] = true;\n                    queue.offer(new int[]{nr, nc});\n                }\n            }\n        }\n\n        return visited;\n    }\n}","filename":"Java"},"revision":1},{"id":"48a49e04-176d-70a8-8afe-02e070c10932","type":"code","position":"aK","content":{"language":"javascript","code":"var pacificAtlantic = function(heights) {\n    const rows = heights.length;\n    const cols = heights[0].length;\n    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];\n\n    const bfs = (starts) => {\n        const visited = Array.from({ length: rows }, () => new Array(cols).fill(false));\n        const queue = [];\n\n        for (const [r, c] of starts) {\n            visited[r][c] = true;\n            queue.push([r, c]);\n        }\n\n        for (let head = 0; head < queue.length; head++) {\n            const [r, c] = queue[head];\n\n            for (const [dr, dc] of dirs) {\n                const nr = r + dr, nc = c + dc;\n\n                if (\n                    nr >= 0 && nr < rows &&\n                    nc >= 0 && nc < cols &&\n                    !visited[nr][nc] &&\n                    heights[nr][nc] >= heights[r][c]\n                ) {\n                    visited[nr][nc] = true;\n                    queue.push([nr, nc]);\n                }\n            }\n        }\n\n        return visited;\n    };\n\n    const pacific = [];\n    for (let r = 0; r < rows; r++) pacific.push([r, 0]);\n    for (let c = 0; c < cols; c++) pacific.push([0, c]);\n\n    const atlantic = [];\n    for (let r = 0; r < rows; r++) atlantic.push([r, cols - 1]);\n    for (let c = 0; c < cols; c++) atlantic.push([rows - 1, c]);\n\n    const p = bfs(pacific);\n    const a = bfs(atlantic);\n\n    const result = [];\n\n    for (let r = 0; r < rows; r++)\n        for (let c = 0; c < cols; c++)\n            if (p[r][c] && a[r][c])\n                result.push([r, c]);\n\n    return result;\n};","filename":"JavaScript"},"revision":1},{"id":"c922ad07-43c4-779e-b380-d1a13b5858c7","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(R × C) · Aux Space: O(R × C)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"8ae1ce38-84db-7e10-833f-85b051d93c90","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"a35f52ce-3fea-7839-8a34-dc7d6ffbda68","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern:","marks":[{"type":"bold"}]},{"type":"text","text":" Reverse the problem (ask which cells can be reached from ocean flowing uphill)."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
