  ('a7204ac2-5927-7263-a238-34fd93901f5a', 'aB', 'code', '{"language":"python","code":"class Solution:\n    def characterReplacement(self, s, k):\n        answer = 0\n\n        for left in range(len(s)):\n            count = {}\n\n            for right in range(left, len(s)):\n                count[s[right]] = (\n                    count.get(s[right], 0) + 1\n                )\n\n                length = right - left + 1\n                most_frequent = max(count.values())\n\n                if length - most_frequent <= k:\n                    answer = max(answer, length)\n\n        return answer","filename":"Python"}'),
  ('4b3725ab-8dee-7c1f-9a12-2f86db2505b3', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    int characterReplacement(string s, int k) {\n        int answer = 0;\n        for (int left = 0; left < s.size(); left++) {\n            unordered_map<char, int> count;\n            for (int right = left; right < s.size(); right++) {\n                count[s[right]]++;\n                int length = right - left + 1;\n                int mostFrequent = 0;\n                for (auto& [ch, c] : count) mostFrequent = max(mostFrequent, c);\n                if (length - mostFrequent <= k) answer = max(answer, length);\n            }\n        }\n        return answer;\n    }\n};","filename":"C++"}'),
  ('6a67c27d-047d-7401-94a2-7988bfe9896b', 'aD', 'code', '{"language":"java","code":"class Solution {\n    public int characterReplacement(String s, int k) {\n        int answer = 0;\n        for (int left = 0; left < s.length(); left++) {\n            Map<Character, Integer> count = new HashMap<>();\n            for (int right = left; right < s.length(); right++) {\n                count.put(s.charAt(right), count.getOrDefault(s.charAt(right), 0) + 1);\n                int length = right - left + 1;\n                int mostFrequent = Collections.max(count.values());\n                if (length - mostFrequent <= k) answer = Math.max(answer, length);\n            }\n        }\n        return answer;\n    }\n}","filename":"Java"}'),
  ('5cefcfe1-e36a-7ae1-a4ca-765077e556ea', 'aE', 'code', '{"language":"javascript","code":"var characterReplacement = function(s, k) {\n    let answer = 0;\n    for (let left = 0; left < s.length; left++) {\n        const count = new Map();\n        for (let right = left; right < s.length; right++) {\n            count.set(s[right], (count.get(s[right]) || 0) + 1);\n            const length = right - left + 1;\n            const mostFrequent = Math.max(...count.values());\n            if (length - mostFrequent <= k) answer = Math.max(answer, length);\n        }\n    }\n    return answer;\n};","filename":"JavaScript"}'),
  ('7927106c-148c-7c6b-a69b-8dee96883d25', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n²) · Space: O(k)","marks":[{"type":"bold"}]}]}]}}'),
  ('16b28b25-99d1-7b4b-90ea-0b2210a544f7', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]}'),
  ('8f36285e-bc9c-7727-8d3d-d0a1ffae6b50', 'aH', 'code', '{"language":"python","code":"class Solution:\n    def characterReplacement(self, s, k):\n        count = {}\n\n        left = 0\n        max_frequency = 0\n        answer = 0\n\n        for right in range(len(s)):\n            count[s[right]] = (\n                count.get(s[right], 0) + 1\n            )\n\n            max_frequency = max(\n                max_frequency,\n                count[s[right]]\n            )\n\n            while (\n                right - left + 1\n                - max_frequency\n                > k\n            ):\n                count[s[left]] -= 1\n                left += 1\n\n            answer = max(\n                answer,\n                right - left + 1\n            )\n\n        return answer","filename":"Python"}'),
  ('36556634-be95-7111-aa8f-48b14151e983', 'aI', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    int characterReplacement(string s, int k) {\n        unordered_map<char, int> count;\n        int left = 0, maxFrequency = 0, answer = 0;\n        for (int right = 0; right < s.size(); right++) {\n            count[s[right]]++;\n            maxFrequency = max(maxFrequency, count[s[right]]);\n            while (right - left + 1 - maxFrequency > k) {\n                count[s[left]]--;\n                left++;\n            }\n            answer = max(answer, right - left + 1);\n        }\n        return answer;\n    }\n};","filename":"C++"}'),
  ('36bb15bd-a6f6-79d8-ae60-a8fcacf85623', 'aJ', 'code', '{"language":"java","code":"class Solution {\n    public int characterReplacement(String s, int k) {\n        Map<Character, Integer> count = new HashMap<>();\n        int left = 0, maxFrequency = 0, answer = 0;\n        for (int right = 0; right < s.length(); right++) {\n            char c = s.charAt(right);\n            count.put(c, count.getOrDefault(c, 0) + 1);\n            maxFrequency = Math.max(maxFrequency, count.get(c));\n            while (right - left + 1 - maxFrequency > k) {\n                count.put(s.charAt(left), count.get(s.charAt(left)) - 1);\n                left++;\n            }\n            answer = Math.max(answer, right - left + 1);\n        }\n        return answer;\n    }\n}","filename":"Java"}'),
  ('8d14d178-4f37-7ebe-864c-8375119c6b1b', 'aK', 'code', '{"language":"javascript","code":"var characterReplacement = function(s, k) {\n    const count = new Map();\n    let left = 0, maxFrequency = 0, answer = 0;\n    for (let right = 0; right < s.length; right++) {\n        count.set(s[right], (count.get(s[right]) || 0) + 1);\n        maxFrequency = Math.max(maxFrequency, count.get(s[right]));\n        while (right - left + 1 - maxFrequency > k) {\n            count.set(s[left], count.get(s[left]) - 1);\n            left++;\n        }\n        answer = Math.max(answer, right - left + 1);\n    }\n    return answer;\n};","filename":"JavaScript"}'),
