  ('2e29eab5-67ba-7b10-b60e-e6fa3a39ef35', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Given two non-negative integers as strings, return their product as a string. You may not convert them to integers directly."}]}]}}'),
  ('83e49974-257f-7326-a492-ef953a8643bd', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]}'),
  ('afcf5032-b8e7-7e49-b94c-d81b18b23583', 'a4', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Digit "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" of "},{"type":"text","text":"num1","marks":[{"type":"code"}]},{"type":"text","text":" multiplied by digit "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":" of "},{"type":"text","text":"num2","marks":[{"type":"code"}]},{"type":"text","text":" contributes to position "},{"type":"text","text":"i+j+1","marks":[{"type":"code"}]},{"type":"text","text":" in the result array (of size "},{"type":"text","text":"n+m","marks":[{"type":"code"}]},{"type":"text","text":"). Propagate carry leftward to position "},{"type":"text","text":"i+j","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('16473094-288d-756c-ab74-1e5c588e71ca', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"Intuition"}]}'),
  ('a1af297d-c60c-745b-8781-1b7b3634a3c4', 'a6', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Simulate elementary-school long multiplication. Use a result array of size "},{"type":"text","text":"n+m","marks":[{"type":"code"}]},{"type":"text","text":". For each pair of digits at indices "},{"type":"text","text":"(i, j)","marks":[{"type":"code"}]},{"type":"text","text":", add their product to "},{"type":"text","text":"result[i+j+1]","marks":[{"type":"code"}]},{"type":"text","text":" and propagate the carry to "},{"type":"text","text":"result[i+j]","marks":[{"type":"code"}]},{"type":"text","text":". Strip leading zeros at the end."}]}]}}'),
  ('b0474a04-60bf-7828-85fb-2de78989b1a7', 'a7', 'heading', '{"level":1,"content":[{"type":"text","text":"Approach"}]}'),
  ('12e9ce62-52b1-76ac-9960-8c9e54af61c4', 'a8', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"''0''","marks":[{"type":"code"}]},{"type":"text","text":" if either input is "},{"type":"text","text":"''0''","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Allocate "},{"type":"text","text":"result = [0] * (n + m)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nested loops "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"n-1","marks":[{"type":"code"}]},{"type":"text","text":" to 0, "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"m-1","marks":[{"type":"code"}]},{"type":"text","text":" to 0."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"product = int(num1[i]) * int(num2[j])","marks":[{"type":"code"}]},{"type":"text","text":"; add to "},{"type":"text","text":"result[i+j+1]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Carry: "},{"type":"text","text":"result[i+j] += result[i+j+1] // 10","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"result[i+j+1] %= 10","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Strip leading zeros and join digits into a string."}]}]}]}]}}'),
  ('17f94c9f-5d10-7ba1-9f92-90192dc22b28', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]}'),
  ('b4f16eb8-f656-7d91-ab71-115533d7b6f6', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Convert both strings to integers, multiply, return the result as a string. (Violates the problem constraint but useful baseline.)"}]}]}}'),
  ('7ce38399-8a2f-7fe7-a709-e2e4f8b06401', 'aB', 'code', '{"language":"python","code":"class Solution:\n    def multiply(self, num1, num2):\n        return str(int(num1) * int(num2))","filename":"Python"}'),
  ('e2c1e301-47ab-75c1-a252-b0fe6ebfea87', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    string multiply(string num1, string num2) {\n        // C++ has no built-in big integer, so the closest shortcut is\n        // \"num1 * digit, shifted\" for each digit of num2, summed up\n        string total = \"0\";\n\n        for (int j = 0; j < (int)num2.size(); j++) {\n            total = add(total + \"0\", times(num1, num2[j] - ''0''));\n        }\n\n        int start = 0;\n        while (start < (int)total.size() - 1 && total[start] == ''0'') {\n            start++;\n        }\n        return total.substr(start);\n    }\n\nprivate:\n    string times(const string& num, int digit) {\n        string result;\n        int carry = 0;\n        for (int i = num.size() - 1; i >= 0; i--) {\n            int value = (num[i] - ''0'') * digit + carry;\n            result += char(''0'' + value % 10);\n            carry = value / 10;\n        }\n        if (carry) result += char(''0'' + carry);\n        reverse(result.begin(), result.end());\n        return result;\n    }\n\n    string add(const string& a, const string& b) {\n        string result;\n        int i = a.size() - 1, j = b.size() - 1, carry = 0;\n        while (i >= 0 || j >= 0 || carry) {\n            int value = carry;\n            if (i >= 0) value += a[i--] - ''0'';\n            if (j >= 0) value += b[j--] - ''0'';\n            result += char(''0'' + value % 10);\n            carry = value / 10;\n        }\n        reverse(result.begin(), result.end());\n        return result;\n    }\n};","filename":"C++"}'),
  ('c5652a1b-8c91-7c7f-9359-a1e41c991440', 'aD', 'code', '{"language":"java","code":"class Solution {\n    public String multiply(String num1, String num2) {\n        return new java.math.BigInteger(num1)\n            .multiply(new java.math.BigInteger(num2))\n            .toString();\n    }\n}","filename":"Java"}'),
  ('36fb71e1-5a8d-7903-b927-346b860e6fa5', 'aE', 'code', '{"language":"javascript","code":"var multiply = function(num1, num2) {\n    return (BigInt(num1) * BigInt(num2)).toString();\n};","filename":"JavaScript"}'),
  ('9de71132-f9ab-76e3-8233-0a274b485e4c', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n + m) · Space: O(n + m)","marks":[{"type":"bold"}]}]}]}}'),
