  ('010e9125-d3e6-7247-9d9d-39cc88555673', 'aH', 'code', '{"language":"python","code":"class Solution:\n    def multiply(self, num1, num2):\n        if num1 == \"0\" or num2 == \"0\":\n            return \"0\"\n\n        n = len(num1)\n        m = len(num2)\n        result = [0] * (n + m)\n\n        for i in range(n - 1, -1, -1):\n            for j in range(m - 1, -1, -1):\n                product = int(num1[i]) * int(num2[j])\n                pos = i + j + 1\n\n                result[pos] += product\n                result[pos - 1] += result[pos] // 10\n                result[pos] %= 10\n\n        # Strip leading zeros\n        start = 0\n        while start < len(result) - 1 and result[start] == 0:\n            start += 1\n\n        return \"\".join(str(d) for d in result[start:])","filename":"Python"}'),
  ('755a2554-025d-7097-82b4-6f4675be8b12', 'aI', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    string multiply(string num1, string num2) {\n        if (num1 == \"0\" || num2 == \"0\") {\n            return \"0\";\n        }\n\n        int n = num1.size();\n        int m = num2.size();\n        vector<int> result(n + m, 0);\n\n        for (int i = n - 1; i >= 0; i--) {\n            for (int j = m - 1; j >= 0; j--) {\n                int product = (num1[i] - ''0'') * (num2[j] - ''0'');\n                int pos = i + j + 1;\n\n                result[pos] += product;\n                result[pos - 1] += result[pos] / 10;\n                result[pos] %= 10;\n            }\n        }\n\n        // Strip leading zeros\n        int start = 0;\n        while (start < (int)result.size() - 1 && result[start] == 0) {\n            start++;\n        }\n\n        string answer;\n        for (int k = start; k < (int)result.size(); k++) {\n            answer += to_string(result[k]);\n        }\n        return answer;\n    }\n};","filename":"C++"}'),
  ('906b3e24-d2f5-7c80-9ceb-700f15c4366d', 'aJ', 'code', '{"language":"java","code":"class Solution {\n    public String multiply(String num1, String num2) {\n        if (num1.equals(\"0\") || num2.equals(\"0\")) {\n            return \"0\";\n        }\n\n        int n = num1.length();\n        int m = num2.length();\n        int[] result = new int[n + m];\n\n        for (int i = n - 1; i >= 0; i--) {\n            for (int j = m - 1; j >= 0; j--) {\n                int product = (num1.charAt(i) - ''0'') * (num2.charAt(j) - ''0'');\n                int pos = i + j + 1;\n\n                result[pos] += product;\n                result[pos - 1] += result[pos] / 10;\n                result[pos] %= 10;\n            }\n        }\n\n        // Strip leading zeros\n        int start = 0;\n        while (start < result.length - 1 && result[start] == 0) {\n            start++;\n        }\n\n        StringBuilder answer = new StringBuilder();\n        for (int k = start; k < result.length; k++) {\n            answer.append(result[k]);\n        }\n        return answer.toString();\n    }\n}","filename":"Java"}'),
  ('e335eeaa-02bf-730a-aa62-aa65d3351309', 'aK', 'code', '{"language":"javascript","code":"var multiply = function(num1, num2) {\n    if (num1 === \"0\" || num2 === \"0\") {\n        return \"0\";\n    }\n\n    const n = num1.length;\n    const m = num2.length;\n    const result = new Array(n + m).fill(0);\n\n    for (let i = n - 1; i >= 0; i--) {\n        for (let j = m - 1; j >= 0; j--) {\n            const product = Number(num1[i]) * Number(num2[j]);\n            const pos = i + j + 1;\n\n            result[pos] += product;\n            result[pos - 1] += Math.floor(result[pos] / 10);\n            result[pos] %= 10;\n        }\n    }\n\n    // Strip leading zeros\n    let start = 0;\n    while (start < result.length - 1 && result[start] === 0) {\n        start++;\n    }\n\n    return result.slice(start).join(\"\");\n};","filename":"JavaScript"}'),
