SELECT 'f4e952a6-18b5-772d-acb6-f1d479edd443', '5ac6d9f6-c870-7ed3-b613-461f446c6041', 1, 'PUBLISHED', 'Target Sum', '[{"id":"094227f0-1c43-77f2-9dbb-dd4094e3f436","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 494","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/target-sum/"}}]}]}]}},"revision":1},{"id":"ca2e2a48-29fb-7981-bdfb-ac6b91b08d77","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"bd83e31c-f834-7e61-85ae-b239cd9583cc","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Assign "},{"type":"text","text":"+","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"-","marks":[{"type":"code"}]},{"type":"text","text":" to every number in "},{"type":"text","text":"nums","marks":[{"type":"code"}]},{"type":"text","text":" to reach "},{"type":"text","text":"target","marks":[{"type":"code"}]},{"type":"text","text":". Return total ways."}]}]}},"revision":1},{"id":"75c63e07-6a41-7483-bc78-9d5f62bc7837","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"64266fc9-d6de-7c1d-b77c-302cb4784336","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can be converted to a subset sum problem: "},{"type":"text","text":"P - N = target","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"P + N = total","marks":[{"type":"code"}]},{"type":"text","text":" ⇒ "},{"type":"text","text":"P = (total + target) // 2","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"6e36a276-c772-7910-912c-1786db4fa83d","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"3a5f7787-2452-7090-8542-f76ddeb5acd4","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reduce problem to finding subset sum equal to "},{"type":"text","text":"(total + target) // 2","marks":[{"type":"code"}]},{"type":"text","text":" using 0/1 Knapsack 1D DP."}]}]}},"revision":1},{"id":"a606bf6e-146a-79e3-b1ff-ab890afbd269","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"81abc545-f6f5-799f-848c-41cf19ecf4c0","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compute "},{"type":"text","text":"total = sum(nums)","marks":[{"type":"code"}]},{"type":"text","text":". If "},{"type":"text","text":"abs(target) > total","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"(total + target) % 2","marks":[{"type":"code"}]},{"type":"text","text":", return 0."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"subset = (total + target) // 2","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialize "},{"type":"text","text":"dp = [0] * (subset + 1)","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"dp[0] = 1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For "},{"type":"text","text":"num","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"nums","marks":[{"type":"code"}]},{"type":"text","text":": loop "},{"type":"text","text":"current","marks":[{"type":"code"}]},{"type":"text","text":" backward from "},{"type":"text","text":"subset","marks":[{"type":"code"}]},{"type":"text","text":" down to "},{"type":"text","text":"num","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"dp[current] += dp[current - num]","marks":[{"type":"code"}]},{"type":"text","text":". Return "},{"type":"text","text":"dp[subset]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"5e295ab6-a44b-7bcb-91fd-99f4df6bd4a3","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Recursion"}]},"revision":1},{"id":"1de7fcff-898d-7017-95f5-e78853dc980a","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Try adding and subtracting each number recursively."}]}]}},"revision":1},{"id":"1b3fe7cd-3811-7fc0-afde-9614195e8870","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def findTargetSumWays(self, nums, target):\n\n        def dfs(index, total):\n            if index == len(nums):\n                return total == target\n\n            return (\n                dfs(index + 1, total + nums[index])\n                +\n                dfs(index + 1, total - nums[index])\n            )\n\n        return dfs(0, 0)","filename":"Python"},"revision":1},{"id":"3bdbbef4-6d62-7866-979c-3db03a03df58","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int findTargetSumWays(vector<int>& nums, int target) {\n        return dfs(nums, target, 0, 0);\n    }\n\nprivate:\n    int dfs(vector<int>& nums, int target, int index, int total) {\n        if (index == (int)nums.size()) return total == target ? 1 : 0;\n\n        return dfs(nums, target, index + 1, total + nums[index])\n             + dfs(nums, target, index + 1, total - nums[index]);\n    }\n};","filename":"C++"},"revision":1},{"id":"93024dc8-a6d2-7baf-bb24-11076b29b07b","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int findTargetSumWays(int[] nums, int target) {\n        return dfs(nums, target, 0, 0);\n    }\n\n    private int dfs(int[] nums, int target, int index, int total) {\n        if (index == nums.length) return total == target ? 1 : 0;\n\n        return dfs(nums, target, index + 1, total + nums[index])\n             + dfs(nums, target, index + 1, total - nums[index]);\n    }\n}","filename":"Java"},"revision":1},{"id":"14b954a6-7695-796e-9413-47d5faa0debd","type":"code","position":"aE","content":{"language":"javascript","code":"var findTargetSumWays = function(nums, target) {\n    const dfs = (index, total) => {\n        if (index === nums.length) return total === target ? 1 : 0;\n\n        return dfs(index + 1, total + nums[index])\n             + dfs(index + 1, total - nums[index]);\n    };\n\n    return dfs(0, 0);\n};","filename":"JavaScript"},"revision":1},{"id":"b28c19e3-e6fd-7df6-8a4d-4662d5e191cd","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(2^n) · Aux Space: O(n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"88afb67d-4a50-7258-81d0-9b6bd5943bcf","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"1db97168-c712-7721-9abc-48b444ec5dd3","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def findTargetSumWays(self, nums, target):\n\n        memo = {}\n\n        def dfs(index, total):\n            if index == len(nums):\n                return 1 if total == target else 0\n\n            key = (index, total)\n\n            if key in memo:\n                return memo[key]\n\n            memo[key] = (\n                dfs(index + 1, total + nums[index])\n                +\n                dfs(index + 1, total - nums[index])\n            )\n\n            return memo[key]\n\n        return dfs(0, 0)","filename":"Python"},"revision":1},{"id":"14bce4de-35eb-700b-8c23-571477ebc68e","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int findTargetSumWays(vector<int>& nums, int target) {\n        memo.clear();\n        return dfs(nums, target, 0, 0);\n    }\n\nprivate:\n    map<pair<int, int>, int> memo;\n\n    int dfs(vector<int>& nums, int target, int index, int total) {\n        if (index == (int)nums.size()) return total == target ? 1 : 0;\n\n        auto key = make_pair(index, total);\n        auto it = memo.find(key);\n        if (it != memo.end()) return it->second;\n\n        int ways = dfs(nums, target, index + 1, total + nums[index])\n                 + dfs(nums, target, index + 1, total - nums[index]);\n\n        memo[key] = ways;\n        return ways;\n    }\n};","filename":"C++"},"revision":1},{"id":"39c1a828-5a8d-7504-83ff-ee3668a3a2f3","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    private Map<String, Integer> memo;\n\n    public int findTargetSumWays(int[] nums, int target) {\n        memo = new HashMap<>();\n        return dfs(nums, target, 0, 0);\n    }\n\n    private int dfs(int[] nums, int target, int index, int total) {\n        if (index == nums.length) return total == target ? 1 : 0;\n\n        String key = index + \",\" + total;\n        if (memo.containsKey(key)) return memo.get(key);\n\n        int ways = dfs(nums, target, index + 1, total + nums[index])\n                 + dfs(nums, target, index + 1, total - nums[index]);\n\n        memo.put(key, ways);\n        return ways;\n    }\n}","filename":"Java"},"revision":1},{"id":"f5d4ac57-9c2e-76b7-a69c-effa902d6c1f","type":"code","position":"aK","content":{"language":"javascript","code":"var findTargetSumWays = function(nums, target) {\n    const memo = new Map();\n\n    const dfs = (index, total) => {\n        if (index === nums.length) return total === target ? 1 : 0;\n\n        const key = `${index},${total}`;\n        if (memo.has(key)) return memo.get(key);\n\n        const ways = dfs(index + 1, total + nums[index])\n                   + dfs(index + 1, total - nums[index]);\n\n        memo.set(key, ways);\n        return ways;\n    };\n\n    return dfs(0, 0);\n};","filename":"JavaScript"},"revision":1},{"id":"4b57d69a-c4a2-7fc1-a946-94c0ca89a48c","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n × subset) · Space: O(subset)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"03595dc7-9538-7922-98d6-117ec7d86083","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"1d7e232e-e1d4-778a-a325-928f5e56f37c","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Subset Sum Reduction","marks":[{"type":"bold"}]},{"type":"text","text":" — Transform +/- Target Sum into 0/1 Knapsack subset counting."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
