ion:\n    def change(self, amount, coins):\n\n        def dfs(index, remaining):\n            if remaining == 0:\n                return 1\n\n            if index == len(coins) or remaining < 0:\n                return 0\n\n            # Use current coin\n            use = dfs(\n                index,\n                remaining - coins[index]\n            )\n\n            # Skip current coin\n            skip = dfs(\n                index + 1,\n                remaining\n            )\n\n            return use + skip\n\n        return dfs(0, amount)","filename":"Python"},"revision":1},{"id":"0167f06f-d59e-7f46-b660-a8f8cfdd2a5a","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int change(int amount, vector<int>& coins) {\n        return dfs(coins, 0, amount);\n    }\n\nprivate:\n    int dfs(vector<int>& coins, int index, int remaining) {\n        if (remaining == 0) return 1;\n        if (index == (int)coins.size() || remaining < 0) return 0;\n\n        // Use current coin\n        int use = dfs(coins, index, remaining - coins[index]);\n\n        // Skip current coin\n        int skip = dfs(coins, index + 1, remaining);\n\n        return use + skip;\n    }\n};","filename":"C++"},"revision":1},{"id":"d7c52e1d-e662-7513-9da3-8be461d604e2","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int change(int amount, int[] coins) {\n        return dfs(coins, 0, amount);\n    }\n\n    private int dfs(int[] coins, int index, int remaining) {\n        if (remaining == 0) return 1;\n        if (index == coins.length || remaining < 0) return 0;\n\n        // Use current coin\n        int use = dfs(coins, index, remaining - coins[index]);\n\n        // Skip current coin\n        int skip = dfs(coins, index + 1, remaining);\n\n        return use + skip;\n    }\n}","filename":"Java"},"revision":1},{"id":"a8e7b8cf-b532-733e-b5b3-746f1c1f8803","type":"code","position":"aE","content":{"language":"javascript","code":"var change = function(amount, coins) {\n    const dfs = (index, remaining) => {\n        if (remaining === 0) return 1;\n        if (index === coins.length || remaining < 0) return 0;\n\n        // Use current coin\n        const use = dfs(index, remaining - coins[index]);\n\n        // Skip current coin\n        const skip = dfs(index + 1, remaining);\n\n        return use + skip;\n    };\n\n    return dfs(0, amount);\n};","filename":"JavaScript"},"revision":1},{"id":"85bd2952-9a43-7a94-9f53-19f614b84175","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: Exponential · Aux Space: O(amount + n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"3e53845e-0673-7681-82ff-9a78c421888a","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"067f837e-6d82-7f43-9b3a-beff6d22e7f3","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def change(self, amount, coins):\n\n        dp = [0] * (amount + 1)\n        dp[0] = 1\n\n        for coin in coins:\n            for current in range(\n                coin,\n                amount + 1\n            ):\n                dp[current] += dp[current - coin]\n\n        return dp[amount]","filename":"Python"},"revision":1},{"id":"ff5f768a-77e8-78f8-a4d0-ea238c8c1205","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int change(int amount, vector<int>& coins) {\n        // unsigned: unrelated cells may overflow, but dp[amount] always fits\n        vector<unsigned long long> dp(amount + 1, 0);\n        dp[0] = 1;\n\n        for (int coin : coins) {\n            for (int current = coin; current <= amount; current++) {\n                dp[current] += dp[current - coin];\n            }\n        }\n\n        return (int)dp[amount];\n    }\n};","filename":"C++"},"revision":1},{"id":"ccd448a0-5767-7a1d-ab9e-3ab7989ccfb9","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public int change(int amount, int[] coins) {\n        long[] dp = new long[amount + 1];\n        dp[0] = 1;\n\n        for (int coin : coins) {\n            for (int current = coin; current <= amount; current++) {\n                dp[current] += dp[current - coin];\n            }\n        }\n\n        return (int) dp[amount];\n    }\n}","filename":"Java"},"revision":1},{"id":"5a668972-7b1b-70b0-96c2-4cb576c901a7","type":"code","position":"aK","content":{"language":"javascript","code":"var change = function(amount, coins) {\n    const dp = new Array(amount + 1).fill(0);\n    dp[0] = 1;\n\n    for (const coin of coins) {\n        for (let current = coin; current <= amount; current++) {\n            dp[current] += dp[current - coin];\n        }\n    }\n\n    return dp[amount];\n};","filename":"JavaScript"},"revision":1},{"id":"3f3c80da-7469-76c5-8e39-5fe0ef442c58","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(amount × n) · Space: O(amount)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"2325b2e4-830c-728c-a487-6bc234962ed4","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"345a41b3-53de-787a-a89e-c945c25254fd","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unbounded Knapsack Combinations","marks":[{"type":"bold"}]},{"type":"text","text":" — Outer loop over "},{"type":"text","text":"coins","marks":[{"type":"code"}]},{"type":"text","text":", inner loop increasing order over "},{"type":"text","text":"amount","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
