  ('e5855c98-6bf1-7d22-9d37-9bd18f734055', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]}'),
  ('0ee0254e-b00b-7226-8d94-5aa427b93280', 'a4', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Track four boundaries: "},{"type":"text","text":"top","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"bottom","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"left","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"right","marks":[{"type":"code"}]},{"type":"text","text":". Process the outermost ring in four sweeps (→ ↓ ← ↑), then shrink boundaries inward and repeat."}]}]}}'),
