  ('db6d6c0b-c247-7747-91b8-0b5e3406fc0a', 'a8', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialize "},{"type":"text","text":"top=0, bottom=rows-1, left=0, right=cols-1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"While "},{"type":"text","text":"top <= bottom","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"left <= right","marks":[{"type":"code"}]},{"type":"text","text":":"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"→ Append "},{"type":"text","text":"matrix[top][left..right]","marks":[{"type":"code"}]},{"type":"text","text":"; increment "},{"type":"text","text":"top","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"↓ Append "},{"type":"text","text":"matrix[top..bottom][right]","marks":[{"type":"code"}]},{"type":"text","text":"; decrement "},{"type":"text","text":"right","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"← If "},{"type":"text","text":"top <= bottom","marks":[{"type":"code"}]},{"type":"text","text":": append "},{"type":"text","text":"matrix[bottom][right..left]","marks":[{"type":"code"}]},{"type":"text","text":" reversed; decrement "},{"type":"text","text":"bottom","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"↑ If "},{"type":"text","text":"left <= right","marks":[{"type":"code"}]},{"type":"text","text":": append "},{"type":"text","text":"matrix[bottom..top][left]","marks":[{"type":"code"}]},{"type":"text","text":" reversed; increment "},{"type":"text","text":"left","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}}'),
  ('37939f64-a5f2-7836-bb00-17f296afa7ee', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]}'),
  ('a4f0bf66-bb07-7d81-bda5-cc370093d9e4', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use a visited boolean matrix and change direction when hitting a boundary or visited cell."}]}]}}'),
  ('79210d13-06d0-70cf-aff5-a708bdb79531', 'aB', 'code', '{"language":"python","code":"class Solution:\n    def spiralOrder(self, matrix):\n        rows = len(matrix)\n        cols = len(matrix[0])\n        visited = [\n            [False] * cols\n            for _ in range(rows)\n        ]\n        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]\n        result = []\n        r = c = direction = 0\n\n        for _ in range(rows * cols):\n            result.append(matrix[r][c])\n            visited[r][c] = True\n\n            nr = r + directions[direction][0]\n            nc = c + directions[direction][1]\n\n            if (\n                nr < 0 or nr >= rows\n                or nc < 0 or nc >= cols\n                or visited[nr][nc]\n            ):\n                direction = (direction + 1) % 4\n                nr = r + directions[direction][0]\n                nc = c + directions[direction][1]\n\n            r, c = nr, nc\n\n        return result","filename":"Python"}'),
  ('37ab7b1e-61a4-7ce8-8bfb-c5b767281288', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    vector<int> spiralOrder(vector<vector<int>>& matrix) {\n        int rows = matrix.size();\n        int cols = matrix[0].size();\n        vector<vector<bool>> visited(rows, vector<bool>(cols, false));\n        int directions[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};\n        vector<int> result;\n        int r = 0, c = 0, direction = 0;\n\n        for (int step = 0; step < rows * cols; step++) {\n            result.push_back(matrix[r][c]);\n            visited[r][c] = true;\n\n            int nr = r + directions[direction][0];\n            int nc = c + directions[direction][1];\n\n            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || visited[nr][nc]) {\n                direction = (direction + 1) % 4;\n                nr = r + directions[direction][0];\n                nc = c + directions[direction][1];\n            }\n\n            r = nr;\n            c = nc;\n        }\n\n        return result;\n    }\n};","filename":"C++"}'),
  ('507f977a-df18-7db6-b137-37e36dc4f38d', 'aD', 'code', '{"language":"java","code":"class Solution {\n    public List<Integer> spiralOrder(int[][] matrix) {\n        int rows = matrix.length;\n        int cols = matrix[0].length;\n        boolean[][] visited = new boolean[rows][cols];\n        int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};\n        List<Integer> result = new ArrayList<>();\n        int r = 0, c = 0, direction = 0;\n\n        for (int step = 0; step < rows * cols; step++) {\n            result.add(matrix[r][c]);\n            visited[r][c] = true;\n\n            int nr = r + directions[direction][0];\n            int nc = c + directions[direction][1];\n\n            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || visited[nr][nc]) {\n                direction = (direction + 1) % 4;\n                nr = r + directions[direction][0];\n                nc = c + directions[direction][1];\n            }\n\n            r = nr;\n            c = nc;\n        }\n\n        return result;\n    }\n}","filename":"Java"}'),
  ('944b41b9-2083-7dd7-8540-e3a6764540d4', 'aE', 'code', '{"language":"javascript","code":"var spiralOrder = function(matrix) {\n    const rows = matrix.length;\n    const cols = matrix[0].length;\n    const visited = Array.from({ length: rows }, () => new Array(cols).fill(false));\n    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];\n    const result = [];\n    let r = 0, c = 0, direction = 0;\n\n    for (let step = 0; step < rows * cols; step++) {\n        result.push(matrix[r][c]);\n        visited[r][c] = true;\n\n        let nr = r + directions[direction][0];\n        let nc = c + directions[direction][1];\n\n        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || visited[nr][nc]) {\n            direction = (direction + 1) % 4;\n            nr = r + directions[direction][0];\n            nc = c + directions[direction][1];\n        }\n\n        r = nr;\n        c = nc;\n    }\n\n    return result;\n};","filename":"JavaScript"}'),
  ('c1341fce-b8f0-77b4-8f6c-f421c57d5657', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(mn) · Space: O(mn)","marks":[{"type":"bold"}]}]}]}}'),
  ('75470d47-9805-71bb-b45c-af5a9c449731', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]}'),
  ('77777107-8d3b-7a06-b977-4ead7dbbb642', 'aH', 'code', '{"language":"python","code":"class Solution:\n    def spiralOrder(self, matrix):\n        result = []\n        top = 0\n        bottom = len(matrix) - 1\n        left = 0\n        right = len(matrix[0]) - 1\n\n        while top <= bottom and left <= right:\n\n            # Left → Right\n            for c in range(left, right + 1):\n                result.append(matrix[top][c])\n            top += 1\n\n            # Top → Bottom\n            for r in range(top, bottom + 1):\n                result.append(matrix[r][right])\n            right -= 1\n\n            if top <= bottom:\n                # Right → Left\n                for c in range(right, left - 1, -1):\n                    result.append(matrix[bottom][c])\n                bottom -= 1\n\n            if left <= right:\n                # Bottom → Top\n                for r in range(bottom, top - 1, -1):\n                    result.append(matrix[r][left])\n                left += 1\n\n        return result","filename":"Python"}'),
