aversal."}]}]}},"revision":1},{"id":"e31ef0ef-68f7-7e6b-9666-c63a6503f356","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"b7e44db0-b6d5-7ec7-a563-8c61c8112192","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialize "},{"type":"text","text":"diameter = 0","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Define "},{"type":"text","text":"dfs(node)","marks":[{"type":"code"}]},{"type":"text","text":": if node is None return 0."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Get "},{"type":"text","text":"left = dfs(node.left)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"right = dfs(node.right)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Update "},{"type":"text","text":"diameter = max(diameter, left + right)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return node height: "},{"type":"text","text":"1 + max(left, right)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"f114c9fc-aeb3-771e-b51f-6c15529425a2","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution"}]},"revision":1},{"id":"a8340dc0-c67b-7cb7-be00-60785e4424c9","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For every node, separately calculate the height of its left and right subtree."}]}]}},"revision":1},{"id":"2b866650-8a3a-7c2e-90fa-a4a4d1be53c1","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def diameterOfBinaryTree(self, root):\n\n        def height(node):\n            if not node:\n                return 0\n\n            return 1 + max(\n                height(node.left),\n                height(node.right)\n            )\n\n        if not root:\n            return 0\n\n        left_diameter = self.diameterOfBinaryTree(root.left)\n        right_diameter = self.diameterOfBinaryTree(root.right)\n\n        current = height(root.left) + height(root.right)\n\n        return max(current, left_diameter, right_diameter)","filename":"Python"},"revision":1},{"id":"cc873bcd-e5bd-7371-964c-8d0bf6abed54","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int diameterOfBinaryTree(TreeNode* root) {\n        if (!root) return 0;\n\n        int leftDiameter = diameterOfBinaryTree(root->left);\n        int rightDiameter = diameterOfBinaryTree(root->right);\n\n        int current = height(root->left) + height(root->right);\n\n        return max({current, leftDiameter, rightDiameter});\n    }\n\nprivate:\n    int height(TreeNode* node) {\n        if (!node) return 0;\n        return 1 + max(height(node->left), height(node->right));\n    }\n};","filename":"C++"},"revision":1},{"id":"4a694ec3-896d-78a7-9deb-91234764a162","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int diameterOfBinaryTree(TreeNode root) {\n        if (root == null) return 0;\n\n        int leftDiameter = diameterOfBinaryTree(root.left);\n        int rightDiameter = diameterOfBinaryTree(root.right);\n\n        int current = height(root.left) + height(root.right);\n\n        return Math.max(current, Math.max(leftDiameter, rightDiameter));\n    }\n\n    private int height(TreeNode node) {\n        if (node == null) return 0;\n        return 1 + Math.max(height(node.left), height(node.right));\n    }\n}","filename":"Java"},"revision":1},{"id":"b7a1bd96-c892-7e84-82f2-15e554138264","type":"code","position":"aE","content":{"language":"javascript","code":"var diameterOfBinaryTree = function(root) {\n    const height = (node) => {\n        if (!node) return 0;\n        return 1 + Math.max(height(node.left), height(node.right));\n    };\n\n    if (!root) return 0;\n\n    const leftDiameter = diameterOfBinaryTree(root.left);\n    const rightDiameter = diameterOfBinaryTree(root.right);\n\n    const current = height(root.left) + height(root.right);\n\n    return Math.max(current, leftDiameter, rightDiameter);\n};","filename":"JavaScript"},"revision":1},{"id":"5d7c92e4-5026-7d73-8cc3-4cc4cb29effe","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n^2) worst case · Aux Space: O(h)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"f8b63aa9-0e6e-78f5-9e75-89478abf9db3","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"d2ac2199-2e77-7956-89aa-2ac7b3680ecb","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def diameterOfBinaryTree(self, root):\n        diameter = 0\n\n        def dfs(node):\n            nonlocal diameter\n\n            if not node:\n                return 0\n\n            left = dfs(node.left)\n            right = dfs(node.right)\n\n            diameter = max(diameter, left + right)\n\n            return 1 + max(left, right)\n\n        dfs(root)\n        return diameter","filename":"Python"},"revision":1},{"id":"e220bc82-f657-7609-bae2-e822ac31a417","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int diameterOfBinaryTree(TreeNode* root) {\n        int diameter = 0;\n        dfs(root, diameter);\n        return diameter;\n    }\n\nprivate:\n    int dfs(TreeNode* node, int& diameter) {\n        if (!node) return 0;\n\n        int left = dfs(node->left, diameter);\n        int right = dfs(node->right, diameter);\n\n        diameter = max(diameter, left + right);\n\n        return 1 + max(left, right);\n    }\n};","filename":"C++"},"revision":1},{"id":"1b7d9691-a727-75b3-bc94-10d0c5cc4448","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    private int diameter = 0;\n\n    public int diameterOfBinaryTree(TreeNode root) {\n        diameter = 0;\n        dfs(root);\n        return diameter;\n    }\n\n    private int dfs(TreeNode node) {\n        if (node == null) return 0;\n\n        int left = dfs(node.left);\n        int right = dfs(node.right);\n\n        diameter = Math.max(diameter, left + right);\n\n        return 1 + Math.max(left, right);\n    }\n}","filename":"Java"},"revision":1},{"id":"4457eb08-0852-711a-8903-fc83bd1f25b5","type":"code","position":"aK","content":{"language":"javascript","code":"var diameterOfBinaryTree = function(root) {\n    let diameter = 0;\n\n    const dfs = (node) => {\n        if (!node) return 0;\n\n        const left = dfs(node.left);\n        const right = dfs(node.right);\n\n        diameter = Math.max(diameter, left + right);\n\n        return 1 + Math.max(left, right);\n    };\n\n    dfs(root);\n    return diameter;\n};","filename":"JavaScript"},"revision":1},{"id":"d25e351f-92cf-76cc-95b7-932f66807a07","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Aux Space: O(h)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"71324b60-c1ee-7544-8484-6cc10962e1e7","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"f7b71b77-e3b0-7798-9398-3066eaf06093","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern:","marks":[{"type":"bold"}]},{"type":"text","text":" Postorder DFS + return useful information upward. This pattern is extremely important."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
