SELECT '708f8121-d38d-7627-a2b6-f44eebd6affc', '83e2b6e2-a30f-7a84-8285-37733ed5011b', 1, 'PUBLISHED', 'Merge Intervals', '[{"id":"44abf31f-7bb5-7d50-9d00-159e8d36493b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 56","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/merge-intervals/"}}]}]}]}},"revision":1},{"id":"0974e9d8-f036-736f-bf51-d5f19c6e70d0","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"700c6cfa-305c-7311-9489-a4df3d75fe23","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Given an array of intervals, merge all overlapping intervals and return the resulting array."}]}]}},"revision":1},{"id":"1b155448-5a4b-79e7-b297-ebc082e04128","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"76111020-d9c5-7874-b460-0ec3ceecccf3","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Once intervals are sorted by start time, any overlap can only occur with the previous interval in the result list. A single left-to-right scan is sufficient."}]}]}},"revision":1},{"id":"9ed6e98a-f768-7344-ba88-85f638509005","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"0c29feab-a1fb-742b-8da2-d0172799bd49","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sort by start time. After sorting, overlapping intervals must be adjacent. Walk once: if the current interval''s start is within the last result interval''s end, extend; otherwise append fresh."}]}]}},"revision":1},{"id":"61266465-4c96-7a36-8230-0b6dbb7c3f44","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"5ac95fa0-153b-740d-8db1-487c44ffd099","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sort "},{"type":"text","text":"intervals","marks":[{"type":"code"}]},{"type":"text","text":" by start time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialize "},{"type":"text","text":"result = []","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For each "},{"type":"text","text":"[start, end]","marks":[{"type":"code"}]},{"type":"text","text":": if result is empty or "},{"type":"text","text":"start > result[-1][1]","marks":[{"type":"code"}]},{"type":"text","text":", append "},{"type":"text","text":"[start, end]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Otherwise: "},{"type":"text","text":"result[-1][1] = max(result[-1][1], end)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"result","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"ee1292b2-e67c-78c3-96a7-90ff5923b0c2","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]},"revision":1},{"id":"dd8da405-311e-7128-b1ee-0dbce4089790","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Repeatedly scan for any overlapping pair and merge them until no overlaps remain."}]}]}},"revision":1},{"id":"fb282032-e9ed-7d25-b407-c845578e3411","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def merge(self, intervals):\n        intervals = [x[:] for x in intervals]\n        changed = True\n\n        while changed:\n            changed = False\n            result = []\n            used = [False] * len(intervals)\n\n            for i in range(len(intervals)):\n                if used[i]:\n                    continue\n\n                current = intervals[i]\n\n                for j in range(i + 1, len(intervals)):\n                    if used[j]:\n                        continue\n\n                    other = intervals[j]\n\n                    if (\n                        current[0] <= other[1]\n                        and other[0] <= current[1]\n                    ):\n                        current = [\n                            min(current[0], other[0]),\n                            max(current[1], other[1]),\n                        ]\n                        used[j] = True\n                        changed = True\n\n                result.append(current)\n\n            intervals = result\n\n        return intervals","filename":"Python"},"revision":1},{"id":"4c6ea7a5-1af4-7aec-b8ca-1a09520068ea","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    vector<vector<int>> merge(vector<vector<int>>& input) {\n        vector<vector<int>> intervals = input;\n        bool changed = true;\n\n        while (changed) {\n            changed = false;\n            vector<vector<int>> result;\n            vector<bool> used(intervals.size(), false);\n\n            for (int i = 0; i < (int)intervals.size(); i++) {\n                if (used[i]) continue;\n\n                vector<int> current = intervals[i];\n\n                for (int j = i + 1; j < (int)intervals.size(); j++) {\n                    if (used[j]) continue;\n\n                    vector<int>& other = intervals[j];\n\n                    if (current[0] <= other[1] && other[0] <= current[1]) {\n                        current = {\n                            min(current[0], other[0]),\n                            max(current[1], other[1]),\n                        };\n                        used[j] = true;\n                        changed = true;\n                    }\n                }\n\n                result.push_back(current);\n            }\n\n            intervals = result;\n        }\n\n        return intervals;\n    }\n};","filename":"C++"},"revision":1},{"id":"eb7610af-f97e-7568-9346-a4d4d92f5f5d","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int[][] merge(int[][] input) {\n        List<int[]> intervals = new ArrayList<>();\n        for (int[] interval : input) intervals.add(interval.clone());\n\n        boolean changed = true;\n\n        while (changed) {\n            changed = false;\n            List<int[]> result = new ArrayList<>();\n            boolean[] used = new boolean[intervals.size()];\n\n            for (int i = 0; i < intervals.size(); i++) {\n                if (used[i]) continue;\n\n                int[] current = intervals.get(i);\n\n                for (int j = i + 1; j < intervals.size(); j++) {\n                    if (used[j]) continue;\n\n                    int[] other = intervals.get(j);\n\n                    if (current[0] <= other[1] && other[0] <= current[1]) {\n                        current = new int[]{\n                            Math.min(current[0], other[0]),\n                            Math.max(current[1], other[1]),\n                        };\n                        used[j] = true;\n                        changed = true;\n                    }\n                }\n\n                result.add(current);\n            }\n\n            intervals = result;\n        }\n\n        return intervals.toArray(new int[0][]);\n    }\n}","filename":"Java"},"revision":1},{"id":"39788e06-c241-781e-b314-bba72e0867e3","type":"code","position":"aE","content":{"language":"javascript","code":"var merge = function(input) {\n    let intervals = input.map((x) => [...x]);\n    let changed = true;\n\n    while (changed) {\n        changed = false;\n        const result = [];\n        const used = new Array(intervals.length).fill(false);\n\n        for (let i = 0; i < intervals.length; i++) {\n            if (used[i]) continue;\n\n            let current = intervals[i];\n\n            for (let j = i + 1; j < intervals.length; j++) {\n                if (used[j]) continue;\n\n                const other = intervals[j];\n\n                if (current[0] <= other[1] && other[0] <= current[1]) {\n                    current = [\n                        Math.min(current[0], other[0]),\n                        Math.max(current[1], other[1]),\n                    ];\n                    used[j] = true;\n                    changed = true;\n                }\n            }\n\n            result.push(current);\n        }\n\n        intervals = result;\n    }\n\n    return intervals;\n};","filename":"JavaScript"},"revision":1},{"id":"d692f57e-6fbb-7116-9450-53bfbca25754","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n²) worst case · Space: O(n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"c86eb8c4-0b8f-721b-9aad-7c5a183213d2","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"af146daa-0333-7174-aa2d-265b4d3f34df","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def merge(self, intervals):\n        intervals.sort()\n        result = []\n\n        for start, end in intervals:\n            if not result or start > result[-1][1]:\n                result.append([start, end])\n            else:\n                result[-1][1] = max(result[-1][1], end)\n\n        return result","filename":"Python"},"revision":1},{"id":"334d0463-7caf-7205-bd57-115c4041b174","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    vector<vector<int>> merge(vector<vector<int>>& intervals) {\n        sort(intervals.begin(), intervals.end());\n        vector<vector<int>> result;\n\n        for (auto& interval : intervals) {\n            int start = interval[0], end = interval[1];\n\n            if (result.empty() || start > result.back()[1]) {\n                result.push_back({start, end});\n            } else {\n                result.back()[1] = max(result.back()[1], end);\n            }\n        }\n\n        return result;\n    }\n};","filename":"C++"},"revision":1},{"id":"56998195-84f7-75ca-ad63-0acde594c613","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public int[][] merge(int[][] intervals) {\n        Arrays.sort(intervals, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));\n        List<int[]> result = new ArrayList<>();\n\n        for (int[] interval : intervals) {\n            int start = interval[0], end = interval[1];\n\n            if (result.isEmpty() || start > result.get(result.size() - 1)[1]) {\n                result.add(new int[]{start, end});\n            } else {\n                int[] last = result.get(result.size() - 1);\n                last[1] = Math.max(last[1], end);\n            }\n        }\n\n        return result.toArray(new int[0][]);\n    }\n}","filename":"Java"},"revision":1},{"id":"d044a944-d4df-788b-978e-1b2c43a21fe7","type":"code","position":"aK","content":{"language":"javascript","code":"var merge = function(intervals) {\n    intervals.sort((a, b) => a[0] - b[0] || a[1] - b[1]);\n    const result = [];\n\n    for (const [start, end] of intervals) {\n        if (!result.length || start > result[result.length - 1][1]) {\n            result.push([start, end]);\n        } else {\n            const last = result[result.length - 1];\n            last[1] = Math.max(last[1], end);\n        }\n    }\n\n    return result;\n};","filename":"JavaScript"},"revision":1},{"id":"16a127bc-9fb3-7ba7-b5e5-a71810e41926","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n log n) · Space: O(n) output","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"056c2f5e-6700-7c5c-a7ce-be049b62a5a1","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"a6c84f0d-dfcf-78c4-89f8-7c3015d38c0f","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Sort by start → compare current start with previous end"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
