  ('a6c84f0d-dfcf-78c4-89f8-7c3015d38c0f', 'aN', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Sort by start → compare current start with previous end"}]}]}}')
