class Solution:
    def checkInclusion(self, s1, s2):
        if len(s1) > len(s2):
            return False

        target = [0] * 26
        window = [0] * 26

        for char in s1:
            target[
                ord(char) - ord(''a'')
            ] += 1

        for i in range(len(s2)):
            window[
                ord(s2[i]) - ord(''a'')
            ] += 1

            if i >= len(s1):
                window[
                    ord(s2[i - len(s1)]) - ord(''a'')
                ] -= 1

            if window == target:
                return True

        return False
