SELECT '88687d85-08af-7f9c-8c23-2acac27111fb', '8dec50d9-ea14-7d55-88cf-28491b5f9809', 1, 'PUBLISHED', 'Unique Paths', '[{"id":"4e8534fa-c63a-738a-b57e-57c687bb98aa","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 62","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/unique-paths/"}}]}]}]}},"revision":1},{"id":"2048fb2a-05e1-724d-9221-f780cb02b787","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"ec38034b-5db6-76a1-b00b-431e2627fe7e","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Robot at "},{"type":"text","text":"(0,0)","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"m x n","marks":[{"type":"code"}]},{"type":"text","text":" grid wants to move to "},{"type":"text","text":"(m-1, n-1)","marks":[{"type":"code"}]},{"type":"text","text":". Can only move down or right. Return total unique paths."}]}]}},"revision":1},{"id":"524313c2-ef5d-783b-9922-5b72d0e8b0d4","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"1c916fec-1208-74f7-bfea-f6c1d9186e59","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To reach cell "},{"type":"text","text":"(r, c)","marks":[{"type":"code"}]},{"type":"text","text":", you can arrive from top "},{"type":"text","text":"(r-1, c)","marks":[{"type":"code"}]},{"type":"text","text":" or left "},{"type":"text","text":"(r, c-1)","marks":[{"type":"code"}]},{"type":"text","text":". Thus "},{"type":"text","text":"dp[r][c] = dp[r-1][c] + dp[r][c-1]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"933f7818-2268-7d48-ac60-3dd9677c4f88","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"52036daf-9dea-78a3-8de2-ae601aaf2fc3","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill 2D grid bottom-up or optimize space to 1D row array of size "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"b4a42b62-7a49-747b-a995-1017bb76d7e9","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"f2fac2f7-cd8c-7071-93da-7e142e809370","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialize "},{"type":"text","text":"dp = [1] * n","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Loop "},{"type":"text","text":"m-1","marks":[{"type":"code"}]},{"type":"text","text":" times: for "},{"type":"text","text":"c","marks":[{"type":"code"}]},{"type":"text","text":" from 1 to "},{"type":"text","text":"n-1","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"dp[c] += dp[c-1]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"dp[-1]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"6eb37336-28eb-76a5-b0e3-6cafa1c9f91d","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Recursion"}]},"revision":1},{"id":"9b68789b-364d-78e2-bc06-eb210c532381","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"At every cell, recursively branch right and down until reaching bottom-right corner."}]}]}},"revision":1},{"id":"0e680ab7-cc08-7c91-b6e2-c938b150d2bf","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def uniquePaths(self, m, n):\n\n        def dfs(r, c):\n            if r == m - 1 and c == n - 1:\n                return 1\n\n            if r >= m or c >= n:\n                return 0\n\n            return (\n                dfs(r + 1, c)\n                +\n                dfs(r, c + 1)\n            )\n\n        return dfs(0, 0)","filename":"Python"},"revision":1},{"id":"9bdaed37-dc58-7147-b270-26d83742d441","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int uniquePaths(int m, int n) {\n        return dfs(0, 0, m, n);\n    }\n\nprivate:\n    int dfs(int r, int c, int m, int n) {\n        if (r == m - 1 && c == n - 1) return 1;\n        if (r >= m || c >= n) return 0;\n\n        return dfs(r + 1, c, m, n) + dfs(r, c + 1, m, n);\n    }\n};","filename":"C++"},"revision":1},{"id":"a0bdb893-2be8-7e12-89c0-d1f72574d960","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int uniquePaths(int m, int n) {\n        return dfs(0, 0, m, n);\n    }\n\n    private int dfs(int r, int c, int m, int n) {\n        if (r == m - 1 && c == n - 1) return 1;\n        if (r >= m || c >= n) return 0;\n\n        return dfs(r + 1, c, m, n) + dfs(r, c + 1, m, n);\n    }\n}","filename":"Java"},"revision":1},{"id":"ec22718d-1f7d-7b48-afa2-20c2b0781f36","type":"code","position":"aE","content":{"language":"javascript","code":"var uniquePaths = function(m, n) {\n    const dfs = (r, c) => {\n        if (r === m - 1 && c === n - 1) return 1;\n        if (r >= m || c >= n) return 0;\n\n        return dfs(r + 1, c) + dfs(r, c + 1);\n    };\n\n    return dfs(0, 0);\n};","filename":"JavaScript"},"revision":1},{"id":"e852892f-fc51-7bfa-865f-7edb0cbc5950","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(2^(m+n)) · Aux Space: O(m+n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"e90d12c2-fada-70e7-a87f-92896d30b20f","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"613b251f-bbd3-7f7f-8cc9-bb53bffea276","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def uniquePaths(self, m, n):\n\n        dp = [[0] * n for _ in range(m)]\n\n        for r in range(m):\n            dp[r][0] = 1\n\n        for c in range(n):\n            dp[0][c] = 1\n\n        for r in range(1, m):\n            for c in range(1, n):\n                dp[r][c] = (\n                    dp[r - 1][c]\n                    +\n                    dp[r][c - 1]\n                )\n\n        return dp[m - 1][n - 1]","filename":"Python"},"revision":1},{"id":"0e959514-c9e3-7a77-86d5-37f254b5c367","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int uniquePaths(int m, int n) {\n        vector<vector<int>> dp(m, vector<int>(n, 0));\n\n        for (int r = 0; r < m; r++) dp[r][0] = 1;\n        for (int c = 0; c < n; c++) dp[0][c] = 1;\n\n        for (int r = 1; r < m; r++) {\n            for (int c = 1; c < n; c++) {\n                dp[r][c] = dp[r - 1][c] + dp[r][c - 1];\n            }\n        }\n\n        return dp[m - 1][n - 1];\n    }\n};","filename":"C++"},"revision":1},{"id":"195bb7f2-e35b-7c69-b8de-abdfe2e5bf87","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public int uniquePaths(int m, int n) {\n        int[][] dp = new int[m][n];\n\n        for (int r = 0; r < m; r++) dp[r][0] = 1;\n        for (int c = 0; c < n; c++) dp[0][c] = 1;\n\n        for (int r = 1; r < m; r++) {\n            for (int c = 1; c < n; c++) {\n                dp[r][c] = dp[r - 1][c] + dp[r][c - 1];\n            }\n        }\n\n        return dp[m - 1][n - 1];\n    }\n}","filename":"Java"},"revision":1},{"id":"adf961da-0cbf-775a-9e1c-3e0b6fce4435","type":"code","position":"aK","content":{"language":"javascript","code":"var uniquePaths = function(m, n) {\n    const dp = Array.from({ length: m }, () => new Array(n).fill(0));\n\n    for (let r = 0; r < m; r++) dp[r][0] = 1;\n    for (let c = 0; c < n; c++) dp[0][c] = 1;\n\n    for (let r = 1; r < m; r++) {\n        for (let c = 1; c < n; c++) {\n            dp[r][c] = dp[r - 1][c] + dp[r][c - 1];\n        }\n    }\n\n    return dp[m - 1][n - 1];\n};","filename":"JavaScript"},"revision":1},{"id":"4829bf0f-c7d7-7b06-9855-6cb25b7e7eef","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(mn) · Space: O(n) (Space Optimized) / O(mn) (2D Grid)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"d0f05066-a0a5-7ada-969f-f0b2a2be8121","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"da5d0b2f-8802-7035-ae5d-5ce9e878508b","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grid DP","marks":[{"type":"bold"}]},{"type":"text","text":" — Each cell transitions from top and left adjacent neighbors."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
