SELECT '3df37cdc-db30-7a61-93cf-b7f80aa458cc', '5bbd8a4c-88c0-7406-85d8-2fbc62938478', 1, 'PUBLISHED', 'Task Scheduler', '[{"id":"c2216f4e-8266-7bf2-a857-8d1cd9bb556e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 621","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/task-scheduler/"}}]}]}]}},"revision":1},{"id":"ce31f33b-9765-7d86-9ba8-218aafb5498a","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"b499da8e-8d9b-74ae-b518-37b7474209c5","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Given CPU tasks represented by letters and cooldown "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" between identical tasks, return minimum CPU units of time to finish all tasks."}]}]}},"revision":1},{"id":"42af09d2-2b60-791e-8409-127d38c4745f","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"957bbe4c-55c2-7081-bfd3-d180e78a5f1f","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prioritize tasks with highest remaining frequency to minimize idle CPU slots."}]}]}},"revision":1},{"id":"4c320bcc-9d78-787a-914c-95271cfb8eb0","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"07757fb4-72ec-7d61-830b-241f6508db67","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Max Heap stores available task frequencies; Dequeue stores tasks in cooldown "},{"type":"text","text":"(freq, available_time)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"f1c93343-a61c-76d9-bbbd-236bbb3df329","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"538b908b-8761-7bb8-a680-7e197a58f15b","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Count frequencies using "},{"type":"text","text":"Counter(tasks)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Push negated frequencies into max heap."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use a queue "},{"type":"text","text":"cooldown = deque()","marks":[{"type":"code"}]},{"type":"text","text":" storing "},{"type":"text","text":"(remaining_freq, ready_time)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Increment "},{"type":"text","text":"time","marks":[{"type":"code"}]},{"type":"text","text":". Re-add ready tasks from queue to max heap."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pop most frequent task, decrement frequency, and push to "},{"type":"text","text":"cooldown","marks":[{"type":"code"}]},{"type":"text","text":" queue with "},{"type":"text","text":"ready_time = time + n + 1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"836d0459-483d-7c1d-ae0d-b0cdf4ad75ca","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]},"revision":1},{"id":"73678e9a-869a-7ef0-a609-0ccdf7d52c08","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Simulate CPU cycles by re-sorting task frequency count every round."}]}]}},"revision":1},{"id":"1088d052-ab0f-74b6-a564-8560f4107680","type":"code","position":"aB","content":{"language":"python","code":"from collections import Counter\n\nclass Solution:\n    def leastInterval(self, tasks, n):\n\n        count = Counter(tasks)\n        time = 0\n\n        while count:\n\n            executed = 0\n\n            # Sort by frequency each round\n            available = sorted(\n                count,\n                key=count.get,\n                reverse=True\n            )\n\n            for task in available[:n + 1]:\n\n                if task in count:\n                    count[task] -= 1\n                    executed += 1\n\n                    if count[task] == 0:\n                        del count[task]\n\n            if count:\n                time += n + 1\n            else:\n                time += executed\n\n        return time","filename":"Python"},"revision":1},{"id":"72de7aa6-690a-798d-ad0b-10d3f242c9d9","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int leastInterval(vector<char>& tasks, int n) {\n        unordered_map<char, int> count;\n        for (char task : tasks) count[task]++;\n\n        int time = 0;\n\n        while (!count.empty()) {\n            int executed = 0;\n\n            // Sort by frequency each round\n            vector<char> available;\n            for (auto& [task, freq] : count) available.push_back(task);\n            sort(available.begin(), available.end(), [&](char a, char b) {\n                return count[a] > count[b];\n            });\n\n            for (int i = 0; i < (int)available.size() && i < n + 1; i++) {\n                char task = available[i];\n                count[task]--;\n                executed++;\n\n                if (count[task] == 0) count.erase(task);\n            }\n\n            if (!count.empty()) time += n + 1;\n            else time += executed;\n        }\n\n        return time;\n    }\n};","filename":"C++"},"revision":1},{"id":"d3a15934-8d17-76ef-82ce-d2dd0d9c2e6c","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int leastInterval(char[] tasks, int n) {\n        Map<Character, Integer> count = new HashMap<>();\n        for (char task : tasks) count.merge(task, 1, Integer::sum);\n\n        int time = 0;\n\n        while (!count.isEmpty()) {\n            int executed = 0;\n\n            // Sort by frequency each round\n            List<Character> available = new ArrayList<>(count.keySet());\n            available.sort((a, b) -> Integer.compare(count.get(b), count.get(a)));\n\n            for (int i = 0; i < available.size() && i < n + 1; i++) {\n                char task = available.get(i);\n                int freq = count.get(task) - 1;\n                executed++;\n\n                if (freq == 0) count.remove(task);\n                else count.put(task, freq);\n            }\n\n            if (!count.isEmpty()) time += n + 1;\n            else time += executed;\n        }\n\n        return time;\n    }\n}","filename":"Java"},"revision":1},{"id":"eddc2cff-69ee-72c1-a967-8dcdb4d2fb12","type":"code","position":"aE","content":{"language":"javascript","code":"var leastInterval = function(tasks, n) {\n    const count = new Map();\n    for (const task of tasks) count.set(task, (count.get(task) || 0) + 1);\n\n    let time = 0;\n\n    while (count.size > 0) {\n        let executed = 0;\n\n        // Sort by frequency each round\n        const available = [...count.keys()].sort((a, b) => count.get(b) - count.get(a));\n\n        for (const task of available.slice(0, n + 1)) {\n            count.set(task, count.get(task) - 1);\n            executed++;\n\n            if (count.get(task) === 0) count.delete(task);\n        }\n\n        if (count.size > 0) time += n + 1;\n        else time += executed;\n    }\n\n    return time;\n};","filename":"JavaScript"},"revision":1},{"id":"7573e22f-5087-7e33-a73b-fdc5bdd612bc","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(T × m log m) · Space: O(m)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"88ac5cea-55fc-79e5-ab49-2ea54016fc31","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"a12500cf-33c1-7094-afc3-8ab466b177da","type":"code","position":"aH","content":{"language":"python","code":"import heapq\nfrom collections import Counter, deque\n\nclass Solution:\n    def leastInterval(self, tasks, n):\n\n        count = Counter(tasks)\n\n        heap = [\n            -freq\n            for freq in count.values()\n        ]\n\n        heapq.heapify(heap)\n\n        cooldown = deque()\n\n        time = 0\n\n        while heap or cooldown:\n            time += 1\n\n            # Add tasks whose cooldown is over\n            while (\n                cooldown\n                and cooldown[0][1] == time\n            ):\n                freq, _ = cooldown.popleft()\n                heapq.heappush(heap, freq)\n\n            if heap:\n                freq = heapq.heappop(heap)\n                freq += 1\n\n                if freq != 0:\n                    cooldown.append(\n                        (freq, time + n + 1)\n                    )\n\n        return time","filename":"Python"},"revision":1},{"id":"12f21052-91f7-7ad7-8131-7f0129565da9","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int leastInterval(vector<char>& tasks, int n) {\n        unordered_map<char, int> count;\n        for (char task : tasks) count[task]++;\n\n        priority_queue<int> heap;  // max-heap of remaining counts\n        for (auto& [task, freq] : count) heap.push(freq);\n\n        queue<pair<int, int>> cooldown;  // {remaining, time it becomes available}\n\n        int time = 0;\n\n        while (!heap.empty() || !cooldown.empty()) {\n            time++;\n\n            // Add tasks whose cooldown is over\n            while (!cooldown.empty() && cooldown.front().second == time) {\n                heap.push(cooldown.front().first);\n                cooldown.pop();\n            }\n\n            if (!heap.empty()) {\n                int freq = heap.top() - 1;\n                heap.pop();\n\n                if (freq != 0) cooldown.push({freq, time + n + 1});\n            }\n        }\n\n        return time;\n    }\n};","filename":"C++"},"revision":1},{"id":"6cf69215-6d3a-7f74-9005-2e0445d569c9","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public int leastInterval(char[] tasks, int n) {\n        Map<Character, Integer> count = new HashMap<>();\n        for (char task : tasks) count.merge(task, 1, Integer::sum);\n\n        // max-heap of remaining counts\n        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());\n        heap.addAll(count.values());\n\n        Deque<int[]> cooldown = new ArrayDeque<>();  // {remaining, time it becomes available}\n\n        int time = 0;\n\n        while (!heap.isEmpty() || !cooldown.isEmpty()) {\n            time++;\n\n            // Add tasks whose cooldown is over\n            while (!cooldown.isEmpty() && cooldown.peekFirst()[1] == time) {\n                heap.offer(cooldown.pollFirst()[0]);\n            }\n\n            if (!heap.isEmpty()) {\n                int freq = heap.poll() - 1;\n\n                if (freq != 0) cooldown.offerLast(new int[]{freq, time + n + 1});\n            }\n        }\n\n        return time;\n    }\n}","filename":"Java"},"revision":1},{"id":"adf68205-8b8d-7c7a-ac0b-65b5925387c5","type":"code","position":"aK","content":{"language":"javascript","code":"class MinHeap {\n    constructor(compare = (a, b) => a - b, items = []) {\n        this.compare = compare;\n        this.data = items;\n        for (let i = (items.length >> 1) - 1; i >= 0; i--) this.siftDown(i);\n    }\n\n    size() { return this.data.length; }\n\n    peek() { return this.data[0]; }\n\n    push(value) {\n        const data = this.data;\n        data.push(value);\n        let i = data.length - 1;\n        while (i > 0) {\n            const parent = (i - 1) >> 1;\n            if (this.compare(data[i], data[parent]) >= 0) break;\n            [data[i], data[parent]] = [data[parent], data[i]];\n            i = parent;\n        }\n    }\n\n    pop() {\n        const data = this.data;\n        const top = data[0];\n        const last = data.pop();\n        if (data.length > 0) {\n            data[0] = last;\n            this.siftDown(0);\n        }\n        return top;\n    }\n\n    siftDown(i) {\n        const data = this.data;\n        while (true) {\n            const left = 2 * i + 1, right = left + 1;\n            let smallest = i;\n            if (left < data.length && this.compare(data[left], data[smallest]) < 0) smallest = left;\n            if (right < data.length && this.compare(data[right], data[smallest]) < 0) smallest = right;\n            if (smallest === i) return;\n            [data[i], data[smallest]] = [data[smallest], data[i]];\n            i = smallest;\n        }\n    }\n}\n\nvar leastInterval = function(tasks, n) {\n    const count = new Map();\n    for (const task of tasks) count.set(task, (count.get(task) || 0) + 1);\n\n    const heap = new MinHeap((a, b) => b - a, [...count.values()]);  // max-heap\n\n    const cooldown = [];  // [remaining, time it becomes available]\n    let head = 0;\n\n    let time = 0;\n\n    while (heap.size() > 0 || head < cooldown.length) {\n        time++;\n\n        // Add tasks whose cooldown is over\n        while (head < cooldown.length && cooldown[head][1] === time) {\n            heap.push(cooldown[head][0]);\n            head++;\n        }\n\n        if (heap.size() > 0) {\n            const freq = heap.pop() - 1;\n\n            if (freq !== 0) cooldown.push([freq, time + n + 1]);\n        }\n    }\n\n    return time;\n};","filename":"JavaScript"},"revision":1},{"id":"af10d59c-ec0d-7265-a2bb-47dceaa68a69","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(T log m) · Space: O(m)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"b74e0ba1-814f-76d3-9203-3687328ee6a1","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"68859f49-709f-7cf5-9390-f5c3e2cce12e","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Frequency + Max Heap + Cooldown Queue"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
