  ('73678e9a-869a-7ef0-a609-0ccdf7d52c08', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Simulate CPU cycles by re-sorting task frequency count every round."}]}]}}'),
  ('1088d052-ab0f-74b6-a564-8560f4107680', 'aB', 'code', '{"language":"python","code":"from collections import Counter\n\nclass Solution:\n    def leastInterval(self, tasks, n):\n\n        count = Counter(tasks)\n        time = 0\n\n        while count:\n\n            executed = 0\n\n            # Sort by frequency each round\n            available = sorted(\n                count,\n                key=count.get,\n                reverse=True\n            )\n\n            for task in available[:n + 1]:\n\n                if task in count:\n                    count[task] -= 1\n                    executed += 1\n\n                    if count[task] == 0:\n                        del count[task]\n\n            if count:\n                time += n + 1\n            else:\n                time += executed\n\n        return time","filename":"Python"}'),
  ('72de7aa6-690a-798d-ad0b-10d3f242c9d9', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    int leastInterval(vector<char>& tasks, int n) {\n        unordered_map<char, int> count;\n        for (char task : tasks) count[task]++;\n\n        int time = 0;\n\n        while (!count.empty()) {\n            int executed = 0;\n\n            // Sort by frequency each round\n            vector<char> available;\n            for (auto& [task, freq] : count) available.push_back(task);\n            sort(available.begin(), available.end(), [&](char a, char b) {\n                return count[a] > count[b];\n            });\n\n            for (int i = 0; i < (int)available.size() && i < n + 1; i++) {\n                char task = available[i];\n                count[task]--;\n                executed++;\n\n                if (count[task] == 0) count.erase(task);\n            }\n\n            if (!count.empty()) time += n + 1;\n            else time += executed;\n        }\n\n        return time;\n    }\n};","filename":"C++"}'),
  ('d3a15934-8d17-76ef-82ce-d2dd0d9c2e6c', 'aD', 'code', '{"language":"java","code":"class Solution {\n    public int leastInterval(char[] tasks, int n) {\n        Map<Character, Integer> count = new HashMap<>();\n        for (char task : tasks) count.merge(task, 1, Integer::sum);\n\n        int time = 0;\n\n        while (!count.isEmpty()) {\n            int executed = 0;\n\n            // Sort by frequency each round\n            List<Character> available = new ArrayList<>(count.keySet());\n            available.sort((a, b) -> Integer.compare(count.get(b), count.get(a)));\n\n            for (int i = 0; i < available.size() && i < n + 1; i++) {\n                char task = available.get(i);\n                int freq = count.get(task) - 1;\n                executed++;\n\n                if (freq == 0) count.remove(task);\n                else count.put(task, freq);\n            }\n\n            if (!count.isEmpty()) time += n + 1;\n            else time += executed;\n        }\n\n        return time;\n    }\n}","filename":"Java"}'),
  ('eddc2cff-69ee-72c1-a967-8dcdb4d2fb12', 'aE', 'code', '{"language":"javascript","code":"var leastInterval = function(tasks, n) {\n    const count = new Map();\n    for (const task of tasks) count.set(task, (count.get(task) || 0) + 1);\n\n    let time = 0;\n\n    while (count.size > 0) {\n        let executed = 0;\n\n        // Sort by frequency each round\n        const available = [...count.keys()].sort((a, b) => count.get(b) - count.get(a));\n\n        for (const task of available.slice(0, n + 1)) {\n            count.set(task, count.get(task) - 1);\n            executed++;\n\n            if (count.get(task) === 0) count.delete(task);\n        }\n\n        if (count.size > 0) time += n + 1;\n        else time += executed;\n    }\n\n    return time;\n};","filename":"JavaScript"}'),
  ('7573e22f-5087-7e33-a73b-fdc5bdd612bc', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(T × m log m) · Space: O(m)","marks":[{"type":"bold"}]}]}]}}'),
