 = 0;\n\n        return 1 + dfs(r + 1, c) + dfs(r - 1, c)\n                 + dfs(r, c + 1) + dfs(r, c - 1);\n    }\n}","filename":"Java"},"revision":1},{"id":"f5d944d1-68fd-79fa-8125-94a76a74a5ee","type":"code","position":"aK","content":{"language":"javascript","code":"var maxAreaOfIsland = function(grid) {\n    const rows = grid.length;\n    const cols = grid[0].length;\n\n    const dfs = (r, c) => {\n        if (\n            r < 0 || r >= rows ||\n            c < 0 || c >= cols ||\n            grid[r][c] === 0\n        ) return 0;\n\n        grid[r][c] = 0;\n\n        return 1 + dfs(r + 1, c) + dfs(r - 1, c)\n                 + dfs(r, c + 1) + dfs(r, c - 1);\n    };\n\n    let answer = 0;\n\n    for (let r = 0; r < rows; r++)\n        for (let c = 0; c < cols; c++)\n            if (grid[r][c] === 1)\n                answer = Math.max(answer, dfs(r, c));\n\n    return answer;\n};","filename":"JavaScript"},"revision":1},{"id":"21ae6cf7-e509-7fd9-9b8b-f91b9f1c1a40","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(R × C) · Aux Space: O(R × C) · Extra Visited Space: O(1)","marks":[{"type":"bold"}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
