  ('0cac7a39-5d4d-7312-b60f-d05e0aaca875', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(log |x|) · Space: O(log |x|)","marks":[{"type":"bold"}]}]}]}}'),
