  ('1f9267d2-53ac-794d-9660-cccdeed05438', 'aH', 'code', '{"language":"python","code":"class Solution:\n    def reverse(self, x):\n        sign = -1 if x < 0 else 1\n        x = abs(x)\n\n        result = 0\n\n        while x:\n            digit = x % 10\n            result = result * 10 + digit\n            x //= 10\n\n        result *= sign\n\n        if result < -(2 ** 31) or result > 2 ** 31 - 1:\n            return 0\n\n        return result","filename":"Python"}'),
  ('be58c7e8-c28d-7af2-a117-a159c35d1dd1', 'aI', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    int reverse(int x) {\n        int sign = x < 0 ? -1 : 1;\n        long long value = llabs((long long)x);  // abs(INT_MIN) overflows int\n\n        // 64-bit result can hold any reversed 10-digit value\n        long long result = 0;\n\n        while (value) {\n            int digit = value % 10;\n            result = result * 10 + digit;\n            value /= 10;\n        }\n\n        result *= sign;\n\n        if (result < INT_MIN || result > INT_MAX) {\n            return 0;\n        }\n\n        return (int)result;\n    }\n};","filename":"C++"}'),
  ('bbe21a08-0c45-7a64-b99f-156ef88644df', 'aJ', 'code', '{"language":"java","code":"class Solution {\n    public int reverse(int x) {\n        int sign = x < 0 ? -1 : 1;\n        long value = Math.abs((long) x);  // Math.abs(Integer.MIN_VALUE) overflows int\n\n        // 64-bit result can hold any reversed 10-digit value\n        long result = 0;\n\n        while (value != 0) {\n            long digit = value % 10;\n            result = result * 10 + digit;\n            value /= 10;\n        }\n\n        result *= sign;\n\n        if (result < Integer.MIN_VALUE || result > Integer.MAX_VALUE) {\n            return 0;\n        }\n\n        return (int) result;\n    }\n}","filename":"Java"}'),
