SELECT 'ede7c034-d896-7525-9cbb-66bfd7902fff', '6c72acf0-3bc6-7553-b754-1edec64f4bd9', 1, 'PUBLISHED', 'Climbing Stairs', '[{"id":"72300467-b731-73d3-8351-b1b4f793ea40","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Easy","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 70","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/climbing-stairs/"}}]}]}]}},"revision":1},{"id":"db512254-1458-718a-b0c7-5899ce57ba5c","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"71d6d1d2-6f6a-7701-a742-d6b3dd252c8f","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"You are climbing a staircase with "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" steps. Each time you can climb "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"2","marks":[{"type":"code"}]},{"type":"text","text":" steps. How many distinct ways can you climb to the top?"}]}]}},"revision":1},{"id":"7d33fb8b-2335-7691-bb43-cd1a01170eb9","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"3f56f88e-6ef2-7cf1-bb70-21f89f9f7ead","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"At every step, you can climb either 1 or 2 stairs. To reach step "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":", you come from "},{"type":"text","text":"n-1","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"n-2","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"fbe37acd-6c8e-7ad5-868d-c3f7a87c2f39","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"bd8df38e-4e80-7f18-827a-7d5f624c1a4b","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Subproblem overlap means "},{"type":"text","text":"dp[i] = dp[i-1] + dp[i-2]","marks":[{"type":"code"}]},{"type":"text","text":". We can build bottom-up or optimize space to only 2 variables."}]}]}},"revision":1},{"id":"aa3296bb-3da5-7cc5-8ffa-72de70a08cb0","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"a602b6fb-7cb9-70e9-90ec-2869487be776","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check base cases: if "},{"type":"text","text":"n <= 2","marks":[{"type":"code"}]},{"type":"text","text":", return "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Maintain "},{"type":"text","text":"prev2 = 1","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"prev1 = 2","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Loop from 3 to "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" updating "},{"type":"text","text":"current = prev1 + prev2","marks":[{"type":"code"}]},{"type":"text","text":", shifting "},{"type":"text","text":"prev2 = prev1","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"prev1 = current","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"prev1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"46e5f895-2c79-778b-926c-5d7e76ffaf8a","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Recursion"}]},"revision":1},{"id":"09eebf07-39c0-7201-aadb-56d253cc2aba","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Generate every climb step combination by recursively deciding whether to take 1 or 2 steps."}]}]}},"revision":1},{"id":"329d945e-e2e6-7c1d-8d8e-0b260fbc77a6","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def climbStairs(self, n):\n        def dfs(step):\n            if step == n:\n                return 1\n\n            if step > n:\n                return 0\n\n            return dfs(step + 1) + dfs(step + 2)\n\n        return dfs(0)","filename":"Python"},"revision":1},{"id":"157ced3a-690e-7bf2-b4fe-a416acddde6b","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int climbStairs(int n) {\n        return dfs(0, n);\n    }\n\nprivate:\n    int dfs(int step, int n) {\n        if (step == n) return 1;\n        if (step > n) return 0;\n        return dfs(step + 1, n) + dfs(step + 2, n);\n    }\n};","filename":"C++"},"revision":1},{"id":"3fc170c7-46f6-75d8-b70e-0f8961aa8580","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int climbStairs(int n) {\n        return dfs(0, n);\n    }\n\n    private int dfs(int step, int n) {\n        if (step == n) return 1;\n        if (step > n) return 0;\n        return dfs(step + 1, n) + dfs(step + 2, n);\n    }\n}","filename":"Java"},"revision":1},{"id":"fe2b951b-323e-73fd-894f-c7eeac7c0cd6","type":"code","position":"aE","content":{"language":"javascript","code":"var climbStairs = function(n) {\n    const dfs = (step) => {\n        if (step === n) return 1;\n        if (step > n) return 0;\n        return dfs(step + 1) + dfs(step + 2);\n    };\n\n    return dfs(0);\n};","filename":"JavaScript"},"revision":1},{"id":"a9a1b50c-f420-7888-bc9d-3d3322075e57","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(2^n) · Aux Space: O(n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"75d87b1b-5fd7-7f7c-9ba1-ff4e40c31333","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"4ff77072-57d6-7ca0-84a5-a85a0cf631dd","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def climbStairs(self, n):\n        if n <= 2:\n            return n\n\n        dp = [0] * (n + 1)\n        dp[1] = 1\n        dp[2] = 2\n\n        for i in range(3, n + 1):\n            dp[i] = dp[i - 1] + dp[i - 2]\n\n        return dp[n]","filename":"Python"},"revision":1},{"id":"0f4bc8b2-5be9-7fc6-90bd-06c6bdb58b56","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int climbStairs(int n) {\n        if (n <= 2) return n;\n\n        vector<int> dp(n + 1, 0);\n        dp[1] = 1;\n        dp[2] = 2;\n\n        for (int i = 3; i <= n; i++) {\n            dp[i] = dp[i - 1] + dp[i - 2];\n        }\n\n        return dp[n];\n    }\n};","filename":"C++"},"revision":1},{"id":"defe772e-12ce-7617-b493-12133374d0b3","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public int climbStairs(int n) {\n        if (n <= 2) return n;\n\n        int[] dp = new int[n + 1];\n        dp[1] = 1;\n        dp[2] = 2;\n\n        for (int i = 3; i <= n; i++) {\n            dp[i] = dp[i - 1] + dp[i - 2];\n        }\n\n        return dp[n];\n    }\n}","filename":"Java"},"revision":1},{"id":"d4e2abdf-1a19-7d64-9d2f-19c7935cafb8","type":"code","position":"aK","content":{"language":"javascript","code":"var climbStairs = function(n) {\n    if (n <= 2) return n;\n\n    const dp = new Array(n + 1).fill(0);\n    dp[1] = 1;\n    dp[2] = 2;\n\n    for (let i = 3; i <= n; i++) {\n        dp[i] = dp[i - 1] + dp[i - 2];\n    }\n\n    return dp[n];\n};","filename":"JavaScript"},"revision":1},{"id":"e0031450-2ef2-7475-84a7-b7e63f68a666","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Space: O(1) (Space Optimized) / O(n) (DP Array)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"1b20c383-7d92-7808-bf7d-ecce9324ca20","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"53a6bc9a-c2ff-7cc5-a1cd-b7d75249774b","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Previous 2 states DP","marks":[{"type":"bold"}]},{"type":"text","text":" — Each state only depends on the immediate two previous states."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
