ult = new int[n];\n        for (int i = 0; i < n; i++)\n            for (int j = i + 1; j < n; j++)\n                if (temperatures[j] > temperatures[i]) {\n                    result[i] = j - i;\n                    break;\n                }\n        return result;\n    }\n}","filename":"Java"},"revision":1},{"id":"8711fa90-eb59-74f0-9e54-811e3705f83f","type":"code","position":"aE","content":{"language":"javascript","code":"var dailyTemperatures = function(temperatures) {\n    const n = temperatures.length;\n    const result = new Array(n).fill(0);\n    for (let i = 0; i < n; i++)\n        for (let j = i + 1; j < n; j++)\n            if (temperatures[j] > temperatures[i]) {\n                result[i] = j - i;\n                break;\n            }\n    return result;\n};","filename":"JavaScript"},"revision":1},{"id":"dea69308-f388-7a70-80bc-397b0cb4f821","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n²) · Space: O(1) aux","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"655cf099-934b-7e5e-8c72-c63904227e36","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"5a504707-2a7e-728a-adf9-b0ad758d6abb","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def dailyTemperatures(self, temperatures):\n\n        result = [0] * len(temperatures)\n\n        stack = []\n\n        for i, temperature in enumerate(temperatures):\n\n            while (\n                stack\n                and temperature > temperatures[stack[-1]]\n            ):\n                previous = stack.pop()\n\n                result[previous] = i - previous\n\n            stack.append(i)\n\n        return result","filename":"Python"},"revision":1},{"id":"2c58ce82-04b6-7d2d-a1a1-7da076928ab9","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    vector<int> dailyTemperatures(vector<int>& temperatures) {\n        vector<int> result(temperatures.size(), 0);\n        stack<int> st;\n        for (int i = 0; i < temperatures.size(); i++) {\n            while (!st.empty() && temperatures[i] > temperatures[st.top()]) {\n                int previous = st.top();\n                st.pop();\n                result[previous] = i - previous;\n            }\n            st.push(i);\n        }\n        return result;\n    }\n};","filename":"C++"},"revision":1},{"id":"34dd3e45-99cf-7a97-8dd8-2b65c5e12709","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public int[] dailyTemperatures(int[] temperatures) {\n        int[] result = new int[temperatures.length];\n        Deque<Integer> stack = new ArrayDeque<>();\n        for (int i = 0; i < temperatures.length; i++) {\n            while (!stack.isEmpty() && temperatures[i] > temperatures[stack.peek()]) {\n                int previous = stack.pop();\n                result[previous] = i - previous;\n            }\n            stack.push(i);\n        }\n        return result;\n    }\n}","filename":"Java"},"revision":1},{"id":"e223dd6f-ba9a-7302-998b-d572ab5ed148","type":"code","position":"aK","content":{"language":"javascript","code":"var dailyTemperatures = function(temperatures) {\n    const result = new Array(temperatures.length).fill(0);\n    const stack = [];\n    for (let i = 0; i < temperatures.length; i++) {\n        while (stack.length && temperatures[i] > temperatures[stack[stack.length - 1]]) {\n            const previous = stack.pop();\n            result[previous] = i - previous;\n        }\n        stack.push(i);\n    }\n    return result;\n};","filename":"JavaScript"},"revision":1},{"id":"2acfbfe0-6269-7510-8c3a-1a7e916f19f5","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Space: O(n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id"