      answer = max(dist[1:])\n\n        return answer if answer != float(\"inf\") else -1","filename":"Python"},"revision":1},{"id":"2aa3fff3-0b24-71f7-81ca-1a575462b1fa","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int networkDelayTime(vector<vector<int>>& times, int n, int k) {\n        const int INF = INT_MAX;\n        vector<int> dist(n + 1, INF);\n        dist[k] = 0;\n\n        // Relax every edge n - 1 times\n        for (int i = 0; i < n - 1; i++) {\n            for (auto& t : times) {\n                int u = t[0], v = t[1], w = t[2];\n                if (dist[u] != INF && dist[u] + w < dist[v])\n                    dist[v] = dist[u] + w;\n            }\n        }\n\n        int answer = 0;\n        for (int node = 1; node <= n; node++) {\n            if (dist[node] == INF) return -1;\n            answer = max(answer, dist[node]);\n        }\n\n        return answer;\n    }\n};","filename":"C++"},"revision":1},{"id":"2050f3b4-d5e8-79fa-9fa4-caaa5dc1fb31","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int networkDelayTime(int[][] times, int n, int k) {\n        final int INF = Integer.MAX_VALUE;\n        int[] dist = new int[n + 1];\n        Arrays.fill(dist, INF);\n        dist[k] = 0;\n\n        // Relax every edge n - 1 times\n        for (int i = 0; i < n - 1; i++) {\n            for (int[] t : times) {\n                int u = t[0], v = t[1], w = t[2];\n                if (dist[u] != INF && dist[u] + w < dist[v])\n                    dist[v] = dist[u] + w;\n            }\n        }\n\n        int answer = 0;\n        for (int node = 1; node <= n; node++) {\n            if (dist[node] == INF) return -1;\n            answer = Math.max(answer, dist[node]);\n        }\n\n        return answer;\n    }\n}","filename":"Java"},"revision":1},{"id":"d113f28f-bfd1-741c-836a-7b99e35dfe59","type":"code","position":"aE","content":{"language":"javascript","code":"var networkDelayTime = function(times, n, k) {\n    const dist = new Array(n + 1).fill(Infinity);\n    dist[k] = 0;\n\n    // Relax every edge n - 1 times\n    for (let i = 0; i < n - 1; i++) {\n        for (const [u, v, w] of times) {\n            if (dist[u] + w < dist[v]) dist[v] = dist[u] + w;\n        }\n    }\n\n    let answer = 0;\n    for (let node = 1; node <= n; node++) {\n        if (dist[node] === Infinity) return -1;\n        answer = Math.max(answer, dist[node]);\n    }\n\n    return answer;\n};","filename":"JavaScript"},"revision":1},{"id":"23e17781-e5a2-7823-9241-50ee4f8db541","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(V × E) · Aux Space: O(V)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"a24d2e6a-b51a-7820-952f-0b9c51cb6846","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"5f54fa91-5299-75aa-a5f8-2d19472dc88d","type":"code","position":"aH","content":{"language":"python","code":"from collections import defaultdict\nimport heapq\n\nclass Solution:\n    def networkDelayTime(self, times, n, k):\n        graph = defaultdict(list)\n\n        for u, v, w in times:\n            graph[u].append((v, w))\n\n        min_heap = [(0, k)]\n        distances = {}\n\n        while min_heap:\n            time, node = heapq.heappop(min_heap)\n\n            if node in distances:\n                continue\n\n            distances[node] = time\n\n            for neighbor, weight in graph[node]:\n                if neighbor not in distances:\n                    heapq.heappush(\n                        min_heap,\n                        (time + weight, neighbor)\n                    )\n\n        if len(distances) == n:\n            return max(distances.values())\n\n        return -1","filename":"Python"},"revision":1},{"id":"94ec2631-4d5f-74af-a56d-bd154e93550e","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int networkDelayTime(vector<vector<int>>& times, int n, int k) {\n        vector<vector<pair<int, int>>> graph(n + 1);\n\n        for (auto& t : times)\n            graph[t[0]].push_back({t[1], t[2]});\n\n        // (time, node)\n        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> minHeap;\n        minHeap.push({0, k});\n\n        vector<int> distances(n + 1, -1);\n        int reached = 0, answer = 0;\n\n        while (!minHeap.empty()) {\n            auto [time, node] = minHeap.top();\n            minHeap.pop();\n\n            if (distances[node] != -1) continue;\n\n            distances[node] = time;\n            reached++;\n            answer = max(answer, time);\n\n            for (auto& [neighbor, weight] : graph[node])\n                if (distances[neighbor] == -1)\n                    minHeap.push({time + weight, neighbor});\n        }\n\n        return reached == n ? answer : -1;\n    }\n};","filename":"C++"},"revision":1},{"id":"5f5d1112-339a-7924-b36b-21fa2f5dde4e","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public int networkDelayTime(int[][] times, int n, int k) {\n        List<List<int[]>> graph = new ArrayList<>();\n        for (int i = 0; i <= n; i++) graph.add(new ArrayList<>());\n\n        for (int[] t : times)\n            graph.get(t[0]).add(new int[]{t[1], t[2]});\n\n        // {time, node}\n        PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));\n        minHeap.offer(new int[]{0, k});\n\n        Map<Integer, Integer> distances = new HashMap<>();\n\n        while (!minHeap.isEmpty()) {\n            int[] top = minHeap.poll();\n            int time = top[0], node = top[1];\n\n            if (distances.containsKey(node)) continue;\n\n            distances.put(node, time);\n\n            for (int[] edge : graph.get(node))\n                if (!distances.containsKey(edge[0]))\n                    minHeap.offer(new int[]{time + edge[1], edge[0]});\n        }\n\n        if (distances.size() == n) return Collections.max(distances.values());\n\n        return -1;\n    }\n}","filename":"Java"},"revision":1},{"id":"b68acf19-a069-7626-9646-5c5036f42abd","type":"code","position":"aK","content":{"language":"javascript","code":"class MinHeap {\n    constructor() { this.heap = []; }\n\n    get size() { return this.heap.length; }\n\n    push(item) {\n        const h = this.heap;\n        h.push(item);\n        let i = h.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (h[p][0] <= h[i][0]) break;\n            [h[p], h[i]] = [h[i], h[p]];\n            i = p;\n        }\n    }\n\n    pop() {\n        const h = this.heap;\n        const top = h[0];\n        const last = h.pop();\n        if (h.length) {\n            h[0] = last;\n            let i = 0;\n            while (true) {\n                const l = 2 * i + 1, r = l + 1;\n                let m = i;\n                if (l < h.length && h[l][0] < h[m][0]) m = l;\n                if (r < h.length && h[r][0] < h[m][0]) m = r;\n                if (m === i) break;\n                [h[m], h[i]] = [h[i], h[m]];\n                i = m;\n            }\n        }\n        return top;\n    }\n}\n\nvar networkDelayTime = function(times, n, k) {\n    const graph = Array.from({ length: n + 1 }, () => []);\n\n    for (const [u, v, w] of times)\n        graph[u].push([v, w]);\n\n    const minHeap = new MinHeap();\n    minHeap.push([0, k]);  // [time, node]\n\n    const distances = new Map();\n\n    while (minHeap.size) {\n        const [time, node] = minHeap.pop();\n\n        if (distances.has(node)) continue;\n\n        distances.set(node, time);\n\n        for (const [neighbor, weight] of graph[node])\n            if (!distances.has(neighbor))\n                minHeap.push([time + weight, neighbor]);\n    }\n\n    if (distances.size === n) return Math.max(...distances.values());\n\n    return -1;\n};","filename":"JavaScript"},"revision":1},{"id":"7c280a15-091e-71be-9a34-47e36d7ec5af","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(E log V) · Aux Space: O(V + E)","marks":[{"type":"bold"}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
