ntent":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"18175997-41fe-745e-bcd5-c80988349b39","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Expand right pointer until window is valid (tracking "},{"type":"text","text":"formed == required","marks":[{"type":"code"}]},{"type":"text","text":"). Then shrink left pointer while valid to find minimum length."}]}]}},"revision":1},{"id":"06054c46-12df-73a0-b209-29d17014d156","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"6ddf32f1-4b4f-7e8e-9b12-a9f9ab382010","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build "},{"type":"text","text":"need","marks":[{"type":"code"}]},{"type":"text","text":" frequency map for "},{"type":"text","text":"t","marks":[{"type":"code"}]},{"type":"text","text":", tracking "},{"type":"text","text":"required = len(need)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Expand "},{"type":"text","text":"right","marks":[{"type":"code"}]},{"type":"text","text":" pointer and update "},{"type":"text","text":"have","marks":[{"type":"code"}]},{"type":"text","text":" map."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Increment "},{"type":"text","text":"formed","marks":[{"type":"code"}]},{"type":"text","text":" when "},{"type":"text","text":"have[char] == need[char]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"While "},{"type":"text","text":"formed == required","marks":[{"type":"code"}]},{"type":"text","text":": record best window, remove "},{"type":"text","text":"s[left]","marks":[{"type":"code"}]},{"type":"text","text":", decrement "},{"type":"text","text":"formed","marks":[{"type":"code"}]},{"type":"text","text":" if needed, and advance "},{"type":"text","text":"left += 1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"598d3e01-830a-73fc-9727-44e8f516d0c6","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]},"revision":1},{"id":"9f021c80-1456-75ba-a847-1cfb93f3f015","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Try every substring, verify if character counts meet requirements of t."}]}]}},"revision":1},{"id":"55ee1427-c002-776e-89fc-304efa98da40","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def minWindow(self, s, t):\n        if not t:\n            return \"\"\n\n        answer = \"\"\n\n        for left in range(len(s)):\n            count = {}\n\n            for right in range(left, len(s)):\n                count[s[right]] = (\n                    count.get(s[right], 0) + 1\n                )\n\n                valid = True\n\n                for char in t:\n                    if count.get(char, 0) < t.count(char):\n                        valid = False\n                        break\n\n                if valid:\n                    current = s[left:right + 1]\n\n                    if (\n                        not answer\n                        or len(current) < len(answer)\n                    ):\n                        answer = current\n\n                    break\n\n        return answer","filename":"Python"},"revision":1},{"id":"dc739ef4-7158-75f8-92be-96f2c71d7cba","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    string minWindow(string s, string t) {\n        if (t.empty()) return \"\";\n        string answer = \"\";\n        for (int left = 0; left < s.size(); left++) {\n            unordered_map<char, int> count;\n            for (int right = left; right < s.size(); right++) {\n                count[s[right]]++;\n                bool valid = true;\n                for (char c : t)\n                    if (count[c] < std::count(t.begin(), t.end(), c)) {\n                        valid = false;\n                        break;\n                    }\n                if (valid) {\n                    string current = s.substr(left, right - left + 1);\n                    if (answer.empty() || current.size() < answer.size()) answer = current;\n                    break;\n                }\n            }\n        }\n        return answer;\n    }\n};","filename":"C++"},"revision":1},{"id":"b113cf50-7262-747d-a95b-942fd19466ce","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public String minWindow(String s, String t) {\n        if (t.isEmpty()) return \"\";\n        String answer = \"\";\n        for (int left = 0; left < s.length(); left++) {\n            Map<Character, Integer> count = new HashMap<>();\n            for (int right = left; right < s.length(); right++) {\n                count.put(s.charAt(right), count.getOrDefault(s.charAt(right), 0) + 1);\n                boolean valid = true;\n                for (char c : t.toCharArray())\n                    if (count.getOrDefault(c, 0) < countOf(t, c)) {\n                        valid = false;\n                        break;\n                    }\n                if (valid) {\n                    String current = s.substring(left, right + 1);\n                    if (answer.isEmpty() || current.length() < answer.length()) answer = current;\n                    break;\n                }\n            }\n        }\n        return answer;\n    }\n\n    private int countOf(String t, char c) {\n        int n = 0;\n        for (char x : t.toCharArray()) if (x == c) n++;\n        return n;\n    }\n}","filename":"Java"},"revision":1},{"id":"0f07d4ae-ea5e-7788-90b1-1a2d02fe0f64","type":"code","position":"aE","content":{"language":"javascript","code":"var minWindow = function(s, t) {\n    if (!t) return \"\";\n    const countOf = c => t.split(c).length - 1;\n    let answer = \"\";\n    for (let left = 0; left < s.length; left++) {\n        const count = new Map();\n        for (let right = left; right < s.length; right++) {\n            count.set(s[right], (count.get(s[right]) || 0) + 1);\n            let valid = true;\n            for (const c of t)\n                if ((count.get(c) || 0) < countOf(c)) {\n                    valid = false;\n                    break;\n                }\n            if (valid) {\n                const current = s.slice(left, right + 1);\n                if (!answer || current.length < answer.length) answer = current;\n                break;\n            }\n        }\n    }\n    return answer;\n};","filename":"JavaScript"},"revision":1},{"id":"59e38685-4cf9-78ab-ab7d-acc2eae094e8","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n² × k) · Space: O(k)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"b2ccad45-8693-71b3-8f0c-3da483001ae6","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"a63d728a-a811-72ae-a870-943321b1e3d6","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def minWindow(self, s, t):\n        if not t:\n            return \"\"\n\n        need = {}\n\n        for char in t:\n            need[char] = need.get(char, 0) + 1\n\n        have = {}\n        required = len(need)\n        formed = 0\n\n        left = 0\n\n        best_length = float(\"inf\")\n        best_start = 0\n\n        for right in range(len(s)):\n            char = s[right]\n\n            have[char] = have.get(char, 0) + 1\n\n            if (\n                char in need\n                and have[char] == need[char]\n            ):\n                formed += 1\n\n            while formed == required:\n                if (\n                    right - left + 1\n                    < best_length\n                ):\n                    best_length = right - left + 1\n                    best_start = left\n\n                left_char = s[left]\n                have[left_char] -= 1\n\n                if (\n                    left_char in need\n                    and have[left_char] < need[left_char]\n                ):\n                    formed -= 1\n\n                left += 1\n\n        if best_length == float(\"inf\"):\n            return \"\"\n\n        return s[\n            best_start:\n            best_start + best_length\n        ]","filename":"Python"},"revision":1},{"id":"015327f9-fc72-74c2-92fa-09d2ec00fb76","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    string minWindow(string s, string t) {\n        if (t.empty()) return \"\";\n        unordered_map<char, int> need, have;\n        for (char c : t) need[c]++;\n        int required = need.size(), formed = 0;\n        int left = 0, bestLength = INT_MAX, bestStart = 0;\n        for (int right = 0; right < s.size(); right++) {\n            char c = s[right];\n            have[c]++;\n            if (need.count(c) && have[c] == need[c]) formed++;\n            while (formed == required) {\n                if (right - left + 1 < bestLength) {\n                    bestLength = right - left + 1;\n                    bestStart = left;\n                }\n                char leftChar = s[left];\n                have[leftChar]--;\n                if (need.count(leftChar) && have[leftChar] < need[leftChar]) formed--;\n                left++;\n            }\n        }\n        if (bestLength == INT_MAX) return \"\";\n        return s.substr(bestStart, bestLength);\n    }\n};","filename":"C++"},"revision":1},{"id":"cfae4192-c906-7d20-9623-53d1134dff38","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public String minWindow(String s, String t) {\n        if (t.isEmpty()) return \"\";\n        Map<Character, Integer> need = new HashMap<>(), have = new HashMap<>();\n        for (char c : t.toCharArray()) need.put(c, need.getOrDefault(c, 0) + 1);\n        int required = need.size(), formed = 0;\n        int left = 0, bestLength = Integer.MAX_VALUE, bestStart = 0;\n        for (int right = 0; right < s.length(); right++) {\n            char c = s.charAt(right);\n            have.put(c, have.getOrDefault(c, 0) + 1);\n            if (need.containsKey(c) && have.get(c).equals(need.get(c))) formed++;\n            while (formed == required) {\n                if (right - left + 1 < bestLength) {\n                    bestLength = right - left + 1;\n                    bestStart = left;\n                }\n                char leftChar = s.charAt(left);\n                have.put(leftChar, have.get(leftChar) - 1);\n                if (need.containsKey(leftChar) && have.get(leftChar) < need.get(leftChar)) formed--;\n                left++;\n            }\n        }\n        if (bestLength == Integer.MAX_VALUE) return \"\";\n        return s.substring(bestStart, bestStart + bestLength);\n    }\n}","filename":"Java"},"revision":1},{"id":"88862f5e-8cde-7d58-974a-e7b2f23a5e93","type":"code","position":"aK","content":{"language":"javascript","code":"var minWindow = function(s, t) {\n    if (!t) return \"\";\n    const need = new Map(), have = new Map();\n    for (const c of t) need.set(c, (need.get(c) || 0) + 1);\n    const required = need.size;\n    let formed = 0, left = 0, bestLength = Infinity, bestStart = 0;\n    for (let right = 0; right < s.length; right++) {\n        const c = s[right];\n        have.set(c, (have.get(c) || 0) + 1);\n        if (need.has(c) && have.get(c) === need.get(c)) formed++;\n        while (formed === required) {\n            if (right - left + 1 < bestLength) {\n                bestLength = right - left + 1;\n                bestStart = left;\n            }\n            const leftChar = s[left];\n            have.set(leftChar, have.get(leftChar) - 1);\n            if (need.has(leftChar) && have.get(leftChar) < need.get(leftChar)) formed--;\n            left++;\n        }\n    }\n    if (bestLength === Infinity) return \"\";\n    return s.slice(bestStart, bestStart + bestLength);\n};","filename":"JavaScript"},"revision":1},{"id":"c21dd417-cd0f-768b-b2e0-fbd9536d0f62","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Space: O(k)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"cf8b2696-16f6-7d90-a0b5-c2b005ae545c","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"44b35db0-6799-7e99-95d9-622a00317f51","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Expand until valid → Shrink while valid"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
