tent":[{"type":"paragraph","content":[{"type":"text","text":"Pre-compute "},{"type":"text","text":"last[char]","marks":[{"type":"code"}]},{"type":"text","text":" = last index of each character. Scan left-to-right. As we see each character, extend "},{"type":"text","text":"end","marks":[{"type":"code"}]},{"type":"text","text":" to at least "},{"type":"text","text":"last[char]","marks":[{"type":"code"}]},{"type":"text","text":". When "},{"type":"text","text":"i == end","marks":[{"type":"code"}]},{"type":"text","text":", a self-contained partition is complete."}]}]}},"revision":1},{"id":"b62dd5d6-2e68-7702-bcd3-427605e8b942","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"9df91a2e-234b-7144-8b9c-d837bcbbe586","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build "},{"type":"text","text":"last = {char: index}","marks":[{"type":"code"}]},{"type":"text","text":" for last occurrence of each character."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialize "},{"type":"text","text":"start = 0","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"end = 0","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Iterate "},{"type":"text","text":"i, char","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Update "},{"type":"text","text":"end = max(end, last[char])","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"When "},{"type":"text","text":"i == end","marks":[{"type":"code"}]},{"type":"text","text":": append "},{"type":"text","text":"end - start + 1","marks":[{"type":"code"}]},{"type":"text","text":" to result, set "},{"type":"text","text":"start = i + 1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return result."}]}]}]}]}},"revision":1},{"id":"1dea8c05-55c0-787e-9204-aa18d59765ed","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]},"revision":1},{"id":"1c341e10-c325-75c0-b4b5-a5fb544ce436","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Scan partitions naively: expand each window until no character inside it has a last occurrence outside the window."}]}]}},"revision":1},{"id":"34c4283b-fe21-753f-ae33-15c6a7ff3426","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def partitionLabels(self, s):\n        result = []\n        start = 0\n\n        while start < len(s):\n            chars = set()\n            end = start\n\n            while end < len(s):\n                chars.add(s[end])\n\n                last = max(\n                    i\n                    for i, c in enumerate(s)\n                    if c in chars\n                )\n\n                if last == end:\n                    break\n\n                end += 1\n\n            result.append(end - start + 1)\n            start = end + 1\n\n        return result","filename":"Python"},"revision":1},{"id":"0d6ba419-1065-75c4-9911-a09f6f0ae732","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    vector<int> partitionLabels(string s) {\n        vector<int> result;\n        int n = s.size();\n        int start = 0;\n\n        while (start < n) {\n            unordered_set<char> chars;\n            int end = start;\n\n            while (end < n) {\n                chars.insert(s[end]);\n\n                int last = 0;\n                for (int i = 0; i < n; i++) {\n                    if (chars.count(s[i])) {\n                        last = i;\n                    }\n                }\n\n                if (last == end) {\n                    break;\n                }\n\n                end++;\n            }\n\n            result.push_back(end - start + 1);\n            start = end + 1;\n        }\n\n        return result;\n    }\n};","filename":"C++"},"revision":1},{"id":"dcc50e64-7970-7d13-b468-ee0f9135c449","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public List<Integer> partitionLabels(String s) {\n        List<Integer> result = new ArrayList<>();\n        int n = s.length();\n        int start = 0;\n\n        while (start < n) {\n            Set<Character> chars = new HashSet<>();\n            int end = start;\n\n            while (end < n) {\n                chars.add(s.charAt(end));\n\n                int last = 0;\n                for (int i = 0; i < n; i++) {\n                    if (chars.contains(s.charAt(i))) {\n                        last = i;\n                    }\n                }\n\n                if (last == end) {\n                    break;\n                }\n\n                end++;\n            }\n\n            result.add(end - start + 1);\n            start = end + 1;\n        }\n\n        return result;\n    }\n}","filename":"Java"},"revision":1},{"id":"9f4366dc-c57d-7581-bce1-ea60291c689b","type":"code","position":"aE","content":{"language":"javascript","code":"var partitionLabels = function(s) {\n    const result = [];\n    const n = s.length;\n    let start = 0;\n\n    while (start < n) {\n        const chars = new Set();\n        let end = start;\n\n        while (end < n) {\n            chars.add(s[end]);\n\n            let last = 0;\n            for (let i = 0; i < n; i++) {\n                if (chars.has(s[i])) {\n                    last = i;\n                }\n            }\n\n            if (last === end) {\n                break;\n            }\n\n            end++;\n        }\n\n        result.push(end - start + 1);\n        start = end + 1;\n    }\n\n    return result;\n};","filename":"JavaScript"},"revision":1},{"id":"2cb7d35c-7a0d-7ff2-a9a4-b6f490ff39e9","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n²) · Space: O(k) — k = alphabet size","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"f055ec26-592a-7492-bc5a-8cacdb315acf","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"94dc37ce-408e-7776-ade9-26c61573b56d","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def partitionLabels(self, s):\n        last = {}\n\n        for i, char in enumerate(s):\n            last[char] = i\n\n        result = []\n        start = 0\n        end = 0\n\n        for i, char in enumerate(s):\n            end = max(end, last[char])\n\n            if i == end:\n                result.append(end - start + 1)\n                start = i + 1\n\n        return result","filename":"Python"},"revision":1},{"id":"35b877e5-7ced-7b83-8eb7-0a0c32d300b1","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    vector<int> partitionLabels(string s) {\n        unordered_map<char, int> last;\n\n        for (int i = 0; i < (int)s.size(); i++) {\n            last[s[i]] = i;\n        }\n\n        vector<int> result;\n        int start = 0;\n        int end = 0;\n\n        for (int i = 0; i < (int)s.size(); i++) {\n            end = max(end, last[s[i]]);\n\n            if (i == end) {\n                result.push_back(end - start + 1);\n                start = i + 1;\n            }\n        }\n\n        return result;\n    }\n};","filename":"C++"},"revision":1},{"id":"e5649261-e5f9-7c8b-9499-a757c03be92c","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public List<Integer> partitionLabels(String s) {\n        Map<Character, Integer> last = new HashMap<>();\n\n        for (int i = 0; i < s.length(); i++) {\n            last.put(s.charAt(i), i);\n        }\n\n        List<Integer> result = new ArrayList<>();\n        int start = 0;\n        int end = 0;\n\n        for (int i = 0; i < s.length(); i++) {\n            end = Math.max(end, last.get(s.charAt(i)));\n\n            if (i == end) {\n                result.add(end - start + 1);\n                start = i + 1;\n            }\n        }\n\n        return result;\n    }\n}","filename":"Java"},"revision":1},{"id":"9844f610-15d7-712d-af58-d7d11972ac01","type":"code","position":"aK","content":{"language":"javascript","code":"var partitionLabels = function(s) {\n    const last = new Map();\n\n    for (let i = 0; i < s.length; i++) {\n        last.set(s[i], i);\n    }\n\n    const result = [];\n    let start = 0;\n    let end = 0;\n\n    for (let i = 0; i < s.length; i++) {\n        end = Math.max(end, last.get(s[i]));\n\n        if (i === end) {\n            result.push(end - start + 1);\n            start = i + 1;\n        }\n    }\n\n    return result;\n};","filename":"JavaScript"},"revision":1},{"id":"ba2c73ff-50ba-7085-b2e1-bc567e7676b1","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Space: O(k) — k = alphabet size","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"31efde9f-ed0c-780f-aa93-d3b545cf7939","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"da16e587-36d2-7d32-9db7-be250abfaabc","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Last Occurrence + Greedy Boundary Expansion — extend window until it is self-contained"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
