  ('34c4283b-fe21-753f-ae33-15c6a7ff3426', 'aB', 'code', '{"language":"python","code":"class Solution:\n    def partitionLabels(self, s):\n        result = []\n        start = 0\n\n        while start < len(s):\n            chars = set()\n            end = start\n\n            while end < len(s):\n                chars.add(s[end])\n\n                last = max(\n                    i\n                    for i, c in enumerate(s)\n                    if c in chars\n                )\n\n                if last == end:\n                    break\n\n                end += 1\n\n            result.append(end - start + 1)\n            start = end + 1\n\n        return result","filename":"Python"}'),
  ('0d6ba419-1065-75c4-9911-a09f6f0ae732', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    vector<int> partitionLabels(string s) {\n        vector<int> result;\n        int n = s.size();\n        int start = 0;\n\n        while (start < n) {\n            unordered_set<char> chars;\n            int end = start;\n\n            while (end < n) {\n                chars.insert(s[end]);\n\n                int last = 0;\n                for (int i = 0; i < n; i++) {\n                    if (chars.count(s[i])) {\n                        last = i;\n                    }\n                }\n\n                if (last == end) {\n                    break;\n                }\n\n                end++;\n            }\n\n            result.push_back(end - start + 1);\n            start = end + 1;\n        }\n\n        return result;\n    }\n};","filename":"C++"}'),
  ('dcc50e64-7970-7d13-b468-ee0f9135c449', 'aD', 'code', '{"language":"java","code":"class Solution {\n    public List<Integer> partitionLabels(String s) {\n        List<Integer> result = new ArrayList<>();\n        int n = s.length();\n        int start = 0;\n\n        while (start < n) {\n            Set<Character> chars = new HashSet<>();\n            int end = start;\n\n            while (end < n) {\n                chars.add(s.charAt(end));\n\n                int last = 0;\n                for (int i = 0; i < n; i++) {\n                    if (chars.contains(s.charAt(i))) {\n                        last = i;\n                    }\n                }\n\n                if (last == end) {\n                    break;\n                }\n\n                end++;\n            }\n\n            result.add(end - start + 1);\n            start = end + 1;\n        }\n\n        return result;\n    }\n}","filename":"Java"}'),
  ('9f4366dc-c57d-7581-bce1-ea60291c689b', 'aE', 'code', '{"language":"javascript","code":"var partitionLabels = function(s) {\n    const result = [];\n    const n = s.length;\n    let start = 0;\n\n    while (start < n) {\n        const chars = new Set();\n        let end = start;\n\n        while (end < n) {\n            chars.add(s[end]);\n\n            let last = 0;\n            for (let i = 0; i < n; i++) {\n                if (chars.has(s[i])) {\n                    last = i;\n                }\n            }\n\n            if (last === end) {\n                break;\n            }\n\n            end++;\n        }\n\n        result.push(end - start + 1);\n        start = end + 1;\n    }\n\n    return result;\n};","filename":"JavaScript"}'),
  ('2cb7d35c-7a0d-7ff2-a9a4-b6f490ff39e9', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n²) · Space: O(k) — k = alphabet size","marks":[{"type":"bold"}]}]}]}}'),
  ('f055ec26-592a-7492-bc5a-8cacdb315acf', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]}'),
  ('94dc37ce-408e-7776-ade9-26c61573b56d', 'aH', 'code', '{"language":"python","code":"class Solution:\n    def partitionLabels(self, s):\n        last = {}\n\n        for i, char in enumerate(s):\n            last[char] = i\n\n        result = []\n        start = 0\n        end = 0\n\n        for i, char in enumerate(s):\n            end = max(end, last[char])\n\n            if i == end:\n                result.append(end - start + 1)\n                start = i + 1\n\n        return result","filename":"Python"}'),
  ('35b877e5-7ced-7b83-8eb7-0a0c32d300b1', 'aI', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    vector<int> partitionLabels(string s) {\n        unordered_map<char, int> last;\n\n        for (int i = 0; i < (int)s.size(); i++) {\n            last[s[i]] = i;\n        }\n\n        vector<int> result;\n        int start = 0;\n        int end = 0;\n\n        for (int i = 0; i < (int)s.size(); i++) {\n            end = max(end, last[s[i]]);\n\n            if (i == end) {\n                result.push_back(end - start + 1);\n                start = i + 1;\n            }\n        }\n\n        return result;\n    }\n};","filename":"C++"}'),
  ('e5649261-e5f9-7c8b-9499-a757c03be92c', 'aJ', 'code', '{"language":"java","code":"class Solution {\n    public List<Integer> partitionLabels(String s) {\n        Map<Character, Integer> last = new HashMap<>();\n\n        for (int i = 0; i < s.length(); i++) {\n            last.put(s.charAt(i), i);\n        }\n\n        List<Integer> result = new ArrayList<>();\n        int start = 0;\n        int end = 0;\n\n        for (int i = 0; i < s.length(); i++) {\n            end = Math.max(end, last.get(s.charAt(i)));\n\n            if (i == end) {\n                result.add(end - start + 1);\n                start = i + 1;\n            }\n        }\n\n        return result;\n    }\n}","filename":"Java"}'),
  ('9844f610-15d7-712d-af58-d7d11972ac01', 'aK', 'code', '{"language":"javascript","code":"var partitionLabels = function(s) {\n    const last = new Map();\n\n    for (let i = 0; i < s.length; i++) {\n        last.set(s[i], i);\n    }\n\n    const result = [];\n    let start = 0;\n    let end = 0;\n\n    for (let i = 0; i < s.length; i++) {\n        end = Math.max(end, last.get(s[i]));\n\n        if (i === end) {\n            result.push(end - start + 1);\n            start = i + 1;\n        }\n    }\n\n    return result;\n};","filename":"JavaScript"}'),
