SELECT '2f936708-03c4-78af-9b9b-a01ad8389339', '05782760-bd33-7b2d-8b44-5fb4a46ad15b', 1, 'PUBLISHED', 'Swim in Rising Water', '[{"id":"6f06cbe0-d529-7df8-92a7-3ab760f9090f","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Hard","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 778","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/swim-in-rising-water/"}}]}]}]}},"revision":1},{"id":"80d01e72-1dc2-7d0b-ad5e-6f44754c3488","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"087932e7-8eeb-75a0-9c2f-d0166d30ac3d","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Return minimum time t to reach bottom-right "},{"type":"text","text":"(n-1, n-1)","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"(0,0)","marks":[{"type":"code"}]},{"type":"text","text":" in grid of water elevations."}]}]}},"revision":1},{"id":"3f0f9c72-1ae1-7b0e-a0b2-16363b4511db","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"715725ed-d9bb-7a0a-b3dc-45613af413dc","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Shortest path where path cost is "},{"type":"text","text":"max(elevation along path)","marks":[{"type":"code"}]},{"type":"text","text":". Solved via Modified Dijkstra."}]}]}},"revision":1},{"id":"b230296f-34e9-7091-8edb-dd9d55af8d3b","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"bfc5bc01-350b-7794-a599-e03a58b57b68","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dijkstra''s Algorithm with Min-Heap pops grid cells ordered by "},{"type":"text","text":"max_elevation","marks":[{"type":"code"}]},{"type":"text","text":" along path."}]}]}},"revision":1},{"id":"cb408697-bee1-76a1-a718-f4ce97ff5c90","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"c3bc3d53-245f-7ab0-89cd-632e220c24fb","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Min-heap [(grid[0][0], 0, 0)], visited = {(0,0)}."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pop (time, r, c). If (r, c) == (n-1, n-1), return time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Push unvisited neighbors with max(time, grid[nr][nc])."}]}]}]}]}},"revision":1},{"id":"2908d24c-3cbb-751f-9acb-6da9e7509daa","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution"}]},"revision":1},{"id":"305bc4ca-0b9f-71a3-b621-49487a6d1920","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Binary search on time t with BFS check."}]}]}},"revision":1},{"id":"59441d54-1ebf-74ba-aac6-3cb813950c5c","type":"code","position":"aB","content":{"language":"python","code":"from collections import deque\n\nclass Solution:\n    def swimInWater(self, grid):\n        n = len(grid)\n\n        # Can we reach the corner using only cells with height <= t?\n        def can_reach(t):\n            if grid[0][0] > t:\n                return False\n\n            visited = {(0, 0)}\n            queue = deque([(0, 0)])\n\n            while queue:\n                r, c = queue.popleft()\n\n                if r == n - 1 and c == n - 1:\n                    return True\n\n                for dr, dc in [\n                    (1, 0), (-1, 0),\n                    (0, 1), (0, -1)\n                ]:\n                    nr, nc = r + dr, c + dc\n\n                    if (\n                        0 <= nr < n and\n                        0 <= nc < n and\n                        (nr, nc) not in visited and\n                        grid[nr][nc] <= t\n                    ):\n                        visited.add((nr, nc))\n                        queue.append((nr, nc))\n\n            return False\n\n        lo, hi = 0, n * n - 1\n\n        while lo < hi:\n            mid = (lo + hi) // 2\n\n            if can_reach(mid):\n                hi = mid\n            else:\n                lo = mid + 1\n\n        return lo","filename":"Python"},"revision":1},{"id":"fddfd008-317b-7579-b9af-436844fea257","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int swimInWater(vector<vector<int>>& grid) {\n        int n = grid.size();\n        int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n\n        // Can we reach the corner using only cells with height <= t?\n        auto canReach = [&](int t) {\n            if (grid[0][0] > t) return false;\n\n            vector<vector<bool>> visited(n, vector<bool>(n, false));\n            queue<pair<int, int>> q;\n            q.push({0, 0});\n            visited[0][0] = true;\n\n            while (!q.empty()) {\n                auto [r, c] = q.front();\n                q.pop();\n\n                if (r == n - 1 && c == n - 1) return true;\n\n                for (auto& d : dirs) {\n                    int nr = r + d[0], nc = c + d[1];\n\n                    if (nr >= 0 && nr < n && nc >= 0 && nc < n &&\n                        !visited[nr][nc] && grid[nr][nc] <= t) {\n                        visited[nr][nc] = true;\n                        q.push({nr, nc});\n                    }\n                }\n            }\n\n            return false;\n        };\n\n        int lo = 0, hi = n * n - 1;\n\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;\n\n            if (canReach(mid)) hi = mid;\n            else lo = mid + 1;\n        }\n\n        return lo;\n    }\n};","filename":"C++"},"revision":1},{"id":"ddf4776f-fba2-7a80-9b4f-961d5c17ea64","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n\n    public int swimInWater(int[][] grid) {\n        int n = grid.length;\n        int lo = 0, hi = n * n - 1;\n\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;\n\n            if (canReach(grid, mid)) hi = mid;\n            else lo = mid + 1;\n        }\n\n        return lo;\n    }\n\n    // Can we reach the corner using only cells with height <= t?\n    private boolean canReach(int[][] grid, int t) {\n        int n = grid.length;\n        if (grid[0][0] > t) return false;\n\n        boolean[][] visited = new boolean[n][n];\n        Deque<int[]> queue = new ArrayDeque<>();\n        queue.offer(new int[]{0, 0});\n        visited[0][0] = true;\n\n        while (!queue.isEmpty()) {\n            int[] cell = queue.poll();\n            int r = cell[0], c = cell[1];\n\n            if (r == n - 1 && c == n - 1) return true;\n\n            for (int[] d : DIRS) {\n                int nr = r + d[0], nc = c + d[1];\n\n                if (nr >= 0 && nr < n && nc >= 0 && nc < n &&\n                    !visited[nr][nc] && grid[nr][nc] <= t) {\n                    visited[nr][nc] = true;\n                    queue.offer(new int[]{nr, nc});\n                }\n            }\n        }\n\n        return false;\n    }\n}","filename":"Java"},"revision":1},{"id":"3460c974-1080-79c4-a6c4-d58e53aa9adf","type":"code","position":"aE","content":{"language":"javascript","code":"var swimInWater = function(grid) {\n    const n = grid.length;\n    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];\n\n    // Can we reach the corner using only cells with height <= t?\n    const canReach = (t) => {\n        if (grid[0][0] > t) return false;\n\n        const visited = Array.from({ length: n }, () => new Array(n).fill(false));\n        const queue = [[0, 0]];\n        visited[0][0] = true;\n\n        for (let head = 0; head < queue.length; head++) {\n            const [r, c] = queue[head];\n\n            if (r === n - 1 && c === n - 1) return true;\n\n            for (const [dr, dc] of dirs) {\n                const nr = r + dr, nc = c + dc;\n\n                if (\n                    nr >= 0 && nr < n &&\n                    nc >= 0 && nc < n &&\n                    !visited[nr][nc] && grid[nr][nc] <= t\n                ) {\n                    visited[nr][nc] = true;\n                    queue.push([nr, nc]);\n                }\n            }\n        }\n\n        return false;\n    };\n\n    let lo = 0, hi = n * n - 1;\n\n    while (lo < hi) {\n        const mid = (lo + hi) >> 1;\n\n        if (canReach(mid)) hi = mid;\n        else lo = mid + 1;\n    }\n\n    return lo;\n};","filename":"JavaScript"},"revision":1},{"id":"97cf13e8-e69d-7a13-aee1-1d403d670afc","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(N^2 log(N^2)) · Aux Space: O(N^2)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"a5fb6099-da50-7aa4-b06f-b968570efbbd","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"d0ae3f25-67e9-7b2e-9270-eea646c17f73","type":"code","position":"aH","content":{"language":"python","code":"import heapq\n\nclass Solution:\n    def swimInWater(self, grid):\n        n = len(grid)\n\n        min_heap = [(grid[0][0], 0, 0)]\n        visited = {(0, 0)}\n\n        while min_heap:\n            time, r, c = heapq.heappop(min_heap)\n\n            if r == n - 1 and c == n - 1:\n                return time\n\n            for dr, dc in [\n                (1, 0), (-1, 0),\n                (0, 1), (0, -1)\n            ]:\n                nr, nc = r + dr, c + dc\n\n                if (\n                    0 <= nr < n and\n                    0 <= nc < n and\n                    (nr, nc) not in visited\n                ):\n                    visited.add((nr, nc))\n                    heapq.heappush(\n                        min_heap,\n                        (max(time, grid[nr][nc]), nr, nc)\n                    )\n\n        return -1","filename":"Python"},"revision":1},{"id":"d923251f-89ca-7cc8-8387-1cd9482d0aad","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int swimInWater(vector<vector<int>>& grid) {\n        int n = grid.size();\n        int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n\n        // (time, r, c)\n        priority_queue<array<int, 3>, vector<array<int, 3>>, greater<>> minHeap;\n        minHeap.push({grid[0][0], 0, 0});\n\n        vector<vector<bool>> visited(n, vector<bool>(n, false));\n        visited[0][0] = true;\n\n        while (!minHeap.empty()) {\n            auto [time, r, c] = minHeap.top();\n            minHeap.pop();\n\n            if (r == n - 1 && c == n - 1) return time;\n\n            for (auto& d : dirs) {\n                int nr = r + d[0], nc = c + d[1];\n\n                if (nr >= 0 && nr < n && nc >= 0 && nc < n && !visited[nr][nc]) {\n                    visited[nr][nc] = true;\n                    minHeap.push({max(time, grid[nr][nc]), nr, nc});\n                }\n            }\n        }\n\n        return -1;\n    }\n};","filename":"C++"},"revision":1},{"id":"e0dd38bd-9f06-7b6f-ba6e-53fe24d2a74b","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public int swimInWater(int[][] grid) {\n        int n = grid.length;\n        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n\n        // {time, r, c}\n        PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));\n        minHeap.offer(new int[]{grid[0][0], 0, 0});\n\n        boolean[][] visited = new boolean[n][n];\n        visited[0][0] = true;\n\n        while (!minHeap.isEmpty()) {\n            int[] top = minHeap.poll();\n            int time = top[0], r = top[1], c = top[2];\n\n            if (r == n - 1 && c == n - 1) return time;\n\n            for (int[] d : dirs) {\n                int nr = r + d[0], nc = c + d[1];\n\n                if (nr >= 0 && nr < n && nc >= 0 && nc < n && !visited[nr][nc]) {\n                    visited[nr][nc] = true;\n                    minHeap.offer(new int[]{Math.max(time, grid[nr][nc]), nr, nc});\n                }\n            }\n        }\n\n        return -1;\n    }\n}","filename":"Java"},"revision":1},{"id":"092579b2-50c1-7b44-9bbe-f6cf327e6ddc","type":"code","position":"aK","content":{"language":"javascript","code":"class MinHeap {\n    constructor() { this.heap = []; }\n\n    get size() { return this.heap.length; }\n\n    push(item) {\n        const h = this.heap;\n        h.push(item);\n        let i = h.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (h[p][0] <= h[i][0]) break;\n            [h[p], h[i]] = [h[i], h[p]];\n            i = p;\n        }\n    }\n\n    pop() {\n        const h = this.heap;\n        const top = h[0];\n        const last = h.pop();\n        if (h.length) {\n            h[0] = last;\n            let i = 0;\n            while (true) {\n                const l = 2 * i + 1, r = l + 1;\n                let m = i;\n                if (l < h.length && h[l][0] < h[m][0]) m = l;\n                if (r < h.length && h[r][0] < h[m][0]) m = r;\n                if (m === i) break;\n                [h[m], h[i]] = [h[i], h[m]];\n                i = m;\n            }\n        }\n        return top;\n    }\n}\n\nvar swimInWater = function(grid) {\n    const n = grid.length;\n    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];\n\n    const minHeap = new MinHeap();\n    minHeap.push([grid[0][0], 0, 0]);  // [time, r, c]\n\n    const visited = Array.from({ length: n }, () => new Array(n).fill(false));\n    visited[0][0] = true;\n\n    while (minHeap.size) {\n        const [time, r, c] = minHeap.pop();\n\n        if (r === n - 1 && c === n - 1) return time;\n\n        for (const [dr, dc] of dirs) {\n            const nr = r + dr, nc = c + dc;\n\n            if (\n                nr >= 0 && nr < n &&\n                nc >= 0 && nc < n &&\n                !visited[nr][nc]\n            ) {\n                visited[nr][nc] = true;\n                minHeap.push([Math.max(time, grid[nr][nc]), nr, nc]);\n            }\n        }\n    }\n\n    return -1;\n};","filename":"JavaScript"},"revision":1},{"id":"b4260aa6-e04a-72be-a498-5ae924bac502","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(N^2 log N) · Aux Space: O(N^2)","marks":[{"type":"bold"}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
