  ('80d01e72-1dc2-7d0b-ad5e-6f44754c3488', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"Problem"}]}'),
  ('087932e7-8eeb-75a0-9c2f-d0166d30ac3d', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Return minimum time t to reach bottom-right "},{"type":"text","text":"(n-1, n-1)","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"(0,0)","marks":[{"type":"code"}]},{"type":"text","text":" in grid of water elevations."}]}]}}'),
