  ('715725ed-d9bb-7a0a-b3dc-45613af413dc', 'a4', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Shortest path where path cost is "},{"type":"text","text":"max(elevation along path)","marks":[{"type":"code"}]},{"type":"text","text":". Solved via Modified Dijkstra."}]}]}}'),
