  ('bfc5bc01-350b-7794-a599-e03a58b57b68', 'a6', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dijkstra''s Algorithm with Min-Heap pops grid cells ordered by "},{"type":"text","text":"max_elevation","marks":[{"type":"code"}]},{"type":"text","text":" along path."}]}]}}'),
