  ('c3bc3d53-245f-7ab0-89cd-632e220c24fb', 'a8', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Min-heap [(grid[0][0], 0, 0)], visited = {(0,0)}."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pop (time, r, c). If (r, c) == (n-1, n-1), return time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Push unvisited neighbors with max(time, grid[nr][nc])."}]}]}]}]}}'),
  ('2908d24c-3cbb-751f-9acb-6da9e7509daa', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"Naive Solution"}]}'),
  ('305bc4ca-0b9f-71a3-b621-49487a6d1920', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Binary search on time t with BFS check."}]}]}}'),
  ('59441d54-1ebf-74ba-aac6-3cb813950c5c', 'aB', 'code', '{"language":"python","code":"from collections import deque\n\nclass Solution:\n    def swimInWater(self, grid):\n        n = len(grid)\n\n        # Can we reach the corner using only cells with height <= t?\n        def can_reach(t):\n            if grid[0][0] > t:\n                return False\n\n            visited = {(0, 0)}\n            queue = deque([(0, 0)])\n\n            while queue:\n                r, c = queue.popleft()\n\n                if r == n - 1 and c == n - 1:\n                    return True\n\n                for dr, dc in [\n                    (1, 0), (-1, 0),\n                    (0, 1), (0, -1)\n                ]:\n                    nr, nc = r + dr, c + dc\n\n                    if (\n                        0 <= nr < n and\n                        0 <= nc < n and\n                        (nr, nc) not in visited and\n                        grid[nr][nc] <= t\n                    ):\n                        visited.add((nr, nc))\n                        queue.append((nr, nc))\n\n            return False\n\n        lo, hi = 0, n * n - 1\n\n        while lo < hi:\n            mid = (lo + hi) // 2\n\n            if can_reach(mid):\n                hi = mid\n            else:\n                lo = mid + 1\n\n        return lo","filename":"Python"}'),
  ('fddfd008-317b-7579-b9af-436844fea257', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    int swimInWater(vector<vector<int>>& grid) {\n        int n = grid.size();\n        int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n\n        // Can we reach the corner using only cells with height <= t?\n        auto canReach = [&](int t) {\n            if (grid[0][0] > t) return false;\n\n            vector<vector<bool>> visited(n, vector<bool>(n, false));\n            queue<pair<int, int>> q;\n            q.push({0, 0});\n            visited[0][0] = true;\n\n            while (!q.empty()) {\n                auto [r, c] = q.front();\n                q.pop();\n\n                if (r == n - 1 && c == n - 1) return true;\n\n                for (auto& d : dirs) {\n                    int nr = r + d[0], nc = c + d[1];\n\n                    if (nr >= 0 && nr < n && nc >= 0 && nc < n &&\n                        !visited[nr][nc] && grid[nr][nc] <= t) {\n                        visited[nr][nc] = true;\n                        q.push({nr, nc});\n                    }\n                }\n            }\n\n            return false;\n        };\n\n        int lo = 0, hi = n * n - 1;\n\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;\n\n            if (canReach(mid)) hi = mid;\n            else lo = mid + 1;\n        }\n\n        return lo;\n    }\n};","filename":"C++"}'),
  ('ddf4776f-fba2-7a80-9b4f-961d5c17ea64', 'aD', 'code', '{"language":"java","code":"class Solution {\n    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n\n    public int swimInWater(int[][] grid) {\n        int n = grid.length;\n        int lo = 0, hi = n * n - 1;\n\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;\n\n            if (canReach(grid, mid)) hi = mid;\n            else lo = mid + 1;\n        }\n\n        return lo;\n    }\n\n    // Can we reach the corner using only cells with height <= t?\n    private boolean canReach(int[][] grid, int t) {\n        int n = grid.length;\n        if (grid[0][0] > t) return false;\n\n        boolean[][] visited = new boolean[n][n];\n        Deque<int[]> queue = new ArrayDeque<>();\n        queue.offer(new int[]{0, 0});\n        visited[0][0] = true;\n\n        while (!queue.isEmpty()) {\n            int[] cell = queue.poll();\n            int r = cell[0], c = cell[1];\n\n            if (r == n - 1 && c == n - 1) return true;\n\n            for (int[] d : DIRS) {\n                int nr = r + d[0], nc = c + d[1];\n\n                if (nr >= 0 && nr < n && nc >= 0 && nc < n &&\n                    !visited[nr][nc] && grid[nr][nc] <= t) {\n                    visited[nr][nc] = true;\n                    queue.offer(new int[]{nr, nc});\n                }\n            }\n        }\n\n        return false;\n    }\n}","filename":"Java"}'),
  ('3460c974-1080-79c4-a6c4-d58e53aa9adf', 'aE', 'code', '{"language":"javascript","code":"var swimInWater = function(grid) {\n    const n = grid.length;\n    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];\n\n    // Can we reach the corner using only cells with height <= t?\n    const canReach = (t) => {\n        if (grid[0][0] > t) return false;\n\n        const visited = Array.from({ length: n }, () => new Array(n).fill(false));\n        const queue = [[0, 0]];\n        visited[0][0] = true;\n\n        for (let head = 0; head < queue.length; head++) {\n            const [r, c] = queue[head];\n\n            if (r === n - 1 && c === n - 1) return true;\n\n            for (const [dr, dc] of dirs) {\n                const nr = r + dr, nc = c + dc;\n\n                if (\n                    nr >= 0 && nr < n &&\n                    nc >= 0 && nc < n &&\n                    !visited[nr][nc] && grid[nr][nc] <= t\n                ) {\n                    visited[nr][nc] = true;\n                    queue.push([nr, nc]);\n                }\n            }\n        }\n\n        return false;\n    };\n\n    let lo = 0, hi = n * n - 1;\n\n    while (lo < hi) {\n        const mid = (lo + hi) >> 1;\n\n        if (canReach(mid)) hi = mid;\n        else lo = mid + 1;\n    }\n\n    return lo;\n};","filename":"JavaScript"}'),
  ('97cf13e8-e69d-7a13-aee1-1d403d670afc', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(N^2 log(N^2)) · Aux Space: O(N^2)","marks":[{"type":"bold"}]}]}]}}'),
  ('a5fb6099-da50-7aa4-b06f-b968570efbbd', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]}'),
