  ('092579b2-50c1-7b44-9bbe-f6cf327e6ddc', 'aK', 'code', '{"language":"javascript","code":"class MinHeap {\n    constructor() { this.heap = []; }\n\n    get size() { return this.heap.length; }\n\n    push(item) {\n        const h = this.heap;\n        h.push(item);\n        let i = h.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (h[p][0] <= h[i][0]) break;\n            [h[p], h[i]] = [h[i], h[p]];\n            i = p;\n        }\n    }\n\n    pop() {\n        const h = this.heap;\n        const top = h[0];\n        const last = h.pop();\n        if (h.length) {\n            h[0] = last;\n            let i = 0;\n            while (true) {\n                const l = 2 * i + 1, r = l + 1;\n                let m = i;\n                if (l < h.length && h[l][0] < h[m][0]) m = l;\n                if (r < h.length && h[r][0] < h[m][0]) m = r;\n                if (m === i) break;\n                [h[m], h[i]] = [h[i], h[m]];\n                i = m;\n            }\n        }\n        return top;\n    }\n}\n\nvar swimInWater = function(grid) {\n    const n = grid.length;\n    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];\n\n    const minHeap = new MinHeap();\n    minHeap.push([grid[0][0], 0, 0]);  // [time, r, c]\n\n    const visited = Array.from({ length: n }, () => new Array(n).fill(false));\n    visited[0][0] = true;\n\n    while (minHeap.size) {\n        const [time, r, c] = minHeap.pop();\n\n        if (r === n - 1 && c === n - 1) return time;\n\n        for (const [dr, dc] of dirs) {\n            const nr = r + dr, nc = c + dc;\n\n            if (\n                nr >= 0 && nr < n &&\n                nc >= 0 && nc < n &&\n                !visited[nr][nc]\n            ) {\n                visited[nr][nc] = true;\n                minHeap.push([Math.max(time, grid[nr][nc]), nr, nc]);\n            }\n        }\n    }\n\n    return -1;\n};","filename":"JavaScript"}'),
