            auto [time, r, c] = minHeap.top();
            minHeap.pop();

            if (r == n - 1 && c == n - 1) return time;

            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];

                if (nr >= 0 && nr < n && nc >= 0 && nc < n && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    minHeap.push({max(time, grid[nr][nc]), nr, nc});
                }
            }
        }

        return -1;
    }
};
