i + 1, current, result);\n            current.remove(current.size() - 1);\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"54471a4b-3a1f-7fa9-a21b-0dda875b22c1","type":"code","position":"aK","content":{"language":"javascript","code":"var subsets = function(nums) {\n    const result = [];\n\n    const backtrack = (start, current) => {\n        result.push([...current]);\n\n        for (let i = start; i < nums.length; i++) {\n            current.push(nums[i]);\n            backtrack(i + 1, current);\n            current.pop();\n        }\n    };\n\n    backtrack(0, []);\n    return result;\n};","filename":"JavaScript"},"revision":1},{"id":"d42a1038-7715-756b-b323-a59ff03b4e1d","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n × 2^n) · Aux Space: O(n) · Output Space: O(n × 2^n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"4aef31dd-a763-7445-b0c1-e721926ee960","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"0643b16a-ff4c-7a33-a848-05052a8f1c5a","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both have the same asymptotic complexity. The optimized version has a cleaner subset-generation pattern."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
