SELECT 'e633dc3b-6340-726c-9315-54e35bf3c5de', '396e0dc9-271a-765e-846e-19d1205cdefb', 1, 'PUBLISHED', 'Cheapest Flights Within K Stops', '[{"id":"4c6d3522-0980-7eab-9498-367fd6b7f83a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 787","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/cheapest-flights-within-k-stops/"}}]}]}]}},"revision":1},{"id":"be96ebac-5589-7ea5-b4d7-0326141b9c3f","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"944fdb57-a090-7255-ade4-6029228ab364","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Return cheapest price from "},{"type":"text","text":"src","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"dst","marks":[{"type":"code"}]},{"type":"text","text":" with at most "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" stops. If no path, return -1."}]}]}},"revision":1},{"id":"8c776d39-e995-74b5-96c8-6cc0e879d9b5","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"14ceb0d5-29ce-73fd-a819-da49169e37b9","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Shortest path with step limit constraint (at most K+1 edges). Ideal for Bellman-Ford algorithm!"}]}]}},"revision":1},{"id":"cefac91f-edb9-717a-a31b-b133dd1776e3","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"f3124bbe-0299-775f-af13-8ef8b2767a3d","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bellman-Ford algorithm run K+1 iterations using a copy of previous distances array."}]}]}},"revision":1},{"id":"af863774-8be3-768a-8879-e48267e5646c","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"1798f875-d6cc-7f6c-a5ca-c5daf238b279","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Distance array prices = [inf] * n, prices[src] = 0."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Loop k + 1 times: copy tmp = list(prices). For u, v, w in flights: if prices[u] != inf, update tmp[v] = min(tmp[v], prices[u] + w)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set prices = tmp. Return prices[dst] if prices[dst] != inf else -1."}]}]}]}]}},"revision":1},{"id":"081b6026-0741-7226-91b8-13f8284e20ff","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution"}]},"revision":1},{"id":"40abc4ff-d376-79e6-9a69-05c197c83d7c","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dijkstra-style search over "},{"type":"text","text":"(cost, city, flights taken)","marks":[{"type":"code"}]},{"type":"text","text":" that respects the "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":"-stop limit but keeps no visited set, so the same city can be expanded many times — correct, but it may explore every route of up to "},{"type":"text","text":"k + 1","marks":[{"type":"code"}]},{"type":"text","text":" flights."}]}]}},"revision":1},{"id":"3073db97-d8e4-73c8-917a-3118ebe022bd","type":"code","position":"aB","content":{"language":"python","code":"import heapq\n\nclass Solution:\n    def findCheapestPrice(self, n, flights, src, dst, k):\n        graph = [[] for _ in range(n)]\n\n        for u, v, price in flights:\n            graph[u].append((v, price))\n\n        # (cost, node, flights taken) - no visited set, so states can repeat\n        min_heap = [(0, src, 0)]\n\n        while min_heap:\n            cost, node, used = heapq.heappop(min_heap)\n\n            if node == dst:\n                return cost\n\n            if used > k:\n                continue  # at most k stops = k + 1 flights\n\n            for nxt, price in graph[node]:\n                heapq.heappush(min_heap, (cost + price, nxt, used + 1))\n\n        return -1","filename":"Python"},"revision":1},{"id":"769759d0-aeae-7605-87ec-cda6539cb1ed","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int findCheapestPrice(int n, vector<vector<int>>& flights, int src, int dst, int k) {\n        vector<vector<pair<int, int>>> graph(n);\n        for (auto& f : flights)\n            graph[f[0]].push_back({f[1], f[2]});\n\n        // (cost, node, flights taken) - no visited set, so states can repeat\n        priority_queue<array<int, 3>, vector<array<int, 3>>, greater<>> minHeap;\n        minHeap.push({0, src, 0});\n\n        while (!minHeap.empty()) {\n            auto [cost, node, used] = minHeap.top();\n            minHeap.pop();\n\n            if (node == dst) return cost;\n            if (used > k) continue;  // at most k stops = k + 1 flights\n\n            for (auto& [next, price] : graph[node])\n                minHeap.push({cost + price, next, used + 1});\n        }\n\n        return -1;\n    }\n};","filename":"C++"},"revision":1},{"id":"23f33331-a386-7587-9283-c5e0357dc724","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) {\n        List<List<int[]>> graph = new ArrayList<>();\n        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());\n        for (int[] f : flights)\n            graph.get(f[0]).add(new int[]{f[1], f[2]});\n\n        // {cost, node, flights taken} - no visited set, so states can repeat\n        PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));\n        minHeap.offer(new int[]{0, src, 0});\n\n        while (!minHeap.isEmpty()) {\n            int[] top = minHeap.poll();\n            int cost = top[0], node = top[1], used = top[2];\n\n            if (node == dst) return cost;\n            if (used > k) continue;  // at most k stops = k + 1 flights\n\n            for (int[] edge : graph.get(node))\n                minHeap.offer(new int[]{cost + edge[1], edge[0], used + 1});\n        }\n\n        return -1;\n    }\n}","filename":"Java"},"revision":1},{"id":"3ea0d937-6603-7aba-bf5a-4d2a7e9a830a","type":"code","position":"aE","content":{"language":"javascript","code":"class MinHeap {\n    constructor() { this.heap = []; }\n\n    get size() { return this.heap.length; }\n\n    push(item) {\n        const h = this.heap;\n        h.push(item);\n        let i = h.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (h[p][0] <= h[i][0]) break;\n            [h[p], h[i]] = [h[i], h[p]];\n            i = p;\n        }\n    }\n\n    pop() {\n        const h = this.heap;\n        const top = h[0];\n        const last = h.pop();\n        if (h.length) {\n            h[0] = last;\n            let i = 0;\n            while (true) {\n                const l = 2 * i + 1, r = l + 1;\n                let m = i;\n                if (l < h.length && h[l][0] < h[m][0]) m = l;\n                if (r < h.length && h[r][0] < h[m][0]) m = r;\n                if (m === i) break;\n                [h[m], h[i]] = [h[i], h[m]];\n                i = m;\n            }\n        }\n        return top;\n    }\n}\n\nvar findCheapestPrice = function(n, flights, src, dst, k) {\n    const graph = Array.from({ length: n }, () => []);\n    for (const [u, v, price] of flights)\n        graph[u].push([v, price]);\n\n    // [cost, node, flights taken] - no visited set, so states can repeat\n    const minHeap = new MinHeap();\n    minHeap.push([0, src, 0]);\n\n    while (minHeap.size) {\n        const [cost, node, used] = minHeap.pop();\n\n        if (node === dst) return cost;\n        if (used > k) continue;  // at most k stops = k + 1 flights\n\n        for (const [next, price] of graph[node])\n            minHeap.push([cost + price, next, used + 1]);\n    }\n\n    return -1;\n};","filename":"JavaScript"},"revision":1},{"id":"32c04068-d21a-74e2-a0de-57a87ca9b65b","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(d^(k+1) · log) — d = max flights out of a city · Aux Space: O(d^(k+1))","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"eefe5eba-b3c6-7e89-8446-e5877edf07db","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"95a6d275-e3af-7393-82b0-d3d2298bfa4e","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def findCheapestPrice(self, n, flights, src, dst, k):\n        prices = [float(\"inf\")] * n\n        prices[src] = 0\n\n        for _ in range(k + 1):\n            tmp = list(prices)\n\n            for u, v, price in flights:\n                if prices[u] == float(\"inf\"):\n                    continue\n\n                if prices[u] + price < tmp[v]:\n                    tmp[v] = prices[u] + price\n\n            prices = tmp\n\n        if prices[dst] != float(\"inf\"):\n            return prices[dst]\n\n        return -1","filename":"Python"},"revision":1},{"id":"9dea9d32-f9cc-752c-a937-dad782baa034","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int findCheapestPrice(int n, vector<vector<int>>& flights, int src, int dst, int k) {\n        const int INF = INT_MAX;\n        vector<int> prices(n, INF);\n        prices[src] = 0;\n\n        for (int i = 0; i <= k; i++) {\n            vector<int> tmp = prices;\n\n            for (auto& f : flights) {\n                int u = f[0], v = f[1], price = f[2];\n\n                if (prices[u] == INF) continue;\n\n                if (prices[u] + price < tmp[v])\n                    tmp[v] = prices[u] + price;\n            }\n\n            prices = tmp;\n        }\n\n        return prices[dst] != INF ? prices[dst] : -1;\n    }\n};","filename":"C++"},"revision":1},{"id":"c0b36c6c-154f-7454-af06-e7d61de4aab0","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) {\n        final int INF = Integer.MAX_VALUE;\n        int[] prices = new int[n];\n        Arrays.fill(prices, INF);\n        prices[src] = 0;\n\n        for (int i = 0; i <= k; i++) {\n            int[] tmp = prices.clone();\n\n            for (int[] f : flights) {\n                int u = f[0], v = f[1], price = f[2];\n\n                if (prices[u] == INF) continue;\n\n                if (prices[u] + price < tmp[v])\n                    tmp[v] = prices[u] + price;\n            }\n\n            prices = tmp;\n        }\n\n        return prices[dst] != INF ? prices[dst] : -1;\n    }\n}","filename":"Java"},"revision":1},{"id":"f19f3f40-56d1-7682-a239-1d93c6bdbcc7","type":"code","position":"aK","content":{"language":"javascript","code":"var findCheapestPrice = function(n, flights, src, dst, k) {\n    let prices = new Array(n).fill(Infinity);\n    prices[src] = 0;\n\n    for (let i = 0; i <= k; i++) {\n        const tmp = [...prices];\n\n        for (const [u, v, price] of flights) {\n            if (prices[u] === Infinity) continue;\n\n            if (prices[u] + price < tmp[v]) tmp[v] = prices[u] + price;\n        }\n\n        prices = tmp;\n    }\n\n    return prices[dst] !== Infinity ? prices[dst] : -1;\n};","filename":"JavaScript"},"revision":1},{"id":"93ab71ad-2cf2-7b46-b909-c772140099dd","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(K × E) · Aux Space: O(V)","marks":[{"type":"bold"}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
