from collections import Counter

class Solution:
    def exist(self, board, word):
        rows = len(board)
        cols = len(board[0])

        board_count = Counter(
            cell
            for row in board
            for cell in row
        )

        word_count = Counter(word)

        for char, count in word_count.items():
            if board_count[char] < count:
                return False

        # Start from the rarer character
        if board_count[word[0]] > board_count[word[-1]]:
            word = word[::-1]

        def dfs(r, c, index):
            if index == len(word):
                return True

            if (
                r < 0 or r >= rows or
                c < 0 or c >= cols or
                board[r][c] != word[index]
            ):
                return False

            temp = board[r][c]
            board[r][c] = ''#''

            found = (
                dfs(r + 1, c, index + 1) or
                dfs(r - 1, c, index + 1) or
                dfs(r, c + 1, index + 1) or
                dfs(r, c - 1, index + 1)
            )

            board[r][c] = temp
            return found

        for r in range(rows):
            for c in range(cols):
                if board[r][c] == word[0]:
                    if dfs(r, c, 0):
                        return True

        return False
class Solution {
public:
    bool exist(vector<vector<char>>& board, string word) {
        int rows = board.size();
        int cols = board[0].size();

        unordered_map<char, int> boardCount, wordCount;
        for (auto& row : board)
            for (char cell : row) boardCount[cell]++;
        for (char ch : word) wordCount[ch]++;

        for (auto& [ch, count] : wordCount) {
            if (boardCount[ch] < count) return false;
        }

        // Start from the rarer character
        if (boardCount[word[0]] > boardCount[word.back()]) {
            reverse(word.begin(), word.end());
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == word[0]) {
                    if (dfs(board, word, r, c, 0)) return true;
                }
            }
        }

        return false;
    }

private:
    bool dfs(vector<vector<char>>& board, const string& word, int r, int c, int index) {
        if (index == (int)word.size()) return true;

        if (r < 0 || r >= (int)board.size() ||
            c < 0 || c >= (int)board[0].size() ||
            board[r][c] != word[index]) {
            return false;
        }

