idth = right - left + 1;\n            answer = max(answer, heights[i] * width);\n        }\n        return answer;\n    }\n};","filename":"C++"},"revision":1},{"id":"a0c8bea1-8d44-7745-9218-6f782263fdb4","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int largestRectangleArea(int[] heights) {\n        int answer = 0;\n        int n = heights.length;\n        for (int i = 0; i < n; i++) {\n            int left = i, right = i;\n            while (left - 1 >= 0 && heights[left - 1] >= heights[i]) left--;\n            while (right + 1 < n && heights[right + 1] >= heights[i]) right++;\n            int width = right - left + 1;\n            answer = Math.max(answer, heights[i] * width);\n        }\n        return answer;\n    }\n}","filename":"Java"},"revision":1},{"id":"4686aeae-c7cb-7e36-84df-1f327a0ec724","type":"code","position":"aE","content":{"language":"javascript","code":"var largestRectangleArea = function(heights) {\n    let answer = 0;\n    const n = heights.length;\n    for (let i = 0; i < n; i++) {\n        let left = i, right = i;\n        while (left - 1 >= 0 && heights[left - 1] >= heights[i]) left--;\n        while (right + 1 < n && heights[right + 1] >= heights[i]) right++;\n        const width = right - left + 1;\n        answer = Math.max(answer, heights[i] * width);\n    }\n    return answer;\n};","filename":"JavaScript"},"revision":1},{"id":"e1d65f2e-3a5d-7402-8de2-d8c70e830c15","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n²) · Space: O(1) aux","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"68bae3af-5b36-7397-a7d3-5e6e1990bbcc","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"fb269f1d-5342-707e-8ee0-f662c79dbd69","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def largestRectangleArea(self, heights):\n\n        stack = []\n        answer = 0\n\n        heights.append(0)\n\n        for i, height in enumerate(heights):\n\n            while (\n                stack\n                and heights[stack[-1]] > height\n            ):\n                h = heights[stack.pop()]\n\n                left_boundary = (\n                    stack[-1]\n                    if stack\n                    else -1\n                )\n\n                width = (\n                    i\n                    - left_boundary\n                    - 1\n                )\n\n                answer = max(\n                    answer,\n                    h * width\n                )\n\n            stack.append(i)\n\n        heights.pop()\n\n        return answer","filename":"Python"},"revision":1},{"id":"ee07be49-583e-7b76-8e99-077de34a5e71","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int largestRectangleArea(vector<int>& heights) {\n        stack<int> st;\n        int answer = 0;\n        heights.push_back(0);\n        for (int i = 0; i < heights.size(); i++) {\n            while (!st.empty() && heights[st.top()] > heights[i]) {\n                int h = heights[st.top()];\n                st.pop();\n                int leftBoundary = st.empty() ? -1 : st.top();\n                int width = i - leftBoundary - 1;\n                answer = max(answer, h * width);\n            }\n            st.push(i);\n        }\n        heights.pop_back();\n        return answer;\n    }\n};","filename":"C++"},"revision":1},{"id":"e0a9fefe-2d28-7ba3-805c-20f22dae8e07","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public int largestRectangleArea(int[] heights) {\n        Deque<Integer> stack = new ArrayDeque<>();\n        int answer = 0;\n        int n = heights.length;\n        for (int i = 0; i <= n; i++) {\n            int height = i == n ? 0 : heights[i]; // sentinel 0 at the end\n            while (!stack.isEmpty() && heights[stack.peek()] > height) {\n                int h = heights[stack.pop()];\n                int leftBoundary = stack.isEmpty() ? -1 : stack.peek();\n                int width = i - leftBoundary - 1;\n                answer = Math.max(answer, h * width);\n            }\n            stack.push(i);\n        }\n        return answer;\n    }\n}","filename":"Java"},"revision":1},{"id":"300e3274-f472-7157-8c52-bda99f0bf301","type":"code","position":"aK","content":{"language":"javascript","code":"var largestRectangleArea = function(heights) {\n    const stack = [];\n    let answer = 0;\n    heights.push(0);\n    for (let i = 0; i < heights.length; i++) {\n        while (stack.length && heights[stack[stack.length - 1]] > heights[i]) {\n            const h = heights[stack.pop()];\n            const leftBoundary = stack.length ? stack[stack.length - 1] : -1;\n            const width = i - leftBoundary - 1;\n            answer = Math.max(answer, h * width);\n        }\n        stack.push(i);\n    }\n    heights.pop();\n    return answer;\n};","filename":"JavaScript"},"revision":1},{"id":"08baebae-c268-760a-91fc-9e12fb64dfb2","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Space: O(n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"cb34fb51-025e-70a9-b541-bef7f3dc449f","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"8b12062c-d342-7ad9-89ca-96e47f3c3b21","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Next / Previous Smaller Element → Monotonic Increasing Stack"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
