  ('0c573fcf-73cc-763a-8b23-6be28527f4af', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sort, then repeatedly remove groups starting from the smallest element using "},{"type":"text","text":"list.remove()","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('b9157a12-d42c-7d21-9b27-1982a73b7f98', 'aB', 'code', '{"language":"python","code":"class Solution:\n    def isNStraightHand(self, hand, groupSize):\n        if len(hand) % groupSize != 0:\n            return False\n\n        hand.sort()\n\n        while hand:\n            first = hand[0]\n\n            for value in range(first, first + groupSize):\n                if value not in hand:\n                    return False\n\n                hand.remove(value)\n\n        return True","filename":"Python"}'),
  ('258f5693-656e-758b-b56a-1d2513d12e5e', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    bool isNStraightHand(vector<int>& hand, int groupSize) {\n        if (hand.size() % groupSize != 0) {\n            return false;\n        }\n\n        sort(hand.begin(), hand.end());\n\n        while (!hand.empty()) {\n            int first = hand[0];\n\n            for (int value = first; value < first + groupSize; value++) {\n                auto it = find(hand.begin(), hand.end(), value);\n                if (it == hand.end()) {\n                    return false;\n                }\n\n                hand.erase(it);\n            }\n        }\n\n        return true;\n    }\n};","filename":"C++"}'),
  ('23d79c23-80d9-7c83-aa2e-df6e4309ec86', 'aD', 'code', '{"language":"java","code":"class Solution {\n    public boolean isNStraightHand(int[] hand, int groupSize) {\n        if (hand.length % groupSize != 0) {\n            return false;\n        }\n\n        Arrays.sort(hand);\n        List<Integer> cards = new ArrayList<>();\n        for (int card : hand) {\n            cards.add(card);\n        }\n\n        while (!cards.isEmpty()) {\n            int first = cards.get(0);\n\n            for (int value = first; value < first + groupSize; value++) {\n                if (!cards.contains(value)) {\n                    return false;\n                }\n\n                cards.remove(Integer.valueOf(value));\n            }\n        }\n\n        return true;\n    }\n}","filename":"Java"}'),
  ('97fcd3a3-d408-7ac3-b8f3-2be2ad22c856', 'aE', 'code', '{"language":"javascript","code":"var isNStraightHand = function(hand, groupSize) {\n    if (hand.length % groupSize !== 0) {\n        return false;\n    }\n\n    hand.sort((a, b) => a - b);\n\n    while (hand.length > 0) {\n        const first = hand[0];\n\n        for (let value = first; value < first + groupSize; value++) {\n            const index = hand.indexOf(value);\n            if (index === -1) {\n                return false;\n            }\n\n            hand.splice(index, 1);\n        }\n    }\n\n    return true;\n};","filename":"JavaScript"}'),
  ('683b8d70-d0ae-713f-8720-7128314b1506', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n²) — list.remove() is O(n) · Space: O(1) auxiliary","marks":[{"type":"bold"}]}]}]}}'),
  ('ed39424d-93ac-776d-8f92-426dc8e81285', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]}'),
  ('ba260278-efd7-7996-b623-659a9a53c1db', 'aH', 'code', '{"language":"python","code":"from collections import Counter\n\nclass Solution:\n    def isNStraightHand(self, hand, groupSize):\n        if len(hand) % groupSize != 0:\n            return False\n\n        count = Counter(hand)\n\n        for first in sorted(count):\n            if count[first] == 0:\n                continue\n\n            frequency = count[first]\n\n            for value in range(first, first + groupSize):\n                if count[value] < frequency:\n                    return False\n\n                count[value] -= frequency\n\n        return True","filename":"Python"}'),
  ('7b117a8a-de58-7b48-acd1-43b7d3403017', 'aI', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    bool isNStraightHand(vector<int>& hand, int groupSize) {\n        if (hand.size() % groupSize != 0) {\n            return false;\n        }\n\n        map<int, int> count;  // ordered by card value\n        for (int card : hand) {\n            count[card]++;\n        }\n\n        for (auto& [first, freq] : count) {\n            if (freq == 0) {\n                continue;\n            }\n\n            int frequency = freq;\n\n            for (int value = first; value < first + groupSize; value++) {\n                if (count[value] < frequency) {\n                    return false;\n                }\n\n                count[value] -= frequency;\n            }\n        }\n\n        return true;\n    }\n};","filename":"C++"}'),
  ('18533dd7-362b-7bc4-bff7-51f3c0a12e92', 'aJ', 'code', '{"language":"java","code":"class Solution {\n    public boolean isNStraightHand(int[] hand, int groupSize) {\n        if (hand.length % groupSize != 0) {\n            return false;\n        }\n\n        TreeMap<Integer, Integer> count = new TreeMap<>();\n        for (int card : hand) {\n            count.merge(card, 1, Integer::sum);\n        }\n\n        for (int first : new ArrayList<>(count.keySet())) {\n            if (count.get(first) == 0) {\n                continue;\n            }\n\n            int frequency = count.get(first);\n\n            for (int value = first; value < first + groupSize; value++) {\n                if (count.getOrDefault(value, 0) < frequency) {\n                    return false;\n                }\n\n                count.put(value, count.get(value) - frequency);\n            }\n        }\n\n        return true;\n    }\n}","filename":"Java"}'),
  ('3da789ca-be5c-7443-a49e-d2bc66f1111c', 'aK', 'code', '{"language":"javascript","code":"var isNStraightHand = function(hand, groupSize) {\n    if (hand.length % groupSize !== 0) {\n        return false;\n    }\n\n    const count = new Map();\n    for (const card of hand) {\n        count.set(card, (count.get(card) || 0) + 1);\n    }\n\n    const keys = [...count.keys()].sort((a, b) => a - b);\n\n    for (const first of keys) {\n        if (count.get(first) === 0) {\n            continue;\n        }\n\n        const frequency = count.get(first);\n\n        for (let value = first; value < first + groupSize; value++) {\n            if ((count.get(value) || 0) < frequency) {\n                return false;\n            }\n\n            count.set(value, count.get(value) - frequency);\n        }\n    }\n\n    return true;\n};","filename":"JavaScript"}'),
  ('d23cd14f-01d8-7d99-91f2-e722ebe3e71c', 'aL', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n log n) — dominated by sort of unique keys · Space: O(n)","marks":[{"type":"bold"}]}]}]}}'),
  ('75884a32-1757-7c27-b6c4-e3271f501917', 'aM', 'heading', '{"level":1,"content":[{"type":"text","text":"Takeaway"}]}'),
