"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":". Optimize space to "},{"type":"text","text":"prev1","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"prev2","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"eec02a56-326d-7ea1-a752-0c49bb795385","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"f20f2289-2fad-7ca8-91db-b34717573545","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If empty string or starts with "},{"type":"text","text":"''0''","marks":[{"type":"code"}]},{"type":"text","text":", return 0."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Maintain "},{"type":"text","text":"prev2 = 1","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"prev1 = 1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For index "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" from 1 to "},{"type":"text","text":"len(s)-1","marks":[{"type":"code"}]},{"type":"text","text":": if "},{"type":"text","text":"s[i] != ''0''","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"current += prev1","marks":[{"type":"code"}]},{"type":"text","text":". If "},{"type":"text","text":"10 <= int(s[i-1:i+1]) <= 26","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"current += prev2","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Shift "},{"type":"text","text":"prev2 = prev1","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"prev1 = current","marks":[{"type":"code"}]},{"type":"text","text":". Return "},{"type":"text","text":"prev1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"ef650632-a879-7b52-a385-81e1a0de1122","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Recursion"}]},"revision":1},{"id":"7429ec49-19bb-7c49-994b-63b94c995e34","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursively try single digit and double digit decodings from index "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"bd658043-3202-7b84-80b4-21046c9303e7","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def numDecodings(self, s):\n\n        def dfs(i):\n            if i == len(s):\n                return 1\n\n            if s[i] == \"0\":\n                return 0\n\n            result = dfs(i + 1)\n\n            if (\n                i + 1 < len(s)\n                and 10 <= int(s[i:i + 2]) <= 26\n            ):\n                result += dfs(i + 2)\n\n            return result\n\n        return dfs(0)","filename":"Python"},"revision":1},{"id":"30ec8f26-50eb-7ce2-b80e-b0abe73fa242","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int numDecodings(string s) {\n        return dfs(s, 0);\n    }\n\nprivate:\n    int dfs(const string& s, int i) {\n        if (i == (int)s.size()) return 1;\n        if (s[i] == ''0'') return 0;\n\n        int result = dfs(s, i + 1);\n\n        if (i + 1 < (int)s.size()) {\n            int twoDigit = stoi(s.substr(i, 2));\n            if (twoDigit >= 10 && twoDigit <= 26) {\n                result += dfs(s, i + 2);\n            }\n        }\n\n        return result;\n    }\n};","filename":"C++"},"revision":1},{"id":"e6c1b72b-71c0-721c-9d48-b3f4170698c7","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int numDecodings(String s) {\n        return dfs(s, 0);\n    }\n\n    private int dfs(String s, int i) {\n        if (i == s.length()) return 1;\n        if (s.charAt(i) == ''0'') return 0;\n\n        int result = dfs(s, i + 1);\n\n        if (i + 1 < s.length()) {\n            int twoDigit = Integer.parseInt(s.substring(i, i + 2));\n            if (twoDigit >= 10 && twoDigit <= 26) {\n                result += dfs(s, i + 2);\n            }\n        }\n\n        return result;\n    }\n}","filename":"Java"},"revision":1},{"id":"d69e2fd2-daa9-7711-91f7-2b68e9056fd3","type":"code","position":"aE","content":{"language":"javascript","code":"var numDecodings = function(s) {\n    const dfs = (i) => {\n        if (i === s.length) return 1;\n        if (s[i] === \"0\") return 0;\n\n        let result = dfs(i + 1);\n\n        if (i + 1 < s.length) {\n            const twoDigit = Number(s.slice(i, i + 2));\n            if (twoDigit >= 10 && twoDigit <= 26) {\n                result += dfs(i + 2);\n            }\n        }\n\n        return result;\n    };\n\n    return dfs(0);\n};","filename":"JavaScript"},"revision":1},{"id":"a21c6501-3d8a-7959-8df2-a15bc1c1077e","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(2^n) · Aux Space: O(n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"04124ca9-8b0d-7875-bbcc-807832808365","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"8f5e0582-eb20-794b-bfe1-d224059e28b9","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def numDecodings(self, s):\n        n = len(s)\n\n        if not s or s[0] == \"0\":\n            return 0\n\n        dp = [0] * (n + 1)\n        dp[0] = 1\n        dp[1] = 1\n\n        for i in range(2, n + 1):\n\n            if s[i - 1] != \"0\":\n        