 )\n\n        def max_value(node):\n            if not node:\n                return -float(\"inf\")\n            return max(\n                node.val,\n                max_value(node.left),\n                max_value(node.right)\n            )\n\n        def check(node):\n            if not node:\n                return True\n\n            left_max = max_value(node.left)\n            right_min = min_value(node.right)\n\n            if node.val <= left_max or node.val >= right_min:\n                return False\n\n            return check(node.left) and check(node.right)\n\n        return check(root)","filename":"Python"},"revision":1},{"id":"3ccea5d8-897e-7eb8-a4d7-db21b850bcce","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    bool isValidBST(TreeNode* root) {\n        return check(root);\n    }\n\nprivate:\n    long long minValue(TreeNode* node) {\n        if (!node) return LLONG_MAX;\n        return min({(long long)node->val, minValue(node->left), minValue(node->right)});\n    }\n\n    long long maxValue(TreeNode* node) {\n        if (!node) return LLONG_MIN;\n        return max({(long long)node->val, maxValue(node->left), maxValue(node->right)});\n    }\n\n    bool check(TreeNode* node) {\n        if (!node) return true;\n\n        long long leftMax = maxValue(node->left);\n        long long rightMin = minValue(node->right);\n\n        if (node->val <= leftMax || node->val >= rightMin) return false;\n\n        return check(node->left) && check(node->right);\n    }\n};","filename":"C++"},"revision":1},{"id":"95ed733e-ae4d-740a-bfdf-f9dc6af2ebe7","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public boolean isValidBST(TreeNode root) {\n        return check(root);\n    }\n\n    private long minValue(TreeNode node) {\n        if (node == null) return Long.MAX_VALUE;\n        return Math.min(node.val, Math.min(minValue(node.left), minValue(node.right)));\n    }\n\n    private long maxValue(TreeNode node) {\n        if (node == null) return Long.MIN_VALUE;\n        return Math.max(node.val, Math.max(maxValue(node.left), maxValue(node.right)));\n    }\n\n    private boolean check(TreeNode node) {\n        if (node == null) return true;\n\n        long leftMax = maxValue(node.left);\n        long rightMin = minValue(node.right);\n\n        if (node.val <= leftMax || node.val >= rightMin) return false;\n\n        return check(node.left) && check(node.right);\n    }\n}","filename":"Java"},"revision":1},{"id":"8b83b5ff-5459-7a4c-bddb-bca4ed3c5a8c","type":"code","position":"aE","content":{"language":"javascript","code":"var isValidBST = function(root) {\n    const minValue = (node) => {\n        if (!node) return Infinity;\n        return Math.min(node.val, minValue(node.left), minValue(node.right));\n    };\n\n    const maxValue = (node) => {\n        if (!node) return -Infinity;\n        return Math.max(node.val, maxValue(node.left), maxValue(node.right));\n    };\n\n    const check = (node) => {\n        if (!node) return true;\n\n        const leftMax = maxValue(node.left);\n        const rightMin = minValue(node.right);\n\n        if (node.val <= leftMax || node.val >= rightMin) return false;\n\n        return check(node.left) && check(node.right);\n    };\n\n    return check(root);\n};","filename":"JavaScript"},"revision":1},{"id":"f5a7aae7-c64c-7946-b0f2-4c1c6ba051cd","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n^2) worst case · Aux Space: O(h)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"da441095-09ca-7845-8fad-529defa0a8bc","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"9d01ca21-4bc2-7e3e-a330-d5ebc1372202","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def isValidBST(self, root):\n\n        def dfs(node, low, high):\n            if not node:\n                return True\n\n            if not (low < node.val < high):\n                return False\n\n            return (\n                dfs(node.left, low, node.val)\n                and\n                dfs(node.right, node.val, high)\n            )\n\n        return dfs(root, -float(\"inf\"), float(\"inf\"))","filename":"Python"},"revision":1},{"id":"88829039-c198-7355-969a-828fb5ea578f","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    bool isValidBST(TreeNode* root) {\n        return dfs(root, LLONG_MIN, LLONG_MAX);\n    }\n\nprivate:\n    bool dfs(TreeNode* node, long long low, long long high) {\n        if (!node) return true;\n\n        if (!(low < node->val && node->val < high)) return false;\n\n        return dfs(node->left, low, node->val) && dfs(node->right, node->val, high);\n    }\n};","filename":"C++"},"revision":1},{"id":"b36c161a-e70c-7a5d-815c-52684c946944","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public boolean isValidBST(TreeNode root) {\n        return dfs(root, Long.MIN_VALUE, Long.MAX_VALUE);\n    }\n\n    private boolean dfs(TreeNode node, long low, long high) {\n        if (node == null) return true;\n\n        if (!(low < node.val && node.val < high)) return false;\n\n        return dfs(node.left, low, node.val) && dfs(node.right, node.val, high);\n    }\n}","filename":"Java"},"revision":1},{"id":"5a1be0c5-d8f6-73a6-851a-e40e7bfe88f3","type":"code","position":"aK","content":{"language":"javascript","code":"var isValidBST = function(root) {\n    const dfs = (node, low, high) => {\n        if (!node) return true;\n\n        if (!(low < node.val && node.val < high)) return false;\n\n        return dfs(node.left, low, node.val) && dfs(node.right, node.val, high);\n    };\n\n    return dfs(root, -Infinity, Infinity);\n};","filename":"JavaScript"},"revision":1},{"id":"2e88760f-675c-7033-9913-eb4df02fad32","