timestamp $\\le$ requested timestamp."}]}]}},"revision":1},{"id":"82ca149d-7de4-796e-88de-c351f64e9ec4","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"e1407608-9891-7c11-aea5-7f0e585881d9","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"set(key, val, time)","marks":[{"type":"code"}]},{"type":"text","text":": append "},{"type":"text","text":"(time, val)","marks":[{"type":"code"}]},{"type":"text","text":" to list "},{"type":"text","text":"store[key]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"get(key, target_time)","marks":[{"type":"code"}]},{"type":"text","text":": binary search "},{"type":"text","text":"values = store[key]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"While "},{"type":"text","text":"left <= right","marks":[{"type":"code"}]},{"type":"text","text":":"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"values[mid][0] <= target_time","marks":[{"type":"code"}]},{"type":"text","text":": record "},{"type":"text","text":"answer = values[mid][1]","marks":[{"type":"code"}]},{"type":"text","text":" and search right "},{"type":"text","text":"left = mid + 1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Else: search left "},{"type":"text","text":"right = mid - 1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"answer","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"465b22f2-6005-772d-b3da-41dc7289165e","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]},"revision":1},{"id":"04760a57-8e6f-7cc5-964e-1acc5703a9f8","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Store list of "},{"type":"text","text":"(timestamp, value)","marks":[{"type":"code"}]},{"type":"text","text":" tuples and scan backward linearly on "},{"type":"text","text":"get()","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"995e11c4-eab4-7d72-862f-be7f168ca763","type":"code","position":"aB","content":{"language":"python","code":"class TimeMap:\n\n    def __init__(self):\n        self.store = {}\n\n    def set(self, key, value, timestamp):\n\n        if key not in self.store:\n            self.store[key] = []\n\n        self.store[key].append(\n            (timestamp, value)\n        )\n\n    def get(self, key, timestamp):\n\n        if key not in self.store:\n            return \"\"\n\n        result = \"\"\n\n        for time, value in reversed(\n            self.store[key]\n        ):\n            if time <= timestamp:\n                return value\n\n        return result","filename":"Python"},"revision":1},{"id":"70440c86-2bbf-7a45-92a0-9fcb90ec8bcf","type":"code","position":"aC","content":{"language":"cpp","code":"class TimeMap {\n    unordered_map<string, vector<pair<int, string>>> store;\n\npublic:\n    TimeMap() {}\n\n    void set(string key, string value, int timestamp) {\n        store[key].push_back({timestamp, value});\n    }\n\n    string get(string key, int timestamp) {\n        auto it = store.find(key);\n        if (it == store.end()) {\n            return \"\";\n        }\n\n        const auto& values = it->second;\n\n        for (int i = values.size() - 1; i >= 0; i--) {\n            if (values[i].first <= timestamp) {\n                return values[i].second;\n            }\n        }\n\n        return \"\";\n    }\n};","filename":"C++"},"revision":1},{"id":"0f51d63a-67b4-7691-9fde-76e104f12cfe","type":"code","position":"aD","content":{"language":"java","code":"class TimeMap {\n    private Map<String, List<Pair>> store;\n\n    private static class Pair {\n        int time;\n        String value;\n\n        Pair(int time, String value) {\n            this.time = time;\n            this.value = value;\n        }\n    }\n\n    public TimeMap() {\n        store = new HashMap<>();\n    }\n\n    public void set(String key, String value, int timestamp) {\n        store.computeIfAbsent(key, k -> new ArrayList<>()).add(new Pair(timestamp, value));\n    }\n\n    public String get(String key, int timestamp) {\n        if (!store.containsKey(key)) {\n            return \"\";\n        }\n\n        List<Pair> values = store.get(key);\n\n        for (int i = values.size() - 1; i >= 0; i--) {\n            if (values.get(i).time <= timestamp) {\n                return values.get(i).value;\n            }\n        }\n\n        return \"\";\n    }\n}","filename":"Java"},"revision":1},{"id":"b001e24a-156e-7377-91e5-929e7d5f6e92","type":"code","position":"aE","content":{"language":"javascript","code":"class TimeMap {\n    constructor() {\n        this.store = new Map();\n    }\n\n    set(key, value, timestamp) {\n        if (!this.store.has(key)) {\n            this.store.set(key, []);\n        }\n\n        this.store.get(key).push([timestamp, value]);\n    }\n\n    get(key, timestamp) {\n        if (!this.store.has(key)) {\n            return \"\";\n        }\n\n        const values = this.store.get(key);\n\n        for (let i = values.length - 1; i >= 0; i--) {\n            if (values[i][0] <= timestamp) {\n                return values[i][1];\n            }\n        }\n\n        return \"\";\n    }\n}","filename":"JavaScript"},"revision":1},{"id":"98d3112d-a109-7256-888c-26ebc1e55c28","type":"text","position":"aF","content":{