  ('fb38600d-b491-786d-99d2-cba80e5cf2e6', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 994","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/rotting-oranges/"}}]}]}]}}'),
