  ('b2fed9e8-34eb-7b1b-b51c-e6c8ba81da19', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Return minimum minutes that must elapse until no cell has a fresh orange. If impossible return -1."}]}]}}'),
  ('09a55625-a328-7e63-bfd5-7da7bb569210', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]}'),
  ('6a3c7883-21e1-7502-8280-d7cff6cb9478', 'a4', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Multi-source BFS where all rotten oranges start in queue at minute 0 and rot adjacent fresh oranges simultaneously."}]}]}}'),
  ('3b768c0f-e006-7231-9ba4-f6444a8d28eb', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"Intuition"}]}'),
  ('89ff922c-bcc9-71f6-84e1-4fd76b923971', 'a6', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Multi-source BFS starting from all rotten oranges simultaneously."}]}]}}'),
  ('2bbeeafb-75ed-70d8-abd7-3efff99156da', 'a7', 'heading', '{"level":1,"content":[{"type":"text","text":"Approach"}]}'),
  ('7e44f07a-cff3-7679-adcd-d1d4269055be', 'a8', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enqueue all rotten oranges (val=2), count total fresh oranges (val=1)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"While queue and fresh > 0: increment minutes, rot fresh neighbors, push to queue, decrement fresh count."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return minutes if fresh == 0 else -1."}]}]}]}]}}'),
  ('c82cb0df-11e3-775e-a7ca-184c41162b2f', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"Naive Solution"}]}'),
  ('cc5983ad-baca-7ad3-ace5-93d8a193974b', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Scan full grid minute-by-minute."}]}]}}'),
  ('a814b59b-3005-78ae-ad02-684ca0f5dd06', 'aB', 'code', '{"language":"python","code":"class Solution:\n    def orangesRotting(self, grid):\n        rows = len(grid)\n        cols = len(grid[0])\n\n        minutes = 0\n\n        # Each minute, rescan the whole grid and rot neighbours of rotten oranges\n        while True:\n            changed = False\n\n            for r in range(rows):\n                for c in range(cols):\n                    if grid[r][c] != 2:\n                        continue\n\n                    for dr, dc in [\n                        (1, 0), (-1, 0),\n                        (0, 1), (0, -1)\n                    ]:\n                        nr, nc = r + dr, c + dc\n\n                        if (\n                            0 <= nr < rows and\n                            0 <= nc < cols and\n                            grid[nr][nc] == 1\n                        ):\n                            grid[nr][nc] = 3  # rots this minute, spreads next minute\n                            changed = True\n\n            if not changed:\n                break\n\n            for row in grid:\n                for c in range(cols):\n                    if row[c] == 3:\n                        row[c] = 2\n\n            minutes += 1\n\n        for row in grid:\n            if 1 in row:\n                return -1\n\n        return minutes","filename":"Python"}'),
  ('df776eef-660c-7788-a19a-038e17892541', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    int orangesRotting(vector<vector<int>>& grid) {\n        int rows = grid.size(), cols = grid[0].size();\n        int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n        int minutes = 0;\n\n        // Each minute, rescan the whole grid and rot neighbours of rotten oranges\n        while (true) {\n            bool changed = false;\n\n            for (int r = 0; r < rows; r++) {\n                for (int c = 0; c < cols; c++) {\n                    if (grid[r][c] != 2) continue;\n\n                    for (auto& d : dirs) {\n                        int nr = r + d[0], nc = c + d[1];\n\n                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 1) {\n                            grid[nr][nc] = 3;  // rots this minute, spreads next minute\n                            changed = true;\n                        }\n                    }\n                }\n            }\n\n            if (!changed) break;\n\n            for (auto& row : grid)\n                for (int& cell : row)\n                    if (cell == 3) cell = 2;\n\n            minutes++;\n        }\n\n        for (auto& row : grid)\n            for (int cell : row)\n                if (cell == 1) return -1;\n\n        return minutes;\n    }\n};","filename":"C++"}'),
  ('fcf3aef2-8a6a-72e1-968a-13a9061b49fd', 'aD', 'code', '{"language":"java","code":"class Solution {\n    public int orangesRotting(int[][] grid) {\n        int rows = grid.length, cols = grid[0].length;\n        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n        int minutes = 0;\n\n        // Each minute, rescan the whole grid and rot neighbours of rotten oranges\n        while (true) {\n            boolean changed = false;\n\n            for (int r = 0; r < rows; r++) {\n                for (int c = 0; c < cols; c++) {\n                    if (grid[r][c] != 2) continue;\n\n                    for (int[] d : dirs) {\n                        int nr = r + d[0], nc = c + d[1];\n\n                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 1) {\n                            grid[nr][nc] = 3;  // rots this minute, spreads next minute\n                            changed = true;\n                        }\n                    }\n                }\n            }\n\n            if (!changed) break;\n\n            for (int[] row : grid)\n                for (int c = 0; c < cols; c++)\n                    if (row[c] == 3) row[c] = 2;\n\n            minutes++;\n        }\n\n        for (int[] row : grid)\n            for (int cell : row)\n                if (cell == 1) return -1;\n\n        return minutes;\n    }\n}","filename":"Java"}'),
  ('bbfeb91a-601a-7e3b-93ca-762b58fd087c', 'aE', 'code', '{"language":"javascript","code":"var orangesRotting = function(grid) {\n    const rows = grid.length;\n    const cols = grid[0].length;\n    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];\n    let minutes = 0;\n\n    // Each minute, rescan the whole grid and rot neighbours of rotten oranges\n    while (true) {\n        let changed = false;\n\n        for (let r = 0; r < rows; r++) {\n            for (let c = 0; c < cols; c++) {\n                if (grid[r][c] !== 2) continue;\n\n                for (const [dr, dc] of dirs) {\n                    const nr = r + dr, nc = c + dc;\n\n                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] === 1) {\n                        grid[nr][nc] = 3;  // rots this minute, spreads next minute\n                        changed = true;\n                    }\n                }\n            }\n        }\n\n        if (!changed) break;\n\n        for (const row of grid)\n            for (let c = 0; c < cols; c++)\n                if (row[c] === 3) row[c] = 2;\n\n        minutes++;\n    }\n\n    for (const row of grid)\n        if (row.includes(1)) return -1;\n\n    return minutes;\n};","filename":"JavaScript"}'),
  ('b9329618-2fd9-7045-b10e-75bdc8126b52', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O((R × C)^2) · Aux Space: O(1)","marks":[{"type":"bold"}]}]}]}}'),
  ('9fa25605-49a4-7134-b929-60027697f318', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]}'),
  ('bb666d43-9fd4-7fc6-a5f8-aa767aed214f', 'aH', 'code', '{"language":"python","code":"from collections import deque\n\nclass Solution:\n    def orangesRotting(self, grid):\n        rows = len(grid)\n        cols = len(grid[0])\n\n        queue = deque()\n        fresh = 0\n\n        for r in range(rows):\n            for c in range(cols):\n                if grid[r][c] == 2:\n                    queue.append((r, c))\n                elif grid[r][c] == 1:\n                    fresh += 1\n\n        minutes = 0\n\n        while queue and fresh:\n            for _ in range(len(queue)):\n                r, c = queue.popleft()\n\n                for dr, dc in [\n                    (1, 0), (-1, 0),\n                    (0, 1), (0, -1)\n                ]:\n                    nr, nc = r + dr, c + dc\n\n                    if (\n                        0 <= nr < rows and\n                        0 <= nc < cols\n                        and grid[nr][nc] == 1\n                    ):\n                        grid[nr][nc] = 2\n                        fresh -= 1\n                        queue.append((nr, nc))\n\n            minutes += 1\n\n        return minutes if fresh == 0 else -1","filename":"Python"}'),
  ('d2f9ce80-529b-710a-b8be-c598e4e8b617', 'aI', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    int orangesRotting(vector<vector<int>>& grid) {\n        int rows = grid.size(), cols = grid[0].size();\n        int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n\n        queue<pair<int, int>> q;\n        int fresh = 0;\n\n        for (int r = 0; r < rows; r++) {\n            for (int c = 0; c < cols; c++) {\n                if (grid[r][c] == 2) q.push({r, c});\n                else if (grid[r][c] == 1) fresh++;\n            }\n        }\n\n        int minutes = 0;\n\n        while (!q.empty() && fresh) {\n            for (int i = q.size(); i > 0; i--) {\n                auto [r, c] = q.front();\n                q.pop();\n\n                for (auto& d : dirs) {\n                    int nr = r + d[0], nc = c + d[1];\n\n                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 1) {\n                        grid[nr][nc] = 2;\n                        fresh--;\n                        q.push({nr, nc});\n                    }\n                }\n            }\n\n            minutes++;\n        }\n\n        return fresh == 0 ? minutes : -1;\n    }\n};","filename":"C++"}'),
