SELECT 'eece1943-7f0f-78be-b2e0-112f7501353d', '918d330b-9024-7f9c-beb0-4115d62451b9', 1, 'PUBLISHED', 'Deep vs Shallow', '[{"id":"01bb7410-4de7-71ac-9506-1857efad2751","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Copying objects that contain pointers requires care. Shallow copy shares memory — dangerous. Deep copy duplicates it — safe."}]}]}},"revision":1},{"id":"d0a6140a-6e57-7da8-b9de-01c2448ed997","type":"callout","position":"a1","content":{"variant":"note","title":"Shallow copy","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Copies member values bit-by-bit. Pointer members are copied — both objects point to the same heap memory."}]},{"type":"paragraph","content":[{"type":"text","text":"int* ptr = new int(42);","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"int* copy = ptr; // same address!","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"delete ptr;       // deletes the data","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"// copy now points to freed memory — crash!","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"103b9d9d-1f09-7c75-b441-d737f6f639a8","type":"callout","position":"a2","content":{"variant":"note","title":"Deep copy","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Allocates new memory and copies the data into it. Both objects are fully independent."}]},{"type":"paragraph","content":[{"type":"text","text":"int* ptr = new int(42);","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"int* copy = new int(*ptr); // new alloc","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"delete ptr;  // safe — copy is independent","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"20df66c4-cd54-7ef4-ad41-d8a8ac0d6a46","type":"callout","position":"a3","content":{"variant":"warning","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rule of Three (C++):","marks":[{"type":"bold"}]},{"type":"text","text":" If you define any of destructor, copy constructor, or copy assignment operator — you should define all three. This ensures deep copies everywhere dynamic memory is used."}]}]}},"revision":1},{"id":"2f7559b2-d18f-7e14-a30b-1c6e7ffd69ac","type":"callout","position":"a4","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When does this matter?","marks":[{"type":"bold"}]},{"type":"text","text":" Only when your class owns heap memory (via "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":"). If all members are value types (int, string, etc.), the default copy constructor is fine."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
