  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = 'f8cc5055-b4f2-76c0-a7ff-d3fdf44a780e' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '18497538-b8c6-74d6-a646-d2e3e9b6e52f' AND n."deletedAt" IS NULL
