SELECT '7f0cdfb6-3e61-7050-b0b8-493e22bb7330', '0d2e6b9e-36dc-748e-b192-288eef219c6b', 1, 'PUBLISHED', 'MAC, ARP & Framing', '[{"id":"2eabbb66-73c7-71e8-a2a3-b6a5183e424d","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The last logical hop before data becomes a raw electrical signal."}]}]}},"revision":1},{"id":"6af26067-16de-770b-b366-679bd1ed0e71","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"DHCP — getting an address automatically"}]},"revision":1},{"id":"444c4700-4d51-751a-8c60-2c3ef337c4c3","type":"callout","position":"a2","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DHCP","marks":[{"type":"bold"}]},{"type":"text","text":" (Dynamic Host Configuration Protocol) automatically assigns IP addresses to new devices joining a network, from a pool of available addresses managed by a DHCP server."}]}]}},"revision":1},{"id":"39e402f6-b250-77d0-92f0-504c25ead77c","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"New device joins LAN → DHCP server (address pool) → Device receives an IP address"}]}]}},"revision":1},{"id":"5d850018-a57c-7935-92de-a0662147920a","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"MAC Addresses"}]},"revision":1},{"id":"ba8377b8-d0bb-79f1-9f28-b77cec521c43","type":"callout","position":"a5","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"MAC address","marks":[{"type":"bold"}]},{"type":"text","text":" (Media Access Control address) is a hardware identifier permanently assigned to a network interface — every network-capable device has one, distinct from its (changeable) IP address."}]}]}},"revision":1},{"id":"7d47b75f-60d7-7bfa-8c42-7e5e9f504d18","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Within a LAN, devices at the Data Link layer communicate using these MAC addresses, not IP addresses."}]}]}},"revision":1},{"id":"d628a9ab-33f9-7edc-b48b-f9eb5140b566","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"ARP — Address Resolution Protocol"}]},"revision":1},{"id":"55a2b354-853a-77cc-bbcb-0662a6ee4287","type":"callout","position":"a8","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ARP","marks":[{"type":"bold"}]},{"type":"text","text":" bridges the gap between Layer 3 and Layer 2 — it resolves a known IP address into the corresponding MAC address needed to actually deliver a frame on the local network. Resolved mappings are cached locally in what''s called the "},{"type":"text","text":"ARP cache","marks":[{"type":"bold"}]},{"type":"text","text":", avoiding repeated lookups for the same address."}]}]}},"revision":1},{"id":"9928c9f9-ad69-7fcc-93de-040d7f118d13","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Frame anatomy"}]},"revision":1},{"id":"1cd00c22-f902-7f91-9bc8-f7b9241f28ba","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Before a network-layer packet can hit the physical wire, the Data Link Layer wraps it into a "},{"type":"text","text":"frame","marks":[{"type":"bold"}]},{"type":"text","text":" containing (at minimum):"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The sender''s Data Link layer address (MAC)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The IP address of the destination, carried inside the encapsulated packet"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Network-layer packet → wrapped into → Data Link frame"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
