  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '0d2e6b9e-36dc-748e-b192-288eef219c6b' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '7f0cdfb6-3e61-7050-b0b8-493e22bb7330' AND n."deletedAt" IS NULL
)
