  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = 'a39d2950-2dc0-72dd-a704-7b6d91d20d04' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = 'a2146fdb-f98a-7049-9696-19e74988eb7e' AND n."deletedAt" IS NULL
)
ON CONFLICT DO NOTHING;

