INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'b589b79b-4c08-78cf-b363-f265aa40aaba', 'ea49b775-9a48-771b-b022-d4f4d15567a8', 1, 'PUBLISHED', 'Email — SMTP/POP3/IMAP', '[{"id":"959d9ca8-5620-7b77-965b-a404781270c7","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three protocols, three different jobs in the lifecycle of an email."}]}]}},"revision":1},{"id":"5f319a2b-115e-7398-ad3e-294dfa8d52e2","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Sending — SMTP"}]},"revision":1},{"id":"a47c8525-f425-750f-b289-046c723994a7","type":"callout","position":"a2","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SMTP","marks":[{"type":"bold"}]},{"type":"text","text":" (Simple Mail Transfer Protocol) is the application-layer protocol used to "},{"type":"text","text":"send","marks":[{"type":"italic"}]},{"type":"text","text":" email between mail servers, running over TCP so no data is lost in transit."}]}]}},"revision":1},{"id":"4b130fe6-b66f-7b33-ba40-597f0d98f079","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sender → Sender''s SMTP server → Receiver''s SMTP server → Receiver"}]},{"type":"paragraph","content":[{"type":"text","text":"To find which server handles mail for a domain, a special DNS record is queried — the "},{"type":"text","text":"MX (Mail Exchange) record","marks":[{"type":"bold"}]},{"type":"text","text":", checkable via "},{"type":"text","text":"dig -type=mx gmail.com","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"1cb81293-d061-7f1c-b512-15e03760889f","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Receiving (download & delete) — POP3"}]},"revision":1},{"id":"4ed0281f-5fe0-7327-9a15-d84d6080a95a","type":"callout","position":"a5","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"POP3","marks":[{"type":"bold"}]},{"type":"text","text":" (Post Office Protocol v3) runs on "},{"type":"text","text":"port 110","marks":[{"type":"bold"}]},{"type":"text","text":". The client authenticates with the POP server, downloads all mail to the local device, then typically "},{"type":"text","text":"deletes it from the server","marks":[{"type":"bold"}]},{"type":"text","text":", and closes the session."}]}]}},"revision":1},{"id":"aae49b59-ec4a-7164-9ffa-55d16f6da352","type":"callout","position":"a6","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Limitation: because mail is downloaded and removed, POP3 doesn''t sync well across multiple devices — your inbox on your phone and laptop can end up out of sync."}]}]}},"revision":1},{"id":"2c87051d-41cc-78cc-9b34-efe6f0ad0b1e","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Receiving (multi-device sync) — IMAP"}]},"revision":1},{"id":"27fdcd7d-6f3e-7d7f-b241-0e0c5a0b117d","type":"callout","position":"a8","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"IMAP","marks":[{"type":"bold"}]},{"type":"text","text":" (Internet Message Access Protocol) allows your email to remain on the server and stay synced across multiple devices — instead of downloading and deleting, it mirrors the server-side state on every device."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'ea49b775-9a48-771b-b022-d4f4d15567a8' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
