SELECT '4b5c2dcc-b0c1-7a7e-9787-3a9acca008a7', 'a179e4c9-76ff-7cd6-b725-36d98933c2f8', 1, 'PUBLISHED', 'HTTP & the Web', '[{"id":"01391b2b-defc-7938-8e9a-c40264a9b565","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The protocol underneath every webpage you''ve ever loaded."}]}]}},"revision":1},{"id":"c1b2813f-35fa-70de-9fe4-432330b958c4","type":"callout","position":"a1","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"HTTP","marks":[{"type":"bold"}]},{"type":"text","text":" (HyperText Transfer Protocol) is an application-layer protocol that defines how a client requests a resource from a server, and how the server formats its response. HTTP itself runs "},{"type":"text","text":"on top of TCP","marks":[{"type":"bold"}]},{"type":"text","text":" — TCP guarantees the underlying bytes actually arrive, HTTP defines what those bytes mean."}]}]}},"revision":1},{"id":"2dd14353-6620-7b9a-aa74-b0f7aaf32df8","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Stateless by design"}]},"revision":1},{"id":"143354c5-64a9-7b5e-a1ce-3e8ea0cadbad","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"HTTP is a "},{"type":"text","text":"stateless protocol","marks":[{"type":"bold"}]},{"type":"text","text":" — by default, each request is independent and the server doesn''t remember anything about previous requests from the same client. This is exactly why "},{"type":"text","text":"cookies","marks":[{"type":"bold"}]},{"type":"text","text":" exist: to layer state on top of a fundamentally stateless protocol."}]}]}},"revision":1},{"id":"44bd9ebc-2071-7b48-96f5-548231c686fe","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"HTTP Methods"}]},"revision":1},{"id":"80f0f581-e17a-7b6d-a347-f531737e5702","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Method"}],[{"type":"text","text":"Purpose"}]],[[{"type":"text","text":"GET","marks":[{"type":"code"}]}],[{"type":"text","text":"Retrieve a resource, no side effects"}]],[[{"type":"text","text":"POST","marks":[{"type":"code"}]}],[{"type":"text","text":"Create a new resource / submit data"}]],[[{"type":"text","text":"PUT","marks":[{"type":"code"}]}],[{"type":"text","text":"Replace a resource entirely"}]],[[{"type":"text","text":"PATCH","marks":[{"type":"code"}]}],[{"type":"text","text":"Partially update a resource"}]],[[{"type":"text","text":"DELETE","marks":[{"type":"code"}]}],[{"type":"text","text":"Remove a resource"}]]]},"revision":1},{"id":"ea9c302e-b9e1-7a42-89a0-f5348f53ba5a","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Status codes"}]},"revision":1},{"id":"e68129bc-0ade-7be4-97d3-50f11161405d","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Range"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"1xx","marks":[{"type":"code"}]}],[{"type":"text","text":"Informational"}]],[[{"type":"text","text":"2xx","marks":[{"type":"code"}]}],[{"type":"text","text":"Success"}]],[[{"type":"text","text":"3xx","marks":[{"type":"code"}]}],[{"type":"text","text":"Redirection"}]],[[{"type":"text","text":"4xx","marks":[{"type":"code"}]}],[{"type":"text","text":"Client mistake (bad request, unauthorized, not found)"}]],[[{"type":"text","text":"5xx","marks":[{"type":"code"}]}],[{"type":"text","text":"Server error"}]]]},"revision":1},{"id":"684dcfbf-5836-75b4-a21f-bec9c1536d07","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Request & Response headers"}]},"revision":1},{"id":"717e29c6-0ef3-7111-a949-ae7858920317","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both requests and responses carry metadata in "},{"type":"text","text":"headers","marks":[{"type":"bold"}]},{"type":"text","text":" — e.g. content type, content length, and "},{"type":"text","text":"Keep-Alive","marks":[{"type":"code"}]},{"type":"text","text":" settings, which define a timeout for how long a TCP connection should stay open for reuse before being closed, avoiding the overhead of reconnecting for every single request."}]}]}},"revision":1},{"id":"365aac81-f001-7096-8f31-801998f1455a","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Cookies"}]},"revision":1},{"id":"7c378460-68d2-7acb-8de4-0ccab1ec2cf0","type":"callout","position":"aB","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"cookie","marks":[{"type":"bold"}]},{"type":"text","text":" is a small unique string set by a server and stored in the client''s browser, used to maintain state across otherwise-stateless HTTP requests (e.g. staying logged in)."}]}]}},"revision":1},{"id":"105bdf4d-620f-7834-ac37-4357acecf1eb","type":"text","position":"aC","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The first time you visit a site, the server sets the cookie in your browser."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On every subsequent visit, the browser automatically sends that cookie back, letting the server recognize you."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cookies have an "},{"type":"text","text":"expiration date","marks":[{"type":"bold"}]},{"type":"text","text":", after which they''re discarded."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Third-party cookies","marks":[{"type":"bold"}]},{"type":"text","text":" — cookies set for domains other than the one you''re actually visiting (commonly used for cross-site tracking/ads)."}]}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
