INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '34df52c8-13a3-72e6-a2f5-7dc9a8842ec9', 'cef357fc-7992-7c6f-a966-6c7398c22bf4', 1, 'PUBLISHED', 'IP Addressing & Subnetting', '[{"id":"e84757c7-b8f9-7438-a70c-20393a426299","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How packets get routed, classed, and divided across the global network."}]}]}},"revision":1},{"id":"40d73b97-6239-7a20-a425-bb87ea2d29fa","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Routing fundamentals"}]},"revision":1},{"id":"f7a566a2-8826-74e6-9c8c-77133db45a0a","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every router maintains a "},{"type":"text","text":"routing table","marks":[{"type":"bold"}]},{"type":"text","text":" (a data structure mapping destination addresses to the next hop) — when computer A sends data to computer B, it doesn''t go directly; it''s relayed "},{"type":"text","text":"hop-by-hop","marks":[{"type":"bold"}]},{"type":"text","text":" through a chain of routers, each forwarding it one step closer using its own table, until it reaches the destination."}]},{"type":"paragraph","content":[{"type":"text","text":"In graph terms: routers are "},{"type":"text","text":"nodes","marks":[{"type":"bold"}]},{"type":"text","text":", the links between them are "},{"type":"text","text":"edges","marks":[{"type":"bold"}]},{"type":"text","text":" — and finding the best path through this graph is a routing/shortest-path problem."}]}]}},"revision":1},{"id":"3ffb52fb-27fd-7b42-95da-c85ecda4f321","type":"callout","position":"a3","content":{"variant":"info","title":"Static routing","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Routes are configured manually by an administrator — simple but doesn''t adapt to network changes."}]}]}},"revision":1},{"id":"6787a980-c631-7c6a-8f18-d871cda883db","type":"callout","position":"a4","content":{"variant":"info","title":"Dynamic routing","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Routes are computed and updated automatically as the network changes, using algorithms like Bellman-Ford or Dijkstra''s algorithm."}]}]}},"revision":1},{"id":"55208053-d136-7cde-8c7b-04a7a2193717","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The component that builds and maintains these routing tables is referred to as the "},{"type":"text","text":"control plane","marks":[{"type":"bold"}]},{"type":"text","text":" of the network."}]}]}},"revision":1},{"id":"983f17d4-be57-78cf-8334-8e6ce2108d9d","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"IPv4 vs IPv6"}]},"revision":1},{"id":"4d9bf05b-4fe0-7701-bbfc-8083212386d4","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Feature"}],[{"type":"text","text":"IPv4"}],[{"type":"text","text":"IPv6"}]],[[{"type":"text","text":"Bit length","marks":[{"type":"bold"}]}],[{"type":"text","text":"32 bits"}],[{"type":"text","text":"128 bits"}]],[[{"type":"text","text":"Format","marks":[{"type":"bold"}]}],[{"type":"text","text":"4 decimal \"octets\" (e.g. 192.168.2.30)"}],[{"type":"text","text":"8 groups of hexadecimal (e.g. ABFE:F001:3210:9182:0:0:1:2)"}]],[[{"type":"text","text":"Address space","marks":[{"type":"bold"}]}],[{"type":"text","text":"2³² ≈ 4.3 billion unique addresses"}],[{"type":"text","text":"2¹²⁸ ≈ 3.403 × 10³⁸ unique addresses"}]],[[{"type":"text","text":"Adoption challenge","marks":[{"type":"bold"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"Not backward compatible with IPv4; requires significant ISP/hardware migration"}]]]},"revision":1},{"id":"e8a125e6-0609-76fc-8c8b-53f611b3b869","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An IPv4 address like "},{"type":"text","text":"192.168.2.30","marks":[{"type":"code"}]},{"type":"text","text":" splits into a "},{"type":"text","text":"network/subnet ID","marks":[{"type":"bold"}]},{"type":"text","text":" (e.g. "},{"type":"text","text":"192.168.2","marks":[{"type":"code"}]},{"type":"text","text":") identifying which network the device belongs to, and a "},{"type":"text","text":"device/host address","marks":[{"type":"bold"}]},{"type":"text","text":" (the final "},{"type":"text","text":"30","marks":[{"type":"code"}]},{"type":"text","text":") identifying the specific machine within that network."}]}]}},"revision":1},{"id":"54a9e197-9912-7f41-aba7-baddbc94f5e9","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"IPv4 address classes"}]},"revision":1},{"id":"7f03fe9d-3c1b-788b-b57d-1588577316fd","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Class"}],[{"type":"text","text":"Range"}],[{"type":"text","text":"Typical use"}]],[[{"type":"text","text":"A","marks":[{"type":"bold"}]}],[{"type":"text","text":"0.0.0.0 – 127.255.255.255"}],[{"type":"text","text":"Very large networks (few networks, huge host count)"}]],[[{"type":"text","text":"B","marks":[{"type":"bold"}]}],[{"type":"text","text":"128.0.0.0 – 191.255.255.255"}],[{"type":"text","text":"Medium-to-large networks"}]],[[{"type":"text","text":"C","marks":[{"type":"bold"}]}],[{"type":"text","text":"192.0.0.0 – 223.255.255.255"}],[{"type":"text","text":"Small networks (most common, e.g. home routers)"}]],[[{"type":"text","text":"D","marks":[{"type":"bold"}]}],[{"type":"text","text":"224.0.0.0 – 239.255.255.255"}],[{"type":"text","text":"Multicast addressing"}]],[[{"type":"text","text":"E","marks":[{"type":"bold"}]}],[{"type":"text","text":"240.0.0.0 – 255.255.255.255"}],[{"type":"text","text":"Reserved, experimental use"}]]]},"revision":1},{"id":"ddf02e47-86a3-716b-bf38-0c52f9155900","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Subnet masking"}]},"revision":1},{"id":"117a869b-8d96-7674-8f3a-8c24c5389023","type":"callout","position":"aC","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"subnet mask","marks":[{"type":"bold"}]},{"type":"text","text":" \"masks\" the network portion of an IP address, leaving the remaining bits to identify the specific host. It tells devices which part of an address is the network and which part is the individual device."}]}]}},"revision":1},{"id":"a9d692dd-cb3d-7799-8918-6f3f65b56672","type":"text","position":"aD","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For a Class C address, the default mask is "},{"type":"text","text":"255.255.255.0","marks":[{"type":"code"}]},{"type":"text","text":" — the first three octets identify the network, the last identifies the host. "},{"type":"text","text":"CIDR notation","marks":[{"type":"bold"}]},{"type":"text","text":" (e.g. "},{"type":"text","text":"/24","marks":[{"type":"code"}]},{"type":"text","text":") is the modern compact way to express this, where the number indicates how many leading bits are the network portion."}]}]}},"revision":1},{"id":"0f7a78b2-8d48-7cd6-a927-0df8f6058e33","type":"callout","position":"aE","content":{"variant":"tip","title":"Worked example — variable length subnetting","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Given "},{"type":"text","text":"192.0.1.0/24","marks":[{"type":"code"}]},{"type":"text","text":": the network covers addresses from "},{"type":"text","text":"192.0.1.0","marks":[{"type":"bold"}]},{"type":"text","text":" (start) to "},{"type":"text","text":"192.0.1.255","marks":[{"type":"bold"}]},{"type":"text","text":" (end) — 256 total addresses, with the /24 meaning the first 24 bits are fixed as the network portion, leaving 8 bits (2⁸ = 256) for host addresses within it."}]}]}},"revision":1},{"id":"a3834edf-f608-79b2-9680-4d0042a957ce","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Reserved & special addresses"}]},"revision":1},{"id":"346bda02-73ce-73ed-8761-0da72ea5dd04","type":"text","position":"aG","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"127.0.0.0/8","marks":[{"type":"code"}]},{"type":"text","text":" — the "},{"type":"text","text":"loopback","marks":[{"type":"bold"}]},{"type":"text","text":" range. "},{"type":"text","text":"127.0.0.1","marks":[{"type":"code"}]},{"type":"text","text":" specifically is \"localhost\" — it lets a device contact itself, useful for a machine acting as both client and server during local development/testing."}]}]}]}]}},"revision":1},{"id":"47dafa1c-1a26-7ed4-9fd9-d25896c7c061","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"Anatomy of an IP packet header"}]},"revision":1},{"id":"a338b9eb-ccc3-7971-97a3-866a0e43aee8","type":"text","position":"aI","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every IP packet carries a 20-byte header containing:"}]},{"type":"paragraph","content":[{"type":"text","text":"Version (IPV)"}]},{"type":"paragraph","content":[{"type":"text","text":"Header Length"}]},{"type":"paragraph","content":[{"type":"text","text":"Identification"}]},{"type":"paragraph","content":[{"type":"text","text":"Flags"}]},{"type":"paragraph","content":[{"type":"text","text":"Protocol"}]},{"type":"paragraph","content":[{"type":"text","text":"Checksum"}]},{"type":"paragraph","content":[{"type":"text","text":"Source Address"}]},{"type":"paragraph","content":[{"type":"text","text":"Destination Address"}]},{"type":"paragraph","content":[{"type":"text","text":"TTL"}]}]}},"revision":1},{"id":"8c7a9e52-0a47-76da-b7ea-1bd9ff0d0066","type":"callout","position":"aJ","content":{"variant":"info","title":"TTL — Time To Live","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A counter that decreases by 1 at every router hop. It exists because packets can sometimes get stuck looping between routers — once TTL hits 0, the packet is dropped, preventing it from circulating forever. A typical starting TTL value is around 60–64."}]}]}},"revision":1},{"id":"2f0ff89b-8479-76f1-9dc1-3caba494fc1d","type":"heading","position":"aK","content":{"level":1,"content":[{"type":"text","text":"Middleboxes — Firewalls"}]},"revision":1},{"id":"db6498f7-cc02-74aa-8f95-7dc322dfab15","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"firewall","marks":[{"type":"bold"}]},{"type":"text","text":" is an extra device sitting between your trusted internal network and the broader, untrusted internet, filtering traffic based on configurable rules."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Filters by source/destination "},{"type":"text","text":"address","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Filters by "},{"type":"text","text":"port number","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Filters by "},{"type":"text","text":"protocol","marks":[{"type":"bold"}]},{"type":"text","text":" and packet "},{"type":"text","text":"flags","marks":[{"type":"bold"}]}]}]}]}]}},"revision":1},{"id":"bbdd3126-7283-70a3-a6e9-4eea0b851632","type":"callout","position":"aM","content":{"variant":"info","title":"Stateless firewall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Examines each packet in isolation against static rules — faster but less context-aware."}]}]}},"revision":1},{"id":"0587d9cc-afaf-7b9c-a190-92984f22c08e","type":"callout","position":"aN","content":{"variant":"info","title":"Stateful firewall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tracks the state of active connections, allowing traffic that''s part of a connection it already recognizes as legitimate (e.g. a response to a request you sent) — more secure but more resource-intensive."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
