  WHERE n.id = 'cef357fc-7992-7c6f-a966-6c7398c22bf4' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '34df52c8-13a3-72e6-a2f5-7dc9a8842ec9' AND n."deletedAt" IS NULL
