INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'c5c5d12d-8ae3-7d99-a244-6a668892f76f', '0ad875cf-f14a-70ba-962a-5d444d12cf07', 1, 'PUBLISHED', 'Layer 1 — Physical', '[{"id":"dc996fbf-a078-7e45-ba86-72f26dc6b5cd","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Where raw bits travel as copper voltages, light pulses, or radio signals."}]}]}},"revision":1},{"id":"2fb249c9-9f9e-7961-9a10-4accd52ff21c","type":"callout","position":"a1","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Physical Layer","marks":[{"type":"bold"}]},{"type":"text","text":" is the hardware base of the network. It deals with the transmission and reception of unstructured raw data streams (bits) over physical media. It defines electrical voltages, light frequencies, connector shapes, cable specs, and transmission speeds."}]}]}},"revision":1},{"id":"1aa62af3-b1a9-7ac4-8782-dc81ace09884","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PDU: Bit"}]},{"type":"paragraph","content":[{"type":"text","text":"Focus: Electrical/Optical Signals"}]},{"type":"paragraph","content":[{"type":"text","text":"Hardware: Hubs, Repeaters, Cables, Modems"}]}]}},"revision":1},{"id":"356939da-b9b0-799c-a744-803d81f7324d","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Core Purpose & Function"}]},"revision":1},{"id":"2a2adbd0-a1b2-7d31-b2a1-c1934e2743e7","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Layer 1 has no understanding of packet headers, addresses, or applications. It is strictly concerned with sending a series of electrical or optical pulses representing \"1\" or \"0\" down a wire, and ensuring that a receiver interprets those physical pulses back into matching bits."}]}]}},"revision":1},{"id":"7c4bca73-da77-792a-8f14-96940f3a979d","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Key Responsibilities"}]},"revision":1},{"id":"90548312-90a8-7e17-acbf-d4f0bae3c169","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bit Representation","marks":[{"type":"bold"}]},{"type":"text","text":": Defining how 1s and 0s are coded (e.g. changes in voltage levels, light brightness, or radio frequency phases)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bandwidth & Data Rates","marks":[{"type":"bold"}]},{"type":"text","text":": Governing the maximum bit rate (transmission speed in Mbps/Gbps) supported by a cable type."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Physical Media Specifications","marks":[{"type":"bold"}]},{"type":"text","text":": Standardizing wire thicknesses, fiber core widths, connector shapes (like RJ45 plugs), and shielding specifications."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Line Configuration & Duplexing","marks":[{"type":"bold"}]},{"type":"text","text":": Defining whether transmission is point-to-point, simplex (one-way), half-duplex, or full-duplex."}]}]}]}]}},"revision":1},{"id":"ca9ccf2b-1c29-7ff9-b245-2ee2c0287371","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Common Physical Media"}]},"revision":1},{"id":"254e9610-fb7b-79f2-9233-73d04ca608e3","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Medium Type"}],[{"type":"text","text":"Description"}],[{"type":"text","text":"Typical Speed"}],[{"type":"text","text":"Pros / Cons"}]],[[{"type":"text","text":"Unshielded Twisted Pair (UTP)","marks":[{"type":"bold"}]}],[{"type":"text","text":"Copper wires twisted to reduce interference"}],[{"type":"text","text":"100 Mbps – 10 Gbps"}],[{"type":"text","text":"Cheap, flexible, but short range (~100m)"}]],[[{"type":"text","text":"Fiber Optic Cable","marks":[{"type":"bold"}]}],[{"type":"text","text":"Glass strands transmitting light pulses"}],[{"type":"text","text":"1 Gbps – 100+ Gbps"}],[{"type":"text","text":"Immune to electromagnetic interference, long range"}]],[[{"type":"text","text":"Coaxial Cable","marks":[{"type":"bold"}]}],[{"type":"text","text":"Shielded copper conductor"}],[{"type":"text","text":"10 – 100 Mbps"}],[{"type":"text","text":"Resistant to noise, used for cable TV/broadband"}]],[[{"type":"text","text":"Radio Frequencies","marks":[{"type":"bold"}]}],[{"type":"text","text":"Electromagnetic waves traveling through air"}],[{"type":"text","text":"Up to 10 Gbps (Wi-Fi 7)"}],[{"type":"text","text":"No physical wires needed, but prone to walls/noise"}]]]},"revision":1},{"id":"379b4f4a-0681-745c-9219-7a5f7bb5993b","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Analogy: The Asphalt Roads & Highways"}]},"revision":1},{"id":"1040926b-5ce9-7d63-a79a-c67aca67a0ef","type":"callout","position":"aA","content":{"variant":"tip","title":"Amazon Analogy","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Physical Layer is the "},{"type":"text","text":"actual asphalt roads, physical bridges, and truck engines","marks":[{"type":"bold"}]},{"type":"text","text":". It represents the physical tires rolling on the road. Without the asphalt, no delivery van can move. It doesn''t know what''s in the van or where it''s going; it is just the physical conduit that allows travel."}]}]}},"revision":1},{"id":"fd85b5e7-4a49-7051-af11-05508fb59f85","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Hardware & Physical Connectors"}]},"revision":1},{"id":"c37f3dee-5859-7ab5-bc7d-2f4c36487bd4","type":"callout","position":"aC","content":{"variant":"tip","title":"Pros","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Establishes the physical link necessary for any network to function."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fiber optics provide near-light-speed transmission over massive distances."}]}]}]}]}},"revision":1},{"id":"927ecfe7-e8c4-7357-a4d0-c1ca49a44fce","type":"callout","position":"aD","content":{"variant":"danger","title":"Cons","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Vulnerable to physical damage (cuts, water leaks, severe weather)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Signal attenuation requires repeaters/amplifiers over long distances."}]}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '0ad875cf-f14a-70ba-962a-5d444d12cf07' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
