INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '6fa0fc5f-f7a6-7787-ac87-82aba9065320', '99cceed1-a96d-74b6-9f7e-4613d71e3b8e', 1, 'PUBLISHED', 'Layer 2 — Data Link', '[{"id":"e048e0e5-e092-7fe9-ac83-61b2a9425986","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hop-by-hop delivery, framing packets into physical frames, and resolving MAC addresses."}]}]}},"revision":1},{"id":"cf60faf3-58f4-753a-92db-6018895fc888","type":"callout","position":"a1","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Data Link Layer","marks":[{"type":"bold"}]},{"type":"text","text":" handles direct node-to-node communication on the same local network. It takes IP packets, wraps them in "},{"type":"text","text":"frames","marks":[{"type":"bold"}]},{"type":"text","text":" containing physical hardware addresses (MAC addresses), detects errors on the wire, and controls access to the physical transmission medium."}]}]}},"revision":1},{"id":"0d03b1a2-5a74-7d6d-bca9-44ba631b819c","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PDU: Frame"}]},{"type":"paragraph","content":[{"type":"text","text":"Focus: Local Hops & Media Access"}]},{"type":"paragraph","content":[{"type":"text","text":"Hardware: Switches, Bridges, NICs"}]}]}},"revision":1},{"id":"abde5547-1bda-733b-af1e-947cadac27b3","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Core Purpose & Function"}]},"revision":1},{"id":"9e561350-941a-74c3-a7f8-915bd590ea95","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Layer 3 moves packets globally, but Layer 2 is what physically walks the packet across individual wires between immediate neighbors. It bridges the logical network layer with the physical copper/glass wire, using MAC addresses to resolve precisely which network card on a shared cable should open a frame."}]}]}},"revision":1},{"id":"52691f42-1253-7d90-90b1-6c57e3c47425","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Key Responsibilities"}]},"revision":1},{"id":"61f2f2db-d183-7041-845f-54682f9fe4a9","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Framing","marks":[{"type":"bold"}]},{"type":"text","text":": Wrapping packets with start/stop indicators and error check sequences (FCS/CRC checksums) to establish where a frame begins and ends."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Physical Addressing","marks":[{"type":"bold"}]},{"type":"text","text":": Adding source and destination MAC addresses to frames. MAC addresses are 48-bit numbers burned into NIC hardware at the factory."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Media Access Control (MAC)","marks":[{"type":"bold"}]},{"type":"text","text":": Coordinating who is allowed to transmit on shared networks (like Wi-Fi frequencies or shared Ethernet hubs) using collision detection or avoidance systems (CSMA/CD, CSMA/CA)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Address Resolution (ARP)","marks":[{"type":"bold"}]},{"type":"text","text":": Finding the hardware MAC address of a destination IP on the local subnet using local ARP broadcasts."}]}]}]}]}},"revision":1},{"id":"fe4c23b6-7b6c-7e47-afb4-e4a8db91c0a5","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Common Protocols at Layer 2"}]},"revision":1},{"id":"51eac7e2-a111-726d-913b-4e1b31c4d61f","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Protocol"}],[{"type":"text","text":"Description"}],[{"type":"text","text":"Role in Local Network"}]],[[{"type":"text","text":"Ethernet (802.3)","marks":[{"type":"bold"}]}],[{"type":"text","text":"Wired network protocol"}],[{"type":"text","text":"Main standard for wired home/office LANs."}]],[[{"type":"text","text":"Wi-Fi (802.11)","marks":[{"type":"bold"}]}],[{"type":"text","text":"Wireless local network standard"}],[{"type":"text","text":"Uses CSMA/CA to transmit frames wirelessly through the air."}]],[[{"type":"text","text":"ARP","marks":[{"type":"bold"}]}],[{"type":"text","text":"Address Resolution Protocol"}],[{"type":"text","text":"Resolves IP addresses to physical MAC addresses."}]],[[{"type":"text","text":"PPP / Frame Relay","marks":[{"type":"bold"}]}],[{"type":"text","text":"Point-to-Point Protocol"}],[{"type":"text","text":"Wired WAN links connecting distant routers directly."}]]]},"revision":1},{"id":"b69459c2-bdba-7239-a9d2-ffbc24a5a46d","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Analogy: The Local Delivery Van"}]},"revision":1},{"id":"3fe332d4-e5bf-7d7b-a722-351072914cd2","type":"callout","position":"aA","content":{"variant":"tip","title":"Amazon Analogy","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Data Link Layer represents the "},{"type":"text","text":"local delivery van driving from the post office to your house","marks":[{"type":"bold"}]},{"type":"text","text":". The van cares about local physical markers (your house number and gate, mapping to MAC addresses) to drop off the box. The van driver only operates on your neighborhood roads (local LAN switch) and doesn''t know about inter-state highways."}]}]}},"revision":1},{"id":"c3a50bc6-f491-75c7-a454-007d5ee55d01","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"LAN Devices & Media Control"}]},"revision":1},{"id":"e1f08d3c-3800-7067-a12c-f11d03f13fdb","type":"callout","position":"aC","content":{"variant":"tip","title":"Pros","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Extremely fast hardware switching (L2 switches read MAC addresses in silicon)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Robust error detection filters out corrupted frames immediately."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Avoids signal collisions on shared media."}]}]}]}]}},"revision":1},{"id":"f6832b65-97c9-77cd-9a05-6d4f3f49435b","type":"callout","position":"aD","content":{"variant":"danger","title":"Cons","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Completely localized: cannot route data beyond its own local subnet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Broadcast storms (ARP loops) can overwhelm the network if L2 loops exist."}]}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
