SELECT '0301fe94-18b6-763b-9374-879361ff88ff', '8310c5ee-2dc6-7be7-836b-b1693eb85eba', 1, 'PUBLISHED', 'Layer 3 — Network', '[{"id":"2580abfa-de18-7741-ac19-e0256a70ceb9","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Where packets are stamped with IP addresses and routed across network borders."}]}]}},"revision":1},{"id":"2ffb9031-8dab-788c-a5b0-80e4c96f385c","type":"callout","position":"a1","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Network Layer","marks":[{"type":"bold"}]},{"type":"text","text":" is the routing engine of the internet. It handles the movement of data units called "},{"type":"text","text":"packets","marks":[{"type":"bold"}]},{"type":"text","text":" across multiple independent networks. It defines logical addressing (IP addresses) and routes packets from their original source host to their final destination using path-selection algorithms."}]}]}},"revision":1},{"id":"1689fe62-e2e2-79d7-8ef1-0d0de811b869","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PDU: Packet"}]},{"type":"paragraph","content":[{"type":"text","text":"Focus: Inter-Network Routing"}]},{"type":"paragraph","content":[{"type":"text","text":"Hardware: Routers / Layer 3 Switches"}]}]}},"revision":1},{"id":"f5f79b67-7d8a-7d53-9979-fd37f50db952","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Core Purpose & Function"}]},"revision":1},{"id":"95f2cd5e-8f21-7095-9932-ad813544cb63","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Network Layer is where the boundaries of local networks (LANs) are crossed. While Layer 2 can only talk to immediate neighbors on the same cable or switch, Layer 3 is what allows packets to travel across routers, ISPs, and undersea cables to reach a server on the other side of the globe."}]}]}},"revision":1},{"id":"7d67bc37-009c-7d7e-9c83-a931c693fb50","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Key Responsibilities"}]},"revision":1},{"id":"05552f57-2523-796f-ab8f-9babf4946b42","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Logical Addressing","marks":[{"type":"bold"}]},{"type":"text","text":": Wrapping segments in IP packets, stamping them with source and destination IP addresses."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Routing & Path Selection","marks":[{"type":"bold"}]},{"type":"text","text":": Routers calculate the optimal path through the global mesh using routing tables and algorithms (e.g. OSPF, BGP, RIP)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Packet Fragmentation","marks":[{"type":"bold"}]},{"type":"text","text":": Splitting large packets into smaller fragments if they exceed the MTU of a router interface, and setting flags to enable reassembly."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Congestion Avoidance","marks":[{"type":"bold"}]},{"type":"text","text":": Dropping or throttling packets when router queues fill up."}]}]}]}]}},"revision":1},{"id":"2c0c90eb-ecaa-7a8c-8399-c8aa11e615bb","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Common Protocols at Layer 3"}]},"revision":1},{"id":"d923e10f-550a-7178-b55f-e65616190c2a","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Protocol"}],[{"type":"text","text":"Full Name"}],[{"type":"text","text":"Purpose"}]],[[{"type":"text","text":"IPv4","marks":[{"type":"bold"}]}],[{"type":"text","text":"Internet Protocol version 4"}],[{"type":"text","text":"32-bit logical addressing system (most common)"}]],[[{"type":"text","text":"IPv6","marks":[{"type":"bold"}]}],[{"type":"text","text":"Internet Protocol version 6"}],[{"type":"text","text":"128-bit next-generation addressing system"}]],[[{"type":"text","text":"ICMP","marks":[{"type":"bold"}]}],[{"type":"text","text":"Internet Control Message Protocol"}],[{"type":"text","text":"Sends diagnostic messages and error reports (used by "},{"type":"text","text":"ping","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"IPSec","marks":[{"type":"bold"}]}],[{"type":"text","text":"Internet Protocol Security"}],[{"type":"text","text":"Provides authentication and encryption for Layer 3 packets (VPN tunnels)"}]]]},"revision":1},{"id":"cd559c4e-e330-7948-8510-de0ede630e57","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Analogy: The Postal Routing Center"}]},"revision":1},{"id":"945cab4a-a04b-7b13-86dd-47c89577817b","type":"callout","position":"aA","content":{"variant":"tip","title":"Amazon Analogy","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Network Layer is like the "},{"type":"text","text":"Postal Routing Center and GPS navigation","marks":[{"type":"bold"}]},{"type":"text","text":". The box is stamped with a destination address (IP). The truck driver uses a map/GPS (routing table) to navigate through multiple toll roads and exits (routers/hops) to move the box closer to the final city, without needing to know who lives in the house."}]}]}},"revision":1},{"id":"5598e4f5-8be9-783f-8918-4de239f8f2ce","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Path Selection Performance"}]},"revision":1},{"id":"866bcaed-3cf0-742a-b50f-cb596dd0c9f6","type":"callout","position":"aC","content":{"variant":"tip","title":"Pros","doc":{"type":"doc","content":[{"type":"bulletLis