SELECT '04c48928-68d4-7128-8d23-7d93b4fb6556', '463a833e-a56f-76ea-9445-dc94a4b133df', 1, 'PUBLISHED', 'Layer 4 — Transport', '[{"id":"1a0bc25c-d820-7c8d-bbcb-01c97b4fa39b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The engine room, managing segment assembly, error correction, and application sockets."}]}]}},"revision":1},{"id":"74bc4c2f-cdfc-7c61-84cd-417111a818d3","type":"callout","position":"a1","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Transport Layer","marks":[{"type":"bold"}]},{"type":"text","text":" is responsible for host-to-host communication. It takes data from the session layer, breaks it into smaller units called "},{"type":"text","text":"segments","marks":[{"type":"bold"}]},{"type":"text","text":", and ensures they are delivered reliably, in the correct order, without error, and directly to the correct application socket using port numbers."}]}]}},"revision":1},{"id":"d6ee506d-7023-786f-95e1-e3e2bdb63f5e","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PDU: Segment (TCP) / Datagram (UDP)"}]},{"type":"paragraph","content":[{"type":"text","text":"Focus: End-to-End Reliability"}]},{"type":"paragraph","content":[{"type":"text","text":"Hardware: OS Kernel / Sockets"}]}]}},"revision":1},{"id":"d56cd262-9434-76fd-af10-9d0abaa64e32","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Core Purpose & Function"}]},"revision":1},{"id":"3a410c29-3cc7-7299-88ac-d121d19933b5","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"While the Network Layer below routes packets to the correct *physical computer*, the Transport Layer is the one that gets the data to the correct *software process* on that computer. It acts as the supervisor of the connection, handling flow control, sequencing, and packet loss recovery."}]}]}},"revision":1},{"id":"dd57d0b0-a0e4-729e-b8e9-d655f2b3fecc","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Key Responsibilities"}]},"revision":1},{"id":"2fa76973-ed53-76c2-a727-23b65ba6974b","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Port Addressing & Multiplexing","marks":[{"type":"bold"}]},{"type":"text","text":": Attaching source and destination ports. This allows a laptop to run Slack, Zoom, and a browser simultaneously without their data streams mixing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Segmentation & Reassembly","marks":[{"type":"bold"}]},{"type":"text","text":": Dividing data into chunks size-optimized for the MTU (Maximum Transmission Unit) of the network, and re-assembling them in order at the destination."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Flow Control","marks":[{"type":"bold"}]},{"type":"text","text":": Preventing a fast sender from overwhelming a slow receiver by negotiating window sizes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Error Recovery & ACKs","marks":[{"type":"bold"}]},{"type":"text","text":": Using checksums to spot corruption and retransmitting lost packets when timers expire."}]}]}]}]}},"revision":1},{"id":"743da122-f2bb-7858-bc8d-16a1ce6cebd4","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"TCP vs UDP — The Transport Split"}]},"revision":1},{"id":"f6188611-642e-7a64-8749-41a9d9aba085","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Feature"}],[{"type":"text","text":"TCP (Transmission Control Protocol)"}],[{"type":"text","text":"UDP (User Datagram Protocol)"}]],[[{"type":"text","text":"Connection","marks":[{"type":"bold"}]}],[{"type":"text","text":"Connection-oriented (Requires 3-Way Handshake)"}],[{"type":"text","text":"Connectionless (Fire and Forget)"}]],[[{"type":"text","text":"Reliability","marks":[{"type":"bold"}]}],[{"type":"text","text":"Guaranteed delivery (Retransmits lost segments)"}],[{"type":"text","text":"Best-effort delivery (No retransmission)"}]],[[{"type":"text","text":"Ordering","marks":[{"type":"bold"}]}],[{"type":"text","text":"Guaranteed in-order reassembly"}],[{"type":"text","text":"No ordering guarantees"}]],[[{"type":"text","text":"Header Size","marks":[{"type":"bold"}]}],[{"type":"text","text":"20 bytes minimum"}],[{"type":"text","text":"8 bytes fixed"}]],[[{"type":"text","text":"Use Case","marks":[{"type":"bold"}]}],[{"type":"text","text":"Web browsing (HTTP), Email, File transfer (FTP)"}],[{"type":"text","text":"Voice calls (VoIP), Video streams, DNS"}]]]},"revision":1},{"id":"3a916a10-7575-75eb-8b03-eeef0f3d19ab","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Analogy: The Shipment Box labeling and Tracking Numbers"}]},"revision":1},{"id":"1891e476-6a93-7f6c-aa55-bde0944e8a12","type":"callout","position":"aA","content":{"variant":"tip","title":"Amazon Analogy","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Transport Layer corresponds to the "},{"type":"text","text":"delivery coordinator packing your items into numbered boxes","marks":[{"type":"bold"}]},{"type":"text","text":". They label box 1/3, 2/3, 3/3, and require a signature (ACK) upon delivery. If box 2/3 goes missing on the highway, they re-ship box 2/3. At your door, they reassemble the three boxes in order before handing them to you."}]}]}},"revision":1},{"id":"dedbd97e-8bd4-70ce-8138-53f958ac2115","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Flow Control & Congestion Control"}]},"revision":1},{"id":"ac03f94f-2548-75e7-857d-d249af5d4338","type":"callout","position":"aC","content":{"variant":"tip","title":"Pros","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"End-to-end data integrity guarantees (for TCP)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enables multitasking (multiplexing) on a single physical link."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prevents packet loss due to receiver buffer overload."}]}]}]}]}},"revision":1},{"id":"a9d05b18-a8e3-72a1-ab6c-dcd15e336136","type":"callout","position":"aD","content":{"variant":"danger","title":"Cons","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"TCP handshakes add latency before any data is sent."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Heavy CPU and memory usage to buffer and track outstanding acknowledgements."}]}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
