  WHERE n.id = 'e84bbdd0-a7b8-7cf4-8b3b-a6f5f57d3a36' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = 'ac8053bd-1f7e-7755-b3ae-91fbee30da7f' AND n."deletedAt" IS NULL
