INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '03fceb27-1994-753c-86c8-d1888b239450', 'ea4aa364-650c-715a-90e5-eb55402348c4', 1, 'PUBLISHED', 'OSI Model — Overview', '[{"id":"5396c997-1b12-739c-ab70-adc3b46ab4bd","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Open Systems Interconnection: the standard mental map for every layer of networking, top to bottom."}]}]}},"revision":1},{"id":"8d690d3d-ec1d-7092-840b-71771ddf8387","type":"callout","position":"a1","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"OSI model","marks":[{"type":"bold"}]},{"type":"text","text":" is a conceptual, standardized framework that describes how data moves through a network in 7 distinct layers, each with a specific responsibility. It''s \"open\" because it''s vendor-neutral — any system following it can interoperate with any other."}]}]}},"revision":1},{"id":"942eb076-9f12-7ee8-96d9-911fbf33e3ef","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Data physically only exists as electrical/light/radio signals — the OSI model is the human-friendly abstraction layered on top so engineers can reason about \"what''s happening\" without tracking every electron. Each layer talks logically to its counterpart layer on the other machine, but physically only ever talks to the layer directly above/below it on the same machine."}]}]}},"revision":1},{"id":"ca6aa886-2f1b-7d26-a889-bc6a99ee907d","type":"callout","position":"a3","content":{"variant":"note","title":"Application","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"L7"}]},{"type":"paragraph","content":[{"type":"text","text":"What the user-facing software does"}]}]}},"revision":1},{"id":"cfa08640-a8b8-75fd-97bb-d5d3e5e6e5c5","type":"callout","position":"a4","content":{"variant":"note","title":"Presentation","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"L6"}]},{"type":"paragraph","content":[{"type":"text","text":"Formatting, encryption, translation"}]}]}},"revision":1},{"id":"2e51db20-7e8d-760a-b4a0-c29678d920c2","type":"callout","position":"a5","content":{"variant":"note","title":"Session","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"L5"}]},{"type":"paragraph","content":[{"type":"text","text":"Setting up & managing connections"}]}]}},"revision":1},{"id":"98c68c35-b435-718c-91eb-4fbb81c9a96d","type":"callout","position":"a6","content":{"variant":"note","title":"Transport","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"L4"}]},{"type":"paragraph","content":[{"type":"text","text":"TCP/UDP, segmentation, ports"}]}]}},"revision":1},{"id":"74e3aa35-e8c7-78ef-858a-d1ba64dc5391","type":"callout","position":"a7","content":{"variant":"note","title":"Network","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"L3"}]},{"type":"paragraph","content":[{"type":"text","text":"IP addressing, routing"}]}]}},"revision":1},{"id":"5f1fba89-c33e-77f6-9165-aa820a556a29","type":"callout","position":"a8","content":{"variant":"note","title":"Data Link","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"L2"}]},{"type":"paragraph","content":[{"type":"text","text":"MAC addresses, framing"}]}]}},"revision":1},{"id":"da7c500d-d20a-7437-a022-b33bcd6458c2","type":"callout","position":"a9","content":{"variant":"note","title":"Physical","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"L1"}]},{"type":"paragraph","content":[{"type":"text","text":"Raw bits as electrical/light signals"}]}]}},"revision":1},{"id":"025fb80a-f1ba-70dc-91b9-3cf98dfd2085","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Memory aid"}]},"revision":1},{"id":"3705223b-e68c-72b4-b980-cf46badc6c85","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A classic mnemonic, top-down: "},{"type":"text","text":"A","marks":[{"type":"bold"}]},{"type":"text","text":"ll "},{"type":"text","text":"P","marks":[{"type":"bold"}]},{"type":"text","text":"eople "},{"type":"text","text":"S","marks":[{"type":"bold"}]},{"type":"text","text":"eem "},{"type":"text","text":"T","marks":[{"type":"bold"}]},{"type":"text","text":"o "},{"type":"text","text":"N","marks":[{"type":"bold"}]},{"type":"text","text":"eed "},{"type":"text","text":"D","marks":[{"type":"bold"}]},{"type":"text","text":"ata "},{"type":"text","text":"P","marks":[{"type":"bold"}]},{"type":"text","text":"rocessing — Application, Presentation, Session, Transport, Network, Data Link, Physical."}]}]}},"revision":1},{"id":"d09babc7-0b50-733b-9d2c-d2465cf6be8d","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"You ↔ Friend — the whole stack in one picture"}]},"revision":1},{"id":"1f7d1bc6-54ee-79a5-8114-023c5f7dc8b5","type":"text","position":"aD","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Think of two people (computers) wanting to talk. On your side, data goes "},{"type":"text","text":"down","marks":[{"type":"italic"}]},{"type":"text","text":" the stack (A→P→S→T→N→D2→Physical), gets physically transmitted, and on the friend''s side it goes back "},{"type":"text","text":"up","marks":[{"type":"italic"}]},{"type":"text","text":" the stack in reverse. Each layer adds its own header as data descends (this is called "},{"type":"text","text":"encapsulation","marks":[{"type":"bold"}]},{"type":"text","text":"), and each corresponding layer strips its header back off as data ascends on the receiving side ("},{"type":"text","text":"decapsulation","marks":[{"type":"bold"}]},{"type":"text","text":")."}]},{"type":"paragraph","content":[{"type":"text","text":"App ↓ Presentation ↓ Session ↓ Transport ↓ Network ↓ Data Link ↓ Physical"}]}]}},"revision":1},{"id":"60db1bdc-b836-7934-a45e-c5ea24fa7815","type":"callout","position":"aE","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"...signal travels across the wire/air..."}]}]}},"revision":1},{"id":"a70456e8-60a8-79a6-86e3-530aea549ddc","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Physical ↑ Data Link ↑ Network ↑ Transport ↑ Session ↑ Presentation ↑ App (friend receives)"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
