INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '535214a3-382c-7e32-9915-2aeb94f354b3', 'e08ff42f-0789-720f-bb71-7ecc8629a7e7', 1, 'PUBLISHED', 'Protocols & Core Terms', '[{"id":"c547f2cb-dfa1-77d5-9a81-7f1edc430c17","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The vocabulary you need before any of the layered models make sense."}]}]}},"revision":1},{"id":"4dadf4b4-8b78-7662-b14a-5c6ec99f524c","type":"callout","position":"a1","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"protocol","marks":[{"type":"bold"}]},{"type":"text","text":" is a set of rules that defines how data is formatted, transmitted, and interpreted between devices. Just like two people need a shared language to have a conversation, two computers need a shared protocol to exchange meaningful data."}]}]}},"revision":1},{"id":"74587ee3-a42b-70b0-ade4-b9f464dd3888","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Protocols aren''t invented by a single company — they''re standardized, often region-by-region and globally, by bodies like the "},{"type":"text","text":"Internet Society","marks":[{"type":"bold"}]},{"type":"text","text":", with the actual technical specifications published as "},{"type":"text","text":"RFCs","marks":[{"type":"bold"}]},{"type":"text","text":" (Request For Comments) through the "},{"type":"text","text":"RFC Editor","marks":[{"type":"bold"}]},{"type":"text","text":". An RFC is essentially the \"spec document\" engineers refer back to when implementing a protocol correctly."}]}]}},"revision":1},{"id":"b0f1d166-3562-7cf2-89d8-531ba2872719","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Client–Server model"}]},"revision":1},{"id":"f6604fcc-f9b9-7a4b-9b19-00210c69eae4","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The dominant pattern for how applications talk over a network:"}]},{"type":"paragraph","content":[{"type":"text","text":"Client request → Server"}]},{"type":"paragraph","content":[{"type":"text","text":"Client ← response Server"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Client","marks":[{"type":"bold"}]},{"type":"text","text":" — initiates the request (your browser, your phone app)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Server","marks":[{"type":"bold"}]},{"type":"text","text":" — a machine that''s always listening, waiting to respond to requests (identified by an IP address)."}]}]}]}]}},"revision":1},{"id":"2d98c8d1-a1f9-7610-93c6-2584822afaf3","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Casting modes: Unicast, Broadcast, Multicast"}]},"revision":1},{"id":"00a661d3-ea66-7295-8a71-a0e7da3a95b2","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How data is addressed and distributed across the network determines its casting mode, operating at both Layer 2 (MAC) and Layer 3 (IP):"}]}]}},"revision":1},{"id":"dcf77049-e2c2-7628-9d66-cc8c0ca2ef27","type":"callout","position":"a7","content":{"variant":"info","title":"Unicast (One-to-One)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Data is sent from a single sender to a single specific receiver. The packet contains one destination IP/MAC address. Used for web browsing, emails, and direct file transfers."}]}]}},"revision":1},{"id":"f76fa4e1-ce03-7063-97a6-8fa233d0504e","type":"callout","position":"a8","content":{"variant":"info","title":"Broadcast (One-to-All)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Data is sent from a single sender to "},{"type":"text","text":"all","marks":[{"type":"italic"}]},{"type":"text","text":" hosts on the same local network subnet. Packets are addressed to a special broadcast address (e.g. "},{"type":"text","text":"255.255.255.255","marks":[{"type":"code"}]},{"type":"text","text":"). Routers block broadcasts to keep traffic localized. Used for ARP resolution and DHCP discovery."}]}]}},"revision":1},{"id":"ac1af9ee-af4a-71fc-a1bc-866b30894b3f","type":"callout","position":"a9","content":{"variant":"info","title":"Multicast (One-to-Many)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Data is sent from a single sender to a specific group of interested receivers who have subscribed to a multicast group IP (ranges "},{"type":"text","text":"224.0.0.0","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"239.255.255.255","marks":[{"type":"code"}]},{"type":"text","text":"). Switches and routers replicate the packets only to ports with active subscribers. Used for live IPTV, video conferencing, and routing protocol updates."}]}]}},"revision":1},{"id":"748c64e4-fe62-7af1-9e7c-a2f7b38a2d76","type":"callout","position":"aA","content":{"variant":"tip","title":"Real-world Analogy","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unicast","marks":[{"type":"bold"}]},{"type":"text","text":" is sending a private letter to a specific home. "},{"type":"text","text":"Broadcast","marks":[{"type":"bold"}]},{"type":"text","text":" is shouting through a megaphone in a neighborhood square where everyone hears you. "},{"type":"text","text":"Multicast","marks":[{"type":"bold"}]},{"type":"text","text":" is sending a magazine only to subscribers of a particular interest club."}]}]}},"revision":1},{"id":"b9421f68-fb03-787b-93ea-5f2c8f6486b2","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Circuit Switching vs Packet Switching"}]},"revision":1},{"id":"2ecdee67-1aae-7555-b237-e7b637c2bd71","type":"text","position":"aC","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The two fundamental paradigms of moving data through a network mesh:"}]}]}},"revision":1},{"id":"ea555911-7347-7524-88ba-cf9ca032ea77","type":"callout","position":"aD","content":{"variant":"info","title":"Circuit Switching","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A dedicated physical communication path (circuit) is established between the sender and receiver before any data is sent. The capacity of the path is reserved and cannot be shared. If no data is sent, the resource is wasted."}]}]}},"revision":1},{"id":"af774943-6136-781a-830e-4db3cb7e713b","type":"callout","position":"aE","content":{"variant":"info","title":"Packet Switching","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Data is broken into smaller chunks called "},{"type":"text","text":"packets","marks":[{"type":"bold"}]},{"type":"text","text":", each containing a header with routing info. Packets travel independently through the network, sharing paths dynamically (statistical multiplexing) and being queued at routers (store-and-forward)."}]}]}},"revision":1},{"id":"757e2fef-efa8-7ff8-8a00-bf59982c8cde","type":"callout","position":"aF","content":{"variant":"tip","title":"Postal vs Phone Analogy","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Circuit Switching","marks":[{"type":"bold"}]},{"type":"text","text":" is like making a phone call: the line is reserved just for your voice, and no one else can use it until you hang up. "},{"type":"text","text":"Packet Switching","marks":[{"type":"bold"}]},{"type":"text","text":" is like sending a multi-chapter book through the mail: each page is placed in an envelope and mailed separately. They might take different routes and arrive out of order, but they are reassembled at the destination."}]}]}},"revision":1},{"id":"0d933648-c467-7dc3-8f40-4f69dfed4c30","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Direct Comparison"}]},"revision":1},{"id":"9ce15f8f-e107-7c69-b0e2-8323d5b504ee","type":"table","position":"aH","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Metric / Feature"}],[{"type":"text","text":"Circuit Switching"}],[{"type":"text","text":"Packet Switching"}]],[[{"type":"text","text":"Resource Reservation","marks":[{"type":"bold"}]}],[{"type":"text","text":"Dedicated path reserved upfront"}],[{"type":"text","text":"Dynamic sharing on demand"}]],[[{"type":"text","text":"Congestion / Queuing","marks":[{"type":"bold"}]}],[{"type":"text","text":"None (Guaranteed bandwidth)"}],[{"type":"text","text":"Yes (Packets wait in router queues)"}]],[[{"type":"text","text":"Setup Delay","marks":[{"type":"bold"}]}],[{"type":"text","text":"High (Requires signaling handshake)"}],[{"type":"text","text":"None (Immediate transmission)"}]],[[{"type":"text","text":"Link Efficiency","marks":[{"type":"bold"}]}],[{"type":"text","text":"Low (Wasted during silence/idle)"}],[{"type":"text","text":"High (Bursty traffic multiplexed)"}]],[[{"type":"text","text":"Failure Resilience","marks":[{"type":"bold"}]}],[{"type":"text","text":"Low (If a link cuts, the call drops)"}],[{"type":"text","text":"High (Packets routed dynamically around faults)"}]],[[{"type":"text","text":"Primary Use Case","marks":[{"type":"bold"}]}],[{"type":"text","text":"Landline telephony (PSTN), GSM voice"}],[{"type":"text","text":"The Internet, LANs, WANs"}]]]},"revision":1},{"id":"3bb2ca97-3858-74ac-ab82-3e1adbe432b9","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"IP Addresses"}]},"revision":1},{"id":"19c5d3aa-b3e1-7778-84f1-b50681994175","type":"callout","position":"aJ","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"IP address","marks":[{"type":"bold"}]},{"type":"text","text":" is a numeric label assigned to every device on a network, used to identify and locate it — conceptually, the \"phone book entry\" of the internet."}]}]}},"revision":1},{"id":"ef31638d-2332-7215-8a69-e50febb0e4a9","type":"text","position":"aK","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every server you talk to is identified by an IP address, even though you usually type a domain name instead (DNS bridges that gap — covered later)."}]}]}},"revision":1},{"id":"aaf860ec-319b-76fd-8bb9-d1a0ab5ca06b","type":"callout","position":"aL","content":{"variant":"tip","title":"Try it","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On macOS/Linux, run "},{"type":"text","text":"curl ifconfig.me -s","marks":[{"type":"code"}]},{"type":"text","text":" in a terminal — it returns your machine''s public IP address as seen from the internet."}]}]}},"revision":1},{"id":"4aadfd1e-b5d6-7934-814b-b4e4b65e6c6d","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"ISPs and the chain to your device"}]},"revision":1},{"id":"372bb5f0-8935-7ea6-9252-3db0e2f84d8c","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Your "},{"type":"text","text":"ISP","marks":[{"type":"bold"}]},{"type":"text","text":" (Internet Service Provider — e.g. Airtel, Jio, Comcast) is the company that actually connects your home or office to the wider internet."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The ISP gives you a "},{"type":"text","text":"modem/router","marks":[{"type":"bold"}]},{"type":"text","text":", which is assigned a "},{"type":"text","text":"global (public) IP address","marks":[{"type":"bold"}]},{"type":"text","text":" — visible to the rest of the internet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inside your home, the router connects to internal devices (laptop, phone, smart TV)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each of those internal devices gets a "},{"type":"text","text":"private/local IP address","marks":[{"type":"bold"}]},{"type":"text","text":", automatically handed out by "},{"type":"text","text":"DHCP","marks":[{"type":"bold"}]},{"type":"text","text":" (Dynamic Host Configuration Protocol)."}]}]}]}]}},"revision":1},{"id":"d46ada24-f2ca-7db8-be51-38f1dd44f595","type":"heading","position":"aO","content":{"level":1,"content":[{"type":"text","text":"Ports"}]},"revision":1},{"id":"ab471fb1-08ed-77d7-bbba-97eb0f428288","type":"callout","position":"aP","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"port number","marks":[{"type":"bold"}]},{"type":"text","text":" identifies a specific application or service running on a device — the IP address gets you to the right machine, the port gets you to the right program on that machine."}]}]}},"revision":1},{"id":"9fa0f91e-2e59-789a-baa3-70b1488a40c8","type":"text","position":"aQ","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ports are "},{"type":"text","text":"16-bit numbers","marks":[{"type":"bold"}]},{"type":"text","text":" → range from 0 to 2¹⁶−1, i.e. roughly "},{"type":"text","text":"65,535","marks":[{"type":"bold"}]},{"type":"text","text":" available ports."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"0–1023","marks":[{"type":"bold"}]},{"type":"text","text":" — well-known / reserved ports (e.g. HTTP = 80, HTTPS = 443, MongoDB = 27017)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"1024–49151","marks":[{"type":"bold"}]},{"type":"text","text":" — registered ports, used by specific named applications."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"49152–65535","marks":[{"type":"bold"}]},{"type":"text","text":" — dynamic/ephemeral ports, free for short-lived use (e.g. the temporary port your browser tab uses for one connection)."}]}]}]}]}},"revision":1},{"id":"13d29e3e-902d-7d97-a696-1420624c4925","type":"heading","position":"aR","content":{"level":1,"content":[{"type":"text","text":"Bandwidth & speed units"}]},"revision":1},{"id":"17bcd74c-e09a-7e91-83a7-4b75852b1a36","type":"table","position":"aS","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Unit"}],[{"type":"text","text":"Meaning"}],[{"type":"text","text":"Value"}]],[[{"type":"text","text":"kbps","marks":[{"type":"bold"}]}],[{"type":"text","text":"kilobits per second"}],[{"type":"text","text":"1,000 bits/sec"}]],[[{"type":"text","text":"Mbps","marks":[{"type":"bold"}]}],[{"type":"text","text":"megabits per second"}],[{"type":"text","text":"1,000,000 bits/sec"}]],[[{"type":"text","text":"Gbps","marks":[{"type":"bold"}]}],[{"type":"text","text":"gigabits per second"}],[{"type":"text","text":"10⁹ bits/sec"}]]]},"revision":1},{"id":"8c619586-a1af-7508-968d-2b7dbc2ccc75","type":"text","position":"aT","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Internet connections are described by separate "},{"type":"text","text":"upload speed","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"download speed","marks":[{"type":"bold"}]},{"type":"text","text":" — most home connections are asymmetric, with download much faster than upload, since typical usage (browsing, streaming) receives far more data than it sends."}]}]}},"revision":1},{"id":"22dd94b0-1e5c-711f-96a4-693f44cf7991","type":"heading","position":"aU","content":{"level":1,"content":[{"type":"text","text":"Network Delay, Throughput & Goodput"}]},"revision":1},{"id":"5a42fa13-0ecf-7273-a2e4-ef3b3ab652e2","type":"text","position":"aV","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When measuring network performance, bandwidth alone is insufficient. We must track how long data takes to travel, how much arrival time varies, and how much actual data is successfully processed."}]}]}},"revision":1},{"id":"caf0ba04-0399-779f-a70c-5d1f83597b0c","type":"callout","position":"aW","content":{"variant":"info","title":"Latency (Delay)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The total time it takes for a data packet to travel from the source to the destination host. Latency is the sum of four distinct components: "},{"type":"text","text":"Nodal Delay","marks":[{"type":"bold"}]},{"type":"text","text":" = Processing Delay + Queuing Delay + Transmission Delay + Propagation Delay."}]}]}},"revision":1},{"id":"c1ef04e7-55d0-763f-897f-5fe9c32008e0","type":"callout","position":"aX","content":{"variant":"info","title":"Jitter","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The variation or fluctuation in packet arrival times (packet delay variation). High jitter causes packets to arrive out of order or clumped together, resulting in choppy audio/video during VoIP calls or video streams."}]}]}},"revision":1},{"id":"868f39c5-0f12-7a4f-a1f8-df699798bae8","type":"callout","position":"aY","content":{"variant":"info","title":"Throughput vs Goodput","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Throughput","marks":[{"type":"bold"}]},{"type":"text","text":" is the total rate at which bits are sent over the physical link per unit time (including TCP/IP headers, metadata, and retransmissions). "},{"type":"text","text":"Goodput","marks":[{"type":"bold"}]},{"type":"text","text":" is the rate of actual useful application-level payload data successfully delivered (excluding all protocol header overhead and duplicate packets)."}]}]}},"revision":1},{"id":"11b320d8-b9ef-7d10-a981-ad945d21b756","type":"callout","position":"aZ","content":{"variant":"tip","title":"Throughput vs Goodput example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If you download a 10MB file and due to a poor connection 2MB of packets are corrupted and retransmitted, your link''s "},{"type":"text","text":"throughput","marks":[{"type":"bold"}]},{"type":"text","text":" counts all 12MB of data sent. However, the "},{"type":"text","text":"goodput","marks":[{"type":"bold"}]},{"type":"text","text":" only counts the 10MB of successfully reassembled file payload delivered to your browser."}]}]}},"revision":1},{"id":"fbc6e4fc-baed-7cb8-8253-3d5671d1b4be","type":"heading","position":"aa","content":{"level":1,"content":[{"type":"text","text":"The Four Sources of Packet Delay (Nodal Delay)"}]},"revision":1},{"id":"8b5be24f-5d9d-7563-be60-0b01630a85c7","type":"text","position":"ab","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A packet experiences different delays at each router hop along its path:"}]}]}},"revision":1},{"id":"1e6d5b52-b502-789a-9856-fd0328f557df","type":"callout","position":"ac","content":{"variant":"info","title":"1. Processing Delay (d_proc)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The time a router takes to inspect a packet''s header, check for bit-level errors using checksums, and determine the next-hop interface. Usually microseconds or less."}]}]}},"revision":1},{"id":"90ecbf96-5e31-72b5-89a0-037df6ac2658","type":"callout","position":"ad","content":{"variant":"info","title":"2. Queuing Delay (d_queue)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The time a packet spends waiting in the router''s buffer queues before being transmitted. Depends heavily on network congestion and the traffic intensity ($L \\cdot a / R$ where $L$ is packet length, $a$ is arrival rate, $R$ is transmission rate). Can range from microseconds to seconds."}]}]}},"revision":1},{"id":"c3c28f21-286c-76cc-8465-8d3e53b75aa5","type":"callout","position":"ae","content":{"variant":"info","title":"3. Transmission Delay (d_trans)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The time taken to push all the packet''s bits onto the physical wire. Formula: "},{"type":"text","text":"d_trans = L / R","marks":[{"type":"code"}]},{"type":"text","text":" (where "},{"type":"text","text":"L","marks":[{"type":"code"}]},{"type":"text","text":" is packet length in bits, and "},{"type":"text","text":"R","marks":[{"type":"code"}]},{"type":"text","text":" is the transmission rate of the link in bps). Depends on packet size and wire speed."}]}]}},"revision":1},{"id":"41be9947-e0ed-77c8-aa6c-6c32f0b7083f","type":"callout","position":"af","content":{"variant":"info","title":"4. Propagation Delay (d_prop)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The time it takes for a single bit to travel physically from one end of the link to the other at the speed of light in the physical medium. Formula: "},{"type":"text","text":"d_prop = d / s","marks":[{"type":"code"}]},{"type":"text","text":" (where "},{"type":"text","text":"d","marks":[{"type":"code"}]},{"type":"text","text":" is physical distance, and "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":" is propagation speed, roughly $2 \\times 10^8$ m/s in optical fiber). Depends only on distance and medium, not packet size."}]}]}},"revision":1},{"id":"b6ec46f7-8183-7eaf-8f70-4f18fa82d9f7","type":"callout","position":"ag","content":{"variant":"tip","title":"Memory Aid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Remember the delay sources top-to-bottom: "},{"type":"text","text":"P","marks":[{"type":"bold"}]},{"type":"text","text":"eople "},{"type":"text","text":"Q","marks":[{"type":"bold"}]},{"type":"text","text":"uickly "},{"type":"text","text":"T","marks":[{"type":"bold"}]},{"type":"text","text":"ake "},{"type":"text","text":"P","marks":[{"type":"bold"}]},{"type":"text","text":"athways — "},{"type":"text","text":"P","marks":[{"type":"bold"}]},{"type":"text","text":"rocessing, "},{"type":"text","text":"Q","marks":[{"type":"bold"}]},{"type":"text","text":"ueuing, "},{"type":"text","text":"T","marks":[{"type":"bold"}]},{"type":"text","text":"ransmission, "},{"type":"text","text":"P","marks":[{"type":"bold"}]},{"type":"text","text":"ropagation."}]}]}},"revision":1},{"id":"260af91a-26dd-7dff-957d-d7261492ad9a","type":"callout","position":"ah","content":{"variant":"info","title":"Quality of Service (QoS)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A suite of technologies (like traffic shaping, packet tagging, and priority queuing) used to manage traffic congestion. QoS ensures high-priority, latency-sensitive packets (like live voice/video) are processed ahead of non-critical traffic (like bulk file downloads)."}]}]}},"revision":1},{"id":"53199e2a-0696-7765-b24e-d06cde649624","type":"heading","position":"ai","content":{"level":1,"content":[{"type":"text","text":"Guided vs unguided media"}]},"revision":1},{"id":"f0b5281c-1746-739b-8bbd-f3306f4e4225","type":"callout","position":"aj","content":{"variant":"info","title":"Guided","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Data travels along a physically defined path — copper or fiber cable. Faster and more reliable because the path is fixed and shielded from interference."}]}]}},"revision":1},{"id":"0988d497-f7cd-77f0-bd21-60ef7069edae","type":"callout","position":"ak","content":{"variant":"info","title":"Unguided","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Data travels through open space with no single fixed path — radio waves. Used by Wi-Fi and Bluetooth (short range) and 3G/4G/LTE/5G (long range)."}]}]}},"revision":1},{"id":"7bd1bb43-647d-76e7-b86b-c10bfd15a874","type":"heading","position":"al","content":{"level":1,"content":[{"type":"text","text":"How continents are physically connected"}]},"revision":1},{"id":"3f072337-f834-7613-bf32-e2f193ae2884","type":"text","position":"am","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Even satellite and radio aside, the backbone of global internet traffic is "},{"type":"text","text":"physical undersea cables","marks":[{"type":"bold"}]},{"type":"text","text":" — optical fiber laid across ocean floors connecting continents. You can see the actual global map of these at "},{"type":"text","text":"submarinecablemap.com","marks":[{"type":"code"}]},{"type":"text","text":", maintained by TeleGeography — it shows hundreds of named cables (2Africa, AEConnect-1, etc.) physically linking landing points across every continent."}]}]}},"revision":1},{"id":"e0b471f6-6e95-712a-ba8a-3e08f68ce80a","type":"callout","position":"an","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Physical cables remain faster and more reliable than wireless long-haul links, which is why almost all intercontinental internet traffic — even from \"wireless\" companies — ultimately rides on undersea fiber."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'e08ff42f-0789-720f-bb71-7ecc8629a7e7' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
ON CONFLICT DO NOTHING;

INSERT INTO "notes"."Card" ("id", "noteId", "position", "type", "content", "revision", "createdAt", "updatedAt")
SELECT c.id::uuid, 'e08ff42f-0789-720f-bb71-7ecc8629a7e7', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('c547f2cb-dfa1-77d5-9a81-7f1edc430c17', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The vocabulary you need before any of the layered models make sense."}]}]}}'),
  ('4dadf4b4-8b78-7662-b14a-5c6ec99f524c', 'a1', 'callout', '{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"protocol","marks":[{"type":"bold"}]},{"type":"text","text":" is a set of rules that defines how data is formatted, transmitted, and interpreted between devices. Just like two people need a shared language to have a conversation, two computers need a shared protocol to exchange meaningful data."}]}]}}'),
  ('74587ee3-a42b-70b0-ade4-b9f464dd3888', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Protocols aren''t invented by a single company — they''re standardized, often region-by-region and globally, by bodies like the "},{"type":"text","text":"Internet Society","marks":[{"type":"bold"}]},{"type":"text","text":", with the actual technical specifications published as "},{"type":"text","text":"RFCs","marks":[{"type":"bold"}]},{"type":"text","text":" (Request For Comments) through the "},{"type":"text","text":"RFC Editor","marks":[{"type":"bold"}]},{"type":"text","text":". An RFC is essentially the \"spec document\" engineers refer back to when implementing a protocol correctly."}]}]}}'),
  ('b0f1d166-3562-7cf2-89d8-531ba2872719', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"Client–Server model"}]}'),
  ('f6604fcc-f9b9-7a4b-9b19-00210c69eae4', 'a4', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The dominant pattern for how applications talk over a network:"}]},{"type":"paragraph","content":[{"type":"text","text":"Client request → Server"}]},{"type":"paragraph","content":[{"type":"text","text":"Client ← response Server"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Client","marks":[{"type":"bold"}]},{"type":"text","text":" — initiates the request (your browser, your phone app)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Server","marks":[{"type":"bold"}]},{"type":"text","text":" — a machine that''s always listening, waiting to respond to requests (identified by an IP address)."}]}]}]}]}}'),
  ('2d98c8d1-a1f9-7610-93c6-2584822afaf3', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"Casting modes: Unicast, Broadcast, Multicast"}]}'),
  ('00a661d3-ea66-7295-8a71-a0e7da3a95b2', 'a6', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How data is addressed and distributed across the network determines its casting mode, operating at both Layer 2 (MAC) and Layer 3 (IP):"}]}]}}'),
  ('dcf77049-e2c2-7628-9d66-cc8c0ca2ef27', 'a7', 'callout', '{"variant":"info","title":"Unicast (One-to-One)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Data is sent from a single sender to a single specific receiver. The packet contains one destination IP/MAC address. Used for web browsing, emails, and direct file transfers."}]}]}}'),
  ('f76fa4e1-ce03-7063-97a6-8fa233d0504e', 'a8', 'callout', '{"variant":"info","title":"Broadcast (One-to-All)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Data is sent from a single sender to "},{"type":"text","text":"all","marks":[{"type":"italic"}]},{"type":"text","text":" hosts on the same local network subnet. Packets are addressed to a special broadcast address (e.g. "},{"type":"text","text":"255.255.255.255","marks":[{"type":"code"}]},{"type":"text","text":"). Routers block broadcasts to keep traffic localized. Used for ARP resolution and DHCP discovery."}]}]}}'),
  ('ac1af9ee-af4a-71fc-a1bc-866b30894b3f', 'a9', 'callout', '{"variant":"info","title":"Multicast (One-to-Many)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Data is sent from a single sender to a specific group of interested receivers who have subscribed to a multicast group IP (ranges "},{"type":"text","text":"224.0.0.0","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"239.255.255.255","marks":[{"type":"code"}]},{"type":"text","text":"). Switches and routers replicate the packets only to ports with active subscribers. Used for live IPTV, video conferencing, and routing protocol updates."}]}]}}'),
  ('748c64e4-fe62-7af1-9e7c-a2f7b38a2d76', 'aA', 'callout', '{"variant":"tip","title":"Real-world Analogy","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unicast","marks":[{"type":"bold"}]},{"type":"text","text":" is sending a private letter to a specific home. "},{"type":"text","text":"Broadcast","marks":[{"type":"bold"}]},{"type":"text","text":" is shouting through a megaphone in a neighborhood square where everyone hears you. "},{"type":"text","text":"Multicast","marks":[{"type":"bold"}]},{"type":"text","text":" is sending a magazine only to subscribers of a particular interest club."}]}]}}'),
  ('b9421f68-fb03-787b-93ea-5f2c8f6486b2', 'aB', 'heading', '{"level":1,"content":[{"type":"text","text":"Circuit Switching vs Packet Switching"}]}'),
  ('2ecdee67-1aae-7555-b237-e7b637c2bd71', 'aC', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The two fundamental paradigms of moving data through a network mesh:"}]}]}}'),
  ('ea555911-7347-7524-88ba-cf9ca032ea77', 'aD', 'callout', '{"variant":"info","title":"Circuit Switching","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A dedicated physical communication path (circuit) is established between the sender and receiver before any data is sent. The capacity of the path is reserved and cannot be shared. If no data is sent, the resource is wasted."}]}]}}'),
  ('af774943-6136-781a-830e-4db3cb7e713b', 'aE', 'callout', '{"variant":"info","title":"Packet Switching","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Data is broken into smaller chunks called "},{"type":"text","text":"packets","marks":[{"type":"bold"}]},{"type":"text","text":", each containing a header with routing info. Packets travel independently through the network, sharing paths dynamically (statistical multiplexing) and being queued at routers (store-and-forward)."}]}]}}'),
  ('757e2fef-efa8-7ff8-8a00-bf59982c8cde', 'aF', 'callout', '{"variant":"tip","title":"Postal vs Phone Analogy","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Circuit Switching","marks":[{"type":"bold"}]},{"type":"text","text":" is like making a phone call: the line is reserved just for your voice, and no one else can use it until you hang up. "},{"type":"text","text":"Packet Switching","marks":[{"type":"bold"}]},{"type":"text","text":" is like sending a multi-chapter book through the mail: each page is placed in an envelope and mailed separately. They might take different routes and arrive out of order, but they are reassembled at the destination."}]}]}}'),
  ('0d933648-c467-7dc3-8f40-4f69dfed4c30', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Direct Comparison"}]}'),
  ('9ce15f8f-e107-7c69-b0e2-8323d5b504ee', 'aH', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Metric / Feature"}],[{"type":"text","text":"Circuit Switching"}],[{"type":"text","text":"Packet Switching"}]],[[{"type":"text","text":"Resource Reservation","marks":[{"type":"bold"}]}],[{"type":"text","text":"Dedicated path reserved upfront"}],[{"type":"text","text":"Dynamic sharing on demand"}]],[[{"type":"text","text":"Congestion / Queuing","marks":[{"type":"bold"}]}],[{"type":"text","text":"None (Guaranteed bandwidth)"}],[{"type":"text","text":"Yes (Packets wait in router queues)"}]],[[{"type":"text","text":"Setup Delay","marks":[{"type":"bold"}]}],[{"type":"text","text":"High (Requires signaling handshake)"}],[{"type":"text","text":"None (Immediate transmission)"}]],[[{"type":"text","text":"Link Efficiency","marks":[{"type":"bold"}]}],[{"type":"text","text":"Low (Wasted during silence/idle)"}],[{"type":"text","text":"High (Bursty traffic multiplexed)"}]],[[{"type":"text","text":"Failure Resilience","marks":[{"type":"bold"}]}],[{"type":"text","text":"Low (If a link cuts, the call drops)"}],[{"type":"text","text":"High (Packets routed dynamically around faults)"}]],[[{"type":"text","text":"Primary Use Case","marks":[{"type":"bold"}]}],[{"type":"text","text":"Landline telephony (PSTN), GSM voice"}],[{"type":"text","text":"The Internet, LANs, WANs"}]]]}'),
  ('3bb2ca97-3858-74ac-ab82-3e1adbe432b9', 'aI', 'heading', '{"level":1,"content":[{"type":"text","text":"IP Addresses"}]}'),
  ('19c5d3aa-b3e1-7778-84f1-b50681994175', 'aJ', 'callout', '{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"IP address","marks":[{"type":"bold"}]},{"type":"text","text":" is a numeric label assigned to every device on a network, used to identify and locate it — conceptually, the \"phone book entry\" of the internet."}]}]}}'),
  ('ef31638d-2332-7215-8a69-e50febb0e4a9', 'aK', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every server you talk to is identified by an IP address, even though you usually type a domain name instead (DNS bridges that gap — covered later)."}]}]}}'),
  ('aaf860ec-319b-76fd-8bb9-d1a0ab5ca06b', 'aL', 'callout', '{"variant":"tip","title":"Try it","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On macOS/Linux, run "},{"type":"text","text":"curl ifconfig.me -s","marks":[{"type":"code"}]},{"type":"text","text":" in a terminal — it returns your machine''s public IP address as seen from the internet."}]}]}}'),
  ('4aadfd1e-b5d6-7934-814b-b4e4b65e6c6d', 'aM', 'heading', '{"level":1,"content":[{"type":"text","text":"ISPs and the chain to your device"}]}'),
  ('372bb5f0-8935-7ea6-9252-3db0e2f84d8c', 'aN', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Your "},{"type":"text","text":"ISP","marks":[{"type":"bold"}]},{"type":"text","text":" (Internet Service Provider — e.g. Airtel, Jio, Comcast) is the company that actually connects your home or office to the wider internet."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The ISP gives you a "},{"type":"text","text":"modem/router","marks":[{"type":"bold"}]},{"type":"text","text":", which is assigned a "},{"type":"text","text":"global (public) IP address","marks":[{"type":"bold"}]},{"type":"text","text":" — visible to the rest of the internet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inside your home, the router connects to internal devices (laptop, phone, smart TV)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each of those internal devices gets a "},{"type":"text","text":"private/local IP address","marks":[{"type":"bold"}]},{"type":"text","text":", automatically handed out by "},{"type":"text","text":"DHCP","marks":[{"type":"bold"}]},{"type":"text","text":" (Dynamic Host Configuration Protocol)."}]}]}]}]}}'),
  ('d46ada24-f2ca-7db8-be51-38f1dd44f595', 'aO', 'heading', '{"level":1,"content":[{"type":"text","text":"Ports"}]}'),
  ('ab471fb1-08ed-77d7-bbba-97eb0f428288', 'aP', 'callout', '{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"port number","marks":[{"type":"bold"}]},{"type":"text","text":" identifies a specific application or service running on a device — the IP address gets you to the right machine, the port gets you to the right program on that machine."}]}]}}'),
  ('9fa0f91e-2e59-789a-baa3-70b1488a40c8', 'aQ', 'text', '{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ports are "},{"type":"text","text":"16-bit numbers","marks":[{"type":"bold"}]},{"type":"text","text":" → range from 0 to 2¹⁶−1, i.e. roughly "},{"type":"text","text":"65,535","marks":[{"type":"bold"}]},{"type":"text","text":" available ports."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"0–1023","marks":[{"type":"bold"}]},{"type":"text","text":" — well-known / reserved ports (e.g. HTTP = 80, HTTPS = 443, MongoDB = 27017)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"1024–49151","marks":[{"type":"bold"}]},{"type":"text","text":" — registered ports, used by specific named applications."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"49152–65535","marks":[{"type":"bold"}]},{"type":"text","text":" — dynamic/ephemeral ports, free for short-lived use (e.g. the temporary port your browser tab uses for one connection)."}]}]}]}]}}'),
  ('13d29e3e-902d-7d97-a696-1420624c4925', 'aR', 'heading', '{"level":1,"content":[{"type":"text","text":"Bandwidth & speed units"}]}'),
  ('17bcd74c-e09a-7e91-83a7-4b75852b1a36', 'aS', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Unit"}],[{"type":"text","text":"Meaning"}],[{"type":"text","text":"Value"}]],[[{"type":"text","text":"kbps","marks":[{"type":"bold"}]}],[{"type":"text","text":"kilobits per second"}],[{"type":"text","text":"1,000 bits/sec"}]],[[{"type":"text","text":"Mbps","marks":[{"type":"bold"}]}],[{"type":"text","text":"megabits per second"}],[{"type":"text","text":"1,000,000 bits/sec"}]],[[{"type":"text","text":"Gbps","marks":[{"type":"bold"}]}],[{"type":"text","text":"gigabits per second"}],[{"type":"text","text":"10⁹ bits/sec"}]]]}'),
  ('8c619586-a1af-7508-968d-2b7dbc2ccc75', 'aT', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Internet connections are described by separate "},{"type":"text","text":"upload speed","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"download speed","marks":[{"type":"bold"}]},{"type":"text","text":" — most home connections are asymmetric, with download much faster than upload, since typical usage (browsing, streaming) receives far more data than it sends."}]}]}}'),
  ('22dd94b0-1e5c-711f-96a4-693f44cf7991', 'aU', 'heading', '{"level":1,"content":[{"type":"text","text":"Network Delay, Throughput & Goodput"}]}'),
  ('5a42fa13-0ecf-7273-a2e4-ef3b3ab652e2', 'aV', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When measuring network performance, bandwidth alone is insufficient. We must track how long data takes to travel, how much arrival time varies, and how much actual data is successfully processed."}]}]}}'),
  ('caf0ba04-0399-779f-a70c-5d1f83597b0c', 'aW', 'callout', '{"variant":"info","title":"Latency (Delay)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The total time it takes for a data packet to travel from the source to the destination host. Latency is the sum of four distinct components: "},{"type":"text","text":"Nodal Delay","marks":[{"type":"bold"}]},{"type":"text","text":" = Processing Delay + Queuing Delay + Transmission Delay + Propagation Delay."}]}]}}'),
  ('c1ef04e7-55d0-763f-897f-5fe9c32008e0', 'aX', 'callout', '{"variant":"info","title":"Jitter","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The variation or fluctuation in packet arrival times (packet delay variation). High jitter causes packets to arrive out of order or clumped together, resulting in choppy audio/video during VoIP calls or video streams."}]}]}}'),
  ('868f39c5-0f12-7a4f-a1f8-df699798bae8', 'aY', 'callout', '{"variant":"info","title":"Throughput vs Goodput","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Throughput","marks":[{"type":"bold"}]},{"type":"text","text":" is the total rate at which bits are sent over the physical link per unit time (including TCP/IP headers, metadata, and retransmissions). "},{"type":"text","text":"Goodput","marks":[{"type":"bold"}]},{"type":"text","text":" is the rate of actual useful application-level payload data successfully delivered (excluding all protocol header overhead and duplicate packets)."}]}]}}'),
  ('11b320d8-b9ef-7d10-a981-ad945d21b756', 'aZ', 'callout', '{"variant":"tip","title":"Throughput vs Goodput example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If you download a 10MB file and due to a poor connection 2MB of packets are corrupted and retransmitted, your link''s "},{"type":"text","text":"throughput","marks":[{"type":"bold"}]},{"type":"text","text":" counts all 12MB of data sent. However, the "},{"type":"text","text":"goodput","marks":[{"type":"bold"}]},{"type":"text","text":" only counts the 10MB of successfully reassembled file payload delivered to your browser."}]}]}}'),
  ('fbc6e4fc-baed-7cb8-8253-3d5671d1b4be', 'aa', 'heading', '{"level":1,"content":[{"type":"text","text":"The Four Sources of Packet Delay (Nodal Delay)"}]}'),
  ('8b5be24f-5d9d-7563-be60-0b01630a85c7', 'ab', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A packet experiences different delays at each router hop along its path:"}]}]}}'),
  ('1e6d5b52-b502-789a-9856-fd0328f557df', 'ac', 'callout', '{"variant":"info","title":"1. Processing Delay (d_proc)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The time a router takes to inspect a packet''s header, check for bit-level errors using checksums, and determine the next-hop interface. Usually microseconds or less."}]}]}}'),
  ('90ecbf96-5e31-72b5-89a0-037df6ac2658', 'ad', 'callout', '{"variant":"info","title":"2. Queuing Delay (d_queue)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The time a packet spends waiting in the router''s buffer queues before being transmitted. Depends heavily on network congestion and the traffic intensity ($L \\cdot a / R$ where $L$ is packet length, $a$ is arrival rate, $R$ is transmission rate). Can range from microseconds to seconds."}]}]}}'),
  ('c3c28f21-286c-76cc-8465-8d3e53b75aa5', 'ae', 'callout', '{"variant":"info","title":"3. Transmission Delay (d_trans)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The time taken to push all the packet''s bits onto the physical wire. Formula: "},{"type":"text","text":"d_trans = L / R","marks":[{"type":"code"}]},{"type":"text","text":" (where "},{"type":"text","text":"L","marks":[{"type":"code"}]},{"type":"text","text":" is packet length in bits, and "},{"type":"text","text":"R","marks":[{"type":"code"}]},{"type":"text","text":" is the transmission rate of the link in bps). Depends on packet size and wire speed."}]}]}}'),
  ('41be9947-e0ed-77c8-aa6c-6c32f0b7083f', 'af', 'callout', '{"variant":"info","title":"4. Propagation Delay (d_prop)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The time it takes for a single bit to travel physically from one end of the link to the other at the speed of light in the physical medium. Formula: "},{"type":"text","text":"d_prop = d / s","marks":[{"type":"code"}]},{"type":"text","text":" (where "},{"type":"text","text":"d","marks":[{"type":"code"}]},{"type":"text","text":" is physical distance, and "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":" is propagation speed, roughly $2 \\times 10^8$ m/s in optical fiber). Depends only on distance and medium, not packet size."}]}]}}'),
  ('b6ec46f7-8183-7eaf-8f70-4f18fa82d9f7', 'ag', 'callout', '{"variant":"tip","title":"Memory Aid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Remember the delay sources top-to-bottom: "},{"type":"text","text":"P","marks":[{"type":"bold"}]},{"type":"text","text":"eople "},{"type":"text","text":"Q","marks":[{"type":"bold"}]},{"type":"text","text":"uickly "},{"type":"text","text":"T","marks":[{"type":"bold"}]},{"type":"text","text":"ake "},{"type":"text","text":"P","marks":[{"type":"bold"}]},{"type":"text","text":"athways — "},{"type":"text","text":"P","marks":[{"type":"bold"}]},{"type":"text","text":"rocessing, "},{"type":"text","text":"Q","marks":[{"type":"bold"}]},{"type":"text","text":"ueuing, "},{"type":"text","text":"T","marks":[{"type":"bold"}]},{"type":"text","text":"ransmission, "},{"type":"text","text":"P","marks":[{"type":"bold"}]},{"type":"text","text":"ropagation."}]}]}}'),
  ('260af91a-26dd-7dff-957d-d7261492ad9a', 'ah', 'callout', '{"variant":"info","title":"Quality of Service (QoS)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A suite of technologies (like traffic shaping, packet tagging, and priority queuing) used to manage traffic congestion. QoS ensures high-priority, latency-sensitive packets (like live voice/video) are processed ahead of non-critical traffic (like bulk file downloads)."}]}]}}'),
  ('53199e2a-0696-7765-b24e-d06cde649624', 'ai', 'heading', '{"level":1,"content":[{"type":"text","text":"Guided vs unguided media"}]}'),
  ('f0b5281c-1746-739b-8bbd-f3306f4e4225', 'aj', 'callout', '{"variant":"info","title":"Guided","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Data travels along a physically defined path — copper or fiber cable. Faster and more reliable because the path is fixed and shielded from interference."}]}]}}'),
  ('0988d497-f7cd-77f0-bd21-60ef7069edae', 'ak', 'callout', '{"variant":"info","title":"Unguided","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Data travels through open space with no single fixed path — radio waves. Used by Wi-Fi and Bluetooth (short range) and 3G/4G/LTE/5G (long range)."}]}]}}'),
  ('7bd1bb43-647d-76e7-b86b-c10bfd15a874', 'al', 'heading', '{"level":1,"content":[{"type":"text","text":"How continents are physically connected"}]}'),
  ('3f072337-f834-7613-bf32-e2f193ae2884', 'am', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Even satellite and radio aside, the backbone of global internet traffic is "},{"type":"text","text":"physical undersea cables","marks":[{"type":"bold"}]},{"type":"text","text":" — optical fiber laid across ocean floors connecting continents. You can see the actual global map of these at "},{"type":"text","text":"submarinecablemap.com","marks":[{"type":"code"}]},{"type":"text","text":", maintained by TeleGeography — it shows hundreds of named cables (2Africa, AEConnect-1, etc.) physically linking landing points across every continent."}]}]}}'),
  ('e0b471f6-6e95-712a-ba8a-3e08f68ce80a', 'an', 'callout', '{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Physical cables remain faster and more reliable than wireless long-haul links, which is why almost all intercontinental internet traffic — even from \"wireless\" companies — ultimately rides on undersea fiber."}]}]}}')
) AS c(id, position, type, content)
