SELECT 'b74e3bb7-36ab-7580-a103-9af31a9c02a1', 'aa873695-84a4-7d9a-96a0-c657b1bb8a2e', 1, 'PUBLISHED', 'LAN / MAN / WAN & Structure', '[{"id":"8fd91802-996c-7600-9d5c-a4d4cbd20618","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How small local networks chain together to form the internet — and the analogy that makes layering click."}]}]}},"revision":1},{"id":"41e50075-64bc-7764-8b5d-b1f3a40ddff3","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Network scale classifications"}]},"revision":1},{"id":"5add7848-7af7-72e8-a2a5-bbae8bba55e6","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Term"}],[{"type":"text","text":"Full name"}],[{"type":"text","text":"Scale"}],[{"type":"text","text":"Typical medium"}]],[[{"type":"text","text":"LAN","marks":[{"type":"bold"}]}],[{"type":"text","text":"Local Area Network"}],[{"type":"text","text":"A single home, office, or building"}],[{"type":"text","text":"Ethernet cables, Wi-Fi"}]],[[{"type":"text","text":"MAN","marks":[{"type":"bold"}]}],[{"type":"text","text":"Metropolitan Area Network"}],[{"type":"text","text":"Across a city"}],[{"type":"text","text":"Fiber backbones connecting multiple LANs"}]],[[{"type":"text","text":"WAN","marks":[{"type":"bold"}]}],[{"type":"text","text":"Wide Area Network"}],[{"type":"text","text":"Across countries / continents"}],[{"type":"text","text":"SONET","marks":[{"type":"bold"}]},{"type":"text","text":" (Synchronous Optical Network), leased lines, satellite"}]]]},"revision":1},{"id":"15ed9f3c-60f9-713c-8f94-41c122b7bb4d","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Frame Relay","marks":[{"type":"bold"}]},{"type":"text","text":" is a WAN protocol historically used to connect LANs across a wide area cost-effectively, by packaging data into variable-length \"frames\" sent over a shared carrier network — a precursor to many of today''s WAN/VPN technologies."}]}]}},"revision":1},{"id":"e1112c20-4344-70e2-88f1-3ef26609f80f","type":"callout","position":"a4","content":{"variant":"info","title":"Big picture","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"internet","marks":[{"type":"bold"}]},{"type":"text","text":" is simply the collection of all interconnected LANs, MANs, and WANs across the world — your home LAN connects to your ISP''s MAN, which peers into global WAN backbones, which connect to other countries'' networks."}]}]}},"revision":1},{"id":"a7a957f3-ba60-7abb-a686-4ae1a4ef2b2b","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Modem / Router — the bridge between worlds"}]},"revision":1},{"id":"f8219b61-37d5-71ed-94bc-09af33dc5fff","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"modem","marks":[{"type":"bold"}]},{"type":"text","text":" converts digital signals (what your computer understands) into analog signals (what travels over telephone/cable lines) and vice versa — the literal translator between your home network and your ISP''s infrastructure. A "},{"type":"text","text":"router","marks":[{"type":"bold"}]},{"type":"text","text":" is the device that decides where to forward data packets next, both within your home network and out to the internet (in home setups, the ISP-provided device is usually a combined modem+router)."}]}]}},"revision":1},{"id":"daadcea3-6713-7b78-a2f7-d63b69048666","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Tier 1 vs Tier 2 ISPs"}]},"revision":1},{"id":"d550d405-1f92-76b9-a3de-4063a33b82a8","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tier 1 ISPs","marks":[{"type":"bold"}]},{"type":"text","text":" — own global backbone infrastructure and don''t pay anyone for transit (e.g. TATA Communications). They peer directly with each other."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tier 2 ISPs","marks":[{"type":"bold"}]},{"type":"text","text":" — regional/national providers (e.g. Airtel, Jio) that buy transit from Tier 1s to reach the rest of the internet, while also peering with each other locally."}]}]}]}]}},"revision":1},{"id":"9ba972af-1929-77ff-9044-6b8ca3b9394a","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"The Amazon delivery analogy"}]},"revision":1},{"id":"1a433658-4461-73a6-9cd4-cd63c1ead162","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is the mental model that makes the entire layered approach (OSI/TCP-IP) click: shipping a physical package mirrors exactly how data is \"shipped\" across a network."}]},{"type":"paragraph","content":[{"type":"text","text":"You order → Amazon → Delivery company → Transported (across India) → Local delivery → You receive"}]},{"type":"paragraph","content":[{"type":"text","text":"Notice each stage only cares about its own job: Amazon doesn''t drive the truck, the delivery company doesn''t know what''s inside the box, and the truck driver doesn''t know who the recipient is beyond an address label. This is exactly the idea of "},{"type":"text","text":"layering","marks":[{"type":"bold"}]},{"type":"text","text":" — each network layer only does its specific job and hands the package to the next layer, ignorant of what the layers above or below are doing with the contents."}]}]}},"revision":1},{"id":"ac4e7ae1-8946-7f72-ac76-74e7f3ec79d5","type":"callout","position":"aB","content":{"variant":"tip","title":"Application layer connection","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In this analogy, \"placing the order\" and \"receiving the package\" are the parts "},{"type":"text","text":"you","marks":[{"type":"italic"}]},{"type":"text","text":" directly interact with — this maps to the "},{"type":"text","text":"Application Layer","marks":[{"type":"bold"}]},{"type":"text","text":", the only layer that''s visible to the end user. Everything else (the courier routing, the trucks, the roads) happens invisibly underneath, just like the lower OSI layers."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
