  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = 'aa873695-84a4-7d9a-96a0-c657b1bb8a2e' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = 'b74e3bb7-36ab-7580-a103-9af31a9c02a1' AND n."deletedAt" IS NULL
