INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '52e8d0f7-c8fe-77d6-9944-282fc9a35c1d', 'fe3a547d-eef6-77c7-962d-59fbdd29b565', 1, 'PUBLISHED', 'TCP vs UDP, Deep Dive', '[{"id":"bd42efa0-fb29-7328-a7e2-b57b7d0442b3","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The two transport protocols, and why an application picks one over the other."}]}]}},"revision":1},{"id":"3f6cdab6-434e-7ceb-9471-a604bb30dc86","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Multiplexing & demultiplexing"}]},"revision":1},{"id":"7857840e-6826-7ea1-b8ba-ae4c11869097","type":"callout","position":"a2","content":{"variant":"info","title":"Multiplexing","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Allows many different streams (a message, a file, a video call) to all be sent to the destination through one shared medium/connection, by the Transport Layer combining them with distinct port numbers."}]}]}},"revision":1},{"id":"9a839d29-894d-7621-af8b-68cd4cf5f13a","type":"callout","position":"a3","content":{"variant":"info","title":"Demultiplexing","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The reverse process on the receiving end — using "},{"type":"text","text":"sockets","marks":[{"type":"bold"}]},{"type":"text","text":" (the gateway between an application and the network, identified by IP + port) to correctly route incoming data back to the right application."}]}]}},"revision":1},{"id":"9b6d220c-f6e0-7e7c-8891-07a4728b702b","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Checksums — how corruption is detected"}]},"revision":1},{"id":"04c681af-8e03-742d-8188-b275ffdc1447","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both TCP and UDP use checksums to detect data corruption:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The sender computes a checksum value from the data using a defined algorithm and attaches it alongside the data."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The data + checksum travel together across the network."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The receiver re-runs the same algorithm on the received data and compares the result against the attached checksum."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If they match, the data is assumed intact; if not, it''s flagged as corrupted."}]}]}]}]}},"revision":1},{"id":"0bc4dff0-c0b9-71fe-95a0-23ad9df0665f","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Reliability mechanics — timers, ACKs, sequencing"}]},"revision":1},{"id":"0e8d5b1b-2874-7177-a5ab-53b6ef597881","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"When data is sent, a "},{"type":"text","text":"timer","marks":[{"type":"bold"}]},{"type":"text","text":" starts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"acknowledgement (ACK)","marks":[{"type":"bold"}]},{"type":"text","text":" from the receiver stops the timer, confirming successful delivery."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If no ACK arrives before the timer expires, a "},{"type":"text","text":"retransmission","marks":[{"type":"bold"}]},{"type":"text","text":" is triggered."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Problem:","marks":[{"type":"bold"}]},{"type":"text","text":" if data was actually received but the ACK itself was lost, naive retransmission would cause "},{"type":"text","text":"duplicate data","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Solution:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"sequence numbers","marks":[{"type":"bold"}]},{"type":"text","text":" let the receiver recognize and discard duplicates, and reassemble data in the correct order even if packets arrive out of sequence."}]}]}]}]}},"revision":1},{"id":"a7aaf0b3-def1-74ba-9fb6-d76ebab572f5","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"UDP — User Datagram Protocol"}]},"revision":1},{"id":"7d2652cd-8fe5-75ea-8d28-752d2e94c534","type":"callout","position":"a9","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"UDP is a lightweight, "},{"type":"text","text":"connectionless","marks":[{"type":"bold"}]},{"type":"text","text":" transport protocol. It sends data without establishing a dedicated connection first, and without guaranteeing delivery, order, or integrity beyond a basic checksum."}]}]}},"revision":1},{"id":"8776e5ff-eec4-7e10-a5aa-495fd9ac1e5e","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Data "},{"type":"text","text":"may or may not","marks":[{"type":"bold"}]},{"type":"text","text":" be delivered — no acknowledgements, no retransmission"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Data may be received out of order, damaged, or duplicated — UDP doesn''t fix any of that itself"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Still uses a checksum, but doesn''t act on a failure beyond detecting it"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Why use it anyway:","marks":[{"type":"bold"}]},{"type":"text","text":" it''s much faster, because it skips all the handshake/acknowledgement/retransmission overhead"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Common uses:","marks":[{"type":"bold"}]},{"type":"text","text":" video conferencing, online gaming, and DNS lookups — all cases where speed matters more than guaranteed perfect delivery (a slightly garbled video frame is fine; waiting for a perfect retransmitted one isn''t)."}]}]}},"revision":1},{"id":"c77bce34-8683-71b1-b7c8-de7434677e52","type":"heading","position":"aB","content":{"level":2,"content":[{"type":"text","text":"UDP Packet structure"}]},"revision":1},{"id":"f01556b6-2e13-7b88-9c26-6c3235a29002","type":"text","position":"aC","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Total header size: "},{"type":"text","text":"8 bytes","marks":[{"type":"bold"}]},{"type":"text","text":", split into four 2-byte fields:"}]}]}},"revision":1},{"id":"d2174e7e-5a97-766a-823d-13b5ffe69657","type":"table","position":"aD","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Field"}],[{"type":"text","text":"Size"}]],[[{"type":"text","text":"Source Port No."}],[{"type":"text","text":"2 bytes"}]],[[{"type":"text","text":"Destination Port No."}],[{"type":"text","text":"2 bytes"}]],[[{"type":"text","text":"Length of datagram"}],[{"type":"text","text":"2 bytes"}]],[[{"type":"text","text":"Checksum"}],[{"type":"text","text":"2 bytes"}]],[[{"type":"text","text":"Data (payload)"}],[{"type":"text","text":"variable"}]]]},"revision":1},{"id":"4ed7274a-343c-7790-a8ad-9083f188f713","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"4 fields × 2 bytes = 8 bytes header (16 bits each × 4 = 64 bits = 8 bytes)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"b168a204-36a4-7ef5-ad10-ffe2d7da0edb","type":"callout","position":"aF","content":{"variant":"tip","title":"Try it","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Run "},{"type":"text","text":"tcpdump -c 5","marks":[{"type":"code"}]},{"type":"text","text":" in a terminal (with sufficient permissions) to capture and inspect the first 5 live packets crossing your network interface."}]}]}},"revision":1},{"id":"4675c550-9a33-7f32-aef9-93dd38f93adc","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"TCP — Transmission Control Protocol"}]},"revision":1},{"id":"730391bf-0cd8-776a-8c35-91b10c7d0ea2","type":"callout","position":"aH","content":{"variant":"info","title":"Definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"TCP is a "},{"type":"text","text":"connection-oriented","marks":[{"type":"bold"}]},{"type":"text","text":", reliable transport protocol. Before any data is sent, both sides establish a dedicated connection, and TCP guarantees that data arrives complete, uncorrupted, and in the correct order."}]}]}},"revision":1},{"id":"3b34adc0-01f7-7d18-bc44-6f600b75f2bc","type":"text","position":"aI","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Application layer hands TCP large amounts of raw data; TCP divides it into chunks, adds headers and a checksum to each"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tracks two critical things: data that doesn''t arrive (via timers/retransmission) and data order (via sequence numbers)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Congestion control","marks":[{"type":"bold"}]},{"type":"text","text":" — dynamically adjusts how much data is sent based on network conditions, to avoid overwhelming the network"}]}]}]}]}},"revision":1},{"id":"0666c249-668b-76c6-abc5-ce465112494c","type":"heading","position":"aJ","content":{"level":2,"content":[{"type":"text","text":"The Three-Way Handshake"}]},"revision":1},{"id":"add3a55c-3cdb-7be7-bfaf-171f1f04caf9","type":"text","position":"aK","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Before any actual data flows, TCP establishes a connection using a three-step exchange:"}]},{"type":"paragraph","content":[{"type":"text","text":"Client → SYN (seq=x) → Server"}]},{"type":"paragraph","content":[{"type":"text","text":"Server → SYN-ACK (seq=y, ack=x+1) → Client"}]},{"type":"paragraph","content":[{"type":"text","text":"Client → ACK (seq=x+1, ack=y+1) → Server"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SYN","marks":[{"type":"bold"}]},{"type":"text","text":" — client sends a synchronization flag with an initial sequence number, requesting a connection."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SYN-ACK","marks":[{"type":"bold"}]},{"type":"text","text":" — server acknowledges and sends its own sequence number back (a mathematically derived next value)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ACK","marks":[{"type":"bold"}]},{"type":"text","text":" — client acknowledges the server''s sequence number, and the connection is now fully established — data can now flow bidirectionally."}]}]}]}]}},"revision":1},{"id":"8c8c96d9-b809-7d1a-9f12-d2d3b9ad664e","type":"heading","position":"aL","content":{"level":1,"content":[{"type":"text","text":"TCP vs UDP — side by side"}]},"revision":1},{"id":"3d4a4cc7-a432-7222-9d3a-a5966077b11f","type":"table","position":"aM","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Property"}],[{"type":"text","text":"TCP"}],[{"type":"text","text":"UDP"}]],[[{"type":"text","text":"Connection","marks":[{"type":"bold"}]}],[{"type":"text","text":"Connection-oriented (handshake first)"}],[{"type":"text","text":"Connectionless"}]],[[{"type":"text","text":"Reliability","marks":[{"type":"bold"}]}],[{"type":"text","text":"Guaranteed delivery, retransmits lost data"}],[{"type":"text","text":"Best-effort, no guarantees"}]],[[{"type":"text","text":"Ordering","marks":[{"type":"bold"}]}],[{"type":"text","text":"Guaranteed in-order delivery"}],[{"type":"text","text":"No ordering guarantee"}]],[[{"type":"text","text":"Speed","marks":[{"type":"bold"}]}],[{"type":"text","text":"Slower (overhead of handshake, ACKs)"}],[{"type":"text","text":"Faster (minimal overhead)"}]],[[{"type":"text","text":"Header size","marks":[{"type":"bold"}]}],[{"type":"text","text":"20 bytes minimum"}],[{"type":"text","text":"8 bytes fixed"}]],[[{"type":"text","text":"Use cases","marks":[{"type":"bold"}]}],[{"type":"text","text":"Web (HTTP), email, file transfer"}],[{"type":"text","text":"Video calls, gaming, DNS"}]]]},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
