INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '29d5304c-43ea-7271-b5c2-419ee9c48be8', '32a609d5-aea1-7696-8248-e50454dac2f6', 1, 'PUBLISHED', 'Network Topologies', '[{"id":"0d7b4d1f-fbaf-71f1-8c6a-3cdc2efe2418","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The five classic shapes you can wire a network into — and exactly why each one wins or loses in practice."}]},{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"topology","marks":[{"type":"bold"}]},{"type":"text","text":" is the arrangement/layout of how nodes (computers, devices) are connected to each other in a network. The choice of topology directly affects cost, reliability, and how a failure behaves."}]}]}},"revision":1},{"id":"92324bf2-529c-788d-b0b3-1534d6786c23","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"1. Bus Topology"}]},"revision":1},{"id":"d9bcb286-ce06-7d28-bc36-e4392afb101b","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"All devices are connected to a single shared central cable (the \"bus\" / backbone). Every device taps into this one line to send and receive data."}]}]}},"revision":1},{"id":"365a7bfc-2711-7528-a2a6-317e097fc302","type":"callout","position":"a3","content":{"variant":"tip","title":"Pros","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Very cheap to set up — minimal cabling"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Easy to extend by adding a new tap"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Good for small, simple networks"}]}]}]}]}},"revision":1},{"id":"f7487d8d-c689-77ab-b112-f476a6ffc48f","type":"callout","position":"a4","content":{"variant":"danger","title":"Cons","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the single backbone cable breaks anywhere, the entire network is split or goes down"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"All devices share the same line → unnecessary collisions/calls when many devices transmit at once"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hard to troubleshoot — a fault anywhere affects everyone"}]}]}]}]}},"revision":1},{"id":"b949023b-1456-7bd4-a6b1-c578a3537286","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"2. Ring Topology"}]},"revision":1},{"id":"0e2e8465-ed68-713b-a471-83cf38e75a65","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each device connects to exactly two neighbors, forming a closed loop. Data travels around the ring, hop by hop, until it reaches its destination."}]}]}},"revision":1},{"id":"82aed55b-f9f2-7f9b-a98a-5f1b9c6a2552","type":"callout","position":"a7","content":{"variant":"tip","title":"Pros","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Predictable, orderly data flow (token-passing variants avoid collisions entirely)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Performs consistently even with many devices, unlike a shared bus"}]}]}]}]}},"revision":1},{"id":"a696cf37-3303-7622-899c-676d7c2bd923","type":"callout","position":"a8","content":{"variant":"danger","title":"Cons","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A single broken link can disrupt the entire ring (unless dual-ring redundancy is used)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Adding/removing a device usually requires briefly breaking the ring"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"One slow or failed device can hold up the whole loop"}]}]}]}]}},"revision":1},{"id":"2001c24e-962e-73e9-9ba6-6f7b29da9088","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"3. Star Topology"}]},"revision":1},{"id":"a4ab1b4f-fff7-7149-800f-6eeeb723cfc6","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every device connects individually to one central device (a hub or switch). All communication passes through this central point."}]}]}},"revision":1},{"id":"9fb37e67-1bb1-7d7e-96c8-68547947c18b","type":"callout","position":"aB","content":{"variant":"tip","title":"Pros","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"One device failing doesn''t affect any other — easy isolation of faults"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Easy to add/remove devices without disrupting the network"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Centralized management and monitoring"}]}]}]}]}},"revision":1},{"id":"fcea65d4-d687-74df-a9fd-39c69674d8a8","type":"callout","position":"aC","content":{"variant":"danger","title":"Cons","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the central device (hub/switch) fails, the "},{"type":"text","text":"entire network goes down","marks":[{"type":"bold"}]},{"type":"text","text":" — single point of failure"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"More cabling required than bus topology"}]}]}]}]}},"revision":1},{"id":"51e715a7-4bb4-7419-b75e-fb8a957e3f4e","type":"callout","position":"aD","content":{"variant":"tip","title":"In practice","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Most modern home and office LANs are star topologies — every device cables back to a central Wi-Fi router or Ethernet switch."}]}]}},"revision":1},{"id":"55253f16-39fd-770d-b56e-b323a63a00f7","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"4. Tree Topology (Bus + Star hybrid)"}]},"revision":1},{"id":"1223e81a-d042-7c5d-abfb-1c522478b14c","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A hierarchical structure: multiple star networks are connected together along a common bus backbone — essentially \"stars hanging off a bus,\" forming a parent-child structure of hubs."}]}]}},"revision":1},{"id":"0d2d2bee-ae4f-73e3-b619-17abcb428f25","type":"callout","position":"aG","content":{"variant":"tip","title":"Pros","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scales well — easy to add new branches/departments without redesigning the whole network"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fault isolation within a branch, similar to star"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Matches how real organizations are structured (HQ → departments → individual machines)"}]}]}]}]}},"revision":1},{"id":"16cb2a4c-8d4c-7645-aeb3-31bb4224e4bf","type":"callout","position":"aH","content":{"variant":"danger","title":"Cons","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Still depends on the backbone bus — if that breaks, branches get isolated from each other"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"More complex to wire and maintain than pure star or pure bus"}]}]}]}]}},"revision":1},{"id":"3b083dc5-0959-7e69-880c-a3e7156dc27c","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"5. Mesh Topology"}]},"revision":1},{"id":"ff05d980-cbff-7066-b250-d6561d058ac1","type":"text","position":"aJ","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every device is connected directly to every other device. Maximum redundancy — there are multiple paths between any two nodes."}]}]}},"revision":1},{"id":"6105e609-9a62-74d8-a4fe-92d6792e9ba3","type":"callout","position":"aK","content":{"variant":"tip","title":"Pros","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Extremely fault-tolerant — many alternate paths if one link fails"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No single point of failure"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"High performance, no shared-bus contention"}]}]}]}]}},"revision":1},{"id":"bf874f7d-8412-7821-90ef-fec1cb5d0d3b","type":"callout","position":"aL","content":{"variant":"danger","title":"Cons","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Expensive","marks":[{"type":"bold"}]},{"type":"text","text":" — cabling grows roughly with n² as devices are added"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scalability issues","marks":[{"type":"bold"}]},{"type":"text","text":" — becomes physically impractical past a small number of nodes"}]}]}]}]}},"revision":1},{"id":"53da6268-b7dd-7092-bce0-65fd4ebe6407","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Quick comparison"}]},"revision":1},{"id":"17fc4bea-2778-7280-8e78-7be90ce08972","type":"table","position":"aN","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Topology"}],[{"type":"text","text":"Single point of failure?"}],[{"type":"text","text":"Cost"}],[{"type":"text","text":"Best for"}]],[[{"type":"text","text":"Bus","marks":[{"type":"bold"}]}],[{"type":"text","text":"Yes (backbone)"}],[{"type":"text","text":"Lowest"}],[{"type":"text","text":"Tiny, temporary networks"}]],[[{"type":"text","text":"Ring","marks":[{"type":"bold"}]}],[{"type":"text","text":"Yes (any link)"}],[{"type":"text","text":"Low–Medium"}],[{"type":"text","text":"Predictable token-based LANs"}]],[[{"type":"text","text":"Star","marks":[{"type":"bold"}]}],[{"type":"text","text":"Yes (central hub)"}],[{"type":"text","text":"Medium"}],[{"type":"text","text":"Home/office LANs (most common today)"}]],[[{"type":"text","text":"Tree","marks":[{"type":"bold"}]}],[{"type":"text","text":"Partial (per branch)"}],[{"type":"text","text":"Medium–High"}],[{"type":"text","text":"Organizations with departments/branches"}]],[[{"type":"text","text":"Mesh","marks":[{"type":"bold"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"Highest"}],[{"type":"text","text":"Mission-critical backbones, military/ISP cores"}]]]},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '32a609d5-aea1-7696-8248-e50454dac2f6' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
