  ('365a7bfc-2711-7528-a2a6-317e097fc302', 'a3', 'callout', '{"variant":"tip","title":"Pros","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Very cheap to set up — minimal cabling"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Easy to extend by adding a new tap"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Good for small, simple networks"}]}]}]}]}}'),
