INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'c16059a9-a83c-7392-8652-9f30912d15e5', '50bdf5c8-e549-7850-93e4-f0ffcad1208a', 1, 'PUBLISHED', 'ER Model', '[{"id":"afb2e2a6-f59f-7708-af85-bf4f18313db3","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Entity-Relationship (ER) model is a conceptual, abstract database design framework representing entities, attributes, and relationships. It is mapped to a relational schema during the implementation phase."}]}]}},"revision":1},{"id":"1093e818-d280-74a7-941c-e37456d48308","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Entities & Entity Sets"}]},"revision":1},{"id":"1e88d768-daa4-75f8-8ddb-d23f4d263640","type":"callout","position":"a2","content":{"variant":"note","title":"Strong Entity Set","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can exist independently of other entities. Must have a primary key (composed of key attributes) to uniquely identify each instance."}]},{"type":"paragraph","content":[{"type":"text","text":"Symbol: Single Rectangle · Example: Customer (CustID)"}]}]}},"revision":1},{"id":"d2d63155-57da-7fe6-a1bc-47e23f395a5a","type":"callout","position":"a3","content":{"variant":"note","title":"Weak Entity Set","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cannot exist without a corresponding strong entity set (its owner entity). Does not have a primary key. It is identified using the owner''s primary key combined with its own "},{"type":"text","text":"partial key / discriminator","marks":[{"type":"bold"}]},{"type":"text","text":" attribute."}]},{"type":"paragraph","content":[{"type":"text","text":"Symbol: Double Rectangle · Example: Payment (PaymentNo, discriminator)"}]}]}},"revision":1},{"id":"db67603e-17fe-7766-9dfb-1a7cf5160585","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Attributes in Detail"}]},"revision":1},{"id":"1b3787eb-ebe8-7c43-8233-aa9e2af9f453","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Attribute Type"}],[{"type":"text","text":"Visual Symbol"}],[{"type":"text","text":"Rule & Mechanics"}],[{"type":"text","text":"Example Description"}]],[[{"type":"text","text":"Key Attribute","marks":[{"type":"bold"}]}],[{"type":"text","text":"Ellipse with underlined text"}],[{"type":"text","text":"Uniquely identifies each instance in the entity set."}],[{"type":"text","text":"RollNo","marks":[{"type":"code"},{"type":"underline"}]},{"type":"text","text":" in Student relation"}]],[[{"type":"text","text":"Composite Attribute","marks":[{"type":"bold"}]}],[{"type":"text","text":"Ellipses branching out from another ellipse"}],[{"type":"text","text":"Attribute composed of multiple sub-attributes. Saves structured details."}],[{"type":"text","text":"Address","marks":[{"type":"code"}]},{"type":"text","text":" branching into "},{"type":"text","text":"Street","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"City","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Zip","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Multivalued Attribute","marks":[{"type":"bold"}]}],[{"type":"text","text":"Double Ellipse"}],[{"type":"text","text":"Can store more than one value for a single entity instance."}],[{"type":"text","text":"Phone_No","marks":[{"type":"code"}]},{"type":"text","text":" (a student can have multiple phone numbers)"}]],[[{"type":"text","text":"Derived Attribute","marks":[{"type":"bold"}]}],[{"type":"text","text":"Dashed Ellipse"}],[{"type":"text","text":"Value is computed dynamically from other stored columns. Not saved directly on disk."}],[{"type":"text","text":"Age","marks":[{"type":"code"}]},{"type":"text","text":" (computed dynamically from "},{"type":"text","text":"Date_Of_Birth","marks":[{"type":"code"}]},{"type":"text","text":")"}]]]},"revision":1},{"id":"d3032d82-5694-7881-b060-1c441e3af3c4","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Relationships & Degree"}]},"revision":1},{"id":"3eee431a-10ec-77d3-b267-c1762af12e87","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A relationship connects two or more entities. The "},{"type":"text","text":"degree","marks":[{"type":"bold"}]},{"type":"text","text":" is the number of participating entity sets:"}]}]}},"revision":1},{"id":"8b8b45ef-1f45-7199-a241-a322a8c9b971","type":"callout","position":"a8","content":{"variant":"note","title":"Unary (Recursive)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A single entity set relates to itself."}]},{"type":"paragraph","content":[{"type":"text","text":"Person — [Marries] — Person","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"ad2c039b-78e2-7b40-ae98-96fbefadfd8f","type":"callout","position":"a9","content":{"variant":"note","title":"Binary","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two entity sets participate."}]},{"type":"paragraph","content":[{"type":"text","text":"Student — [Enrolled] — Course","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"e6b554b4-2cd9-7b98-a87b-34780167b94f","type":"callout","position":"aA","content":{"variant":"note","title":"Ternary","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three entity sets participate."}]},{"type":"paragraph","content":[{"type":"text","text":"Doctor — [Treats] — Patient","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"           |       ","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"      [Medicine]","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"08639d32-c04f-7d21-8018-5d19a85dc69b","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Cardinality & Structural Constraints"}]},"revision":1},{"id":"3b668493-52a4-7866-bc29-42311306f0a7","type":"callout","position":"aC","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Participation Constraints (min cardinality):","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"Total Participation (Double Line):","marks":[{"type":"bold"}]},{"type":"text","text":" Every entity in the set must participate in at least one relationship instance. (e.g., every "},{"type":"text","text":"Employee","marks":[{"type":"code"}]},{"type":"text","text":" must belong to a "},{"type":"text","text":"Department","marks":[{"type":"code"}]},{"type":"text","text":"). "},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"Partial Participation (Single Line):","marks":[{"type":"bold"}]},{"type":"text","text":" Entities can exist without participating in the relationship. (e.g., not every "},{"type":"text","text":"Employee","marks":[{"type":"code"}]},{"type":"text","text":" manages a "},{"type":"text","text":"Department","marks":[{"type":"code"}]},{"type":"text","text":"). "},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":" "},{"type":"text","text":"Min-Max Notation ","marks":[{"type":"bold"}]},{"type":"text","text":"(min, max)","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":":","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"• Placed on the line connecting the entity set and relationship. "},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"min = 0","marks":[{"type":"code"}]},{"type":"text","text":" indicates partial participation. "},{"type":"text","text":"min ≥ 1","marks":[{"type":"code"}]},{"type":"text","text":" indicates total participation. "},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"max","marks":[{"type":"code"}]},{"type":"text","text":" represents the cardinality ratio limit (e.g., 1 or N)."}]}]}},"revision":1},{"id":"8462eeff-dc8e-7331-9369-d5974438e3d6","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Generalization, Specialization, Aggregation & Inheritance"}]},"revision":1},{"id":"d755547e-413a-70e7-a402-8998f83f06fe","type":"callout","position":"aE","content":{"variant":"note","title":"Generalization & Specialization","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Generalization:","marks":[{"type":"bold"}]},{"type":"text","text":" Bottom-up approach where common attributes of lower-level entities are combined into a high-level parent entity. "},{"type":"hardBreak"},{"type":"text","text":"Specialization:","marks":[{"type":"bold"}]},{"type":"text","text":" Top-down approach where a parent entity is decomposed into lower-level sub-entities based on specialized attributes."}]}]}},"revision":1},{"id":"e5a716a0-2182-7b4a-893d-556edeeb3996","type":"callout","position":"aF","content":{"variant":"note","title":"Aggregation","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Abstraction where a relationship set (and participating entities) is enclosed in a box and treated as a single higher-level entity, allowing it to have relationship links to other entities."}]}]}},"revision":1},{"id":"ffa2dfe2-9387-7671-bf5d-7fa5a88ea438","type":"callout","position":"aG","content":{"variant":"note","title":"Types of Inheritance","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Attribute Inheritance:","marks":[{"type":"bold"}]},{"type":"text","text":" Lower-level entities inherit all attributes of the parent entity automatically."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Relationship Inheritance:","marks":[{"type":"bold"}]},{"type":"text","text":" Lower-level entities participate in all relationships that the parent entity participates in."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Overriding Inheritance:","marks":[{"type":"bold"}]},{"type":"text","text":" A sub-entity can redefine a parent attribute or relationship for its specific type."}]}]}]}]}},"revision":1},{"id":"13499d99-8748-7695-8134-23aa3e10427f","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"ER-to-Relational Mapping Algorithm"}]},"revision":1},{"id":"1dec5cfa-4f13-7798-9b73-feea0deb811c","type":"text","position":"aI","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Step-by-step logic to map conceptual ER diagrams into database tables:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Strong Entity","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Create a table. Simple attributes become columns. Composite attributes are flattened into individual columns (e.g. "},{"type":"text","text":"Street","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"City","marks":[{"type":"code"}]},{"type":"text","text":" columns). Key attribute becomes the Primary Key."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Weak Entity","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Create a table. Add all attributes of the weak entity. Put the Primary Key of the owner entity as a Foreign Key. The Primary Key is a composite key: "},{"type":"text","text":"{Owner_PK, Discriminator}","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"1:1 Relationships","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Based