SELECT '33a85260-c633-7ea3-8978-0c69a7fd20a2', '1ee299b2-42d6-7d82-9389-081c43ee7cb1', 1, 'PUBLISHED', 'Indexing', '[{"id":"5f0cf4e6-a022-78ad-9f26-569396061996","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Indexing is an essential data structure technique designed to speed up search operations by reducing the number of physical disk block accesses required to retrieve rows."}]}]}},"revision":1},{"id":"56ae6983-a575-7162-a715-ccd6b5ec1726","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Indexing Classifications"}]},"revision":1},{"id":"bb410b8a-9424-7f07-9d68-c29942bcc8d0","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Index Type"}],[{"type":"text","text":"Key Order Alignment"}],[{"type":"text","text":"Index density"}],[{"type":"text","text":"Description"}]],[[{"type":"text","text":"Primary Index","marks":[{"type":"bold"}]}],[{"type":"text","text":"Ordered key matches table structure."}],[{"type":"text","text":"Usually Sparse"}],[{"type":"text","text":"Defined on the primary key of an ordered data file. Only one primary index can exist."}]],[[{"type":"text","text":"Clustering Index","marks":[{"type":"bold"}]}],[{"type":"text","text":"Non-key field ordered matches table."}],[{"type":"text","text":"Sparse"}],[{"type":"text","text":"Defined on a non-key ordered field (e.g., grouping employees by Department ID)."}]],[[{"type":"text","text":"Secondary Index","marks":[{"type":"bold"}]}],[{"type":"text","text":"Table physical order is independent of index key."}],[{"type":"text","text":"Dense"}],[{"type":"text","text":"Defined on unordered fields (e.g., creating an index on email field). Multiple secondary indexes are allowed."}]]]},"revision":1},{"id":"b9774a12-bfa2-79d4-b5d1-a77733f14561","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Index Dense vs Sparse"}]},"revision":1},{"id":"a76636c6-ff39-7d40-b5f2-014f25921a56","type":"callout","position":"a4","content":{"variant":"note","title":"Dense Index","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An index record is created for "},{"type":"text","text":"every single search key value","marks":[{"type":"bold"}]},{"type":"text","text":" in the database table. Faster lookup, but requires significantly more memory."}]}]}},"revision":1},{"id":"2da2bab0-8504-7d0f-8430-b3a396854f06","type":"callout","position":"a5","content":{"variant":"note","title":"Sparse Index","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An index record is created only for some search keys (typically one per data block). Requires less memory, but requires traversing the physical block to find the exact row."}]}]}},"revision":1},{"id":"ad4bd264-b1f7-76c5-96ca-202f79038cad","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"B-Tree vs B+ Tree Node Layout"}]},"revision":1},{"id":"c39773c6-2642-78c6-9516-7c00ad25cbe6","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Database engines use B+ Trees for relational indexes due to their physical layout advantages:"}]}]}},"revision":1},{"id":"88260312-e421-730d-b8d1-2beab21521fa","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Feature"}],[{"type":"text","text":"B-Tree"}],[{"type":"text","text":"B+ Tree"}]],[[{"type":"text","text":"Data pointers","marks":[{"type":"bold"}]}],[{"type":"text","text":"Stored in both leaf and non-leaf nodes."}],[{"type":"text","text":"Stored "},{"type":"text","text":"only in leaf nodes","marks":[{"type":"bold"}]},{"type":"text","text":". Non-leaf nodes only store search key values to route queries."}]],[[{"type":"text","text":"Leaf linking","marks":[{"type":"bold"}]}],[{"type":"text","text":"Leaf nodes are not linked together."}],[{"type":"text","text":"Leaf nodes are connected sequentially in a "},{"type":"text","text":"doubly linked list","marks":[{"type":"bold"}]},{"type":"text","text":"."}]],[[{"type":"text","text":"Range Queries","marks":[{"type":"bold"}]}],[{"type":"text","text":"Slow. Requires executing in-order traversal (up and down the tree)."}],[{"type":"text","text":"Fast. Locate the starting key in a leaf, then traverse the linked list."}]],[[{"type":"text","text":"Internal Node capacity","marks":[{"type":"bold"}]}],[{"type":"text","text":"Low, because data pointers occupy space in internal nodes."}],[{"type":"text","text":"High. Can store many child pointers, leading to a much wider fan-out and shorter tree."}]]]},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
