INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '1cd1ca6b-b6f1-701b-be3e-f7cc8a90d913', '9520c5c0-2f3d-7a03-8cbf-d8be4d2b2aca', 1, 'PUBLISHED', 'NoSQL Databases', '[{"id":"d878ba7a-9938-7aaf-9d93-d073200180e9","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"NoSQL (Not Only SQL) databases are built for horizontal scalability, unstructured schemas, and high write throughput, departing from the rigid ACID constraints of relational systems."}]}]}},"revision":1},{"id":"7dc22db3-f5f1-7bfd-854e-2125a0ada568","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Why NoSQL?"}]},"revision":1},{"id":"3d272df9-0eb1-7ca1-bdee-0f446c30a484","type":"callout","position":"a2","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Traditional RDBMS scales "},{"type":"text","text":"vertically","marks":[{"type":"bold"}]},{"type":"text","text":" (faster CPU, more RAM), which has physical scaling limits and high hardware costs. NoSQL is designed to scale "},{"type":"text","text":"horizontally","marks":[{"type":"bold"}]},{"type":"text","text":" (adding cheap server nodes in a distributed cluster). "},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"Dynamic Schemas:","marks":[{"type":"bold"}]},{"type":"text","text":" Allows storing unstructured document records (JSON) without running migrations. "},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"Low Latency:","marks":[{"type":"bold"}]},{"type":"text","text":" Uses simple query patterns (e.g. key-value hash lookups) to bypass slow relational joins."}]}]}},"revision":1},{"id":"2376169c-82c4-7d91-83d6-5f0b7593905c","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"SQL vs NoSQL Comparison"}]},"revision":1},{"id":"4549aaf1-a9bc-7672-a520-193534031d46","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Dimension"}],[{"type":"text","text":"SQL Databases (RDBMS)"}],[{"type":"text","text":"NoSQL Databases"}]],[[{"type":"text","text":"Schema","marks":[{"type":"bold"}]}],[{"type":"text","text":"Strict, predefined tabular schema. Changes require DDL migration locks."}],[{"type":"text","text":"Dynamic / Schema-less. Records can store custom dynamic columns."}]],[[{"type":"text","text":"Scaling","marks":[{"type":"bold"}]}],[{"type":"text","text":"Vertical (Scale Up)."}],[{"type":"text","text":"Horizontal (Scale Out). Shards data partitions across multiple nodes."}]],[[{"type":"text","text":"Joins","marks":[{"type":"bold"}]}],[{"type":"text","text":"Supported natively. Executed horizontally."}],[{"type":"text","text":"Not supported. Data is denormalized in documents to avoid joins."}]],[[{"type":"text","text":"Transactions","marks":[{"type":"bold"}]}],[{"type":"text","text":"Strict ACID properties. Absolute consistency."}],[{"type":"text","text":"BASE model. Prioritizes availability; eventual consistency."}]]]},"revision":1},{"id":"40a3db45-9581-77f5-84b2-ff07b7f681a9","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"The 4 Types of NoSQL Databases"}]},"revision":1},{"id":"161b9b1f-b048-7633-b894-afd5a44a3ccb","type":"callout","position":"a6","content":{"variant":"note","title":"1. Document Database","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Stores records as documents (JSON/BSON). Documents can nest objects and arrays inside themselves."}]},{"type":"paragraph","content":[{"type":"text","text":"Use Cases:","marks":[{"type":"bold"}]},{"type":"text","text":" E-commerce catalogs, Content Management Systems (CMS), user profile configurations."}]},{"type":"paragraph","content":[{"type":"text","text":"MongoDB · CouchDB"}]}]}},"revision":1},{"id":"ff74485c-e2c5-7563-86dc-5acc84140478","type":"callout","position":"a7","content":{"variant":"note","title":"2. Key-Value Store","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Stores simple key-to-value associations. Extremely fast because it behaves as a giant hash table in RAM."}]},{"type":"paragraph","content":[{"type":"text","text":"Use Cases:","marks":[{"type":"bold"}]},{"type":"text","text":" Real-time caching, user session states, global leaderboards."}]},{"type":"paragraph","content":[{"type":"text","text":"Redis · Memcached"}]}]}},"revision":1},{"id":"35b08b41-297c-7785-91d0-229cb14534b4","type":"callout","position":"a8","content":{"variant":"note","title":"3. Column-Family Store","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Stores columns of data together on disk, rather than rows. Highly optimized for mass writes across columns."}]},{"type":"paragraph","content":[{"type":"text","text":"Use Cases:","marks":[{"type":"bold"}]},{"type":"text","text":" IoT sensor metrics, time-series telemetry data, event logs."}]},{"type":"paragraph","content":[{"type":"text","text":"Apache Cassandra · HBase"}]}]}},"revision":1},{"id":"e81aab89-85c8-7d37-b167-f28b1a5f8274","type":"callout","position":"a9","content":{"variant":"note","title":"4. Graph Database","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Stores data nodes and directed edges (relationships) natively, bypassing join layers for deep networks."}]},{"type":"paragraph","content":[{"type":"text","text":"Use Cases:","marks":[{"type":"bold"}]},{"type":"text","text":" Social graph analysis, fraud detection, recommendation engines."}]},{"type":"paragraph","content":[{"type":"text","text":"Neo4j · Amazon Neptune"}]}]}},"revision":1},{"id":"5db0c05b-4faf-77a9-80c5-0d18d061322f","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Query Comparison: SQL vs MongoDB"}]},"revision":1},{"id":"3cb7e854-8ce5-7ba6-8aa3-59414bc19f7d","type":"table","position":"aB","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Action"}],[{"type":"text","text":"SQL Database"}],[{"type":"text","text":"MongoDB (NoSQL Document)"}]],[[{"type":"text","text":"Insert Row","marks":[{"type":"bold"}]}],[{"type":"text","text":"INSERT INTO Users (Name, Age) VALUES (''Alice'', 25);","marks":[{"type":"code"}]}],[{"type":"text","text":"db.users.insertOne({ name: \"Alice\", age: 25 });","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Select rows","marks":[{"type":"bold"}]}],[{"type":"text","text":"SELECT * FROM Users WHERE Age > 21;","marks":[{"type":"code"}]}],[{"type":"text","text":"db.users.find({ age: { $gt: 21 } });","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Update rows","marks":[{"type":"bold"}]}],[{"type":"text","text":"UPDATE Users SET Age=26 WHERE Name=''Alice'';","marks":[{"type":"code"}]}],[{"type":"text","text":"db.users.updateMany({ name: \"Alice\" }, { $set: { age: 26 } });","marks":[{"type":"code"}]}]]]},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '9520c5c0-2f3d-7a03-8cbf-d8be4d2b2aca' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
