INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'c9883cbb-d9ae-7348-9bf6-6053e02a52b2', 'c774b8f3-889c-7f17-bb1a-c800824f0b5b', 1, 'PUBLISHED', 'Relational Algebra', '[{"id":"1fd76b61-1c70-7ca8-b6da-ce0f9d751027","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Relational algebra is a mathematical procedural query language containing operations to retrieve data. Relational calculus is its non-procedural, declarative counterpart."}]}]}},"revision":1},{"id":"64cebe28-a99e-74f6-b436-61c9c158d67d","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Relational Algebra Operators"}]},"revision":1},{"id":"062b2b34-f4df-7b2d-a025-ede8de8a1822","type":"heading","position":"a2","content":{"level":3,"content":[{"type":"text","text":"Basic Operators"}]},"revision":1},{"id":"c9283bad-8d49-76cb-b2b8-e2ef9018c89f","type":"callout","position":"a3","content":{"variant":"note","title":"Selection (σ)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Filters rows based on a logical predicate. Removes no columns."}]},{"type":"paragraph","content":[{"type":"text","text":"σDept = ''HR'' ∧ Salary > 50000(Employees)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"0853dc9e-755c-7dae-9ea5-10a70fefaabe","type":"callout","position":"a4","content":{"variant":"note","title":"Projection (π)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Selects specified columns and discards others. "},{"type":"text","text":"Removes duplicates","marks":[{"type":"bold"}]},{"type":"text","text":" automatically in relational theory."}]},{"type":"paragraph","content":[{"type":"text","text":"πName, Dept(Employees)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"ddb57c6f-f11f-76a9-8e5e-55d83e37c2de","type":"callout","position":"a5","content":{"variant":"note","title":"Union (∪)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Combines rows from two tables. Both tables must be "},{"type":"text","text":"union-compatible","marks":[{"type":"bold"}]},{"type":"text","text":" (same number of columns, matching domain types in order)."}]},{"type":"paragraph","content":[{"type":"text","text":"Students ∪ Instructors","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"af00b8cb-4348-7692-a433-3fa3ae1cfcf5","type":"callout","position":"a6","content":{"variant":"note","title":"Set Difference (-)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Returns rows present in the first table but not in the second table. Must be union-compatible."}]},{"type":"paragraph","content":[{"type":"text","text":"Students - Graduates","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"3b30eaf0-5331-7b9d-9544-9d18a9d1ec99","type":"callout","position":"a7","content":{"variant":"note","title":"Cartesian Product (×)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Combines every row of the left table with every row of the right table. Output columns = Sum of columns; Output rows = Product of rows."}]},{"type":"paragraph","content":[{"type":"text","text":"A × B","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"3e00a020-d9ad-7eef-8e3e-e0e12e02537c","type":"heading","position":"a8","content":{"level":3,"content":[{"type":"text","text":"Derived Operators"}]},"revision":1},{"id":"9a5040c5-6689-7f28-9420-e84e848e36d7","type":"callout","position":"a9","content":{"variant":"note","title":"Natural Join (⋈)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Joins tables based on matching column names and data types, removing duplicate join columns from the output."}]},{"type":"paragraph","content":[{"type":"text","text":"Employees ⋈ Departments","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"a5ddab4a-97ac-7a08-bd69-abbd54432fba","type":"callout","position":"aA","content":{"variant":"note","title":"Theta Join (⋈θ)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An inner join that combines rows using an arbitrary comparison condition "},{"type":"text","text":"θ","marks":[{"type":"code"}]},{"type":"text","text":" (e.g. "},{"type":"text","text":"=, <, >, ≤, ≥, ≠","marks":[{"type":"code"}]},{"type":"text","text":")."}]},{"type":"paragraph","content":[{"type":"text","text":"A ⋈A.Age < B.MinAge B","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"0104bd56-7d8b-764e-a62f-a4a3f0cb77fc","type":"callout","position":"aB","content":{"variant":"note","title":"Division (÷)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Used for queries containing the word \"all\". R ÷ S returns tuples in R that are paired with "},{"type":"text","text":"every","marks":[{"type":"italic"}]},{"type":"text","text":" tuple in S."}]},{"type":"paragraph","content":[{"type":"text","text":"Enrolls(Student, Course) ÷ Mandatory(Course)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"d731e81f-6b2a-7265-8a2b-42f3f11cdb71","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Relational Calculus Syntax Comparison"}]},"revision":1},{"id":"7510b50f-eddf-76a2-8ff5-e647bba6f177","type":"table","position":"aD","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Aspect"}],[{"type":"text","text":"Tuple Relational Calculus (TRC)"}],[{"type":"text","text":"Domain Relational Calculus (DRC)"}]],[[{"type":"text","text":"Variables","marks":[{"type":"bold"}]}],[{"type":"text","text":"Variables represent entire rows (tuples). e.g., "},{"type":"text","text":"t","marks":[{"type":"code"}]}],[{"type":"text","text":"Variables represent individual attributes (domains). e.g., "},{"type":"text","text":"x, y, z","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Query focus","marks":[{"type":"bold"}]}],[{"type":"text","text":"Filters rows. Very close to SQL concept."}],[{"type":"text","text":"Filters values in columns directly. More abstract."}]],[[{"type":"text","text":"Syntax","marks":[{"type":"bold"}]}],[{"type":"text","text":"{ t | P(t) }","marks":[{"type":"code"}]}],[{"type":"text","text":"{ <x1, x2, ...> | P(x1, x2, ...) }","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Example Query","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"type":"text","text":"(Get Names of Students in CS dept)"}],[{"type":"text","text":"{ t.Name | t ∈ Students ∧ t.Dept = ''CS'' }","marks":[{"type":"code"}]}],[{"type":"text","text":"{ <n> | ∃ i, d (<i, n, d> ∈ Students ∧ d = ''CS'') }","marks":[{"type":"code"}]}]]]},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
