SELECT 'f72d1830-e033-7d4b-b88d-076d87395d98', 'a973495b-1e83-7c6b-8382-6ebe85bef27b', 1, 'PUBLISHED', 'SQL Masterclass', '[{"id":"5cb3f0db-9610-7a17-aa57-03a825d0954f","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Structured Query Language (SQL) is the standard declarative implementation language for database query operations. This section covers production-grade queries, syntax, and structures."}]}]}},"revision":1},{"id":"283dd5a5-848f-788a-b259-91ce74e87980","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"DDL & DML Syntax"}]},"revision":1},{"id":"eb1fe060-b9e3-7cb3-b4d7-186a84ed4be4","type":"callout","position":"a2","content":{"variant":"note","title":"Creating tables with constraints","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Common field constraints include "},{"type":"text","text":"PRIMARY KEY","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"FOREIGN KEY","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"NOT NULL","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"UNIQUE","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"CHECK","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"DEFAULT","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"CREATE TABLE Employees (","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"  EmpID INT PRIMARY KEY,","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"  Name VARCHAR(100) NOT NULL,","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"  Email VARCHAR(100) UNIQUE,","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"  Salary DECIMAL(10,2) CHECK (Salary > 0),","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"  DeptID INT,","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"  JoinDate DATE DEFAULT CURRENT_DATE,","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"  CONSTRAINT fk_dept FOREIGN KEY (DeptID) REFERENCES Departments(Id) ON DELETE SET NULL","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":");","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"7c824963-db09-7658-a002-a1c7efefba88","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"SQL Joins Deep-Dive"}]},"revision":1},{"id":"36461d0d-70b0-7553-bf7d-ee438635bdb5","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Consider two tables: "},{"type":"text","text":"Employees","marks":[{"type":"bold"}]},{"type":"text","text":" (ID, Name, ManagerID) and "},{"type":"text","text":"Departments","marks":[{"type":"bold"}]},{"type":"text","text":" (ID, DeptName)."}]}]}},"revision":1},{"id":"4bbc88d6-59c8-7350-ad70-bb71b804fa83","type":"heading","position":"a5","content":{"level":3,"content":[{"type":"text","text":"Self Join Query"}]},"revision":1},{"id":"77dcdb65-6851-76c4-8845-5801e60742b9","type":"callout","position":"a6","content":{"variant":"note","title":"Self Join (Table references itself)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Typically used for hierarchical columns in a single table, like employee-manager relations."}]},{"type":"paragraph","content":[{"type":"text","text":"-- Find employees who earn more than their direct manager","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"SELECT e.Name AS Employee, m.Name AS Manager","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"FROM Employees e","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"INNER JOIN Employees m ON e.ManagerID = m.EmpID","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"WHERE e.Salary > m.Salary;","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"cf7efc3c-6e6e-7798-9c12-d990a1135e72","type":"heading","position":"a7","content":{"level":3,"content":[{"type":"text","text":"Cross Join Query"}]},"revision":1},{"id":"18385b6c-aeaa-72fa-be33-727ff22f56a0","type":"callout","position":"a8","content":{"variant":"note","title":"Cross Join (Cartesian Product)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Returns the cartesian product of rows from both tables without matching conditions."}]},{"type":"paragraph","content":[{"type":"text","text":"-- Generate all possible combinations of sizes and colors","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"SELECT s.SizeName, c.ColorName","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"FROM Sizes s","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"CROSS JOIN Colors c;","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"8dac73ac-9b27-71d6-ba87-45e619331861","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Aggregations & Group By"}]},"revision":1},{"id":"bed981d5-ccd5-7a35-87d0-a4dd9c1a35a8","type":"callout","position":"aA","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Aggregate functions ("},{"type":"text","text":"COUNT","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"SUM","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"AVG","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"MIN","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"MAX","marks":[{"type":"code"}]},{"type":"text","text":") perform calculations on a set of values. "},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"GROUP BY:","marks":[{"type":"bold"}]},{"type":"text","text":" Groups rows sharing identical values in summary columns. "},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"HAVING:","marks":[{"type":"bold"}]},{"type":"text","text":" Filters grouped results. Equivalent to "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":" but runs "},{"type":"text","text":"after","marks":[{"type":"italic"}]},{"type":"text","text":" values are aggregated."}]}]}},"revision":1},{"id":"adf64cc6-df2a-728a-b8a7-3b640bfe5e2f","type":"code","position":"aB","content":{"language":"sql","code":"-- Get departments with more than 5 employees and an average salary above 60000\nSELECT DeptID, COUNT(*) AS EmpCount, AVG(Salary) AS AvgSalary\nFROM Employees\nGROUP BY DeptID\nHAVING COUNT(*) > 5 AND AVG(Salary) > 60000;","filename":"SQL"},"revision":1},{"id":"7c0d51e2-4eef-75b5-b6b9-d773882d9f3b","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Nested & Subqueries"}]},"revision":1},{"id":"ddec742f-d83b-7283-94ed-cfcea714f349","type":"callout","position":"aD","content":{"variant":"note","title":"Correlated Subquery (EXISTS)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The inner query executes repeatedly — once for each row evaluated by the outer query."}]},{"type":"paragraph","content":[{"type":"text","text":"-- Find departments with active employees","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"SELECT d.DeptName","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"FROM Departments d","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"WHERE EXISTS (","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"  SELECT 1 FROM Employees e ","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"  WHERE e.DeptID = d.ID","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":");","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"9acf92e6-db8f-75f1-9bc8-82e107abd9d1","type":"callout","position":"aE","content":{"variant":"note","title":"Common Table Expressions (CTEs)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"WITH","marks":[{"type":"code"}]},{"type":"text","text":" clause creates a temporary named result set, making complex queries readable."}]},{"type":"paragraph","content":[{"type":"text","text":"-- Filter employees earning above average","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"WITH AvgSal AS (","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"  SELECT AVG(Salary) AS avg_s FROM Employees","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":")","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"SELECT Name, Salary ","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"FROM Employees, AvgSal","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"WHERE Salary > avg_s;","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"6ba0c639-b5b7-73c5-a6d2-e234ed460469","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Window Functions"}]},"revision":1},{"id":"fa929371-75e3-7d0f-a388-3313ffe0d623","type":"text","position":"aG","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Compute values across a set of table rows related to the current row, without collapsing the results (unlike GROUP BY):"}]}]}},"revision":1},{"id":"1736d5e5-b887-74a7-880a-840574c7d587","type":"table","position":"aH","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Function"}],[{"type":"text","text":"Mechanics"}],[{"type":"text","text":"Syntax / Usage"}]],[[{"type":"text","text":"ROW_NUMBER()","marks":[{"type":"bold"}]}],[{"type":"text","text":"Assigns a sequential integer to rows starting at 1."}]