SELECT '1e651431-15a8-7ed7-867f-58b9671d30f8', '3506e364-58d6-701f-b5c0-f910f1cad42b', 1, 'PUBLISHED', 'Transaction & Concurrency', '[{"id":"090ae2e6-ea6c-7005-8611-154b30252de2","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A transaction is a logical unit of work. To maintain database consistency, transactions must adhere to ACID properties, and concurrent operations must be serializable."}]}]}},"revision":1},{"id":"ce8e3869-053e-75f9-8119-4d7f2390258a","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"ACID vs BASE"}]},"revision":1},{"id":"2753b064-9a5a-743a-bfb3-c0d125388c48","type":"heading","position":"a2","content":{"level":3,"content":[{"type":"text","text":"ACID (Strict Consistency)"}]},"revision":1},{"id":"c5c96dda-a717-7409-8a71-e55a6d847870","type":"callout","position":"a3","content":{"variant":"tip","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ACID Properties:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"Atomicity:","marks":[{"type":"bold"}]},{"type":"text","text":" All-or-nothing execution. Rollback on failure. (Managed by "},{"type":"text","text":"Transaction Manager","marks":[{"type":"italic"}]},{"type":"text","text":") "},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"Consistency:","marks":[{"type":"bold"}]},{"type":"text","text":" The database transitions only between valid states conforming to rules. (Managed by "},{"type":"text","text":"Application Programmer","marks":[{"type":"italic"}]},{"type":"text","text":") "},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"Isolation:","marks":[{"type":"bold"}]},{"type":"text","text":" Concurrent transactions run independently without interference. (Managed by "},{"type":"text","text":"Concurrency Control Manager","marks":[{"type":"italic"}]},{"type":"text","text":") "},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"Durability:","marks":[{"type":"bold"}]},{"type":"text","text":" Once committed, changes survive system crashes. (Managed by "},{"type":"text","text":"Recovery Manager","marks":[{"type":"italic"}]},{"type":"text","text":")"}]}]}},"revision":1},{"id":"74806532-a61d-730b-9f81-e7b65de68e73","type":"heading","position":"a4","content":{"level":3,"content":[{"type":"text","text":"BASE (Eventual Consistency)"}]},"revision":1},{"id":"4d215407-f26a-71bf-b6f9-9ff706cdee85","type":"callout","position":"a5","content":{"variant":"warning","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"BASE Model (NoSQL systems):","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"Basically Available:","marks":[{"type":"bold"}]},{"type":"text","text":" The system responds to requests, even if some nodes are down. "},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"Soft State:","marks":[{"type":"bold"}]},{"type":"text","text":" The state of the data can drift or change over time without user interaction. "},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"Eventual Consistency:","marks":[{"type":"bold"}]},{"type":"text","text":" Data copies across global servers will sync up and become identical over time."}]}]}},"revision":1},{"id":"d69bc6b5-da33-7dd3-b129-e60e8e30673b","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"CAP Theorem"}]},"revision":1},{"id":"b33516f2-d983-7eb1-adf0-c132aa418be4","type":"callout","position":"a7","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"States that a distributed data store can simultaneously provide at most two of the following three guarantees: "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"Consistency (C):","marks":[{"type":"bold"}]},{"type":"text","text":" Every read receives the most recent write or an error. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"Availability (A):","marks":[{"type":"bold"}]},{"type":"text","text":" Every non-failing node returns a response for every request. "},{"type":"hardBreak"},{"type":"text","text":"3. "},{"type":"text","text":"Partition Tolerance (P):","marks":[{"type":"bold"}]},{"type":"text","text":" The system continues to operate despite arbitrary communication network splits. "},{"type":"hardBreak"},{"type":"text","text":"Tradeoff:","marks":[{"type":"bold"}]},{"type":"text","text":" When a network partition (P) occurs, a database must choose either Consistency (CP) or Availability (AP)."}]}]}},"revision":1},{"id":"d2aed8f7-977b-7b35-9db8-3810f8c4ee0d","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Concurrency Problems"}]},"revision":1},{"id":"f227fa3c-0e19-706d-8708-90604e59b9f8","type":"callout","position":"a9","content":{"variant":"note","title":"Dirty Read","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Transaction T1 reads data modified by T2. T2 then aborts and rolls back, leaving T1 with invalid, uncommitted data."}]}]}},"revision":1},{"id":"8f65e81c-a003-7c94-9646-e3083fd6a68a","type":"callout","position":"aA","content":{"variant":"note","title":"Lost Update","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"T1 and T2 read the same value, modify it independently, and write it back. One update overwrites the other."}]}]}},"revision":1},{"id":"f4bb918b-f79a-7b0b-be15-a24e82464e74","type":"callout","position":"aB","content":{"variant":"note","title":"Non-Repeatable Read","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"T1 reads a value. T2 updates that value and commits. T1 reads the value again and gets a different result."}]}]}},"revision":1},{"id":"38ae759e-296e-7c18-816a-459a9ca74bda","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Schedules & Serializability"}]},"revision":1},{"id":"188aea15-cde5-73ac-9410-6ffe13ae7da6","type":"text","position":"aD","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Serial Schedule:","marks":[{"type":"bold"}]},{"type":"text","text":" Transactions execute one after another without interleaving. Always consistent. · "},{"type":"text","text":"Non-Serial Schedule:","marks":[{"type":"bold"}]},{"type":"text","text":" Operations interleave. Improves performance but can lead to conflicts. · "},{"type":"text","text":"Conflict Serializable:","marks":[{"type":"bold"}]},{"type":"text","text":" A schedule that can be transformed into a serial schedule by swapping non-conflicting adjacent operations. · "},{"type":"text","text":"View Serializable:","marks":[{"type":"bold"}]},{"type":"text","text":" A weaker check than conflict serializability, verifying identical read/write flow states."}]}]}},"revision":1},{"id":"2a7fa88e-0ab5-7607-84c7-b264dc1341a1","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Recoverability of Schedules"}]},"revision":1},{"id":"1fd339cc-ff37-76ac-9af0-298dccc3467b","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recoverable Schedule","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"T2 reads a value written by T1. T2 commits only "},{"type":"text","text":"after","marks":[{"type":"italic"}]},{"type":"text","text":" T1 commits. If T1 aborts, T2 can also safely abort."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cascadeless Schedule","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"T2 is only allowed to read values written by T1 "},{"type":"text","text":"after","marks":[{"type":"italic"}]},{"type":"text","text":" T1 has committed. Prevents cascading rollbacks where one transaction failure forces aborting multiple active ones."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Strict Schedule","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"A transaction cannot read "},{"type":"text","text":"or write","marks":[{"type":"italic"}]},{"type":"text","text":" a data item written by another transaction until that transaction has committed or aborted. Prevents dirty writes."}]}]}]}]}},"revision":1},{"id":"090932fd-599b-7579-8bbe-a3789f67de66","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Concurrency Protocols"}]},"revision":1},{"id":"b52f2dc9-d680-770a-be00-293873c7c35f","type":"heading","position":"aH","content":{"level":3,"content":[{"type":"text","text":"Two-Phase Locking (2PL)"}]},"revision":1},{"id":"f378220b-ea64-77d2-94de-590915e527d2","type":"callout","position":"aI","content":{"variant":"note","title":"Two-Phase Locking (2PL) Rules","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Guarantees conflict serializability but does not prevent deadlocks:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Growing Phase:","marks":[{"type":"bold"}]},{"type":"text","text":" Transaction can acquire locks but cannot release any."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Shrinking Phase:","marks":[{"type":"bold"}]},{"type":"text","text":" Transaction can release locks but cannot acquire new ones."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Strict 2PL:","marks":[{"type":"bold"}]},{"type":"text","text":" All exclusive (X) locks held by a transaction must be kept until the transaction commits."}]}]}]}]}},"revision":1},{"id":"aa94c398-b03f-7133-aaa1-493dffb684b4","type":"heading","position":"aJ","content":{"level":3,"content":[{"type":"text","text":"Multiple Granularity Locking (MGL)"}]},"revision":1},{"id":"ac551414-8deb-7b3d-b6a6-4548024e8d2d","type":"callout","position":"aK","content":{"variant":"note","title":"Multiple Granularity Compatibility Matrix","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Introduces Intention Locks to allow locking entire folders or individual records without parsing every child node:"}]},{"type":"paragraph","content":[{"type":"text","text":"Lock Mode","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"IS","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"IX","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"S","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"SIX","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"X","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"IS","marks":[{"type":"bold"}]},{"type":"text","text":" (Intention Shared) | OK | OK | OK | OK | Conflict"}]},{"type":"paragraph","content":[{"type":"text","text":"IX","marks":[{"type":"bold"}]},{"type":"text","text":" (Intention Exclusive) | OK | OK | Conflict | Conflict | Conflict"}]},{"type":"paragraph","content":[{"type":"text","text":"S","marks":[{"type":"bold"}]},{"type":"text","text":" (Shared) | OK | Conflict | OK | Conflict | Conflict"}]},{"type":"paragraph","content":[{"type":"text","text":"SIX","marks":[{"type":"bold"}]},{"type":"text","text":" (Shared Intention Excl) | OK | Conflict | Conflict | Conflict | Conflict"}]},{"type":"paragraph","content":[{"type":"text","text":"X","marks":[{"type":"bold"}]},{"type":"text","text":" (Exclusive) | Conflict | Conflict | Conflict | Conflict | Conflict"}]}]}},"revision":1},{"id":"a9dd068c-6df5-7dbc-a5d8-63cf617e6a27","type":"heading","position":"aL","content":{"level":1,"content":[{"type":"text","text":"Database Recovery Techniques"}]},"revision":1},{"id":"a957bb2b-93b5-7c00-b2f8-3acdebc3e66c","type":"callout","position":"aM","content":{"variant":"note","title":"Log-Based Recovery","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Uses a sequential write-ahead log file to recover data:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deferred Update (No-Undo/Redo):","marks":[{"type":"bold"}]},{"type":"text","text":" Changes written to disk only after commit. On failure, apply REDO. No UNDO is ever needed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Immediate Update (Undo/Redo):","marks":[{"type":"bold"}]},{"type":"text","text":" Changes can be written to disk before commit. On failure, apply UNDO for uncommitted, and REDO for committed transactions."}]}]}]}]}},"revision":1},{"id":"9d29589f-b58e-71a0-9e27-bc11694f7696","type":"callout","position":"aN","content":{"variant":"note","title":"Shadow Paging","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Alternative recovery scheme that avoids logs. Keeps two page tables: a "},{"type":"text","text":"Current Page Table","marks":[{"type":"bold"}]},{"type":"text","text":" and a "},{"type":"text","text":"Shadow Page Table","marks":[{"type":"bold"}]},{"type":"text","text":". On commit, the current pointer overwrites the shadow pointer."}]}]}},"revision":1},{"id":"781a45a4-2a38-74ec-b8b9-9aac51d4ebae","type":"heading","position":"aO","content":{"level":1,"content":[{"type":"text","text":"Deadlock Prevention Schemes"}]},"revision":1},{"id":"7fbd3f47-554e-72ab-bffe-32dce4cb871f","type":"heading","position":"aP","content":{"level":3,"content":[{"type":"text","text":"Wait-Die Scheme"}]},"revision":1},{"id":"a944174a-1c3d-71a2-b63b-2dfb6cc19feb","type":"callout","position":"aQ","content":{"variant":"warning","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Wait-Die Scheme (Non-preemptive):","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"• If an older transaction requests a resource held by a younger one, the older is allowed to "},{"type":"text","text":"wait","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"hardBreak"},{"type":"text","text":"• If a younger transaction requests a resource held by an older one, the younger is killed ("},{"type":"text","text":"dies","marks":[{"type":"bold"}]},{"type":"text","text":") and restarted."}]}]}},"revision":1},{"id":"8caa163c-bde3-7562-ae54-be365462b975","type":"heading","position":"aR","content":{"level":3,"content":[{"type":"text","text":"Wound-Wait Scheme"}]},"revision":1},{"id":"7ed930f2-cbb3-76d3-91c3-e4920368284d","type":"callout","position":"aS","content":{"variant":"tip","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Wound-Wait Scheme (Preemptive):","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"• If an older transaction requests a resource held by a younger one, the older pre-empts ("},{"type":"text","text":"wounds","marks":[{"type":"bold"}]},{"type":"text","text":") the younger, forcing it to abort and roll back. "},{"type":"hardBreak"},{"type":"text","text":"• If a younger transaction requests a resource held by an older one, the younger is allowed to "},{"type":"text","text":"wait","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
