  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '3506e364-58d6-701f-b5c0-f910f1cad42b' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '1e651431-15a8-7ed7-867f-58b9671d30f8' AND n."deletedAt" IS NULL
