INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '10b879e6-5f71-7ae8-babe-bc2efa1d6ff9', 'e47e14ba-7ea8-716c-928d-656960f08e89', 1, 'PUBLISHED', 'Memory & Virtual Memory', '[{"id":"120038e5-10ee-7ff2-bffc-31e37c8eddde","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Contiguous allocation, paging address translation, TLB access calculations, and page replacement traces."}]}]}},"revision":1},{"id":"0a6ea638-6172-762a-9149-57a047bfe1a5","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Amazon SDE-1 Masterclass"}]},"revision":1},{"id":"c6ac71f2-38d8-7d0b-abfb-82a89ef772db","type":"callout","position":"a2","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Question:","marks":[{"type":"bold"}]},{"type":"text","text":" Explain virtual memory like I''m five years old (ELI5)."}]}]}},"revision":1},{"id":"13ee3351-7992-7fc4-99b1-d52579de5682","type":"callout","position":"a3","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Imagine you have a giant toy chest (the Hard Drive) that holds hundreds of toys, but you only have a small play table (RAM) that can hold three toys at a time. The Operating System is like your parent. When you want to play with a toy, your parent grabs it from the toy chest and puts it on the table. If the table is full, your parent swaps out a toy you haven''t played with in a long time back to the chest to make room. Virtual memory is the magic table that makes you feel like you can play with all your toys at once!\""}]}]}},"revision":1},{"id":"dea2eaef-8aa4-74f9-a13f-d688015a55d1","type":"callout","position":"a4","content":{"variant":"note","title":"Why Virtual Memory?","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Protects Memory:","marks":[{"type":"bold"}]},{"type":"text","text":" Prevents Process A from reading or modifying Process B''s memory."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enables Oversubscription:","marks":[{"type":"bold"}]},{"type":"text","text":" Spawns applications that require more memory than physical RAM installed, using the disk backing store."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Simplifies Development:","marks":[{"type":"bold"}]},{"type":"text","text":" Every process sees a uniform, contiguous logical memory space starting at address `0`."}]}]}]}]}},"revision":1},{"id":"d3f1022d-0b13-7256-852b-884b3772549a","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Partitioning & Fragmentations"}]},"revision":1},{"id":"73b783a1-c4c4-7c42-8b1b-96e9ee88b670","type":"callout","position":"a6","content":{"variant":"note","title":"Internal Fragmentation","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Occurs when memory is allocated in "},{"type":"text","text":"fixed-size partitions","marks":[{"type":"bold"}]},{"type":"text","text":" (e.g. standard pages). If a process requests 3 KB, but the page block is 4 KB, the remaining 1 KB remains allocated but unused. It is wasted internally."}]}]}},"revision":1},{"id":"59fc5b41-997d-73e3-ba7f-b6dd09d05a11","type":"callout","position":"a7","content":{"variant":"note","title":"External Fragmentation","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Occurs when memory is allocated in "},{"type":"text","text":"dynamic-size partitions","marks":[{"type":"bold"}]},{"type":"text","text":" (e.g. segmentation). Over time, memory is carved into tiny blocks. Total free space may equal 10 MB, but if it is fragmented into ten 1 MB chunks, a new process requesting 2 MB cannot start because no contiguous block is available."}]}]}},"revision":1},{"id":"d9d7b285-4877-782d-888c-a5296aaaf246","type":"callout","position":"a8","content":{"variant":"note","title":"Paging vs. Segmentation","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"• "},{"type":"text","text":"Paging:","marks":[{"type":"bold"}]},{"type":"text","text":" Divides logical memory into fixed-size blocks (Pages). Divides physical memory into identical frames. Eliminates external fragmentation entirely but causes minor internal fragmentation in the last page."}]},{"type":"paragraph","content":[{"type":"text","text":"• "},{"type":"text","text":"Segmentation:","marks":[{"type":"bold"}]},{"type":"text","text":" Divides memory into variable-sized chunks based on program sections (code, stack, heap). Aligns with programmer view, but causes external fragmentation and requires compaction overhead."}]}]}},"revision":1},{"id":"afc0f805-fea3-77ea-bd43-3523cddd17b6","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Page Fault Sequence"}]},"revision":1},{"id":"0699b2e1-be25-7e96-9e9d-3f1d9b5da1d8","type":"callout","position":"aA","content":{"variant":"note","title":"What happens during a Page Fault?","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A page fault is an MMU exception raised when a process references a page marked \"invalid\" in the page table (not loaded in physical RAM):"}]},{"type":"paragraph","content":[{"type":"text","text":"1. Memory Reference → 2. MMU Trap to Kernel → 3. Locate on Backing Disk → 4. Fetch Frame (Swap if full) → 5. Read Block into Frame → 6. Update Page Table → 7. Restart Instruction"}]}]}},"revision":1},{"id":"d79a1250-c410-73c2-b025-48d0caca0ab0","type":"callout","position":"aB","content":{"variant":"note","title":"Swapping","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The system-wide action of moving a process''s entire memory image out of RAM onto disk (swap space) when memory pressure is high, and restoring it later when physical RAM becomes free."}]}]}},"revision":1},{"id":"ec8df7fb-97b2-75b2-9679-818dfb050562","type":"callout","position":"aC","content":{"variant":"note","title":"Thrashing","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A catastrophic operating state where the OS spends more time constantly writing and reading memory pages to disk (handling page faults) than executing actual instructions. Occurs when processes lack frames to hold their active working sets."}]}]}},"revision":1},{"id":"f6b46109-3a66-77c3-a30c-1cb42e00c9b6","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"TLB Access Math"}]},"revision":1},{"id":"f13acde9-2d93-7d1e-96f4-e3b2ae3cf619","type":"callout","position":"aE","content":{"variant":"note","title":"TLB lookup math.","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Translation Lookaside Buffer (TLB)","marks":[{"type":"bold"}]},{"type":"text","text":" is a fast cache located inside the CPU''s memory management unit. Let:"},{"type":"hardBreak"},{"type":"text","text":" • $h$ = TLB hit ratio."},{"type":"hardBreak"},{"type":"text","text":" • $c$ = TLB lookup time."},{"type":"hardBreak"},{"type":"text","text":" • $m$ = Main memory access time."}]},{"type":"paragraph","content":[{"type":"text","text":"EMAT (Effective Access Time) = h * (c + m) + (1 - h) * (c + 2 * m)","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Note:","marks":[{"type":"italic"}]},{"type":"text","text":" On a TLB miss, we must access memory twice: once to read the page table entry to find the frame, and a second time to retrieve the actual data byte."}]}]}},"revision":1},{"id":"4777ce57-d08f-7ba9-9d84-7043b278e303","type":"callout","position":"aF","content":{"variant":"note","title":"Numerical Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Given hit ratio $h = 90\\%$, TLB lookup time $c = 10\\text{ ns}$, memory access time $m = 100\\text{ ns}$."}]},{"type":"paragraph","content":[{"type":"text","text":"EMAT = 0.90 * (10 + 100) + 0.10 * (10 + 200)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"     = 0.90 * 110 + 0.10 * 210","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"     = 99 + 21","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"     = 120 ns","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"d791b68d-1ab0-7e73-bf25-fa62b627ab33","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Numerical Page Replacement Traces"}]},"revision":1},{"id":"609f6c84-dcce-7931-9243-f6507b48cc1c","type":"callout","position":"aH","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Trace Scenario:","marks":[{"type":"bold"}]},{"type":"text","text":" 3 Frames. Reference string: "},{"type":"text","text":"7, 0, 1, 2, 0, 3, 0, 4, 2, 3, 0, 3, 2","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"ddac18ec-73ae-73a8-99b6-31528eeb00b8","type":"callout","position":"aI","content":{"variant":"note","title":"First-In, First-Out (FIFO)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pros","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Low execution overhead and simple to implement (FIFO queue of frame pointers)."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Cons","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Belady''s Anomaly:","marks":[{"type":"bold"}]},{"type":"text","text":" Increasing the physical frame count can counter-intuitively increase page faults."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ignores how frequently or recently a page is being used."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Ref","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"7","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"0","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"1","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"2","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"0","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"3","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"0","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"4","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"2","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"3","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"0","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"3","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"2","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"F0 | 7 | 7 | 7 | 2 | 2 | 2 | 2 | 4 | 4 | 4 | 0 | 0 | 0"}]},{"type":"paragraph","content":[{"type":"text","text":"F1 | - | 0 | 0 | 0 | 0 | 3 | 3 | 3 | 2 | 2 | 2 | 2 | 2"}]},{"type":"paragraph","content":[{"type":"text","text":"F2 | - | - | 1 | 1 | 1 | 1 | 0 | 0 | 0 | 3 | 3 | 3 | 3"}]},{"type":"paragraph","content":[{"type":"text","text":"Stat | F | F | F | F | H | F | F | F | F | F | F | H | H"}]},{"type":"paragraph","content":[{"type":"text","text":"• Total Page Faults: "},{"type":"text","text":"10","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"bed526f9-abaf-7926-9b04-34b9f634af47","type":"callout","position":"aJ","content":{"variant":"note","title":"Least Recently Used (LRU)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pros","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Highly effective; aligns closely with the "},{"type":"text","text":"temporal locality of reference","marks":[{"type":"bold"}]},{"type":"text","text":" principle."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Does not suffer from Belady''s Anomaly (belongs to the class of stack algorithms)."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Cons","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Expensive hardware support needed to track reference timestamps or stack positions on every memory request."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Ref","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"7","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"0","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"1","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"2","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"0","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"3","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"0","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"4","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"2","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"3","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"0","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"3","marks":[{"type":"bold"}]},{"type":"text","text":" | "},{"type":"text","text":"2","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"F0 | 7 | 7 | 7 | 2 | 2 | 2 | 2 | 4 | 4 | 4 | 0 | 0 | 0"}]},{"type":"paragraph","content":[{"type":"text","text":"F1 | - | 0 | 0 | 0 | 0 | 0 | 0 | 0 | 2 | 2 | 2 | 2 | 2"}]},{"type":"paragraph","content":[{"type":"text","text":"F2 | - | - | 1 | 1 | 1 | 3 | 3 | 3 | 3 | 3 | 3 | 3 | 3"}]},{"type":"paragraph","content":[{"type":"text","text":"Stat | F | F | F | F | H | F | H | F | F | F | H | H | H"}]},{"type":"paragraph","content":[{"type":"text","text":"• Total Page Faults: "},{"type":"text","text":"8","marks":[{"type":"bold"}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
