  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '31d94c2a-0f21-7ea2-86b5-b9126d9d8f24' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '7f0077cc-6bfb-74e9-b099-0d52e037575d' AND n."deletedAt" IS NULL
