INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'b1e6c157-d6a3-740f-b8c5-d0a2c2e1c873', 'fcfae5da-ed4d-7459-b015-ac098324267d', 1, 'PUBLISHED', 'Multithreading & Sync', '[{"id":"37ea054d-1d76-7d8f-9a20-d03b6378fe1d","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Concurrency vs Parallelism, shared data race conditions, memory safety, and lock styles."}]}]}},"revision":1},{"id":"f3047e07-6448-7012-96e3-5ad2e4f57198","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Concurrency Fundamentals"}]},"revision":1},{"id":"e361ca53-b6fe-7553-853e-d1bb531004d1","type":"callout","position":"a2","content":{"variant":"note","title":"Concurrency","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The execution of multiple tasks overlapping in time. On a single-core CPU, this is achieved by rapidly switching execution context (interleaving processes), creating the "},{"type":"text","text":"illusion","marks":[{"type":"bold"}]},{"type":"text","text":" of simultaneous progress."}]}]}},"revision":1},{"id":"46b00190-538e-79c5-979f-5eaf91cc1041","type":"callout","position":"a3","content":{"variant":"note","title":"Parallelism","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The execution of multiple tasks at the exact same physical instant. This requires multi-core, multi-processor hardware where distinct threads execute on separate physical CPU cores simultaneously."}]}]}},"revision":1},{"id":"62014226-892c-71dc-86b1-34c2b4456c10","type":"callout","position":"a4","content":{"variant":"note","title":"Race Condition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A scenario where multiple threads access and manipulate the same shared resource concurrently, and the final value depends on the exact ordering of execution. Consider a simple count increment:"}]},{"type":"paragraph","content":[{"type":"text","text":"Thread A (Read): count = 0","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Thread B (Read): count = 0","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Thread A (Add):  count + 1 = 1","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Thread B (Add):  count + 1 = 1","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Thread A (Write): count becomes 1","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Thread B (Write): count becomes 1 (Lost update! Output should be 2)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"7111bc8a-3e95-7226-ad9a-0f173b7d40b9","type":"callout","position":"a5","content":{"variant":"note","title":"Critical Section Requirements","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The code segment containing shared memory modifications. A valid solution must satisfy:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mutual Exclusion:","marks":[{"type":"bold"}]},{"type":"text","text":" Only one thread can execute in the critical section at any instant."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Progress:","marks":[{"type":"bold"}]},{"type":"text","text":" If no thread is in the critical section, only threads waiting to enter can decide which one gets to enter. The decision cannot be delayed indefinitely."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bounded Waiting:","marks":[{"type":"bold"}]},{"type":"text","text":" There is a limit on the number of times other threads can enter their critical sections before a waiting thread''s request is granted (no starvation)."}]}]}]}]}},"revision":1},{"id":"9705d9f2-d496-76e6-a28b-d7a06a724124","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Locks, Semaphores & Atomicity"}]},"revision":1},{"id":"b3ba871e-9a0c-76b7-962e-adcca77f2bfc","type":"callout","position":"a7","content":{"variant":"note","title":"Mutex","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mutual Exclusion Lock. A locking primitive with an owner. Only the thread that locks the mutex can release/unlock it. Good for simple critical section protection."}]}]}},"revision":1},{"id":"5814a92b-4bb4-74c9-b180-537219f208a2","type":"callout","position":"a8","content":{"variant":"note","title":"Semaphore","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A signaling primitive containing an integer counter. Non-owner based: any thread can call `signal()` to increment the semaphore, waking up waiting threads."}]}]}},"revision":1},{"id":"72de1710-b8a7-7281-8c15-20550174d9dc","type":"callout","position":"a9","content":{"variant":"note","title":"Binary Semaphore vs. Mutex","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"While a Binary Semaphore is restricted to values 0 and 1, it differs fundamentally from a Mutex:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ownership:","marks":[{"type":"bold"}]},{"type":"text","text":" Mutexes have ownership. The thread that locks a mutex *must* unlock it. Semaphores can be signaled (unlocked) by any thread."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use Case:","marks":[{"type":"bold"}]},{"type":"text","text":" Mutexes are for protecting data structures. Semaphores are for scheduling/producer-consumer signaling."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reentrancy:","marks":[{"type":"bold"}]},{"type":"text","text":" Mutexes can support recursive locking (a thread can lock it multiple times). Semaphores deadlock if locked again by the same thread."}]}]}]}]}},"revision":1},{"id":"ddc8dfb7-2110-72f2-bd50-d6164a70112e","type":"callout","position":"aA","content":{"variant":"note","title":"Spin Lock","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A lock where a waiting thread continuously polls the lock status in a tight loop. Wastes CPU cycles (busy waiting), but avoided context switch cost. Used in kernel code where lock hold times are guaranteed to be extremely brief."}]}]}},"revision":1},{"id":"0dff48c0-b113-7101-815f-d8ba7ebda8c1","type":"callout","position":"aB","content":{"variant":"note","title":"Read-Write Lock","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Allows multiple threads to read shared data simultaneously (shared lock), but only one thread to write at a time (exclusive lock). Boosts read-heavy application throughput."}]}]}},"revision":1},{"id":"75dc9d01-4aff-7abb-89f3-7cba8f47dfd5","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Advanced Memory Synchronization"}]},"revision":1},{"id":"76f5f6bb-f6a7-7254-92c9-6726f61cbe82","type":"callout","position":"aD","content":{"variant":"note","title":"Atomicity","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An operation is atomic if it completes as a single, indivisible step relative to all other threads. Hardware primitives like "},{"type":"text","text":"Compare-And-Swap (CAS)","marks":[{"type":"bold"}]},{"type":"text","text":" provide atomicity."}]}]}},"revision":1},{"id":"56c8046c-785e-7139-b449-863407ea39af","type":"callout","position":"aE","content":{"variant":"note","title":"Memory Visibility","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CPU cores cache values in L1/L2 caches. Writes by Core A are not instantly seen by Core B unless variables are declared `volatile` or memory barrier synchronization instructions are run."}]}]}},"revision":1},{"id":"c8a4775d-d7a6-7d9b-aac0-909d271ac575","type":"callout","position":"aF","content":{"variant":"note","title":"False Sharing","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Occurs when two threads running on different CPU cores modify independent variables that happen to share the same cache line. Cores repeatedly invalidate each other''s cache lines, destroying speed."}]}]}},"revision":1},{"id":"8c144483-d022-7f4f-abad-bde537846ca3","type":"callout","position":"aG","content":{"variant":"note","title":"Thread-Safety & Reentrant Code","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Thread Safety:","marks":[{"type":"bold"}]},{"type":"text","text":" A design guarantee that code functions correctly when called by multiple concurrent threads without side effects."}]},{"type":"paragraph","content":[{"type":"text","text":"Reentrancy:","marks":[{"type":"bold"}]},{"type":"text","text":" A stronger condition: code is reentrant if it can be interrupted in the middle of execution, called again (re-entered) by another thread, and both calls complete safely. Reentrant code completely avoids global/static variables and only modifies stack/arguments."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'fcfae5da-ed4d-7459-b015-ac098324267d' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
