  ('37ea054d-1d76-7d8f-9a20-d03b6378fe1d', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Concurrency vs Parallelism, shared data race conditions, memory safety, and lock styles."}]}]}}'),
  ('f3047e07-6448-7012-96e3-5ad2e4f57198', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"Concurrency Fundamentals"}]}'),
  ('e361ca53-b6fe-7553-853e-d1bb531004d1', 'a2', 'callout', '{"variant":"note","title":"Concurrency","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The execution of multiple tasks overlapping in time. On a single-core CPU, this is achieved by rapidly switching execution context (interleaving processes), creating the "},{"type":"text","text":"illusion","marks":[{"type":"bold"}]},{"type":"text","text":" of simultaneous progress."}]}]}}'),
  ('46b00190-538e-79c5-979f-5eaf91cc1041', 'a3', 'callout', '{"variant":"note","title":"Parallelism","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The execution of multiple tasks at the exact same physical instant. This requires multi-core, multi-processor hardware where distinct threads execute on separate physical CPU cores simultaneously."}]}]}}'),
