INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '7208dd20-f57d-7870-91c2-18feaea13a4d', '1e8753c6-93b4-7fbf-a557-4e14d3808114', 1, 'PUBLISHED', 'OS Fundamentals', '[{"id":"bd5f9d11-328e-716d-ac72-76255389fe69","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Under the hood basics: core components, system execution modes, hardware abstractions, and system call lifecycles."}]}]}},"revision":1},{"id":"bfb74b05-4772-796a-a849-12ef10319425","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Core Roles & Components"}]},"revision":1},{"id":"c341a8e5-5f54-7f92-963d-8d6941b104ad","type":"callout","position":"a2","content":{"variant":"note","title":"Explain the role of an OS.","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"Operating System (OS)","marks":[{"type":"bold"}]},{"type":"text","text":" is system software that acts as an intermediary between user applications and physical hardware. Its primary roles include:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Resource Allocator:","marks":[{"type":"bold"}]},{"type":"text","text":" Fairly and efficiently allocates CPU time, memory space, I/O devices, and file storage among competing processes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Control Program:","marks":[{"type":"bold"}]},{"type":"text","text":" Directs execution of user code, prevents errors, controls access, and prevents improper use of hardware."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hardware Abstraction Layer (HAL):","marks":[{"type":"bold"}]},{"type":"text","text":" Hides complex, vendor-specific hardware details behind simple, standardized software APIs."}]}]}]}]}},"revision":1},{"id":"e4fb90ea-f255-7d7d-8dce-3a488008322e","type":"callout","position":"a3","content":{"variant":"note","title":"Kernel","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The core program of the OS that runs at all times at the lowest level. It has direct, unrestricted access to physical hardware (executes in "},{"type":"text","text":"Kernel Mode","marks":[{"type":"bold"}]},{"type":"text","text":") and is responsible for process, memory, filesystem, and device management."}]}]}},"revision":1},{"id":"8340eaaf-c3fd-7657-8169-270d5ff90c89","type":"callout","position":"a4","content":{"variant":"note","title":"Shell","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A user-space command-line interpreter or graphical interface that translates human commands into system calls. It is not part of the kernel; it acts as a user application running in "},{"type":"text","text":"User Mode","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"6c74358c-d01b-7f10-a424-0ec40b401be5","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"System Modes & Hardware Access"}]},"revision":1},{"id":"59f1af73-a6c1-7f57-8301-292f0e0c7f56","type":"callout","position":"a6","content":{"variant":"note","title":"Difference between User Mode and Kernel Mode.","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Modern CPUs enforce memory and hardware protection via physical execution modes:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"User Mode (Mode bit = 1):","marks":[{"type":"bold"}]},{"type":"text","text":" Restricted mode. The CPU cannot execute privileged instructions (such as disabling interrupts, modifying page tables, or writing directly to hardware ports). Access to memory is bounded to the process''s allocated range."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kernel Mode (Mode bit = 0):","marks":[{"type":"bold"}]},{"type":"text","text":" Unrestricted mode. The CPU can execute any machine instruction and access any physical address in the system. The core OS kernel executes here."}]}]}]}]}},"revision":1},{"id":"1a254d81-0c29-7cfb-a7fb-e3ea3854f8e6","type":"callout","position":"a7","content":{"variant":"note","title":"Why can''t applications directly access hardware?","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If user applications had direct hardware access:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Security Violation:","marks":[{"type":"bold"}]},{"type":"text","text":" An application could read sensitive data directly from disk blocks belonging to other users."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"System Instability:","marks":[{"type":"bold"}]},{"type":"text","text":" A bug in one application (e.g., writing to memory-mapped control registers) could corrupt physical memory or crash the entire computer."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Complexity:","marks":[{"type":"bold"}]},{"type":"text","text":" Every developer would need to write low-level code to communicate with specific disk controller chips, network cards, and screen monitors."}]}]}]}]}},"revision":1},{"id":"2173c31e-670b-7132-a4bf-97e7578fbeb7","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"System Calls & Interrupts"}]},"revision":1},{"id":"15358cdf-3e2f-7790-8b69-d7eefaa713dd","type":"callout","position":"a9","content":{"variant":"note","title":"What is a system call?","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A programmatic interface that allows a user-mode application to request services from the kernel (e.g., reading a file, spawning a process, sending packets). It transitions the CPU from User Mode to Kernel Mode via a controlled "},{"type":"text","text":"software interrupt/trap","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"8594b2a6-646b-717c-bb03-8a8a043370a4","type":"callout","position":"aA","content":{"variant":"note","title":"fork() vs. exec()","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"fork():","marks":[{"type":"bold"}]},{"type":"text","text":" Spawns a new child process by duplicating the calling parent process''s memory space, descriptors, and execution state. Both execute the next instruction."}]},{"type":"paragraph","content":[{"type":"text","text":"exec():","marks":[{"type":"bold"}]},{"type":"text","text":" Replaces the entire address space and code image of the current process with a new executable program. It does not create a new process; it overwrites the current one."}]}]}},"revision":1},{"id":"419eb78a-86ec-7b7c-a1c3-83d0e189e0b1","type":"callout","position":"aB","content":{"variant":"note","title":"Interrupt vs. Exception","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Interrupt:","marks":[{"type":"bold"}]},{"type":"text","text":" An "},{"type":"text","text":"asynchronous","marks":[{"type":"italic"}]},{"type":"text","text":" event generated by external hardware (e.g., timer clock tick, disk write complete, key press) indicating it needs CPU attention."}]},{"type":"paragraph","content":[{"type":"text","text":"Exception (Trap):","marks":[{"type":"bold"}]},{"type":"text","text":" A "},{"type":"text","text":"synchronous","marks":[{"type":"italic"}]},{"type":"text","text":" event generated by the CPU itself during execution of an instruction due to an error (e.g., divide-by-zero, page fault) or a programmatic request (system call trap)."}]}]}},"revision":1},{"id":"f962968c-2b9b-7299-a5f3-4ad9851ef0ec","type":"callout","position":"aC","content":{"variant":"note","title":"What is Context Switching? Why is it expensive?","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The mechanism of saving the CPU execution state (Program Counter, registers, stack pointer, MMU page tables) of a running process or thread, and loading the saved state of another to resume its execution."}]},{"type":"paragraph","content":[{"type":"text","text":"Why it is expensive:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Direct Cost:","marks":[{"type":"bold"}]},{"type":"text","text":" Time spent executing OS scheduler code, saving registers, and updating process state tables."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Indirect Cost:","marks":[{"type":"bold"}]},{"type":"text","text":" Flushing the "},{"type":"text","text":"Translation Lookaside Buffer (TLB)","marks":[{"type":"bold"}]},{"type":"text","text":" and invalidating L1/L2/L3 caches. When the new process runs, it suffers major cache misses, leading to slow instruction execution until caches are warmed up again."}]}]}]}]}},"revision":1},{"id":"9eeb71f8-10f3-71f5-ba49-a7bf9c13487f","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Amazon SDE-1 Follow-up Scenario"}]},"revision":1},{"id":"13cf452a-62e4-7405-91fe-db4c98bc5f1e","type":"callout","position":"aE","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Question:","marks":[{"type":"bold"}]},{"type":"text","text":" Walk me through everything that happens step-by-step when your Python code runs: "},{"type":"hardBreak"},{"type":"text","text":" "},{"type":"text","text":"open(\"file.txt\")","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":" until the file contents are returned."}]}]}},"revision":1},{"id":"01a36d1a-880f-7472-8b25-4f5e96c055e5","type":"callout","position":"aF","content":{"variant":"note","title":"Step-by-Step Kernel Execution Lifecycle","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"1. Python Runtime → 2. Trap System Call → 3. Permission & Inode Lookup → 4. Block Request / Context Switch → 5. Disk Controller I/O → 6. Hardware Interrupt → 7. Copy to User Space & Return"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Translation:","marks":[{"type":"bold"}]},{"type":"text","text":" The Python runtime translates the `open()` call to the low-level library function (e.g., POSIX `open(2)`)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mode Transition (Trap):","marks":[{"type":"bold"}]},{"type":"text","text":" The library places the system call identifier for open in a CPU register and executes a software interrupt/trap instruction (e.g., `syscall` or `int 0x80`). The CPU switches the mode bit from `1` (User) to `0` (Kernel) and jumps to the kernel''s system call interrupt handler."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Descriptor Allocation:","marks":[{"type":"bold"}]},{"type":"text","text":" The kernel''s VFS (Virtual File System) checks process permissions, resolves the path `\"file.txt\"` to an "},{"type":"text","text":"Inode","marks":[{"type":"bold"}]},{"type":"text","text":", allocates an entry in the system-wide open file table, and returns a unique integer File Descriptor (FD) inside the process''s file table."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"I/O Scheduling:","marks":[{"type":"bold"}]},{"type":"text","text":" The kernel initiates a read request to the device driver for the disk sectors containing `\"file.txt\"`."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Blocked State:","marks":[{"type":"bold"}]},{"type":"text","text":" Because disk I/O is slow (milliseconds), the kernel moves the calling process from the "},{"type":"text","text":"Running","marks":[{"type":"bold"}]},{"type":"text","text":" state to the "},{"type":"text","text":"Blocked/Waiting","marks":[{"type":"bold"}]},{"type":"text","text":" queue. The CPU executes a "},{"type":"text","text":"Context Switch","marks":[{"type":"bold"}]},{"type":"text","text":" to run another active process, keeping CPU utilization high."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interrupt Trigger:","marks":[{"type":"bold"}]},{"type":"text","text":" The disk controller retrieves the block bytes, stores them in its buffer, and signals a physical line on the interrupt controller. The controller raises a "},{"type":"text","text":"hardware interrupt","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interrupt Handler:","marks":[{"type":"bold"}]},{"type":"text","text":" The CPU halts its current instruction, jumps to the kernel''s interrupt service routine (ISR). The ISR reads bytes from the controller buffer into the kernel''s "},{"type":"text","text":"Page Cache","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Wake Up:","marks":[{"type":"bold"}]},{"type":"text","text":" The kernel updates the waiting Python process state from "},{"type":"text","text":"Blocked","marks":[{"type":"bold"}]},{"type":"text","text":" to "},{"type":"text","text":"Ready","marks":[{"type":"bold"}]},{"type":"text","text":" in the scheduler queue."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reschedule & Return:","marks":[{"type":"bold"}]},{"type":"text","text":" The CPU schedules the Python process. The kernel copies the file buffer data from kernel memory space to the process''s user memory space, transitions back to "},{"type":"text","text":"User Mode","marks":[{"type":"bold"}]},{"type":"text","text":" (mode bit = 1), and return execution control back to Python."}]}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '1e8753c6-93b4-7fbf-a557-4e14d3808114' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
