FROM (VALUES
  ('bd5f9d11-328e-716d-ac72-76255389fe69', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Under the hood basics: core components, system execution modes, hardware abstractions, and system call lifecycles."}]}]}}'),
  ('bfb74b05-4772-796a-a849-12ef10319425', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"Core Roles & Components"}]}'),
  ('c341a8e5-5f54-7f92-963d-8d6941b104ad', 'a2', 'callout', '{"variant":"note","title":"Explain the role of an OS.","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"Operating System (OS)","marks":[{"type":"bold"}]},{"type":"text","text":" is system software that acts as an intermediary between user applications and physical hardware. Its primary roles include:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Resource Allocator:","marks":[{"type":"bold"}]},{"type":"text","text":" Fairly and efficiently allocates CPU time, memory space, I/O devices, and file storage among competing processes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Control Program:","marks":[{"type":"bold"}]},{"type":"text","text":" Directs execution of user code, prevents errors, controls access, and prevents improper use of hardware."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hardware Abstraction Layer (HAL):","marks":[{"type":"bold"}]},{"type":"text","text":" Hides complex, vendor-specific hardware details behind simple, standardized software APIs."}]}]}]}]}}'),
  ('e4fb90ea-f255-7d7d-8dce-3a488008322e', 'a3', 'callout', '{"variant":"note","title":"Kernel","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The core program of the OS that runs at all times at the lowest level. It has direct, unrestricted access to physical hardware (executes in "},{"type":"text","text":"Kernel Mode","marks":[{"type":"bold"}]},{"type":"text","text":") and is responsible for process, memory, filesystem, and device management."}]}]}}'),
  ('8340eaaf-c3fd-7657-8169-270d5ff90c89', 'a4', 'callout', '{"variant":"note","title":"Shell","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A user-space command-line interpreter or graphical interface that translates human commands into system calls. It is not part of the kernel; it acts as a user application running in "},{"type":"text","text":"User Mode","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}}'),
  ('6c74358c-d01b-7f10-a424-0ec40b401be5', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"System Modes & Hardware Access"}]}'),
  ('59f1af73-a6c1-7f57-8301-292f0e0c7f56', 'a6', 'callout', '{"variant":"note","title":"Difference between User Mode and Kernel Mode.","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Modern CPUs enforce memory and hardware protection via physical execution modes:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"User Mode (Mode bit = 1):","marks":[{"type":"bold"}]},{"type":"text","text":" Restricted mode. The CPU cannot execute privileged instructions (such as disabling interrupts, modifying page tables, or writing directly to hardware ports). Access to memory is bounded to the process''s allocated range."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kernel Mode (Mode bit = 0):","marks":[{"type":"bold"}]},{"type":"text","text":" Unrestricted mode. The CPU can execute any machine instruction and access any physical address in the system. The core OS kernel executes here."}]}]}]}]}}'),
  ('1a254d81-0c29-7cfb-a7fb-e3ea3854f8e6', 'a7', 'callout', '{"variant":"note","title":"Why can''t applications directly access hardware?","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If user applications had direct hardware access:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Security Violation:","marks":[{"type":"bold"}]},{"type":"text","text":" An application could read sensitive data directly from disk blocks belonging to other users."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"System Instability:","marks":[{"type":"bold"}]},{"type":"text","text":" A bug in one application (e.g., writing to memory-mapped control registers) could corrupt physical memory or crash the entire computer."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Complexity:","marks":[{"type":"bold"}]},{"type":"text","text":" Every developer would need to write low-level code to communicate with specific disk controller chips, network cards, and screen monitors."}]}]}]}]}}'),
  ('2173c31e-670b-7132-a4bf-97e7578fbeb7', 'a8', 'heading', '{"level":1,"content":[{"type":"text","text":"System Calls & Interrupts"}]}'),
  ('15358cdf-3e2f-7790-8b69-d7eefaa713dd', 'a9', 'callout', '{"variant":"note","title":"What is a system call?","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A programmatic interface that allows a user-mode application to request services from the kernel (e.g., reading a file, spawning a process, sending packets). It transitions the CPU from User Mode to Kernel Mode via a controlled "},{"type":"text","text":"software interrupt/trap","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}}'),
  ('8594b2a6-646b-717c-bb03-8a8a043370a4', 'aA', 'callout', '{"variant":"note","title":"fork() vs. exec()","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"fork():","marks":[{"type":"bold"}]},{"type":"text","text":" Spawns a new child process by duplicating the calling parent process''s memory space, descriptors, and execution state. Both execute the next instruction."}]},{"type":"paragraph","content":[{"type":"text","text":"exec():","marks":[{"type":"bold"}]},{"type":"text","text":" Replaces the entire address space and code image of the current process with a new executable program. It does not create a new process; it overwrites the current one."}]}]}}'),
  ('419eb78a-86ec-7b7c-a1c3-83d0e189e0b1', 'aB', 'callout', '{"variant":"note","title":"Interrupt vs. Exception","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Interrupt:","marks":[{"type":"bold"}]},{"type":"text","text":" An "},{"type":"text","text":"asynchronous","marks":[{"type":"italic"}]},{"type":"text","text":" event generated by external hardware (e.g., timer clock tick, disk write complete, key press) indicating it needs CPU attention."}]},{"type":"paragraph","content":[{"type":"text","text":"Exception (Trap):","marks":[{"type":"bold"}]},{"type":"text","text":" A "},{"type":"text","text":"synchronous","marks":[{"type":"italic"}]},{"type":"text","text":" event generated by the CPU itself during execution of an instruction due to an error (e.g., divide-by-zero, page fault) or a programmatic request (system call trap)."}]}]}}'),
  ('f962968c-2b9b-7299-a5f3-4ad9851ef0ec', 'aC', 'callout', '{"variant":"note","title":"What is Context Switching? Why is it expensive?","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The mechanism of saving the CPU execution state (Program Counter, registers, stack pointer, MMU page tables) of a running process or thread, and loading the saved state of another to resume its execution."}]},{"type":"paragraph","content":[{"type":"text","text":"Why it is expensive:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Direct Cost:","marks":[{"type":"bold"}]},{"type":"text","text":" Time spent executing OS scheduler code, saving registers, and updating process state tables."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Indirect Cost:","marks":[{"type":"bold"}]},{"type":"text","text":" Flushing the "},{"type":"text","text":"Translation Lookaside Buffer (TLB)","marks":[{"type":"bold"}]},{"type":"text","text":" and invalidating L1/L2/L3 caches. When the new process runs, it suffers major cache misses, leading to slow instruction execution until caches are warmed up again."}]}]}]}]}}'),
