INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '268b507c-5275-79c4-a562-59c71d106ae7', '8df6a9f9-15db-7f0a-84e8-c831303b171d', 1, 'PUBLISHED', 'Processes & Threads', '[{"id":"f9af352a-cc21-7370-82d8-3fb837f77c14","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Process lifecycle, resources allocation, lightweight executing structures, and thread pool design."}]}]}},"revision":1},{"id":"2a8adabe-9bb6-7c2a-acf1-6abc2e8e2dae","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Process Architecture & States"}]},"revision":1},{"id":"8983d214-8ae1-7944-afd1-4edf7e5700bb","type":"callout","position":"a2","content":{"variant":"note","title":"What is a process? What is stored in the PCB?","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"Process","marks":[{"type":"bold"}]},{"type":"text","text":" is an active program instance in execution, isolated by memory boundaries. The OS tracks and manages each process using a kernel data structure called the "},{"type":"text","text":"Process Control Block (PCB)","marks":[{"type":"bold"}]},{"type":"text","text":", which stores:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Process ID (PID) & Process State:","marks":[{"type":"bold"}]},{"type":"text","text":" Unique identifier and current execution state (New, Ready, Running, Waiting, Terminated)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Program Counter (PC):","marks":[{"type":"bold"}]},{"type":"text","text":" Address of the next CPU instruction to execute for this process."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Registers:","marks":[{"type":"bold"}]},{"type":"text","text":" Saved CPU register values when the process is context-switched out."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Memory Management Info:","marks":[{"type":"bold"}]},{"type":"text","text":" Page tables, segment tables, and base/limit registers representing the virtual address space."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"File Descriptor Table:","marks":[{"type":"bold"}]},{"type":"text","text":" Pointers to open files, network sockets, and I/O descriptors."}]}]}]}]}},"revision":1},{"id":"94c9c46e-529a-7660-b9b5-6c4b7c41d962","type":"callout","position":"a3","content":{"variant":"note","title":"Program vs. Process","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"Program","marks":[{"type":"bold"}]},{"type":"text","text":" is a passive entity: a compiled binary file containing machine code instructions stored on disk. A "},{"type":"text","text":"Process","marks":[{"type":"bold"}]},{"type":"text","text":" is an active entity: it represents the active execution of those instructions, possessing resources like virtual memory, registers, stack, and heap allocated by the kernel."}]}]}},"revision":1},{"id":"334cba85-19f9-71c6-874a-57cc325ff1af","type":"callout","position":"a4","content":{"variant":"note","title":"Why are processes isolated?","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Processes have completely isolated virtual address spaces. If Process A has a bug (e.g., null pointer dereference or array index write out of bounds), it triggers a segmentation fault. The OS terminates Process A, but Process B continues running completely unaffected. Memory isolation guarantees safety and security."}]}]}},"revision":1},{"id":"23f81a95-59c5-79d1-a3fe-ce997489272f","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Process & Thread Lifecycles"}]},"revision":1},{"id":"07666886-a479-700f-8696-47e6439dcb85","type":"callout","position":"a6","content":{"variant":"note","title":"Zombie Process","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A child process that has completed execution (called `exit()`) but its parent has not yet read its exit status (via `wait()`). It holds an entry in the system process table, though it releases all other memory."}]}]}},"revision":1},{"id":"334a1ab9-68b7-727f-a066-7c95f706860b","type":"callout","position":"a7","content":{"variant":"note","title":"Orphan Process","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A process whose parent has terminated while the child is still executing. The child is immediately adopted by the root system process (`init` or PID 1) which cleans up its exit state on termination."}]}]}},"revision":1},{"id":"e854e0a6-ea40-7690-9098-902c4004c595","type":"callout","position":"a8","content":{"variant":"note","title":"Daemon Process","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A background service process that runs continuously, detached from any user session or terminal. It handles system service tasks (e.g., `crond`, `syslogd`, web server listening loops)."}]}]}},"revision":1},{"id":"77e4bbe6-be02-75df-84c6-edcb5b012017","type":"callout","position":"a9","content":{"variant":"note","title":"Why is creating a process expensive?","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Creating a process requires allocating a new PID, setting up a fresh PCB, building new page tables, copying file descriptors, and copying the parent''s memory layout (often optimized via "},{"type":"text","text":"Copy-on-Write","marks":[{"type":"bold"}]},{"type":"text","text":", but still incurs overhead). In contrast, threads simply run inside the existing process environment."}]}]}},"revision":1},{"id":"867048e9-a4c6-7118-aa17-9c72df289ce4","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Threads: The Lightweight Alternative"}]},"revision":1},{"id":"94c7468e-7c57-7530-a1f7-1330ed221f49","type":"callout","position":"aB","content":{"variant":"note","title":"What is a thread? Why is it lightweight?","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"Thread","marks":[{"type":"bold"}]},{"type":"text","text":" is the basic, smallest unit of CPU execution scheduled by the OS. It is \"lightweight\" because it runs inside its parent process''s memory context, avoiding the need to allocate separate virtual memory page tables or address space descriptors."}]}]}},"revision":1},{"id":"db7b0a1f-bc12-703c-9f03-c8dd0380aa8f","type":"callout","position":"aC","content":{"variant":"note","title":"Shared Resources","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Code Segment (instructions)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Data Segment (global variables)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Heap memory (objects, dynamically allocated variables)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"System resources (open files, sockets)"}]}]}]}]}},"revision":1},{"id":"87f3a4d4-5fa2-78f8-842c-0a43517732dd","type":"callout","position":"aD","content":{"variant":"note","title":"Private Resources","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Thread ID (TID)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Program Counter (PC)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CPU registers"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stack (local variables, function call frames)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Thread Local Storage (TLS)"}]}]}]}]}},"revision":1},{"id":"b2486d08-fafd-7e53-b3af-6dddc83a1463","type":"callout","position":"aE","content":{"variant":"note","title":"Can one thread crash another?","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes.","marks":[{"type":"bold"}]},{"type":"text","text":" Because all threads of a process share the same virtual address space, if one thread executes a invalid memory operation (e.g., null pointer dereference, writing outside allocated boundaries), it triggers a segmentation fault at the process level. The OS sends a `SIGSEGV` signal to the parent process, causing the immediate termination of the entire process and all of its executing threads."}]}]}},"revision":1},{"id":"da612841-6a3e-7a06-9445-deb5efc2399b","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Amazon SDE-1 Follow-up Scenario"}]},"revision":1},{"id":"781203d2-81a2-7381-89d9-4d7753ad3acc","type":"callout","position":"aG","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Question:","marks":[{"type":"bold"}]},{"type":"text","text":" Suppose your backend server needs to handle 10,000 concurrent client requests. Would you create 10,000 threads? Why or why not? What are the alternatives?"}]}]}},"revision":1},{"id":"ce93b3ec-b0e3-760a-8c9e-953d87332c39","type":"callout","position":"aH","content":{"variant":"note","title":"Why 10,000 threads will crash your server:","doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Memory Exhaustion (Out Of Memory):","marks":[{"type":"bold"}]},{"type":"text","text":" Each thread requires its own private stack segment. By default on Linux, stack size is 8MB (can be tuned down to 512KB-2MB). At 1MB per thread, 10,000 threads consume "},{"type":"text","text":"10 GB of RAM","marks":[{"type":"bold"}]},{"type":"text","text":" just for stack frames, completely starving the application heap."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Context Switching Storm:","marks":[{"type":"bold"}]},{"type":"text","text":" If 10,000 threads compete for CPU cycles on an 8-core CPU, the CPU spends almost all its time swapping register states, page base pointers, and flushing caches (CPU thrashing). The CPU spends more time on context switching than running actual business logic."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Thread Creation Overhead:","marks":[{"type":"bold"}]},{"type":"text","text":" Initiating, scheduling, and tearing down 10,000 OS-level kernel threads wastes massive system cycles."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The Production-Grade Alternatives:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Thread Pool (Bounded Workers):","marks":[{"type":"bold"}]},{"type":"text","text":" Maintain a fixed pool of worker threads (e.g., `num_cores * 2`). Incoming requests are placed in a thread-safe task queue. Worker threads poll the queue, process requests, and return to the pool for reuse. This bounds resource usage."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Non-blocking Asynchronous I/O (Event Loop / Reactor Pattern):","marks":[{"type":"bold"}]},{"type":"text","text":" Used in Node.js, Nginx, Netty. A single thread (or one thread per core) multiplexes thousands of active connections using OS event notifications (such as `epoll` on Linux or `kqueue` on macOS). Instead of blocking a thread while waiting on disk/network I/O, the thread registers a callback and instantly moves to the next request. When I/O finishes, the OS raises an event and the thread executes the callback."}]}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
