SELECT '8be5a546-25e6-77b7-a8e0-05cffcb740cb', 'c3fc6136-0fbf-74ef-abfa-2c5253802abd', 1, 'PUBLISHED', 'Key Management', '[{"id":"5de32be5-2647-7667-8b91-d223b457a399","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The key lifecycle: generation entropy rules, key storage security (HSMs), rotation strategies, and split secrets."}]}]}},"revision":1},{"id":"27d0276b-3bb7-7380-962f-75be75b5c89d","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"1. Key Lifecycle Phases"}]},"revision":1},{"id":"cd2d5e2b-7119-7276-b81e-df49c0c87721","type":"callout","position":"a2","content":{"variant":"note","title":"1. Generation & Entropy","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keys must be generated using high-entropy random number generators (CSPRNG) inside secure boundary hardware modules. Weak entropy allows attackers to predict generated keys."}]}]}},"revision":1},{"id":"ba78b1a6-8932-753d-9e01-2d4d9c3ad9cc","type":"callout","position":"a3","content":{"variant":"note","title":"2. Secure Storage","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Private keys should never be stored in plain configurations or application source code. Always use dedicated Hardware Security Modules (HSMs) or cloud Key Management Services (KMS)."}]}]}},"revision":1},{"id":"5bd0af73-752a-7608-bd24-21e76a5afd61","type":"callout","position":"a4","content":{"variant":"note","title":"3. Rotation","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keys must be rotated periodically (e.g. every 90 days) to limit the amount of ciphertext encrypted under a single key, reducing the impact if a key is compromised."}]}]}},"revision":1},{"id":"3350c05b-8895-76ea-854f-4cca33f0ac96","type":"callout","position":"a5","content":{"variant":"note","title":"4. Destruction","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When a key is retired or revoked, it must be securely deleted from all systems and media to prevent decryption of historical archives (ensuring Forward Secrecy)."}]}]}},"revision":1},{"id":"8747d890-3343-7e98-a58b-71e17f5d1b37","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"2. KMS & HSM Hardware Boundaries"}]},"revision":1},{"id":"c9875e7c-23b3-7c7b-bf6f-84732b82c963","type":"callout","position":"a7","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"• "},{"type":"text","text":"HSM (Hardware Security Module):","marks":[{"type":"bold"}]},{"type":"text","text":" A physical tamper-resistant device that generates, stores, and protects keys. Keys never leave the HSM in plaintext; all cryptographic operations (encryption, decryption, signing) are executed inside the module''s secure memory boundary."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"KMS (Key Management Service):","marks":[{"type":"bold"}]},{"type":"text","text":" A cloud service (e.g. AWS KMS, GCP KMS) that manages key lifecycles and enforces access policies (IAM) for keys, while using HSMs on the backend."}]}]}},"revision":1},{"id":"0e00aadc-2c06-7f94-b74d-c9ef24292b36","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"3. Shamir''s Secret Sharing (SSS)"}]},"revision":1},{"id":"b4e8ba35-b0ba-7d30-a051-c7292977a958","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To secure highly sensitive keys (like root keys), "},{"type":"text","text":"Shamir''s Secret Sharing","marks":[{"type":"bold"}]},{"type":"text","text":" splits a secret into "},{"type":"text","text":"N","marks":[{"type":"code"}]},{"type":"text","text":" unique shares. The secret can only be reconstructed if a threshold of "},{"type":"text","text":"T","marks":[{"type":"code"}]},{"type":"text","text":" shares (where "},{"type":"text","text":"T ≤ N","marks":[{"type":"code"}]},{"type":"text","text":") are combined, preventing a single point of failure or compromise."}]},{"type":"paragraph","content":[{"type":"text","text":"SSS relies on polynomial interpolation: any point on a 2D graph can reconstruct a polynomial of degree T-1 if T distinct coordinates are known.","marks":[{"type":"code"}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'c3fc6136-0fbf-74ef-abfa-2c5253802abd' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
